// Runtime-owned objects use the high half of the u64 handle space. A
// narrowing cast would turn those handles into valid host slots on wasm32.
fn host_object_index(handle: u64) -> usize {
    usize::try_from(handle).unwrap_or(usize::MAX)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct CellAddress {
    sheet: usize,
    row: u32,
    column: u32,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct CellRange {
    sheet: usize,
    start_row: u32,
    start_column: u32,
    end_row: u32,
    end_column: u32,
}

fn condition_corner(ranges: &[CellRange]) -> Option<(u32, u32)> {
    Some((ranges.iter().map(|range| range.start_row).min()?, ranges.iter().map(|range| range.start_column).min()?))
}

fn condition_areas(sheet: usize, mut cells: Vec<CellAddress>) -> Vec<CellRange> {
    cells.sort_unstable_by_key(|cell| (cell.row, cell.column));
    cells.dedup();
    let mut areas: Vec<CellRange> = Vec::new();
    let mut previous: std::collections::HashMap<(u32, u32), usize> = std::collections::HashMap::new();
    let mut index = 0;
    let mut last_row = None;
    while index < cells.len() {
        let row = cells[index].row;
        if last_row.is_some_and(|last| last + 1 != row) { previous.clear(); }
        let mut current = std::collections::HashMap::new();
        while index < cells.len() && cells[index].row == row {
            let start = cells[index].column;
            let mut end = start;
            index += 1;
            while index < cells.len() && cells[index].row == row && cells[index].column == end + 1 {
                end += 1; index += 1;
            }
            let key = (start, end);
            let area = if let Some(&area) = previous.get(&key) {
                areas[area].end_row = row; area
            } else {
                areas.push(CellRange { sheet, start_row: row, end_row: row, start_column: start, end_column: end });
                areas.len() - 1
            };
            current.insert(key, area);
        }
        previous = current;
        last_row = Some(row);
    }
    areas
}

fn merge_condition_blocks(blocks: Vec<CellRange>) -> Vec<CellRange> {
    let mut areas: Vec<CellRange> = Vec::new();
    for mut block in blocks {
        while let Some(index) = areas.iter().rposition(|held| joined(*held, block).is_some()) {
            block = joined(areas.remove(index), block).expect("matching blocks");
        }
        areas.push(block);
    }
    areas
}

#[derive(Default)]
struct RangeInputWrite {
    wrote: bool,
    dynamic_recalc: bool,
    refused: bool,
    failure: Option<String>,
    formulas: Vec<CellAddress>,
}

struct RangeInputContinuation {
    block: InputBlock,
    writes: RangeInputWrite,
    broadcast_dress: Option<Worn>,
    header_writes: Vec<CellAddress>,
    row: u32,
    column: u32,
}

enum RangeInputProgress {
    Done(RangeInputWrite),
    Resolve(Value, Box<RangeInputContinuation>),
}

struct RangeArrayAssignment {
    range: CellRange,
    value: Value,
    name: String,
    style: FormulaStyle,
    continuation: Option<Box<RangeInputContinuation>>,
}

impl RangeInputWrite {
    fn absorb(&mut self, other: Self) {
        self.wrote |= other.wrote;
        self.dynamic_recalc |= other.dynamic_recalc;
        self.refused |= other.refused;
        if self.failure.is_none() { self.failure = other.failure; }
        self.formulas.extend(other.formulas);
    }
    fn finish(&self) -> Result<(), String> {
        if let Some(error) = &self.failure { return Err(error.clone()); }
        if self.refused { Err("the cell is locked and the sheet is protected; unprotect it first".to_string()) } else { Ok(()) }
    }
}

