/// A rectangular block of values a lookup searches, built either from a cell
/// range or from a VBA array. Excel treats a one-dimensional VBA array as a
/// single row, so `Array(5, 15, 25)` has one row and three columns.
struct LookupTable {
    rows: usize,
    columns: usize,
    /// How many columns `values` holds per row. A whole column is searched
    /// at its full length -- the sorted search's path depends on it -- but
    /// only what the sheet holds is read, and past that every cell is Empty.
    held_columns: usize,
    values: Vec<Value>,
}

impl LookupTable {
    fn get(&self, row: usize, column: usize) -> Value {
        if column >= self.held_columns {
            return Value::Empty;
        }
        self.values
            .get(row * self.held_columns + column)
            .cloned()
            .unwrap_or(Value::Empty)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum BorderSelection {
    All,
    EdgeLeft,
    EdgeTop,
    EdgeBottom,
    EdgeRight,
    InsideVertical,
    InsideHorizontal,
    /// xlDiagonalDown (5) and xlDiagonalUp (6): the rule from corner to
    /// corner, which `Borders.LineStyle = xlContinuous` over the whole
    /// leaves alone -- measured, it answers None after that.
    DiagonalDown,
    DiagonalUp,
}

/// What an undressed cell answers with: its writing is black and its fill is
/// white, which is what Excel says of a cell nobody has touched.
const BLACK: i64 = 0;
const WHITE: i64 = 16_777_215;

/// `xlUnderlineStyleSingle` and `xlUnderlineStyleNone`, which is what
/// `Font.Underline` answers rather than True and False.
const UNDERLINE_SINGLE: i64 = 2;
const UNDERLINE_NONE: i64 = -4142;

/// `xlNone`, which is the fill a cell has when it has none, and
/// `xlAutomatic`, which is the writing colour a cell has when it names none.
const COLOUR_NONE: i64 = -4142;
const COLOUR_AUTOMATIC: i64 = -4105;

/// The 56 colours `ColorIndex` counts, read off Excel one index at a time.
///
/// Each is packed the way VBA writes a colour — red, then green, then blue,
/// least significant first — so it can be compared with what `Color` answers
/// without turning it round. Eight of them are repeats (25 to 32 say again
/// what 9, 7, 6, 8, 13, 9, 14 and 5 said), and where two match Excel names
/// the lower.
const COLOUR_PALETTE: [i64; 56] = [
    0, 16777215, 255, 65280, 16711680, 65535, 16711935,
    16776960, 128, 32768, 8388608, 32896, 8388736, 8421376,
    12632256, 8421504, 16751001, 6697881, 13434879, 16777164, 6684774,
    8421631, 13395456, 16764108, 8388608, 16711935, 65535, 16776960,
    8388736, 128, 8421376, 16711680, 16763904, 16777164, 13434828,
    10092543, 16764057, 13408767, 16751052, 10079487, 16737843, 13421619,
    52377, 52479, 39423, 26367, 10053222, 9868950, 6697728,
    6723891, 13056, 13107, 13209, 6697881, 10040115, 3355443,
];

/// Excel first looks for the RGB value in the workbook's current palette and
/// returns its first matching index. If there is no exact match, it quantises
/// against the built-in palette, even when the workbook has replaced colors.
/// The first eight built-in colors that are absent from the current palette
/// answer their measured legacy values (index minus eight).
fn nearest_palette_index(colour: i64) -> i64 {
    nearest_palette_index_in(colour, &COLOUR_PALETTE)
}

fn nearest_palette_index_in(colour: i64, palette: &[i64; 56]) -> i64 {
    if let Some(index) = palette.iter().position(|held| *held == colour) {
        return index as i64 + 1;
    }
    if palette != &COLOUR_PALETTE {
        if let Some(index) = COLOUR_PALETTE
            .iter()
            .take(8)
            .position(|held| *held == colour)
        {
            return index as i64 - 7;
        }
    }

    let red = colour & 0xff;
    let green = (colour >> 8) & 0xff;
    let blue = (colour >> 16) & 0xff;
    let achromatic = red == green && green == blue;
    let has_achromatic = achromatic
        && COLOUR_PALETTE.iter().any(|held| {
            let held_red = held & 0xff;
            let held_green = (held >> 8) & 0xff;
            let held_blue = (held >> 16) & 0xff;
            held_red == held_green && held_green == held_blue
        });
    let mut nearest = 1;
    let mut best = i64::MAX;
    for (step, held) in COLOUR_PALETTE.iter().enumerate() {
        let held_red = held & 0xff;
        let held_green = (held >> 8) & 0xff;
        let held_blue = (held >> 16) & 0xff;
        if has_achromatic && !(held_red == held_green && held_green == held_blue) {
            continue;
        }
        let score = (red - held_red).abs() + (green - held_green).abs() + (blue - held_blue).abs();
        if score < best {
            nearest = step as i64 + 1;
            best = score;
        }
    }
    nearest
}

/// One of the 56, or the constant that clears the colour altogether.
///
/// `clears` is `xlNone` for a fill and `xlAutomatic` for writing — the two
/// names Excel gives to "this cell chooses no colour of its own".
fn palette_choice_in(
    value: &Value,
    clears: i64,
    what: &str,
    palette: &[i64; 56],
) -> Result<Option<String>, String> {
    let asked = match value {
        value if any_whole_number(value).is_some() => any_whole_number(value).unwrap_or_default(),
        _ => return Err(format!("{what} takes one of the 56 colours by number")),
    };
    // Nought is the same as the clearing constant, and past the palette is
    // out of range: measured, Interior.ColorIndex = 0 reads back -4142, and
    // = 57 or Tab.ColorIndex = 99 is error 9.
    if asked == clears || asked == 0 {
        return Ok(None);
    }
    if (1..=56).contains(&asked) {
        return Ok(Some(colour_from_packed(palette[(asked - 1) as usize])));
    }
    Err(host_error(9, format!("{what} has no colour {asked}")))
}

/// A colour packed the way VBA writes it, as the IR spells it: six hex digits
/// with nothing in front, which is what the file says and what the page puts a
/// `#` in front of to draw with.
fn colour_from_packed(colour: i64) -> String {
    let (red, green, blue) = (colour & 0xff, (colour >> 8) & 0xff, (colour >> 16) & 0xff);
    format!("{red:02X}{green:02X}{blue:02X}")
}

/// The same the other way, or nothing where the cell names no colour.
fn colour_to_packed(colour: Option<&str>) -> Option<i64> {
    let colour = colour?;
    let hex = colour.strip_prefix('#').unwrap_or(colour);
    if hex.len() != 6 {
        return None;
    }
    let rgb = u32::from_str_radix(hex, 16).ok()?;
    let (red, green, blue) = ((rgb >> 16) & 0xff, (rgb >> 8) & 0xff, rgb & 0xff);
    Some(i64::from(red | (green << 8) | (blue << 16)))
}

/// Whether one range lies wholly inside another, on the same sheet.
fn range_within(inner: CellRange, outer: CellRange) -> bool {
    inner.sheet == outer.sheet
        && inner.start_row >= outer.start_row
        && inner.end_row <= outer.end_row
        && inner.start_column >= outer.start_column
        && inner.end_column <= outer.end_column
}

const MAX_WORKSHEET_ROW: u32 = 1_048_576;
const MAX_WORKSHEET_COLUMN: u32 = 16_383;

impl CellRange {
    /// The corner it starts at: top-left, and the cell Excel puts in front
    /// when the block is selected.
    fn first(self) -> CellAddress {
        CellAddress {
            sheet: self.sheet,
            row: self.start_row,
            column: self.start_column,
        }
    }

    fn single(address: CellAddress) -> Self {
        Self {
            sheet: address.sheet,
            start_row: address.row,
            start_column: address.column,
            end_row: address.row,
            end_column: address.column,
        }
    }

    fn is_single(self) -> bool {
        self.start_row == self.end_row && self.start_column == self.end_column
    }

    fn addresses(self) -> impl Iterator<Item = CellAddress> {
        (self.start_row..=self.end_row).flat_map(move |row| {
            (self.start_column..=self.end_column).map(move |column| CellAddress {
                sheet: self.sheet,
                row,
                column,
            })
        })
    }
}

