const THEME_COLOURS: [i64; 12] = [
    16_777_215, 0, 15_263_976, 4_270_094, 8_544_277, 3_305_961, 2_386_713, 13_999_631,
    9_644_960, 3_057_486, 8_812_614, 8_216_726,
];

/// Which theme colour a number names, or error 9 for one the theme has not.
fn theme_colour(value: &Value) -> Result<usize, String> {
    let asked = any_whole_number(value)
        .ok_or_else(|| "ThemeColor takes a theme colour by number".to_string())?;
    if !(1..=12).contains(&asked) {
        return Err(host_error(9, format!("there is no theme colour {asked}")));
    }
    Ok(asked as usize)
}

/// Office ColorFormat's ObjectThemeColor order is dark1/light1/dark2/light2;
/// Excel cell ThemeColor is measured and numbered light1/dark1/light2/dark2.
#[cfg(test)]
fn office_theme_colour(theme: usize) -> i64 {
    match theme {
        1 => THEME_COLOURS[1],
        2 => THEME_COLOURS[0],
        3 => THEME_COLOURS[3],
        4 => THEME_COLOURS[2],
        5..=12 => THEME_COLOURS[theme - 1],
        _ => 0,
    }
}

fn workbook_office_theme_palette(colours: &[String]) -> [i64; 12] {
    const DEFAULT: [&str; 12] = [
        "000000", "FFFFFF", "0E2841", "E8E8E8", "156082", "E97132",
        "196B24", "0F9ED5", "A02B93", "4EA72E", "467886", "96607D",
    ];
    std::array::from_fn(|slot| {
        let value = colours.get(slot).map(String::as_str).unwrap_or(DEFAULT[slot]);
        let Ok(rgb) = i64::from_str_radix(value.trim_start_matches('#'), 16) else {
            return i64::from_str_radix(DEFAULT[slot], 16).unwrap_or(0);
        };
        ((rgb & 0xFF) << 16) | (rgb & 0xFF00) | ((rgb >> 16) & 0xFF)
    })
}

fn office_theme_colour_from(palette: &[i64; 12], theme: usize) -> i64 {
    palette.get(theme.saturating_sub(1)).copied().unwrap_or(0)
}

