            // open in a browser is the first of those with a name of its own:
            // there is a file behind it, but no folder anyone can name.
            // No chart sheet is active in a book of worksheets: measured.
            if name.eq_ignore_ascii_case("activechart") {
                return Ok(Some(Value::Nothing));
            }
            if name.eq_ignore_ascii_case("name") {
                return Ok(Some(Value::String(self.file_name.clone().unwrap_or_else(|| "Book1".to_string()))));
            }
            if name.eq_ignore_ascii_case("fullname") || name.eq_ignore_ascii_case("fullnameurlencoded") {
                return Ok(Some(Value::String(self.file_io.full_name.clone().or_else(||self.file_name.clone()).unwrap_or_else(|| "Book1".to_string()))));
            }
            if name.eq_ignore_ascii_case("path") {
                let path=self.file_io.full_name.as_deref().and_then(|name|name.rsplit_once(['\\','/'])).map(|(parent,_)|parent).unwrap_or("");
                return Ok(Some(Value::String(path.to_string())));
            }
            // Cell edits already set `saved` false. `wrote` only tracks pending
            // recalculation and must not override an explicit Saved=True.
            if name.eq_ignore_ascii_case("saved") {
                return Ok(Some(Value::Boolean(self.saved)));
            }
            if name.eq_ignore_ascii_case("readonly") {
                return Ok(Some(Value::Boolean(self.file_io.read_only)));
            }
