            // measured, Date1904 and PrecisionAsDisplayed both False.
            if name.eq_ignore_ascii_case("date1904") || name.eq_ignore_ascii_case("precisionasdisplayed") {
                return Ok(Some(Value::Boolean(false)));
            }
