/// Split what a name stands for into the worksheet it says and the rest.
///
/// A sheet name cannot hold a `!`, so the last one separates them, and a name
/// needing quotes carries doubled apostrophes inside them.
fn split_sheet_reference(refers_to: &str) -> (Option<String>, &str) {
    let Some(at) = refers_to.rfind('!') else {
        return (None, refers_to);
    };
    let (named, reference) = (refers_to[..at].trim(), refers_to[at + 1..].trim());
    // A name written from another workbook carries `[1]` or `[Book1]` first.
    let named = match named.rfind(']') {
        Some(end) => &named[end + 1..],
        None => named,
    };
    let named = match named
        .strip_prefix('\'')
        .and_then(|rest| rest.strip_suffix('\''))
    {
        Some(quoted) => quoted.replace("''", "'"),
        None => named.to_string(),
    };
    (Some(named), reference)
}

fn parse_range_reference(reference: &str) -> Result<((u32, u32), (u32, u32)), String> {
    let mut parts = reference.split(':');
    let start = parts.next().unwrap_or_default();
    let end = parts.next();
    if parts.next().is_some() {
        return Err(format!("invalid range reference: {reference}"));
    }
    let start = parse_a1_reference(start)?;
    let end = match end {
        Some(end) => parse_a1_reference(end)?,
        None => start,
    };
    Ok((start, end))
}

/// A whole-row or whole-column reference: `2:4`, `A:C`, either with `$`, in
/// either case, and with the two ends in either order.
///
/// Measured in Excel 16.0: `4:2` is rows 2 to 4 and `C:A` is columns A to C,
/// `a:c` is the same as `A:C`, a mixed pair like `A:2` is refused, and so is
/// an end past the sheet — `2:1048577` and `A:XFE` both raise. Answers
/// `(start row, start column, end row, end column)`.
fn parse_band_reference(text: &str) -> Option<(u32, u32, u32, u32)> {
    let (left, right) = text.trim().split_once(':')?;
    fn bare(part: &str) -> &str {
        let part = part.trim();
        part.strip_prefix('$').unwrap_or(part)
    }
    let (left, right) = (bare(left), bare(right));
    if left.is_empty() || right.is_empty() {
        return None;
    }
    if left.bytes().all(|byte| byte.is_ascii_digit()) && right.bytes().all(|byte| byte.is_ascii_digit())
    {
        let (one, two) = (left.parse::<u32>().ok()?, right.parse::<u32>().ok()?);
        if one == 0 || two == 0 || one > MAX_WORKSHEET_ROW || two > MAX_WORKSHEET_ROW {
            return None;
        }
        return Some((one.min(two), 0, one.max(two), MAX_WORKSHEET_COLUMN));
    }
    let one = column_from_letters(left)?;
    let two = column_from_letters(right)?;
    Some((1, one.min(two), MAX_WORKSHEET_ROW, one.max(two)))
}

/// One index or a pair of them, written out: `2`, `B`, `2:4`, `B:D`. Both
/// count from one, and a letter counts as its place in the alphabet — the
/// same number `Columns(2)` would have been handed.
fn parse_band_span(text: &str) -> Option<(u32, u32)> {
    let one = |part: &str| -> Option<u32> {
        let part = part.trim();
        let part = part.strip_prefix('$').unwrap_or(part);
        if part.is_empty() {
            return None;
        }
        if part.bytes().all(|byte| byte.is_ascii_digit()) {
            let number = part.parse::<u32>().ok()?;
            return (number > 0).then_some(number);
        }
        column_from_letters(part).map(|column| column + 1)
    };
    match text.trim().split_once(':') {
        Some((left, right)) => {
            let (left, right) = (one(left)?, one(right)?);
            Some((left.min(right), left.max(right)))
        }
        None => one(text).map(|only| (only, only)),
    }
}

/// A column's letters as its number, counted from nought. `None` when the
/// text is not letters at all, or names a column past the last one.
fn column_from_letters(letters: &str) -> Option<u32> {
    if letters.is_empty() || !letters.bytes().all(|byte| byte.is_ascii_alphabetic()) {
        return None;
    }
    let mut column = 0_u32;
    for letter in letters.bytes() {
        column = column
            .checked_mul(26)?
            .checked_add(u32::from(letter.to_ascii_uppercase() - b'A') + 1)?;
    }
    let column = column.checked_sub(1)?;
    (column <= MAX_WORKSHEET_COLUMN).then_some(column)
}

/// A single R1C1 cell, `R2C2`, as (column, row) both zero/one as the rest
/// of the host counts them: column zero-based, row one-based. Relative or
/// bracketed forms are not a place a `Goto` can name, so they are None.
fn parse_r1c1_cell(text: &str) -> Option<(u32, u32)> {
    let text = text.trim();
    let rest = text.strip_prefix(['R', 'r'])?;
    let (row, rest) = rest.split_at(rest.find(['C', 'c'])?);
    let column = &rest[1..];
    let row: u32 = row.parse().ok()?;
    let column: u32 = column.parse().ok()?;
    (row >= 1 && column >= 1).then(|| (column - 1, row))
}

fn parse_a1_reference(reference: &str) -> Result<(u32, u32), String> {
    let reference = reference.trim().replace('$', "");
    let reference = reference.as_str();
    if reference.is_empty() || reference.contains(':') || reference.contains('!') {
        return Err(format!(
            "only a single-sheet cell reference is supported: {reference}"
        ));
    }
    let split = reference
        .find(|ch: char| ch.is_ascii_digit())
        .ok_or_else(|| format!("invalid cell reference: {reference}"))?;
    let (letters, digits) = reference.split_at(split);
    if letters.is_empty()
        || digits.is_empty()
        || !letters.chars().all(|ch| ch.is_ascii_alphabetic())
        || !digits.chars().all(|ch| ch.is_ascii_digit())
    {
        return Err(format!("invalid cell reference: {reference}"));
    }
    let mut column = 0_u32;
    for letter in letters.bytes() {
        column = column
            .checked_mul(26)
            .and_then(|value| value.checked_add((letter.to_ascii_uppercase() - b'A' + 1) as u32))
            .ok_or_else(|| format!("cell column is too large: {reference}"))?;
    }
    let row = digits
        .parse::<u32>()
        .map_err(|_| format!("cell row is too large: {reference}"))?;
    if row == 0 || row > MAX_WORKSHEET_ROW {
        return Err(format!("cell row is outside the worksheet: {reference}"));
    }
    if column == 0 || column - 1 > MAX_WORKSHEET_COLUMN {
        return Err(format!("cell column is outside the worksheet: {reference}"));
    }
    Ok((column - 1, row))
}

/// The characters a column of `px` pixels reads as, to two places: the
/// gutter of 5 comes off first, unless the column is narrower than a
/// character, when the gutter shrinks with it.
fn characters_of_pixels(px: f32, digit: f32) -> f64 {
    let characters = oxicells_calc::column_width::pixels_to_characters(f64::from(px), f64::from(digit));
    (characters * 100.0).round() / 100.0
}

/// A stored column width already carries the gutter either side of a
/// cell's text; pixels come back out of it by OOXML's own rule. The same
/// function the renderer draws by.
fn column_pixels(width: f32, digit: f32) -> f32 {
    oxicells_calc::column_width::stored_width_to_pixels(f64::from(width), f64::from(digit)) as f32
}

/// A column for `Cells`: a number, or its letters -- measured,
/// `Cells(Rows.Count, "N")` is N1048576.
fn column_index(value: &Value) -> Result<u32, String> {
    if let Value::String(letters) = value {
        if let Some(column) = column_from_letters(letters.trim()) {
            return Ok(column + 1);
        }
        return Err(host_error(1004, format!("{letters:?} is not a column")));
    }
    positive_index(value, "column")
}

fn areas_item_index(value: &Value, count: usize) -> Result<usize, String> {
    use oxivba_core::runtime::{coerce_automation_scalar, AutomationScalarType};

    // Areas.Item takes an Automation Long, including ties-to-even rounding.
    let Value::Double(number) = coerce_automation_scalar(value, AutomationScalarType::Double)? else {
        unreachable!("Double coercion returns a Double");
    };
    let number = number.round_ties_even();
    if !number.is_finite() || number < f64::from(i32::MIN) || number > f64::from(i32::MAX) {
        return Err(host_error(6, "Areas.Item index overflows Long"));
    }
    if number < 1.0 || number > count as f64 {
        return Err(host_error(1004, "Areas.Item index is outside the collection"));
    }
    Ok(number as usize - 1)
}

fn positive_index(value: &Value, label: &str) -> Result<u32, String> {
    let number = match value {
        value if any_number(value).is_some() => any_number(value).unwrap_or_default(),
        _ => return Err(format!("Cells {label} must be numeric")),
    };
    if !number.is_finite() || number.fract() != 0.0 || !(1.0..=u32::MAX as f64).contains(&number) {
        return Err(format!("Cells {label} must be a positive integer"));
    }
    Ok(number as u32)
}

fn optional_positive_index(value: &Value, default: u32, label: &str) -> Result<u32, String> {
    if matches!(value, Value::Missing) {
        Ok(default)
    } else {
        positive_index(value, label)
    }
}

fn range_axis_name(axis: RangeAxis) -> &'static str {
    match axis {
        RangeAxis::Rows => "Rows",
        RangeAxis::Columns => "Columns",
    }
}

fn integer_offset(value: &Value, label: &str) -> Result<i64, String> {
    let number = match value {
        value if any_number(value).is_some() => any_number(value).unwrap_or_default(),
        _ => return Err(format!("Range.Offset {label} offset must be numeric")),
    };
    if !number.is_finite()
        || number.fract() != 0.0
        || !(i64::MIN as f64..=i64::MAX as f64).contains(&number)
    {
        return Err(format!(
            "Range.Offset {label} offset must be a whole number"
        ));
    }
    Ok(number as i64)
}

fn optional_integer_offset(value: &Value, default: i64, label: &str) -> Result<i64, String> {
    if matches!(value, Value::Missing) {
        Ok(default)
    } else {
        integer_offset(value, label)
    }
}

/// What a kind of paste carries with it.
///
/// Measured on Excel by pasting a cell holding a formula, a fill, a number
/// format and a line under it onto a cell dressed differently, and asking what
/// changed: `xlPasteAllExceptBorders` carried everything but the line,
/// `xlPasteColumnWidths` carried nothing but the width of the column, and
/// `xlPasteValuesAndNumberFormats` carried the VALUE — not the formula — and
/// the number format, leaving the fill alone.
#[derive(Debug, Clone, Copy)]
struct PasteWhat {
    values: bool,
    formulas: bool,
    styles: bool,
    /// Whether the dress it carries includes the lines round the cell.
    borders: bool,
    /// The number format on its own, where the rest of the dress stays.
    number_format: bool,
    column_widths: bool,
    /// The notes on the cells. Measured: `xlPasteAll` and `xlPasteComments`
    /// carry them, `xlPasteValues` and `xlPasteFormats` do not.
    comments: bool,
    validations: bool,
}

impl PasteWhat {
    fn of(kind: i64) -> Result<Self, String> {
        let nothing = Self {
            values: false,
            formulas: false,
            styles: false,
            borders: false,
            number_format: false,
            column_widths: false,
            comments: false,
            validations: false,
        };
        Ok(match kind {
            -4104 | 13 => Self {
                values: true,
                formulas: true,
                styles: true,
                borders: true,
                comments: true,
                validations: true,
                ..nothing
            },
            -4144 => Self {
                comments: true,
                ..nothing
            },
            6 => Self {
                validations: true,
                ..nothing
            },
            -4163 => Self {
                values: true,
                ..nothing
            },
            -4122 => Self {
                styles: true,
                borders: true,
                ..nothing
            },
            7 => Self {
                values: true,
                formulas: true,
                styles: true,
                comments: true,
                validations: true,
                ..nothing
            },
            8 => Self {
                column_widths: true,
                ..nothing
            },
            12 => Self {
                values: true,
                number_format: true,
                ..nothing
            },
            -4123 => Self {
                values: true,
                formulas: true,
                ..nothing
            },
            11 => Self {
                values: true,
                formulas: true,
                number_format: true,
                ..nothing
            },
            other => return Err(format!("Range.PasteSpecial cannot paste {other}")),
        })
    }
}

/// Whether what a cell holds is one of the kinds asked for.
///
/// The mask is Excel's: 1 a number, 2 text, 4 a Boolean, 16 an error, and 23 遯�E�繝ｻ/// the default 遯�E�繝ｻall of them. A formula whose answer this build has not worked
/// out holds nothing it can name, so it answers only to that default rather
/// than being counted as some kind it might not be.
fn value_answers(value: &CellValue, mask: i64) -> bool {
    if mask == 23 {
        return true;
    }
    let kind = match value {
        CellValue::Number(_) => 1,
        CellValue::String(_) => 2,
        CellValue::Utf16(_) => 2,
        CellValue::Boolean(_) => 4,
        CellValue::Error(_) => 16,
        _ => return false,
    };
    mask & kind != 0
}

/// The one block two make, where two make one.
///
/// Two blocks come together only when what they cover is itself a block: one
/// inside the other, or two that line up along a side and touch or overlap.
/// A1:A2 and A3:A4 make A1:A4; A1:A2 and C1:C2 make nothing.
fn joined(one: CellRange, other: CellRange) -> Option<CellRange> {
    if one.sheet != other.sheet {
        return None;
    }
    let covers = |outer: CellRange, inner: CellRange| {
        outer.start_row <= inner.start_row
            && outer.end_row >= inner.end_row
            && outer.start_column <= inner.start_column
            && outer.end_column >= inner.end_column
    };
    if covers(one, other) {
        return Some(one);
    }
    if covers(other, one) {
        return Some(other);
    }
    let all_of = CellRange {
        sheet: one.sheet,
        start_row: one.start_row.min(other.start_row),
        start_column: one.start_column.min(other.start_column),
        end_row: one.end_row.max(other.end_row),
        end_column: one.end_column.max(other.end_column),
    };
    let side_by_side = one.start_row == other.start_row
        && one.end_row == other.end_row
        && one.start_column.max(other.start_column) <= one.end_column.min(other.end_column) + 1;
    let one_above_the_other = one.start_column == other.start_column
        && one.end_column == other.end_column
        && one.start_row.max(other.start_row) <= one.end_row.min(other.end_row) + 1;
    (side_by_side || one_above_the_other).then_some(all_of)
}

/// A sheet's name as a formula has to write it, in quotes where it needs them.
fn quoted_sheet(name: &str) -> String {
    let plain = !name.is_empty()
        && !name.chars().next().is_some_and(|first| first.is_ascii_digit())
        && name
            .chars()
            .all(|character| character.is_alphanumeric() || character == '_' || character == '.');
    if plain {
        name.to_string()
    } else {
        format!("'{}'", name.replace('\'', "''"))
    }
}

/// What Excel allows a name to be called.
///
/// Asked of it, `1Bad`, `Two Words` and `B7` are all refused: a name has to
/// start with a letter or an underscore, hold no spaces, and not be shaped
/// like a cell reference — otherwise it could not be told from one.
fn check_name(name: &str) -> Result<(), String> {
    let refuse = |why: &str| Err(format!("{name:?} cannot be a name: {why}"));
    let Some(first) = name.chars().next() else {
        return refuse("it is empty");
    };
    if !(first.is_alphabetic() || first == '_') {
        return refuse("a name starts with a letter or an underscore");
    }
    if let Some(bad) = name
        .chars()
        .find(|character| !(character.is_alphanumeric() || *character == '_' || *character == '.'))
    {
        return refuse(&format!("a name cannot hold {bad:?}"));
    }
    if parse_a1_reference(name).is_ok() {
        return refuse("it is shaped like a cell reference");
    }
    // Nor may it read as an R1C1 reference: measured, "R" and "C1R" are
    // refused (1004), as are R, C, R2, C3, R2C3 and C3R2 alike.
    let lower = name.to_ascii_lowercase();
    let r1c1 = |text: &str, first: char, second: char| -> bool {
        let Some(rest) = text.strip_prefix(first) else { return false };
        let digits = rest.chars().take_while(|c| c.is_ascii_digit()).count();
        let rest = &rest[digits..];
        rest.is_empty() || rest.strip_prefix(second).is_some_and(|tail| tail.chars().all(|c| c.is_ascii_digit()))
    };
    if r1c1(&lower, 'r', 'c') || r1c1(&lower, 'c', 'r') {
        return refuse("it is shaped like an R1C1 reference");
    }
    Ok(())
}

fn optional_boolean_argument(value: &Value, default: bool, label: &str) -> Result<bool, String> {
    if matches!(value, Value::Missing) {
        Ok(default)
    } else {
        boolean_argument(value, label)
    }
}

fn boolean_argument(value: &Value, label: &str) -> Result<bool, String> {
    match value {
        Value::Boolean(value) => Ok(*value),
        value if any_number(value).is_some() => Ok(any_number(value).unwrap_or_default() != 0.0),
        Value::Double(value) if value.is_finite() => Ok(*value != 0.0),
        _ => Err(format!("Range.Address {label} must be Boolean")),
    }
}

fn format_range_address(range: CellRange, row_absolute: bool, column_absolute: bool) -> String {
    let format_cell = |row: u32, column: u32| {
        format!(
            "{}{}{}{}",
            if column_absolute { "$" } else { "" },
            oxicells_core::editor::col_to_letter(column),
            if row_absolute { "$" } else { "" },
            row
        )
    };
    // Excel abbreviates a range that covers whole rows or whole columns:
    // `Range("B2").EntireRow.Address` answers `$2:$2`, not
    // `$A$2:$XFD$2`, and `Columns(2).Address` answers `$B:$B`.
    let whole_rows = range.start_column == 0 && range.end_column == MAX_WORKSHEET_COLUMN;
    let whole_columns = range.start_row == 1 && range.end_row == MAX_WORKSHEET_ROW;
    // A range that is both at once is the whole grid, and Excel spells that
    // in rows: `Cells`, `Rows` and `Columns` alike answer `$1:$1048576`,
    // never `$A$1:$XFD$1048576` and never `$A:$XFD`.
    if whole_rows {
        let mark = if row_absolute { "$" } else { "" };
        return format!("{mark}{}:{mark}{}", range.start_row, range.end_row);
    }
    if whole_columns {
        let mark = if column_absolute { "$" } else { "" };
        return format!(
            "{mark}{}:{mark}{}",
            oxicells_core::editor::col_to_letter(range.start_column),
            oxicells_core::editor::col_to_letter(range.end_column)
        );
    }
    let start = format_cell(range.start_row, range.start_column);
    if range.is_single() {
        start
    } else {
        format!("{start}:{}", format_cell(range.end_row, range.end_column))
    }
}

/// A range written the other way round: the row first, and each part either
/// where it is or how far from somewhere else.
fn format_range_address_r1c1(
    range: CellRange,
    row_absolute: bool,
    column_absolute: bool,
    relative_to: (u32, u32),
) -> String {
    let part = |letter: char, value: u32, absolute: bool, from: u32| -> String {
        if absolute {
            format!("{letter}{value}")
        } else {
            let offset = i64::from(value) - i64::from(from);
            if offset == 0 {
                letter.to_string()
            } else {
                format!("{letter}[{offset}]")
            }
        }
    };
    let row = |value: u32| part('R', value, row_absolute, relative_to.0);
    let column =
        |value: u32| part('C', value + 1, column_absolute, relative_to.1 + 1);
    let whole_rows = range.start_column == 0 && range.end_column == MAX_WORKSHEET_COLUMN;
    let whole_columns = range.start_row == 1 && range.end_row == MAX_WORKSHEET_ROW;
    if whole_rows {
        let (start, end) = (row(range.start_row), row(range.end_row));
        return if start == end {
            start
        } else {
            format!("{start}:{end}")
        };
    }
    if whole_columns {
        let (start, end) = (column(range.start_column), column(range.end_column));
        return if start == end {
            start
        } else {
            format!("{start}:{end}")
        };
    }
    let start = format!("{}{}", row(range.start_row), column(range.start_column));
    if range.is_single() {
        start
    } else {
        format!(
            "{start}:{}{}",
            row(range.end_row),
            column(range.end_column)
        )
    }
}

fn vba_of_calculation_value(value: &oxicells_calc::Value) -> Value {
    match value {
        oxicells_calc::Value::Number(number) => Value::Double(*number),
        oxicells_calc::Value::Text(text) => Value::String(text.clone()),
        oxicells_calc::Value::Utf16(units) => Value::from_utf16(units.clone()),
        oxicells_calc::Value::Logical(value) => Value::Boolean(*value),
        oxicells_calc::Value::Blank => Value::Empty,
        oxicells_calc::Value::Lambda(function) => Value::Error(if function.is_external_reference() { 2029 } else { 2015 }),
        oxicells_calc::Value::Error(error) => Value::Error(spreadsheet_error_number(error.as_str())),
    }
}

fn from_cell_value(value: &CellValue) -> Value {
    match value {
        CellValue::Empty => Value::Empty,
        CellValue::String(value) => Value::String(value.clone()),
        CellValue::Utf16(value) => Value::from_utf16(value.clone()),
        CellValue::Error(value) => Value::Error(spreadsheet_error_number(value)),
        // Every number in a cell is a Double, whole or not, which is the type
        // VarType and TypeName report for one.
        CellValue::Number(value) => Value::Double(*value),
        CellValue::Boolean(value) => Value::Boolean(*value),
    }
}

/// A formula with every `[book]` naming this workbook taken out, outside its
/// string literals.
fn without_own_book(formula: &str, book: &str) -> String {
    let wanted = format!("[{book}]").to_lowercase();
    let mut out = String::with_capacity(formula.len());
    let mut quoted = false;
    let mut rest = formula;
    while let Some(ch) = rest.chars().next() {
        if ch == '"' {
            quoted = !quoted;
        }
        if !quoted && ch == '[' && rest.len() >= wanted.len() && rest.is_char_boundary(wanted.len())
            && rest[..wanted.len()].to_lowercase() == wanted
        {
            rest = &rest[wanted.len()..];
            continue;
        }
        out.push(ch);
        rest = &rest[ch.len_utf8()..];
    }
    out
}

// A calculation owns these observations. Nested value getters share its
// observations; a nested/new calculation gets a fresh scope and restores its
// caller's scope when the host operation returns.
type FormulaReadObservations = std::rc::Rc<std::cell::RefCell<std::collections::HashMap<String, BTreeSet<oxicells_calc::FormulaCell>>>>;

struct CachedUserAnswer {
    value: Option<oxicells_calc::functions::Arg>,
    reference_was_unready: bool,
    reference_retried: bool,
}

// Only use a previous returned cell as an ordering hint when the procedure
// unconditionally returns one literal A1 reference. A function can otherwise
// change its target through VBA variables even without reading the workbook.
fn fixed_reference_functions(module: &oxivba_core::Module, classes: &[(String, oxivba_core::Module)]) -> BTreeSet<String> {
    use oxivba_core::ast::{Expr, Literal, ModuleItem, ProcKind, Procedure, Statement};

    let modules = std::iter::once(module)
        .chain(module.standard_modules.iter().map(|(_, module)| module))
        .chain(classes.iter().map(|(_, module)| module));
    let shadows_range = classes.iter().any(|(name, _)| name.eq_ignore_ascii_case("Range"))
        || modules.into_iter().any(|module| !module.syntax_errors.is_empty() || module.items.iter().any(|item| match item {
        ModuleItem::Procedure(procedure) => procedure.name.eq_ignore_ascii_case("Range"),
        ModuleItem::ExternalProc(procedure) => procedure.name.eq_ignore_ascii_case("Range"),
        ModuleItem::Variables(declarations) => declarations.items.iter().any(|item| item.name.eq_ignore_ascii_case("Range")),
        ModuleItem::Type(declaration) => declaration.name.eq_ignore_ascii_case("Range"),
        ModuleItem::Enum(declaration) => declaration.name.eq_ignore_ascii_case("Range")
            || declaration.members.iter().any(|(name, _)| name.eq_ignore_ascii_case("Range")),
        ModuleItem::Directive { .. } | ModuleItem::Unknown { .. } => true,
        _ => false,
    }));
    if shadows_range { return BTreeSet::new(); }

    fn fixed(procedure: &Procedure) -> bool {
        if procedure.kind != ProcKind::Function || !procedure.params.is_empty() || !procedure.syntax_errors.is_empty() { return false; }
        let mut returned = false;
        for statement in &procedure.body {
            match statement {
                Statement::Comment { .. } => {}
                Statement::Assign { target: Expr::Ident(name, _), .. }
                    if !returned && !name.eq_ignore_ascii_case(&procedure.name) && !name.eq_ignore_ascii_case("Range") => {}
                Statement::SetAssign { target: Expr::Ident(name, _), value: Expr::Index { target, args, force_by_value: false, .. }, .. }
                    if name.eq_ignore_ascii_case(&procedure.name) && !returned
                        && matches!(target.as_ref(), Expr::Ident(name, _) if name.eq_ignore_ascii_case("Range"))
                        && args.len() == 1 && args[0].name.is_none() && !args[0].file_number && !args[0].force_by_value
                        && matches!(&args[0].value, Some(Expr::Literal(Literal::Str(address), _)) if oxicells_calc::reference::parse_a1(address).is_some()) =>
                {
                    returned = true;
                }
                _ => return false,
            }
        }
        returned
    }

    let mut names = BTreeSet::new();
    let mut seen = BTreeSet::new();
    let mut ambiguous = BTreeSet::new();
    for item in &module.items {
        if let ModuleItem::Procedure(procedure) = item {
            let name = procedure.name.to_ascii_uppercase();
            if !seen.insert(name.clone()) { ambiguous.insert(name.clone()); }
            if fixed(procedure) { names.insert(name); }
        }
    }
    for (scope, module) in &module.standard_modules {
        for item in &module.items {
            if let ModuleItem::Procedure(procedure) = item {
                let qualified = format!("{scope}.{}", procedure.name).to_ascii_uppercase();
                if !seen.insert(qualified.clone()) { ambiguous.insert(qualified.clone()); }
                if fixed(procedure) { names.insert(qualified); }
            }
        }
    }
    names.retain(|name| !ambiguous.contains(name));
    names
}

/// The module's own functions as the formula engine sees them.
#[derive(Default)]
struct UserFunctions {
    names: Vec<String>,
    reference_arguments: Vec<(String, Vec<usize>)>,
    variant_arguments: Vec<(String, Vec<usize>)>,
    value_read_arguments: std::collections::HashMap<String, BTreeSet<usize>>,
    address_only_arguments: std::collections::HashMap<String, BTreeSet<usize>>,
    address_only_candidates: std::collections::HashMap<String, BTreeSet<usize>>,
    formula_reads: FormulaReadObservations,
    answers: std::collections::HashMap<String, CachedUserAnswer>,
    operations: Vec<UserOperation>,
    calculation: Option<UserCalculation>,
    calculation_baseline: Option<CalculationBaseline>,
    evaluation_pass: usize,
    calculation_done: bool,
    force_full_calculation: bool,
    defer_dynamic_references_once: bool,
    copy_saved: Option<bool>,
    text_columns_result: Option<Result<Value, String>>,
    pending: Vec<PendingCall>,
    asked: std::collections::HashMap<u64, (String, bool, usize)>,
    read_views: std::collections::HashMap<u64, oxicells_calc::engine::UserFunctionReadView>,
    callback_results_by_cell: std::collections::HashMap<CellAddress, Value>,
    fixed_reference_functions: BTreeSet<String>,
    observed_returned_references: std::collections::HashMap<(CellAddress, String, usize), CellAddress>,
    callback_bodies: std::collections::HashSet<u64>,
    callback_body_environment_reads: std::collections::HashSet<u64>,
    callback_body_reads: std::collections::HashMap<u64, Vec<oxicells_calc::FormulaCell>>,
    callback_provisional_indirect_text: std::collections::HashMap<u64, bool>,
    callback_dynamic_reference_arguments: std::collections::HashMap<u64, u64>,
    callback_argument_ranges: std::collections::HashMap<u64, (String, Vec<Option<(String, oxicells_calc::RangeRef)>>)>,
    callback_written_dependencies: std::collections::HashMap<u64, Vec<(String, oxicells_calc::RangeRef)>>,
    provisional_probe_target: Option<(String, (u32, u32), String, (u32, u32))>,
    provisional_probe_seen: bool,
    callers: std::collections::HashMap<u64, CellAddress>,
    refused: std::collections::HashSet<u64>,
    running_key: Option<u64>,
    running_stack: Vec<(u64, Option<CellAddress>, Option<u64>)>,
    /// The cell whose formula is running a function right now.
    running: Option<CellAddress>,
    next: u64,
}

impl UserFunctions {
    fn has_outstanding_key(&self, key: &str) -> bool {
        let depth = self.operations.len();
        self.asked.values().any(|(asked, _, operation_depth)| *operation_depth == depth && asked == key)
    }

    fn has_outstanding_callbacks(&self) -> bool {
        let depth = self.operations.len();
        self.asked.values().any(|(_, _, operation_depth)| *operation_depth == depth)
    }

    fn cache_key(&self, name: &str, args: &[oxicells_calc::UserArg], caller: &oxicells_calc::UserCaller,
        context: oxicells_calc::engine::UserFunctionCallContext) -> String {
        let function = name.to_ascii_uppercase();
        let mut stable_reference_arguments = self.address_only_arguments.get(&function).cloned().unwrap_or_default();
        if context.provisional_indirect_text_value {
            for (index, argument) in args.iter().enumerate() {
                if self.reference_arguments.iter().any(|(name, indexes)| name.eq_ignore_ascii_case(&function) && indexes.contains(&index))
                    && user_arg_reference_range(argument).is_some()
                    && !self.value_read_arguments.get(&function).is_some_and(|indexes| indexes.contains(&index))
                {
                    stable_reference_arguments.insert(index);
                }
            }
        }
        let mut key_args = args.to_vec();
        for (index, argument) in key_args.iter_mut().enumerate() {
            if !stable_reference_arguments.contains(&index) { continue; }
            match argument {
                oxicells_calc::UserArg::Cells { values, .. } => values.clear(),
                oxicells_calc::UserArg::Block(block)
                    if matches!(&block.origin, oxicells_calc::functions::BlockOrigin::Cells { .. }) => block.cells.clear(),
                _ => {}
            }
        }
        format!("{}|{:?}|{:?}|{}|{}", function, key_args, caller, context.occurrence, context.provisional)
    }
}

fn computed_selector_zero_target_priority(workbook: &Workbook, functions: &UserFunctions, changed_independent_only: bool) -> bool {
    for sheet in &workbook.sheets {
        for row in &sheet.rows {
            for cell in &row.cells {
                let Some(formula) = cell.formula.as_deref() else { continue; };
                let Ok(expr) = oxicells_calc::parser::parse(formula) else { continue; };
                let mut found = false;
                expr.visit(&mut |node| {
                    let oxicells_calc::Expr::Function { name, args } = node else { return; };
                    let Some(function) = functions.names.iter().find(|known| known.eq_ignore_ascii_case(name)) else { return; };
                    for (index, argument) in args.iter().enumerate() {
                        let by_reference = functions.reference_arguments.iter().any(|(known, indexes)| known.eq_ignore_ascii_case(function) && indexes.contains(&index));
                        let variant = functions.variant_arguments.iter().any(|(known, indexes)| known.eq_ignore_ascii_case(function) && indexes.contains(&index));
                        if by_reference || variant { continue; }
                        argument.visit(&mut |nested| {
                            let oxicells_calc::Expr::Function { name, args } = nested else { return; };
                            if !name.eq_ignore_ascii_case("INDIRECT") { return; }
                            let Some(oxicells_calc::Expr::Ref(selector)) = args.first() else { return; };
                            if selector.book.is_some() || selector.sheet.is_some() || !selector.range.is_single() { return; }
                            let selector_at = selector.range.start;
                            let selector_cell = sheet.rows.iter().find(|row| row.index == selector_at.row + 1)
                                .and_then(|row| row.cells.iter().find(|cell| cell.col == selector_at.col));
                            let Some(selector_cell) = selector_cell else { return; };
                            let Some(selector_formula) = selector_cell.formula.as_deref() else { return; };
                            let Ok(selector_expr) = oxicells_calc::parser::parse(selector_formula) else { return; };
                            let mut computed = false;
                            let mut user_defined = false;
                            selector_expr.visit(&mut |part| match part {
                                oxicells_calc::Expr::Ref(_) | oxicells_calc::Expr::Name(_) | oxicells_calc::Expr::Table { .. } => computed = true,
                                oxicells_calc::Expr::Function { name, .. } if functions.names.iter().any(|known| known.eq_ignore_ascii_case(name)) => {
                                    computed = true;
                                    user_defined = true;
                                }
                                _ => {}
                            });
                            if !computed || user_defined { return; }
                            let Value::String(address) = from_cell_value(&selector_cell.value) else { return; };
                            let (target_sheet, address) = match address.rsplit_once('!') {
                                Some((requested, address)) => {
                                    let requested = requested.trim_matches('\'').replace("''", "'");
                                    let Some(index) = workbook.sheets.iter().position(|candidate| same_sheet_name(&candidate.name, &requested)) else { return; };
                                    (index, address)
                                }
                                None => (workbook.sheets.iter().position(|candidate| same_sheet_name(&candidate.name, &sheet.name)).unwrap_or(0), address.as_str()),
                            };
                            let Some(target) = oxicells_calc::reference::parse_a1(address.trim_start_matches('$')) else { return; };
                            let Some(target_cell) = workbook.sheets.get(target_sheet).and_then(|sheet| sheet.rows.iter().find(|row| row.index == target.row + 1))
                                .and_then(|row| row.cells.iter().find(|cell| cell.col == target.col)) else { return; };
                            if target_cell.formula.is_some() && matches!(&target_cell.value, CellValue::Number(value) if *value == 0.0)
                                && (!changed_independent_only || changed_independent_formula_exists(workbook, &workbook.sheets[target_sheet].name, target.col, target.row)) {
                                found = true;
                            }
                        });
                    }
                });
                if found { return true; }
            }
        }
    }
    false
}

fn changed_independent_formula_exists(workbook: &Workbook, target_sheet: &str, target_col: u32, target_row: u32) -> bool {
    let mut changed_inputs = Vec::new();
    for (changed_sheet, (left, top, right, bottom)) in &workbook.recalculation.changed {
        let Some(sheet) = workbook.sheets.iter().find(|sheet| same_sheet_name(&sheet.name, changed_sheet)) else { continue; };
        for row in sheet.rows.iter().filter(|row| row.index.saturating_sub(1) >= *top && row.index.saturating_sub(1) <= *bottom) {
            for cell in row.cells.iter().filter(|cell| cell.col >= *left && cell.col <= *right && cell.formula.is_none()) {
                changed_inputs.push((changed_sheet.clone(), cell.col, row.index.saturating_sub(1)));
            }
        }
    }
    let reads_changed = |formula: &oxicells_calc::Expr, formula_sheet: &str| formula.value_references().iter().any(|reference| {
        let reference_sheet = reference.sheet.as_deref().unwrap_or(formula_sheet);
        changed_inputs.iter().any(|(changed_sheet, col, row)| same_sheet_name(reference_sheet, changed_sheet) && reference.range.contains(*col, *row))
    });
    let target_formula = workbook.sheets.iter().find(|sheet| same_sheet_name(&sheet.name, target_sheet))
        .and_then(|sheet| sheet.rows.iter().find(|row| row.index == target_row + 1))
        .and_then(|row| row.cells.iter().find(|cell| cell.col == target_col))
        .and_then(|cell| cell.formula.as_deref())
        .and_then(|formula| oxicells_calc::parser::parse(formula).ok());
    if target_formula.as_ref().is_some_and(|formula| reads_changed(formula, target_sheet)) { return false; }
    for sheet in &workbook.sheets {
        for row in &sheet.rows {
            for cell in &row.cells {
                if cell.formula.is_none() || (same_sheet_name(&sheet.name, target_sheet) && cell.col == target_col && row.index.saturating_sub(1) == target_row) { continue; }
                let Some(formula) = cell.formula.as_deref().and_then(|formula| oxicells_calc::parser::parse(formula).ok()) else { continue; };
                let mut dynamic_lookup = false;
                formula.visit(&mut |node| if matches!(node, oxicells_calc::Expr::Function { name, .. } if name.eq_ignore_ascii_case("INDIRECT")) { dynamic_lookup = true; });
                if !dynamic_lookup && reads_changed(&formula, &sheet.name) { return true; }
            }
        }
    }
    false
}

fn full_rebuild_needs_zero_text_probe(workbook: &Workbook, functions: &UserFunctions) -> bool {
    for (sheet_index, sheet) in workbook.sheets.iter().enumerate() {
        for row in &sheet.rows {
            for cell in &row.cells {
                let Some(formula) = cell.formula.as_deref() else { continue; };
                let Ok(expr) = oxicells_calc::parser::parse(formula) else { continue; };
                let mut needs_probe = false;
                expr.visit(&mut |node| {
                    let oxicells_calc::Expr::Function { name, args } = node else { return; };
                    let Some(function) = functions.names.iter().find(|known| known.eq_ignore_ascii_case(name)) else { return; };
                    for (index, argument) in args.iter().enumerate() {
                        let is_reference = functions.reference_arguments.iter().any(|(known, indexes)| known.eq_ignore_ascii_case(function) && indexes.contains(&index));
                        let is_variant = functions.variant_arguments.iter().any(|(known, indexes)| known.eq_ignore_ascii_case(function) && indexes.contains(&index));
                        if is_reference || is_variant { continue; }
                        argument.visit(&mut |nested| {
                            let oxicells_calc::Expr::Function { name, args } = nested else { return; };
                            if name != "INDIRECT" { return; }
                            let Some(oxicells_calc::Expr::Ref(selector)) = args.first() else { return; };
                            if selector.book.is_some() || selector.sheet.is_some() || !selector.range.is_single() { return; }
                            let selector_at = selector.range.start;
                            let selector_cell = sheet.rows.iter().find(|row| row.index == selector_at.row + 1)
                                .and_then(|row| row.cells.iter().find(|cell| cell.col == selector_at.col));
                            let Some(selector_cell) = selector_cell else { return; };
                            let Some(selector_formula) = selector_cell.formula.as_deref() else { return; };
                            let Ok(selector_expr) = oxicells_calc::parser::parse(selector_formula) else { return; };
                            let mut dynamic_selector = false;
                            selector_expr.visit(&mut |part| match part {
                                oxicells_calc::Expr::Ref(_) | oxicells_calc::Expr::Name(_) | oxicells_calc::Expr::Table { .. } => dynamic_selector = true,
                                _ => {}
                            });
                            if dynamic_selector { return; }
                            let Value::String(address) = from_cell_value(&selector_cell.value) else { return; };
                            let (target_sheet, address) = match address.rsplit_once('!') {
                                Some((requested, address)) => {
                                    let requested = requested.trim_matches('\'').replace("''", "'");
                                    let Some(index) = workbook.sheets.iter().position(|candidate| same_sheet_name(&candidate.name, &requested)) else { return; };
                                    (index, address)
                                }
                                None => (sheet_index, address.as_str()),
                            };
                            let Some(target) = oxicells_calc::reference::parse_a1(address.trim_start_matches('$')) else { return; };
                            let target_cell = workbook.sheets.get(target_sheet).and_then(|sheet| sheet.rows.iter().find(|row| row.index == target.row + 1))
                                .and_then(|row| row.cells.iter().find(|cell| cell.col == target.col));
                            if target_cell.is_some_and(|cell| cell.formula.is_some() && matches!(&cell.value, CellValue::Number(value) if *value == 0.0)) {
                                needs_probe = true;
                            }
                        });
                    }
                });
                if needs_probe { return true; }
            }
        }
    }
    false
}

fn has_dynamic_indirect_text_selector(workbook: &Workbook, functions: &UserFunctions) -> bool {
    for sheet in &workbook.sheets {
        for row in &sheet.rows {
            for cell in &row.cells {
                let Some(formula) = cell.formula.as_deref() else { continue; };
                let Ok(expr) = oxicells_calc::parser::parse(formula) else { continue; };
                let mut found = false;
                expr.visit(&mut |node| {
                    let oxicells_calc::Expr::Function { name, args } = node else { return; };
                    let Some(function) = functions.names.iter().find(|known| known.eq_ignore_ascii_case(name)) else { return; };
                    for (index, argument) in args.iter().enumerate() {
                        let by_reference = functions.reference_arguments.iter().any(|(known, indexes)| known.eq_ignore_ascii_case(function) && indexes.contains(&index));
                        let variant = functions.variant_arguments.iter().any(|(known, indexes)| known.eq_ignore_ascii_case(function) && indexes.contains(&index));
                        if by_reference || variant { continue; }
                        argument.visit(&mut |nested| {
                            let oxicells_calc::Expr::Function { name, args } = nested else { return; };
                            if !name.eq_ignore_ascii_case("INDIRECT") { return; }
                            let Some(oxicells_calc::Expr::Ref(selector)) = args.first() else { return; };
                            if selector.book.is_some() || selector.sheet.is_some() || !selector.range.is_single() { return; }
                            let selector_at = selector.range.start;
                            let selector_cell = sheet.rows.iter().find(|row| row.index == selector_at.row + 1)
                                .and_then(|row| row.cells.iter().find(|cell| cell.col == selector_at.col));
                            let Some(selector_formula) = selector_cell.and_then(|cell| cell.formula.as_deref()) else { return; };
                            let Ok(selector_expr) = oxicells_calc::parser::parse(selector_formula) else { return; };
                            selector_expr.visit(&mut |part| match part {
                                oxicells_calc::Expr::Ref(_) | oxicells_calc::Expr::Name(_) | oxicells_calc::Expr::Table { .. } => found = true,
                                _ => {}
                            });
                        });
                    }
                });
                if found { return true; }
            }
        }
    }
    false
}

fn user_defined_indirect_selector_cell(workbook: &Workbook, functions: &UserFunctions, selected_target: bool) -> Option<oxicells_calc::FormulaCell> {
    for sheet in &workbook.sheets {
        for row in &sheet.rows {
            for cell in &row.cells {
                let Some(formula) = cell.formula.as_deref() else { continue; };
                let Ok(expr) = oxicells_calc::parser::parse(formula) else { continue; };
                let mut selector_target = None;
                expr.visit(&mut |node| {
                    let oxicells_calc::Expr::Function { name, args } = node else { return; };
                    let Some(function) = functions.names.iter().find(|known| known.eq_ignore_ascii_case(name)) else { return; };
                    for (index, argument) in args.iter().enumerate() {
                        let by_reference = functions.reference_arguments.iter().any(|(known, indexes)| known.eq_ignore_ascii_case(function) && indexes.contains(&index));
                        let variant = functions.variant_arguments.iter().any(|(known, indexes)| known.eq_ignore_ascii_case(function) && indexes.contains(&index));
                        if by_reference || variant { continue; }
                        argument.visit(&mut |nested| {
                            let oxicells_calc::Expr::Function { name, args } = nested else { return; };
                            if !name.eq_ignore_ascii_case("INDIRECT") { return; }
                            let Some(oxicells_calc::Expr::Ref(selector)) = args.first() else { return; };
                            if selector.book.is_some() || selector.sheet.is_some() || !selector.range.is_single() { return; }
                            let selector_at = selector.range.start;
                            let selector_cell = sheet.rows.iter().find(|row| row.index == selector_at.row + 1)
                                .and_then(|row| row.cells.iter().find(|cell| cell.col == selector_at.col));
                            let Some(selector_formula) = selector_cell.and_then(|cell| cell.formula.as_deref()) else { return; };
                            let Ok(selector_expr) = oxicells_calc::parser::parse(selector_formula) else { return; };
                            let mut calls_user_function = false;
                            selector_expr.visit(&mut |part| {
                                if let oxicells_calc::Expr::Function { name, .. } = part {
                                    if functions.names.iter().any(|known| known.eq_ignore_ascii_case(name)) {
                                        calls_user_function = true;
                                    }
                                }
                            });
                            if calls_user_function {
                                let location = if selected_target {
                                    let Some(selector_cell) = selector_cell else { return; };
                                    let Value::String(address) = from_cell_value(&selector_cell.value) else { return; };
                                    let (target_sheet, address) = match address.rsplit_once('!') {
                                        Some((requested, address)) => {
                                            let requested = requested.trim_matches('\'').replace("''", "'");
                                            let Some(index) = workbook.sheets.iter().position(|candidate| same_sheet_name(&candidate.name, &requested)) else { return; };
                                            (index, address)
                                        }
                                        None => (workbook.sheets.iter().position(|candidate| same_sheet_name(&candidate.name, &sheet.name)).unwrap_or(0), address.as_str()),
                                    };
                                    let Some(target) = oxicells_calc::reference::parse_a1(address.trim_start_matches('$')) else { return; };
                                    let Some(target_sheet_data) = workbook.sheets.get(target_sheet) else { return; };
                                    let is_formula = target_sheet_data.rows.iter().find(|row| row.index == target.row + 1)
                                        .and_then(|row| row.cells.iter().find(|cell| cell.col == target.col))
                                        .is_some_and(|cell| cell.formula.is_some());
                                    if !is_formula { return; }
                                    (target_sheet_data.name.clone(), (target.col, target.row))
                                } else {
                                    (sheet.name.clone(), (selector_at.col, selector_at.row))
                                };
                                selector_target = Some(location);
                            }
                        });
                    }
                });
                if selector_target.is_some() { return selector_target; }
            }
        }
    }
    None
}

fn calculate_needs_lagging_scalar_indirect_probe(workbook: &Workbook, functions: &UserFunctions) -> Option<((String, (u32, u32), String, (u32, u32)), bool)> {
    for (sheet_index, sheet) in workbook.sheets.iter().enumerate() {
        for row in &sheet.rows {
            for cell in &row.cells {
                let Some(formula) = cell.formula.as_deref() else { continue; };
                let Ok(expr) = oxicells_calc::parser::parse(formula) else { continue; };
                let mut probe_target = None;
                expr.visit(&mut |node| {
                    let oxicells_calc::Expr::Function { name, args } = node else { return; };
                    let Some(function) = functions.names.iter().find(|known| known.eq_ignore_ascii_case(name)) else { return; };
                    for (index, argument) in args.iter().enumerate() {
                        let by_reference = functions.reference_arguments.iter().any(|(known, indexes)| known.eq_ignore_ascii_case(function) && indexes.contains(&index));
                        let variant = functions.variant_arguments.iter().any(|(known, indexes)| known.eq_ignore_ascii_case(function) && indexes.contains(&index));
                        if by_reference || variant { continue; }
                        argument.visit(&mut |nested| {
                            let oxicells_calc::Expr::Function { name, args } = nested else { return; };
                            if !name.eq_ignore_ascii_case("INDIRECT") { return; }
                            let Some(oxicells_calc::Expr::Ref(selector)) = args.first() else { return; };
                            if selector.book.is_some() || selector.sheet.is_some() || !selector.range.is_single() { return; }
                            let selector_at = selector.range.start;
                            let selector_cell = sheet.rows.iter().find(|row| row.index == selector_at.row + 1)
                                .and_then(|row| row.cells.iter().find(|cell| cell.col == selector_at.col));
                            let Some(selector_cell) = selector_cell else { return; };
                            let Some(selector_formula) = selector_cell.formula.as_deref() else { return; };
                            let Ok(selector_expr) = oxicells_calc::parser::parse(selector_formula) else { return; };
                            let mut dynamic_selector = false;
                            let mut user_defined_selector = false;
                            selector_expr.visit(&mut |part| match part {
                                oxicells_calc::Expr::Ref(_) | oxicells_calc::Expr::Name(_) | oxicells_calc::Expr::Table { .. } => dynamic_selector = true,
                                oxicells_calc::Expr::Function { name, .. } if functions.names.iter().any(|known| known.eq_ignore_ascii_case(name)) => {
                                    dynamic_selector = true;
                                    user_defined_selector = true;
                                }
                                _ => {}
                            });
                            if !dynamic_selector { return; }
                            let Value::String(address) = from_cell_value(&selector_cell.value) else { return; };
                            let (target_sheet, address) = match address.rsplit_once('!') {
                                Some((requested, address)) => {
                                    let requested = requested.trim_matches('\'').replace("''", "'");
                                    let Some(index) = workbook.sheets.iter().position(|candidate| same_sheet_name(&candidate.name, &requested)) else { return; };
                                    (index, address)
                                }
                                None => (sheet_index, address.as_str()),
                            };
                            let Some(target) = oxicells_calc::reference::parse_a1(address.trim_start_matches('$')) else { return; };
                            let Some(target_sheet_data) = workbook.sheets.get(target_sheet) else { return; };
                            let target_cell = target_sheet_data.rows.iter().find(|row| row.index == target.row + 1)
                                .and_then(|row| row.cells.iter().find(|cell| cell.col == target.col));
                            let Some(target_cell) = target_cell else { return; };
                            let Some(target_formula) = target_cell.formula.as_deref() else { return; };
                            if !matches!(&target_cell.value, CellValue::Number(value) if *value != 0.0)
                                && !(user_defined_selector && matches!(&target_cell.value, CellValue::Number(value) if *value == 0.0)) { return; }
                            let Ok(target_expr) = oxicells_calc::parser::parse(target_formula) else { return; };
                            for (changed_sheet, (left, top, right, bottom)) in &workbook.recalculation.changed {
                                if !same_sheet_name(changed_sheet, &target_sheet_data.name) { continue; }
                                let changed_inputs: Vec<_> = workbook.sheets.iter().find(|candidate| same_sheet_name(&candidate.name, changed_sheet))
                                    .into_iter().flat_map(|candidate| candidate.rows.iter())
                                    .filter(|row| row.index.saturating_sub(1) >= *top && row.index.saturating_sub(1) <= *bottom)
                                    .flat_map(|row| row.cells.iter().filter(move |changed| changed.col >= *left && changed.col <= *right)
                                        .filter(|changed| changed.formula.is_none()).map(move |changed| (changed.col, row.index.saturating_sub(1))))
                                    .collect();
                                let reads_changed_input = target_expr.value_references().iter().any(|reference| {
                                    same_sheet_name(reference.sheet.as_deref().unwrap_or(&target_sheet_data.name), &target_sheet_data.name)
                                        && changed_inputs.iter().any(|(col, row)| reference.range.contains(*col, *row))
                                });
                                if reads_changed_input {
                                    probe_target = Some(((target_sheet_data.name.clone(), (target.col, target.row), sheet.name.clone(), (cell.col, row.index.saturating_sub(1))), user_defined_selector));
                                }
                            }
                        });
                    }
                });
                if probe_target.is_some() { return probe_target; }
            }
        }
    }
    None
}

#[derive(Clone)]
enum UserCalculation { All, Cells { cells: Vec<(String, (u32, u32))>, changed: bool, clear_dirty: bool, reason: CalculationReason } }
#[derive(Clone, Copy)]
enum CalculationReason { Calculate, Dirty { sheet: Option<usize> }, ManualEntry, AutomaticEntry, ArrayEntry }
struct UserOperation { formula_reads: FormulaReadObservations, answers: std::collections::HashMap<String, CachedUserAnswer>, calculation: Option<UserCalculation>, calculation_baseline: Option<CalculationBaseline>, evaluation_pass: usize, calculation_done: bool, wait_for_dependencies: bool, wait_for_dynamic_lookups: bool, provisional_dynamic_text_value: bool, provisional_zero_text_probe: bool, prioritize_dynamic_indirect_consumers: bool, provisional_text_probe_target: Option<oxicells_calc::FormulaCell>, distinct_provisional_calls: bool, full_rebuild: bool, full_calculation: bool, copy_saved: Option<bool>, text_columns_result: Option<Result<Value, String>>, spill_probe_layout: Option<oxicells_calc::engine::SpillProbeLayout> }

#[derive(Clone)]
struct CalculationBaseline { sheets: Vec<SheetCalculationBaseline>, spill_layout: oxicells_core::recalculation::SpillLayout }

#[derive(Clone)]
struct SheetCalculationBaseline {
    name: String,
    cells: std::collections::BTreeMap<(u32, u32), (CellValue, bool)>,
    spills: Option<Vec<oxicells_core::ir::CachedSpill>>,
}

impl CalculationBaseline {
    fn capture(workbook: &Workbook) -> Self {
        Self { sheets: workbook.sheets.iter().map(|sheet| SheetCalculationBaseline {
            name: sheet.name.clone(),
            cells: sheet.rows.iter().flat_map(|row| row.cells.iter().filter_map(move |cell| {
                let member = cell.spill == oxicells_core::ir::Spill::Member;
                (cell.formula.is_some() || member).then(|| ((cell.col, row.index), (cell.value.clone(), member)))
            })).collect(),
            spills: sheet.cached_spills.clone(),
        }).collect(), spill_layout: oxicells_core::recalculation::spill_layout(workbook) }
    }

    fn restore(&self, workbook: &mut Workbook) {
        for saved in &self.sheets {
            let Some(sheet) = workbook.sheets.iter_mut().find(|sheet| sheet.name == saved.name) else { continue; };
            for row in &mut sheet.rows {
                for cell in &mut row.cells {
                    let previous = saved.cells.get(&(cell.col, row.index));
                    if cell.spill == oxicells_core::ir::Spill::Member && !previous.is_some_and(|(_, member)| *member) {
                        cell.value = CellValue::Empty;
                        cell.spill = oxicells_core::ir::Spill::None;
                    }
                    if let Some((value, member)) = previous {
                        if cell.formula.is_some() || *member { cell.value = value.clone(); }
                        if *member { cell.spill = oxicells_core::ir::Spill::Member; }
                    }
                }
            }
            sheet.cached_spills = saved.spills.clone();
        }
    }
}

struct PendingCall {
    number: u64,
    operation_depth: usize,
    name: String,
    key: String,
    provisional_indirect_text_value: bool,
    dynamic_reference_argument_mask: u64,
    args: PendingArgs,
    once: bool,
    caller: oxicells_calc::UserCaller,
    read_view: Option<oxicells_calc::engine::UserFunctionReadView>,
    written_dependencies: Vec<(String, oxicells_calc::RangeRef)>,
}

enum PendingArgs {
    Sheet(Vec<oxicells_calc::UserArg>),
    Vba(Vec<Value>),
}

fn user_arg_reference_range(argument: &oxicells_calc::UserArg) -> Option<(String, oxicells_calc::RangeRef)> {
    match argument {
        oxicells_calc::UserArg::Cells { sheet, range, .. } => Some((sheet.clone(), *range)),
        oxicells_calc::UserArg::Block(block) => match &block.origin {
            oxicells_calc::functions::BlockOrigin::Cells { sheet, range } => Some((sheet.clone(), *range)),
            _ => None,
        },
        _ => None,
    }
}

/// A macro's answer as the sheet holds it: an array is a block of values.
fn sheet_arg_of(value: &Value) -> oxicells_calc::functions::Arg {
    use oxicells_calc::functions::{Arg, RangeData};
    match value {
        Value::Array(array) => {
            let (width, height) = match array.dimensions.as_slice() {
                [columns] => (columns.length, 1),
                [rows, columns] => (columns.length, rows.length),
                _ => (array.values.len(), 1),
            };
            Arg::Range(RangeData {origin: oxicells_calc::functions::BlockOrigin::Array,  width, height, cells: array.values.iter().map(engine_value).collect() })
        }
        other => Arg::Value(engine_value(other)),
    }
}

/// The format a Currency written to a cell puts on it.
const MONEY_FORMAT: &str = "$#,##0.00_);($#,##0.00)";

fn to_cell_value(value: Value) -> Result<CellValue, String> {
    match value {
        Value::NullString=>to_cell_value(Value::String(String::new())),
        value @ Value::ByteString(_)=>to_cell_value(Value::from_utf16(value.padded_string_units().expect("BSTR units").into_owned())),
        Value::Utf16(mut units)=>{
            if let Some(end)=units.iter().position(|u|*u==0){units.truncate(end);}
            match String::from_utf16(&units){
                Ok(text)=>to_cell_value(Value::String(text)),
                Err(_)=>Ok(CellValue::Utf16(units)),
            }
        },
        Value::Empty | Value::Null => Ok(CellValue::Empty),
        Value::Missing => Err("an omitted VBA argument cannot be assigned to a cell".to_string()),
        Value::Nothing => Err("Nothing cannot be assigned to a spreadsheet cell".to_string()),
        Value::Boolean(value) => Ok(CellValue::Boolean(value)),
        Value::Int16(value) => Ok(CellValue::Number(value as f64)),
        Value::Byte(value) => Ok(CellValue::Number(value as f64)),
        Value::Integer(value) => Ok(CellValue::Number(value as f64)),
        Value::Decimal(value) => Ok(CellValue::Number(value.to_f64())),
        Value::LongLong(value) => Ok(CellValue::Number(value as f64)),
        Value::Single(value) => Ok(CellValue::Number(value as f64)),
        Value::Currency(value) => Ok(CellValue::Number(value as f64 / 10_000.0)),
        // A cell told to hold a date keeps the serial. What Excel ALSO
        // does is give the cell a date format, which has not been
        // measured here, so the number goes in and the dressing does not.
        Value::Date(value) => Ok(CellValue::Number(value)),
        // Excel turns nonfinite VBA numbers into #NUM! when writing a cell.
        Value::Double(value) if !value.is_finite() => Ok(CellValue::Error("#NUM!".to_string())),
        // A cell holds no negative zero.
        Value::Double(value) => Ok(CellValue::Number(value + 0.0)),
        // Only a REAL error code may be put in a cell. Asked of Excel,
        // `Range("A1").Value = CVErr(2042)` leaves #N/A, and so do 2000, 2007,
        // 2015, 2023, 2029, 2036 and 2043 through 2049 -- while `CVErr(0)`,
        // `CVErr(1)`, `CVErr(1999)`, `CVErr(2001)` and `CVErr(3000)` are all
        // error 1004. It is a list, not a range: 2001 sits between two that
        // are accepted and is refused.
        //
        // Writing #VALUE! for anything unrecognised was the quiet kind of
        // wrong: the cell ended up holding an error that was never asked for,
        // and the macro carried on believing the write had worked.
        Value::Error(value) => match spreadsheet_error_text_exact(value) {
            Some(text) => Ok(CellValue::Error(text.to_string())),
            None => Err(format!("{value} is not a spreadsheet error value")),
        },
        // A cell CUTS its text at the first NUL, and what is left decides the
        // rest. Asked of Excel, `Range("A1").Value = "a" & Chr(0) & "b"`
        // leaves the cell holding `a`, and a value that is nothing but NULs
        // leaves it Empty -- the same as the empty string, which also does not
        // stay a string: `Range("F1").Value = ""` leaves the cell Empty and
        // TypeName says so.
        //
        // Every other control character goes in whole: Chr(1), Chr(9), Chr(10)
        // and Chr(12) all leave a cell one character long. It is the NUL alone
        // that ends the text.
        Value::String(value) => {
            let kept = text_a_cell_keeps(&value);
            if kept.is_empty() {
                Ok(CellValue::Empty)
            } else {
                Ok(typed_from_text(kept))
            }
        }
        // An array where one value belongs -- an element of an array of
        // arrays -- leaves the cell empty: measured,
        // `Range("S1:S2").Value = Array(Array(1, 2), Array(3, 4))` leaves S1
        // with nothing in it and raises nothing.
        Value::Array(_) => Ok(CellValue::Empty),
        Value::Record(_) => Err("a VBA Type cannot be assigned to one cell".to_string()),
        Value::Object(_) => Err("a VBA object cannot be assigned to one cell".to_string()),
    }
}

/// The mark that tells Excel to leave what follows as text.
const APOSTROPHE: char = '\u{27}';

/// A string assigned to a cell is read the way typing it would be.
///
/// Asked of Excel, `Range("A1").Value = "0123"` leaves the NUMBER 123 behind,
/// not the text; `"TRUE"` leaves a Boolean; `"(5)"` leaves −5; a leading
/// apostrophe forces the rest to stay text; and anything Excel cannot read as
/// a number stays as it was written.
///
/// Excel reads more than this. `"50%"`, `"1e3"`, `"$5"`, `"1/2"`, `"1:30"`,
/// `"1,234"` and `"1 1/2"` all become numbers too — but each of them also sets
/// the cell's number format, which this cannot do from here, and four of them
/// read differently under a different locale: on the machine this was measured
/// `"1/2"` became a date formatted `m"月"d"日"` and `"$5"` took a yen-less
/// dollar format, neither of which is a fact about Excel. Those are left as
/// text on purpose until the format can travel with the value and the locale
/// has been measured rather than assumed.
fn typed_from_text(written: &str) -> CellValue {
    typed_from_written(written, this_year_now()).0
}

#[cfg(not(target_arch = "wasm32"))]
fn this_year_now() -> i64 {
    use std::time::{SystemTime, UNIX_EPOCH};

    let serial = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs_f64() / 86_400.0 + 25_569.0)
        .unwrap_or(0.0);
    year_of_serial(serial)
}

#[cfg(target_arch = "wasm32")]
fn this_year_now() -> i64 {
    let now = js_sys::Date::new_0();
    year_of_serial((now.get_time() - now.get_timezone_offset() * 60_000.0) / 86_400_000.0 + 25_569.0)
}

/// The calendar year an Excel serial falls in.
/// A date serial moved by whole months, the day held back to the end of a
/// shorter month, the time of day kept.
fn add_months_to_serial(serial: f64, months: i64) -> f64 {
    let days = serial.floor() as i64;
    let time = serial - serial.floor();
    // Days from 1899-12-30 to civil, by Howard Hinnant's algorithm.
    let z = days - 25569 + 719468;
    let era = z.div_euclid(146097);
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = yoe + era * 400 + i64::from(month <= 2);
    let total = year * 12 + (month - 1) + months;
    let (year, month) = (total.div_euclid(12), total.rem_euclid(12) + 1);
    let leap = (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
    let last = match month {
        2 if leap => 29,
        2 => 28,
        4 | 6 | 9 | 11 => 30,
        _ => 31,
    };
    let day = day.min(last);
    let (y, m) = if month <= 2 { (year - 1, month + 9) } else { (year, month - 3) };
    let era = y.div_euclid(400);
    let yoe = y - era * 400;
    let doy = (153 * m + 2) / 5 + day - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    (era * 146097 + doe - 719468 + 25569) as f64 + time
}

fn year_of_serial(serial: f64) -> i64 {
    let days = serial.floor() as i64 + EXCEL_EPOCH_DAYS;
    civil_year_of_days(days)
}

/// Days from 1970-01-01 to 1899-12-30, Excel's day zero.
const EXCEL_EPOCH_DAYS: i64 = -25_569;

/// Days since 1970-01-01 of a calendar date (Howard Hinnant's algorithm).
fn days_since_epoch(year: i64, month: u32, day: u32) -> i64 {
    let year = if month <= 2 { year - 1 } else { year };
    let era = year.div_euclid(400);
    let year_of_era = year.rem_euclid(400);
    let month_index = (i64::from(month) + 9) % 12;
    let day_of_year = (153 * month_index + 2) / 5 + i64::from(day) - 1;
    let day_of_era = year_of_era * 365 + year_of_era / 4 - year_of_era / 100 + day_of_year;
    era * 146_097 + day_of_era - 719_468
}

fn civil_year_of_days(days: i64) -> i64 {
    let days = days + 719_468;
    let era = days.div_euclid(146_097);
    let day_of_era = days.rem_euclid(146_097);
    let year_of_era =
        (day_of_era - day_of_era / 1_460 + day_of_era / 36_524 - day_of_era / 146_096) / 365;
    let year = year_of_era + era * 400;
    let day_of_year = day_of_era - (365 * year_of_era + year_of_era / 4 - year_of_era / 100);
    let month_index = (5 * day_of_year + 2) / 153;
    let month = if month_index < 10 { month_index + 3 } else { month_index - 9 };
    if month <= 2 { year + 1 } else { year }
}

/// The Excel serial of a calendar date, or None when there is no such day.
fn excel_serial(year: i64, month: u32, day: u32) -> Option<f64> {
    if !(1900..=9999).contains(&year) || !(1..=12).contains(&month) || day == 0 {
        return None;
    }
    // Excel's calendar holds a 29 February 1900 (serial 60), so its days
    // before March of that year stand one lower than the true count: measured,
    // "1900/1/1" writes 1 and "1900/2/28" 59.
    if (year, month, day) == (1900, 2, 29) {
        return Some(60.0);
    }
    let leap = (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
    let days_in_month = match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        _ if leap => 29,
        _ => 28,
    };
    if day > days_in_month {
        return None;
    }
    let early = i64::from(year == 1900 && month <= 2);
    Some((days_since_epoch(year, month, day) - EXCEL_EPOCH_DAYS - early) as f64)
}

/// A two-digit year the way Excel reads one: 00-29 this century, 30-99 last.
fn widened_year(year: i64, digits: usize) -> i64 {
    match digits {
        1 | 2 if year < 30 => year + 2000,
        1 | 2 => year + 1900,
        _ => year,
    }
}

/// The month an English name stands for, whole or in its first three letters.
fn month_named(name: &str) -> Option<u32> {
    const NAMES: [&str; 12] = [
        "january",
        "february",
        "march",
        "april",
        "may",
        "june",
        "july",
        "august",
        "september",
        "october",
        "november",
        "december",
    ];
    let lower = name.to_ascii_lowercase();
    if lower.len() < 3 {
        return None;
    }
    NAMES
        .iter()
        .position(|full| *full == lower || (lower.len() == 3 && full.starts_with(&lower)))
        .map(|index| index as u32 + 1)
}

fn digits_only(text: &str) -> Option<i64> {
    if text.is_empty() || text.len() > 4 || !text.bytes().all(|byte| byte.is_ascii_digit()) {
        return None;
    }
    text.parse().ok()
}

/// A time of day as written -- `13:30`, `1:30 PM`, `1:30:15`, `24:00` -- as a
/// fraction of a day and the format it asks for.
fn written_time(text: &str) -> Option<(f64, &'static str)> {
    let text = text.trim();
    let upper = text.to_ascii_uppercase();
    let (body, meridiem) = if let Some(body) = upper.strip_suffix("AM") {
        (&text[..body.trim_end().len()], Some(false))
    } else if let Some(body) = upper.strip_suffix("PM") {
        (&text[..body.trim_end().len()], Some(true))
    } else {
        (text, None)
    };
    let parts: Vec<&str> = body.split(':').collect();
    if parts.len() < 2 || parts.len() > 3 {
        return None;
    }
    // Two parts whose second has a fraction are minutes and seconds:
    // measured, "10:30.5" is 630.5 seconds and "1:2.5" 62.5, shown mm:ss.0.
    if parts.len() == 2 && meridiem.is_none() {
        if let Some((whole, fraction)) = parts[1].split_once('.') {
            let (minutes, seconds) = (digits_only(parts[0])?, digits_only(whole)?);
            digits_only(fraction)?;
            let fraction: f64 = format!("0.{fraction}").parse().ok()?;
            if seconds > 59 {
                return None;
            }
            return Some(((minutes as f64 * 60.0 + seconds as f64 + fraction) / 86_400.0, "mm:ss.0"));
        }
    }
    let hour = digits_only(parts[0])?;
    let minute = digits_only(parts[1])?;
    // Seconds may carry a fraction: measured, "12:00:00.5" is half a second
    // past noon and "12:00:00.5 PM" the same, shown mm:ss.0.
    let (seconds_text, tenths) = match parts.get(2).and_then(|part| part.split_once('.')) {
        Some((whole, fraction)) => (Some(whole), Some(fraction)),
        _ => (parts.get(2).copied(), None),
    };
    let second = match seconds_text {
        Some(part) => Some(digits_only(part)?),
        None => None,
    };
    let fraction_of_second = match tenths {
        Some(fraction) => {
            digits_only(fraction)?;
            format!("0.{fraction}").parse::<f64>().ok()?
        }
        None => 0.0,
    };
    if minute > 59 || second.is_some_and(|second| second > 59) {
        return None;
    }
    let hour = match meridiem {
        Some(_) if !(1..=12).contains(&hour) => return None,
        Some(true) if hour < 12 => hour + 12,
        Some(false) if hour == 12 => 0,
        _ => hour,
    };
    let fraction = (hour as f64 * 3600.0 + minute as f64 * 60.0 + second.unwrap_or(0) as f64 + fraction_of_second)
        / 86_400.0;
    if tenths.is_some() {
        return Some((fraction, "mm:ss.0"));
    }
    let shown = match (meridiem.is_some(), second.is_some(), hour >= 24) {
        (_, _, true) => "[h]:mm:ss",
        (true, true, _) => "h:mm:ss AM/PM",
        (true, false, _) => "h:mm AM/PM",
        (false, true, _) => "h:mm:ss",
        (false, false, _) => "h:mm",
    };
    Some((fraction, shown))
}

/// A date or a time written with its kanji units.
///
/// Measured on the same machine as the rest: `3月5日` and `12月31日` are this
/// year's, shown `m"月"d"日"`; `2024年3月` and `24年3月` are the first of the
/// month, shown `yyyy"年"m"月"`; `12時30分` is a time shown `h"時"mm"分"` and
/// `1隴弱・陋ｻ繝ｻ驕倩寁Eone shown `h"隴弱・mm"陋ｻ繝ｻss"驕倥・`. `13隴帙�E隴鯉ｽ�E�`, `2隴帙�E0隴鯉ｽ�E�`,
/// `2024陝ｷ・�E�13隴帙�E, `25隴弱・0陋ｻ繝ｻ, `12隴趣�E��E�, `30陋ｻ繝ｻ, `3隴帙�E, `5隴鯉ｽ�E�` and even
/// `2024年3月5日` stay text.
fn written_kanji_moment(text: &str, this_year: i64) -> Option<(f64, &'static str)> {
    let number = |part: &str| -> Option<i64> {
        (!part.is_empty() && part.len() <= 4 && part.bytes().all(|byte| byte.is_ascii_digit()))
            .then(|| part.parse().ok()).flatten()
    };
    if let Some(rest) = text.strip_suffix("日") {
        let (month_text, day_text) = rest.split_once("月")?;
        let (month, day) = (number(month_text)?, number(day_text)?);
        let serial = excel_serial(this_year, u32::try_from(month).ok()?, u32::try_from(day).ok()?)?;
        return Some((serial, r#"m"月"d"日""#));
    }
    if let Some(rest) = text.strip_suffix("月") {
        let (year_text, month_text) = rest.split_once("年")?;
        if !matches!(year_text.len(), 2 | 4) { return None; }
        let year = widened_year(number(year_text)?, year_text.len());
        let serial = excel_serial(year, u32::try_from(number(month_text)?).ok()?, 1)?;
        return Some((serial, r#"yyyy"年"m"月""#));
    }
    if let Some(rest) = text.strip_suffix("秒") {
        let (left, seconds) = rest.rsplit_once("分")?;
        let (hours, minutes) = left.split_once("時")?;
        let (hours, minutes, seconds) = (number(hours)?, number(minutes)?, number(seconds)?);
        if hours > 23 || minutes > 59 || seconds > 59 { return None; }
        let value = (hours * 3600 + minutes * 60 + seconds) as f64 / 86_400.0;
        return Some((value, r#"h"時"mm"分"ss"秒""#));
    }
    None
}

fn written_calendar_date(text: &str, this_year: i64) -> Option<(f64, &'static str)> {
    let text = text.trim();
    // Numeric, with `/` or `-` between the parts.
    let separator = if text.contains('/') {
        '/'
    } else if text.contains('-') {
        '-'
    } else {
        ' '
    };
    if separator != ' ' {
        let parts: Vec<&str> = text.split(separator).map(str::trim).collect();
        let numeric: Option<Vec<(i64, usize)>> = parts
            .iter()
            .map(|part| digits_only(part).map(|value| (value, part.len())))
            .collect();
        if let Some(numeric) = numeric {
            return match numeric.as_slice() {
                [(first, 4), (month, _), (day, _)] => {
                    let serial = excel_serial(*first, *month as u32, *day as u32)?;
                    Some((serial, "m/d/yyyy"))
                }
                [(month, _), (day, _), (year, digits)] => {
                    let year = widened_year(*year, *digits);
                    let serial = excel_serial(year, *month as u32, *day as u32)?;
                    Some((serial, "m/d/yyyy"))
                }
                // Measured: `3/2024` and `3-2024` are March 2024, shown `mmm-yy`.
                [(month, _), (year, 4)] => {
                    let serial = excel_serial(*year, *month as u32, 1)?;
                    Some((serial, "mmm-yy"))
                }
                // A day of this year where the second number can be one,
                // else the month of a two-digit year: measured, `12/31` is
                // this year's, `1/32` January 1932, `2/29` (2026) February
                // 2029, `1/0` January 2000, and `1/100` stays text.
                [(month, _), (day, digits)] => match excel_serial(this_year, *month as u32, *day as u32) {
                    Some(serial) => Some((serial, "d-mmm")),
                    None if *digits <= 2 => {
                        let serial = excel_serial(widened_year(*day, *digits), *month as u32, 1)?;
                        Some((serial, "mmm-yy"))
                    }
                    None => None,
                },
                _ => None,
            };
        }
        // `5-Jan`, `5-Jan-24`, `Feb-30`, `Mar/24`.
        if separator == '-' || separator == '/' {
            return match parts.as_slice() {
                [first, second] => {
                    // Day and month, or month and day, or month and year.
                    if let (Some(day), Some(month)) = (digits_only(first), month_named(second)) {
                        let serial = excel_serial(this_year, month, day as u32)?;
                        return Some((serial, "d-mmm"));
                    }
                    // Measured: `Mar-24` is the 24th of March this year, and
                    // `Mar-32` March 1932.
                    let month = month_named(first)?;
                    let number = digits_only(second)?;
                    if let Some(serial) = excel_serial(this_year, month, number as u32) {
                        return Some((serial, "d-mmm"));
                    }
                    let year = widened_year(number, second.len());
                    let serial = excel_serial(year, month, 1)?;
                    Some((serial, "mmm-yy"))
                }
                [day, month, year] => {
                    let month = month_named(month)?;
                    let day = digits_only(day)?;
                    let year = widened_year(digits_only(year)?, year.len());
                    let serial = excel_serial(year, month, day as u32)?;
                    Some((serial, "d-mmm-yy"))
                }
                _ => None,
            };
        }
        return None;
    }
    // `January 5, 2024` and `Feb 30`.
    let words: Vec<&str> = text.split_whitespace().collect();
    match words.as_slice() {
        [month, day, year] if month_named(month).is_some() => {
            let month = month_named(month)?;
            let day = digits_only(day.strip_suffix(',')?)?;
            let year = widened_year(digits_only(year)?, year.len());
            let serial = excel_serial(year, month, day as u32)?;
            Some((serial, "d-mmm-yy"))
        }
        // `5 Mar 24` reads as `5-Mar-24` does: measured, 3/5/2024 shown
        // d-mmm-yy.
        [day, month, year] if digits_only(day).is_some() && month_named(month).is_some() => {
            let year = widened_year(digits_only(year)?, year.len());
            let serial = excel_serial(year, month_named(month)?, digits_only(day)? as u32)?;
            Some((serial, "d-mmm-yy"))
        }
        // `5 Jan` reads as `5-Jan` does: measured, the 5th of January of this
        // year, shown d-mmm.
        [day, month] if digits_only(day).is_some() && month_named(month).is_some() => {
            let serial = excel_serial(this_year, month_named(month)?, digits_only(day)? as u32)?;
            Some((serial, "d-mmm"))
        }
        [month, number] => {
            let month = month_named(month)?;
            let digits = number.len();
            let number = digits_only(number)?;
            match excel_serial(this_year, month, number as u32) {
                Some(serial) => Some((serial, "d-mmm")),
                None => {
                    // Measured: "Mar 2024" is March 2024, not 3924.
                    let year = widened_year(number, digits);
                    let serial = excel_serial(year, month, 1)?;
                    Some((serial, "mmm-yy"))
                }
            }
        }
        _ => None,
    }
}

/// A written moment: a date, a time, or a date followed by a time.
///
/// A time alone is a Double under a time format, as Excel keeps it. A date
/// with a time is shown `m/d/yyyy h:mm`; a date with a time whose hour runs
/// past 23 -- measured, `1/5/2024 25:00` -- is a plain number under General.
fn written_moment(written: &str, this_year: i64) -> Option<(CellValue, Option<&'static str>)> {
    let trimmed = written.trim();
    if let Some((number, shown)) = written_kanji_moment(trimmed, this_year) {
        return Some((CellValue::Number(number), Some(shown)));
    }
    if let Some((fraction, shown)) = written_time(trimmed) {
        return Some((CellValue::Number(fraction), Some(shown)));
    }
    // One part running over its sixty is still read, as that many minutes or
    // seconds, and the cell stays General: measured, `10:61` is 11:01,
    // `10:100` 11:40 and `10:30:61` 10:31:01 -- while `10:60:60`, `24:60`
    // and `1:61 PM` stay text.
    let parts: Vec<&str> = trimmed.split(':').collect();
    if (2..=3).contains(&parts.len())
        && parts.iter().all(|part| !part.is_empty() && part.bytes().all(|b| b.is_ascii_digit()))
    {
        let read: Vec<u64> = parts.iter().filter_map(|part| part.parse().ok()).collect();
        let over = read[1..].iter().filter(|part| **part >= 60).count();
        if read.len() == parts.len() && read[0] < 24 && over == 1 {
            let seconds = read[0] * 3600 + read[1] * 60 + read.get(2).copied().unwrap_or(0);
            return Some((CellValue::Number(seconds as f64 / 86_400.0), None));
        }
    }
    if let Some((serial, shown)) = written_calendar_date(trimmed, this_year) {
        return Some((CellValue::Number(serial), Some(shown)));
    }
    // A date and then a time: the time is the tail from the last one or two
    // words, whichever reads as one.
    let words: Vec<&str> = trimmed.split_whitespace().collect();
    for take in [2usize, 1] {
        if words.len() <= take {
            continue;
        }
        let (head, tail) = words.split_at(words.len() - take);
        let Some((fraction, _)) = written_time(&tail.join(" ")) else {
            continue;
        };
        let Some((serial, _)) = written_calendar_date(&head.join(" "), this_year) else {
            continue;
        };
        let value = CellValue::Number(serial + fraction);
        return Some(if fraction >= 1.0 {
            (value, None)
        } else {
            (value, Some("m/d/yyyy h:mm"))
        });
    }
    None
}

/// A sum of money as written: `$3`, `$1,234.5`, `-$3`, `$-3` and `($3)` are
/// numbers under a dollar format, with two decimals when the writing had any;
/// `3$` is text. Measured under a Windows whose currency is the dollar.
fn written_currency(written: &str) -> Option<(CellValue, Option<&'static str>)> {
    let trimmed = written.trim();
    let (body, bracketed) = match trimmed.strip_prefix('(').and_then(|rest| rest.strip_suffix(')'))
    {
        Some(inside) => (inside.trim(), true),
        None => (trimmed, false),
    };
    let (negative, body) = match body.strip_prefix('-') {
        Some(rest) => (true, rest.trim_start()),
        None => (false, body),
    };
    let body = body.strip_prefix('$')?.trim_start();
    let (negative, body) = match body.strip_prefix('-') {
        Some(rest) if !negative => (true, rest.trim_start()),
        Some(_) => return None,
        None => (negative, body),
    };
    if body.starts_with(['+', '-']) {
        return None;
    }
    let (number, _) = grouped_number(body)?;
    let number = if negative || bracketed { -number } else { number };
    let shown = if body.contains('.') {
        "$#,##0.00_);[Red]($#,##0.00)"
    } else {
        "$#,##0_);[Red]($#,##0)"
    };
    Some((CellValue::Number(number), Some(shown)))
}

/// What Excel makes of a written string: the value, and the way of showing it
/// that the writing itself asks for.
///
/// Some ways of writing a number carry a format with them. Asked of Excel by
/// writing each into a fresh cell and reading `.Value` and `.NumberFormat`
/// back:
///
/// - a per cent is the number over a hundred, shown as `0%` where it was
///   written without a point and `0.00%` where it was written with one,
///   however many decimals followed it — `1.2%`, `1.234%` and `1.23456%` all
///   ask for `0.00%`. The sign may lead as well as follow: `%5` is 0.05.
/// - an exponent is read and shown as `0.00E+00`, whatever its mantissa.
///   Only `E` — `1D3` stays text, though VBA takes `D` in a literal — and the
///   exponent must be whole, so `1E3.5` stays text too.
/// - a fraction needs a whole part and ONE space: `1 1/2` is 1.5 shown as
///   `# ?/?`, `1  1/2` with two spaces stays text, and `3/4` on its own is a
///   date rather than a fraction, so it is left alone here. The width follows
///   the denominator and stops at two: `1/16`, `1/100` and `1/1000` all ask
///   for `# ??/??`.
///
/// The format is only ever ASKED for. Excel gives it to the cell only where
/// the cell is still General — writing `50%` into a cell already showing
/// `0.000` leaves `0.000` there — and that is decided where the cell is
/// written, not here.
fn typed_from_written(written: &str, this_year: i64) -> (CellValue, Option<&'static str>) {
    // An apostrophe is the instruction "leave this alone", and is not kept.
    if let Some(rest) = written.strip_prefix(APOSTROPHE) {
        return (CellValue::String(rest.to_string()), None);
    }
    // A written error word IS that error, and is one of the few things read
    // without trimming first -- see `written_error`.
    if let Some(named) = written_error(written) {
        return (CellValue::Error(named.to_string()), None);
    }
    if let Some(read) = written_percent(written) {
        return read;
    }
    if let Some(read) = written_exponent(written) {
        return read;
    }
    if let Some(read) = written_fraction(written) {
        return read;
    }
    if let Some(read) = written_currency(written) {
        return read;
    }
    if let Some(read) = written_moment(written, this_year) {
        return read;
    }
    let trimmed = written.trim();
    // A logical is its word and nothing more: measured, "TRUE " with a space
    // after it stays text.
    if written.eq_ignore_ascii_case("true") {
        return (CellValue::Boolean(true), None);
    }
    if written.eq_ignore_ascii_case("false") {
        return (CellValue::Boolean(false), None);
    }
    // A number in brackets is a negative one, the way an accountant writes it.
    let (body, bracketed) = match trimmed.strip_prefix('(').and_then(|rest| rest.strip_suffix(')'))
    {
        Some(inside) => (inside.trim(), true),
        None => (trimmed, false),
    };
    // Only plain decimal digits with an optional sign: `1e3` and the rest all
    // carry a format with them, so they are not read here.
    let readable = !body.is_empty()
        && body
            .chars()
            .enumerate()
            .all(|(at, one)| one.is_ascii_digit() || one == '.' || (at == 0 && matches!(one, '+' | '-')))
        && body.chars().filter(|one| *one == '.').count() <= 1
        && body.chars().any(|one| one.is_ascii_digit());
    if let Some((number, grouped)) = grouped_number(body) {
        // Brackets keep the separated form: `(1,234)` is -1234 shown as
        // `#,##0`, where a plain `(5)` is -5 and stays General.
        return (
            CellValue::Number(if bracketed { -number } else { number }),
            grouped.then(|| grouped_format(body)),
        );
    }
    (CellValue::String(written.to_string()), None)
}

/// Whether a written string is a plain decimal number, which is all any of the
/// three readings below accepts around their own punctuation.
fn plain_number(body: &str) -> Option<f64> {
    let readable = !body.is_empty()
        && body.chars().enumerate().all(|(at, one)| {
            one.is_ascii_digit() || one == '.' || (at == 0 && matches!(one, '+' | '-'))
        })
        && body.chars().filter(|one| *one == '.').count() <= 1
        && body.chars().any(|one| one.is_ascii_digit());
    if !readable {
        return None;
    }
    // What is typed past the fifteenth figure is dropped, not rounded:
    // measured, "1234567890123456789012345" is 1.23456789012345E+24.
    let mut seen = 0usize;
    let kept: String = body
        .chars()
        .map(|one| {
            if !one.is_ascii_digit() {
                return one;
            }
            if seen == 0 && one == '0' {
                return one;
            }
            seen += 1;
            if seen > 15 { '0' } else { one }
        })
        .collect();
    kept.parse::<f64>().ok()
}

/// A written decimal number that may have its thousands separated.
///
/// Measured by writing each into a cell: a group after the first must carry at
/// least three digits, so `1,234`, `12,345`, `1,234,567` and even `1,2345` are
/// read, while `1,23`, `12,34` and `1,234,56` stay text -- as do `,123` and
/// `1,`, which leave a group empty. The second value says whether any
/// separator was there, since that is what the cell is then shown with.
///
/// English and Japanese separate thousands the same way, and those are the two
/// this is built for, so there is nothing here that waits on a locale.
fn grouped_number(body: &str) -> Option<(f64, bool)> {
    if !body.contains(',') {
        return plain_number(body).map(|number| (number, false));
    }
    let (sign, digits) = match body.strip_prefix(['+', '-']) {
        Some(rest) => (&body[..1], rest),
        None => ("", body),
    };
    let groups: Vec<&str> = digits.split(',').collect();
    if groups.len() < 2 || groups.iter().any(|group| group.is_empty()) {
        return None;
    }
    // Only the last group may carry the decimal point, and every group after
    // the first needs three digits in front of it.
    for (at, group) in groups.iter().enumerate() {
        let whole = group.split('.').next().unwrap_or(group);
        if at > 0 && whole.len() < 3 {
            return None;
        }
        if at + 1 < groups.len() && group.contains('.') {
            return None;
        }
    }
    let joined = format!("{sign}{}", groups.concat());
    plain_number(&joined).map(|number| (number, true))
}

/// How a cell shows a number whose thousands were written out: measured as
/// `#,##0` where nothing followed a point and `#,##0.00` where anything did,
/// however many digits followed it.
fn grouped_format(body: &str) -> &'static str {
    if body.contains('.') {
        "#,##0.00"
    } else {
        "#,##0"
    }
}

fn written_percent(written: &str) -> Option<(CellValue, Option<&'static str>)> {
    let trimmed = written.trim();
    let body = match trimmed.strip_suffix('%') {
        Some(body) => body,
        None => trimmed.strip_prefix('%')?,
    };
    let body = body.trim();
    let (number, _) = grouped_number(body)?;
    // Written with a point, shown with two decimals; written without one,
    // shown with none. How many decimals were written makes no difference, and
    // neither do separated thousands: `1,234%` is 12.34 shown as `0%`.
    let shown = if body.contains('.') { "0.00%" } else { "0%" };
    Some((CellValue::Number(number / 100.0), Some(shown)))
}

fn written_exponent(written: &str) -> Option<(CellValue, Option<&'static str>)> {
    let trimmed = written.trim();
    let at = trimmed.find(['e', 'E'])?;
    let (mantissa, rest) = trimmed.split_at(at);
    let power = &rest[1..];
    plain_number(mantissa)?;
    // The power must be a whole number, with a sign at most.
    let digits = power.strip_prefix(['+', '-']).unwrap_or(power);
    if digits.is_empty() || !digits.chars().all(|one| one.is_ascii_digit()) {
        return None;
    }
    // A power past what a double holds is no number: measured, "1e400"
    // stays text.
    let number = trimmed.parse::<f64>().ok().filter(|number| number.is_finite())?;
    Some((CellValue::Number(number), Some("0.00E+00")))
}

fn written_fraction(written: &str) -> Option<(CellValue, Option<&'static str>)> {
    let trimmed = written.trim();
    let (whole, rest) = trimmed.split_once(' ')?;
    // One space, and one only: `1  1/2` is text.
    let (numerator, denominator) = rest.split_once('/')?;
    if numerator.is_empty() || numerator.starts_with(['+', '-']) {
        return None;
    }
    let whole = plain_number(whole)?;
    if whole.fract() != 0.0 {
        return None;
    }
    let numerator = plain_number(numerator)?;
    let denominator = plain_number(denominator)?;
    if numerator.fract() != 0.0 || denominator.fract() != 0.0 || denominator == 0.0 {
        return None;
    }
    let part = numerator / denominator;
    let number = if whole.is_sign_negative() || written.trim_start().starts_with('-') {
        whole - part
    } else {
        whole + part
    };
    // The width follows the denominator, and stops at two.
    let shown = if denominator < 10.0 {
        "# ?/?"
    } else {
        "# ??/??"
    };
    Some((CellValue::Number(number), Some(shown)))
}

/// One side of a paste that combines rather than replaces.
enum Operand {
    /// A number. A blank cell is one of these, worth nothing: asked of Excel,
    /// multiplying 100 by a blank answers 0 and dividing by one answers
    /// `#DIV/0!`.
    Number(f64),
    /// A formula, which goes into the answer in brackets.
    Formula(Vec<u16>),
    /// Text, a Boolean, an error — anything the sum cannot take. Excel leaves
    /// the destination exactly as it was rather than making something of it.
    Other,
}

/// What the two sides came to.
enum Combined {
    Value(CellValue),
    Formula(Vec<u16>),
}

impl Operand {
    fn of(value: &CellValue) -> Self {
        match value {
            CellValue::Empty => Self::Number(0.0),
            CellValue::Number(number) => Self::Number(*number),
            _ => Self::Other,
        }
    }

    /// How it is written into a formula: a formula in brackets, a number bare.
    fn written(&self) -> Option<Vec<u16>> {
        match self {
            Self::Number(number) => Some(format_number_plainly(*number).encode_utf16().collect()),
            Self::Formula(formula) => {
                let mut body = formula.as_slice();
                while body.first() == Some(&(b'=' as u16)) { body = &body[1..]; }
                Some(std::iter::once(b'(' as u16).chain(body.iter().copied()).chain([b')' as u16]).collect())
            }
            Self::Other => None,
        }
    }

    fn combined(&self, operation: char, source: &Self) -> Option<Combined> {
        if let (Self::Number(left), Self::Number(right)) = (self, source) {
            let answer = match operation {
                '+' => left + right,
                '-' => left - right,
                '*' => left * right,
                '/' if *right == 0.0 => {
                    return Some(Combined::Value(CellValue::Error("#DIV/0!".to_string())))
                }
                '/' => left / right,
                _ => return None,
            };
            return Some(Combined::Value(CellValue::Number(answer)));
        }
        let (mut left, right) = (self.written()?, source.written()?);
        left.push(operation as u16);
        left.extend(right);
        Some(Combined::Formula(left))
    }
}

/// A number as a formula spells it, with no trailing nothing.
fn format_number_plainly(number: f64) -> String {
    if number.fract() == 0.0 && number.abs() < 1e15 {
        format!("{number:.0}")
    } else {
        number.to_string()
    }
}

/// What one cell is left holding by an assignment.
enum CellInput {
    Formula(String),
    /// A value, and the way of showing it the writing asked for, if any.
    Constant(CellValue, Option<&'static str>),
}

/// What was assigned, as the block of cells Excel treats it as.
///
/// A single value is one cell. An array is its own shape, and a
/// one-dimensional array is a single ROW — which is why `Array(1, 2, 3)`
/// written down a column leaves the FIRST entry filled down it rather than the
/// three entries stacked.
fn range_value2_input(value: Value) -> Value {
    match value {
        Value::Date(serial) => Value::Double(serial),
        Value::Currency(units) => Value::Double(units as f64 / 10_000.0),
        Value::Array(mut array) => {
            array.values = array.values.into_iter().map(range_value2_input).collect();
            Value::Array(array)
        }
        value => value,
    }
}

struct InputBlock {
    rows: usize,
    columns: usize,
    values: Vec<Value>,
    object_broadcast: bool,
}

impl InputBlock {
    fn of(value: Value, operation: &str) -> Result<Self, String> {
        match value {
            Value::Array(array) => {
                let (rows, columns) = match array.dimensions.as_slice() {
                    [across] => (1, across.length),
                    [down, across] => (down.length, across.length),
                    dimensions => {
                        return Err(format!(
                            "{operation} cannot take a {}-dimensional array",
                            dimensions.len()
                        ))
                    }
                };
                Ok(Self {
                    rows,
                    columns,
                    values: array.values,
                    object_broadcast: false,
                })
            }
            value => Ok(Self {
                rows: 1,
                columns: 1,
                values: vec![value],
                object_broadcast: false,
            }),
        }
    }

    /// What the block holds there, or nothing where it does not reach.
    fn at(&self, row: usize, column: usize) -> Option<Value> {
        if row >= self.rows || column >= self.columns {
            return None;
        }
        self.values.get(row * self.columns + column).cloned()
    }
}

/// How much of a string a cell keeps.
///
/// It CUTS at the first NUL. Asked of Excel, `Range("A1").Value = "a" &
/// Chr(0) & "b"` leaves the cell holding `a`, and a value that is nothing but
/// NULs leaves it Empty. Every other control character goes in whole -- Chr(1),
/// Chr(9), Chr(10) and Chr(12) each leave a cell one character long, so it is
/// the NUL alone that ends the text.
fn text_a_cell_keeps(written: &str) -> &str {
    match written.find('\0') {
        Some(cut) => &written[..cut],
        None => written,
    }
}

/// A formula narrowed for entry with its table references put back as they
/// were written: a table's name and what its brackets hold are matched with
/// width kept. Measured, "=SUM(TB" & ChrW(&HFF21) & "[Qty])" reaches a table
/// named "Tb" & ChrW(&HFF41) while "=SUM(" & ChrW(&HFF54) & ChrW(&HFF42) &
/// ChrW(&HFF41) & "[Amt])" is 1004, though ChrW(&HFF33) & ChrW(&HFF35) &
/// ChrW(&HFF2D) is read as SUM.
fn keep_table_references_wide(written: &str, narrowed: &str) -> String {
    let original: Vec<char> = written.chars().collect();
    let mut out: Vec<char> = narrowed.chars().collect();
    if original.len() != out.len() {
        return narrowed.to_string();
    }
    let mut quoted = false;
    let mut depth = 0usize;
    let mut index = 0;
    while index < out.len() {
        let one = out[index];
        if one == '"' && depth == 0 {
            quoted = !quoted;
        } else if !quoted && one == '[' {
            if depth == 0 {
                // The table's name, if one stands straight before it.
                let mut back = index;
                while back > 0 && (out[back - 1].is_alphanumeric() || matches!(out[back - 1], '_' | '.')) {
                    back -= 1;
                    out[back] = original[back];
                }
            }
            depth += 1;
        } else if !quoted && one == ']' && depth > 0 {
            depth -= 1;
        } else if depth > 0 {
            out[index] = original[index];
        }
        index += 1;
    }
    out.into_iter().collect()
}

/// Read an assigned value the way Excel reads it, whichever door it came
/// through.
///
/// A string beginning with `=` and carrying something after it is a formula;
/// everything else — including `"="` on its own, which Excel leaves as the
/// text `=` — is read the way typing it would be.
fn formula_has_invalid_reference_argument(source: &str) -> bool {
    let Ok(expr) = oxicells_calc::parse(source) else { return false; };
    let mut invalid = false;
    expr.visit(&mut |node| {
        if let oxicells_calc::Expr::Function { name, args } = node {
            let index = match name.as_str() {
                "ROW" | "COLUMN" | "ISFORMULA" | "AREAS" | "FORMULATEXT" | "PHONETIC" => Some(0),
                "CELL" if args.len() == 2 => Some(1),
                _ => None,
            };
            if index.and_then(|at| args.get(at)).is_some_and(|arg| !arg.can_return_reference()) { invalid = true; }
        }
    });
    invalid
}

fn cell_input(value: Value, this_year: i64) -> Result<CellInput, String> {
    // Full-width letters, digits and signs are read as their narrow selves,
    // and kept as written when that reading is still text. Measured: `繝ｻ謁E���E��E�謚ｵ・�E�莨・    // is 123, `繝ｻ蛹・�E��E�繝ｻ 5%, `繝ｻ闌ｨ・�E�謁E���E��E�謦�E�・�E�謦�E�・�E�闕�E-100, `繝ｻ繝ｻ・�E�繝ｻ・�E�魁E��ｽ�E�髮�E�・�E�繝ｻ False, `繝ｻ謁E���E��E�螟ｲ・�E�髮�E�・�E�謦�E�・�E�螟ｲ・�E�雋ｻ・�E�謠・a
    // time and `繝ｻ譎｢・�E�謁E���E��E�蜈ｷ・�E�逍�Ethe formula `=1+1`, while `繝ｻ謁E���E��E�謚ｵ・�E�轣倥・` and `繝ｻ繝ｻ・�E�・�E�繝ｻ謫�E�・�E�・�E�`
    // stay the text they were.
    if let Value::String(written) = &value {
        if written.chars().any(|one| matches!(one, '\u{FF01}'..='\u{FF5E}' | '\u{3000}')) {
            // Inside a formula's quoted text the letters stay as written:
            // measured, `="A"="繝ｻ繝ｻ` keeps its 繝ｻ繝ｻ and is FALSE.
            let formula = matches!(written.chars().next(), Some('=' | '\u{ff1d}'));
            let mut quoted = false;
            let narrowed: String = written
                .chars()
                .map(|one| {
                    let narrow = match one {
                        '\u{FF01}'..='\u{FF5E}' => char::from_u32(one as u32 - 0xFEE0).unwrap_or(one),
                        '\u{3000}' => ' ',
                        _ => one,
                    };
                    if formula && narrow == '"' {
                        quoted = !quoted;
                        return narrow;
                    }
                    if quoted { one } else { narrow }
                })
                .collect();
            let narrowed = if formula { keep_table_references_wide(written, &narrowed) } else { narrowed };
            if narrowed.starts_with('=') && narrowed.len() > 1 && !formula_is_malformed(&narrowed[1..]) && !formula_has_invalid_reference_argument(&narrowed[1..]) {
                return Ok(CellInput::Formula(narrowed));
            }
            if !narrowed.starts_with(APOSTROPHE) && !narrowed.starts_with('=') {
                let (cell, shown) = typed_from_written(text_a_cell_keeps(&narrowed), this_year);
                if !matches!(cell, CellValue::String(_) | CellValue::Utf16(_) | CellValue::Error(_) | CellValue::Empty) {
                    return Ok(CellInput::Constant(cell, shown));
                }
            }
        }
    }
    if let Value::String(written) = &value {
        if let Some(rest) = written.strip_prefix('=') {
            if !rest.is_empty() {
                // Measured: `="f`, `=1+` and `=nosuchfn(` are all refused with
                // 1004 -- a formula that cannot be read is not stored -- where
                // `=nosuchfn()` is stored and works out to #NAME?.
                if formula_is_malformed(rest) || formula_has_invalid_reference_argument(rest) {
                    return Err(format!("the formula {written:?} cannot be read"));
                }
                return Ok(CellInput::Formula(written.clone()));
            }
        }
    }
    if let Value::String(written) = &value {
        let written = text_a_cell_keeps(written);
        if !written.is_empty() {
            let (cell, shown) = typed_from_written(written, this_year);
            return Ok(CellInput::Constant(cell, shown));
        }
        return Ok(CellInput::Constant(CellValue::Empty, None));
    }
    // A DATE dresses the cell it lands in, and the dress depends on the
    // moment. Asked of Excel, after `Range("A1").Value = #1/2/2003#` the cell
    // reads `m/d/yyyy`; a moment carrying a time as well reads
    // `m/d/yyyy h:mm`; and a time alone reads `h:mm:ss AM/PM`.
    //
    // The last is the one that matters twice over: a cell under a time-only
    // format hands its value back as a DOUBLE, not a Date, so writing a Date
    // and reading it again does not always return one. A plain number gets no
    // dress at all and stays General.
    if let Value::Date(serial) = value {
        let shown = if serial < 1.0 {
            "h:mm:ss AM/PM"
        } else if serial.fract() == 0.0 {
            "m/d/yyyy"
        } else {
            "m/d/yyyy h:mm"
        };
        return to_cell_value(value).map(|cell| CellInput::Constant(cell, Some(shown)));
    }
    // A Currency lands as money: measured, `Range("A1").Value =
    // CCur(12.3456)` holds 12.35, reads back a Currency and wears
    // `$#,##0.00_);($#,##0.00)` -- over General and over a percent, while a
    // cell already showing `0.000` keeps that and holds 1.23 for 1.23456.
    if let Value::Currency(units) = value {
        let cents = (units as f64 / 100.0).round_ties_even();
        return Ok(CellInput::Constant(CellValue::Number(cents / 100.0), Some(MONEY_FORMAT)));
    }
    to_cell_value(value).map(|cell| CellInput::Constant(cell, None))
}


fn exact_input_decimal(text: &str) -> Result<oxivba_core::decimal::Dec, String> {
    let (negative, digits) = text.strip_prefix('-').map_or((false, text), |rest| (true, rest));
    let (whole, fraction) = digits.split_once('.').unwrap_or((digits, ""));
    if whole.is_empty() || !whole.bytes().all(|b| b.is_ascii_digit())
        || !fraction.bytes().all(|b| b.is_ascii_digit())
        || (digits.contains('.') && fraction.is_empty()) {
        return Err("expected a finite decimal string".into());
    }
    let fraction = fraction.trim_end_matches('0');
    if fraction.len() > 28 { return Err("decimal scale exceeds 28".into()); }
    let magnitude = format!("{whole}{fraction}").parse::<u128>()
        .map_err(|_| "decimal magnitude is out of range".to_string())?;
    if magnitude > (1u128 << 96) - 1 { return Err("decimal magnitude exceeds 96 bits".into()); }
    Ok(oxivba_core::decimal::Dec {
        negative: negative && magnitude != 0,
        magnitude,
        scale: fraction.len() as u8,
    })
}

fn decode_typed_scalar(input: &serde_json::Value) -> Result<oxivba_core::Value, String> {
    use oxivba_core::Value;
    let object = input.as_object().ok_or("typed scalar must be an object")?;
    if object.keys().any(|key| key != "type" && key != "value") {
        return Err("unknown typed scalar field".into());
    }
    let tag = object.get("type").and_then(|v| v.as_str()).ok_or("typed scalar has no type")?;
    let unit = match tag {
        "empty" => Some(Value::Empty),
        "missing" => Some(Value::Missing),
        "null" => Some(Value::Null),
        "nothing" => Some(Value::Nothing),
        "null_string" => Some(Value::NullString),
        _ => None,
    };
    if let Some(value) = unit {
        if object.contains_key("value") { return Err("unit scalar has an unexpected value".into()); }
        return Ok(value);
    }
    let payload = object.get("value").ok_or("typed scalar has no value")?;
    let integral = || payload.as_i64().ok_or_else(|| "expected an exact integral payload".to_string());
    let decimal = || payload.as_str().ok_or_else(|| "expected a decimal string".to_string())
        .and_then(exact_input_decimal);
    let finite = || payload.as_f64().filter(|v| v.is_finite())
        .ok_or_else(|| "expected a finite numeric payload".to_string());
    match tag {
        "boolean" => payload.as_bool().map(Value::Boolean).ok_or_else(|| "expected a boolean".into()),
        "byte" => u8::try_from(integral()?).map(Value::Byte).map_err(|_| "Byte is out of range".into()),
        "integer" => i16::try_from(integral()?).map(Value::Int16).map_err(|_| "Integer is out of range".into()),
        "long" => i32::try_from(integral()?).map(|v| Value::Integer(i64::from(v)))
            .map_err(|_| "Long is out of range".into()),
        "long_long" => payload.as_str().ok_or_else(|| "LongLong requires an exact decimal string".to_string())?
            .parse::<i64>().map(Value::LongLong).map_err(|_| "LongLong is out of range".into()),
        "single" => {
            let value = finite()? as f32;
            if !value.is_finite() { return Err("Single is out of range".into()); }
            Ok(Value::Single(value))
        }
        "double" => finite().map(Value::Double),
        "date" => finite().map(Value::Date),
        "currency" => {
            let value = decimal()?;
            if value.scale > 4 { return Err("Currency scale exceeds 4".into()); }
            let units = i128::try_from(value.magnitude).map_err(|_| "Currency is out of range".to_string())?
                * 10i128.pow(u32::from(4 - value.scale));
            let units = if value.negative { -units } else { units };
            i64::try_from(units).map(Value::Currency).map_err(|_| "Currency is out of range".into())
        }
        "decimal" => decimal().map(Value::Decimal),
        "error" => i32::try_from(integral()?).map(|v| Value::Error(i64::from(v)))
            .map_err(|_| "Error code is out of range".into()),
        "string" => payload.as_str().map(|v| Value::String(v.into()))
            .ok_or_else(|| "expected a string".into()),
        "bstr" => {
            let bytes = payload.as_array().ok_or("expected BSTR bytes")?.iter()
                .map(|v| v.as_u64().and_then(|n| u8::try_from(n).ok())
                    .ok_or_else(|| "invalid BSTR byte".to_string()))
                .collect::<Result<Vec<_>, _>>()?;
            Ok(Value::from_bstr_bytes(bytes))
        }
        "utf16" => {
            let units = payload.as_array().ok_or("expected UTF-16 units")?.iter()
                .map(|v| v.as_u64().and_then(|n| u16::try_from(n).ok())
                     .ok_or_else(|| "invalid UTF-16 unit".to_string()))
                .collect::<Result<Vec<_>, _>>()?;
            Ok(Value::from_utf16(units))
        }
        _ => Err(format!("unsupported typed scalar {tag}")),
    }
}

#[derive(Deserialize)]
#[serde(untagged)]
enum InputValue {
    Null(()),
    Boolean(bool),
    Number(f64),
    String(String),
    Typed(serde_json::Value),
}

impl TryFrom<InputValue> for Value {
    type Error = String;

    fn try_from(value: InputValue) -> Result<Self, String> {
        Ok(match value {
            InputValue::Null(()) => Value::Null,
            InputValue::Boolean(value) => Value::Boolean(value),
            InputValue::Number(value)
                if value.fract() == 0.0 && value >= f64::from(i32::MIN) && value <= f64::from(i32::MAX) =>
            {
                Value::Integer(value as i64)
            }
            InputValue::Number(value) => Value::Double(value),
            InputValue::String(value) => Value::String(value),
            InputValue::Typed(value) => return decode_typed_scalar(&value),
        })
    }
}


fn decode_vba_input_scalar_descriptor(value: &JsValue, tag: &str) -> Result<Value, JsError> {
    let invalid = |message: &str| JsError::new(&format!("invalid VBA argument: {message}"));
    let descriptor = if matches!(tag, "empty" | "missing" | "null" | "nothing" | "null_string") {
        if js_sys::Object::keys(&js_sys::Object::from(value.clone())).length() != 1 {
            return Err(invalid("unit scalar has an unexpected value"));
        }
        serde_json::json!({"type": tag})
    } else {
        let payload = vba_input_property(value, "value")?;
        let payload = match tag {
            "boolean" => serde_json::Value::Bool(payload.as_bool()
                .ok_or_else(|| invalid("expected a boolean"))?),
            "byte" | "integer" | "long" | "error" => {
                let number = payload.as_f64().filter(|value| value.is_finite() && value.fract() == 0.0
                    && *value >= f64::from(i32::MIN) && *value <= f64::from(i32::MAX))
                    .ok_or_else(|| invalid("expected an in-range integral payload"))?;
                serde_json::Value::from(number as i64)
            }
            "long_long" | "currency" | "decimal" => serde_json::Value::String(payload.as_string()
                .ok_or_else(|| invalid("expected an exact decimal string"))?),
            "bstr" => {
                if !js_sys::Array::is_array(&payload) { return Err(invalid("expected BSTR bytes")); }
                let bytes = js_sys::Array::from(&payload).iter().map(|byte|
                    byte.as_f64().filter(|v| v.is_finite() && v.fract() == 0.0 && *v >= 0.0 && *v <= 255.0)
                        .map(|v| serde_json::Value::from(v as u8))
                        .ok_or_else(|| invalid("invalid BSTR byte"))
                ).collect::<Result<Vec<_>, _>>()?;
                serde_json::Value::Array(bytes)
            }
            "utf16" => {
                if !js_sys::Array::is_array(&payload) { return Err(invalid("expected UTF-16 units")); }
                let units = js_sys::Array::from(&payload).iter().map(|unit|
                    unit.as_f64().filter(|value| value.is_finite() && value.fract() == 0.0
                        && *value >= 0.0 && *value <= 65535.0)
                        .map(|value| serde_json::Value::from(value as u16))
                        .ok_or_else(|| invalid("invalid UTF-16 unit"))
                ).collect::<Result<Vec<_>, _>>()?;
                serde_json::Value::Array(units)
            }
            _ => return Err(invalid("unsupported typed scalar")),
        };
        serde_json::json!({"type": tag, "value": payload})
    };
    decode_typed_scalar(&descriptor).map_err(|message| invalid(&message))
}

struct VbaInputArraySchema {
    dimensions: Vec<ArrayDimension>,
    element_type: String,
    element_default: Value,
    resizable: bool,
}

fn decode_vba_input_array_schema(
    metadata: &serde_json::Value,
    value_count: usize,
) -> Result<VbaInputArraySchema, String> {
    let object = metadata.as_object().ok_or("array metadata must be an object")?;
    if object.keys().any(|key| !matches!(key.as_str(), "dimensions" | "element_type" | "resizable")) {
        return Err("unknown array metadata field".into());
    }
    let kind = object.get("element_type").and_then(|value| value.as_str())
        .ok_or("array has no element type")?;
    let element_default = match kind {
        "variant" => Value::Empty,
        "boolean" => Value::Boolean(false),
        "byte" => Value::Byte(0),
        "integer" => Value::Int16(0),
        "long" => Value::Integer(0),
        "long_long" => Value::LongLong(0),
        "single" => Value::Single(0.0),
        "double" => Value::Double(0.0),
        "date" => Value::Date(0.0),
        "currency" => Value::Currency(0),
        "decimal" => return Err("Excel Automation does not accept Decimal element arrays; use a Variant array".into()),
        "error" => Value::Error(0),
        "string" => Value::NullString,
        "object" => Value::Nothing,
        _ => return Err(format!("unsupported array element type {kind}")),
    };
    let resizable = object.get("resizable").map_or(Ok(true), |value|
        value.as_bool().ok_or("array resizable must be boolean"))?;
    let bounds = object.get("dimensions").and_then(|value| value.as_array())
        .ok_or("array dimensions must be an array")?;
    if bounds.len() > usize::from(u16::MAX) { return Err("array rank exceeds the Automation descriptor limit".into()); }
    let dimensions = bounds.iter().map(|bound| {
        let fields = bound.as_object().ok_or("array dimension must be an object")?;
        if fields.len() != 2 || !fields.contains_key("lower_bound") || !fields.contains_key("length") {
            return Err("array dimension requires lower_bound and length".to_string());
        }
        let lower_bound = fields["lower_bound"].as_i64()
            .and_then(|value| i32::try_from(value).ok()).ok_or("array lower bound is out of range")?;
        let length = fields["length"].as_u64()
            .and_then(|value| u32::try_from(value).ok()).ok_or("array length is out of range")?;
        let length = usize::try_from(length).map_err(|_| "array length exceeds address space")?;
        Ok(ArrayDimension { lower_bound: i64::from(lower_bound), length })
    }).collect::<Result<Vec<_>, String>>()?;
    let count = if dimensions.is_empty() || dimensions.iter().any(|dimension| dimension.length == 0) {
        0
    } else {
        dimensions.iter().try_fold(1usize, |count, dimension| count.checked_mul(dimension.length))
            .ok_or("array dimension product exceeds address space")?
    };
    if count != value_count { return Err("array shape does not match supplied values".into()); }
    Ok(VbaInputArraySchema { dimensions, element_type: kind.into(), element_default, resizable })
}

fn finish_vba_input_array(schema: VbaInputArraySchema, values: Vec<Value>) -> Result<Value, String> {
    for (index, value) in values.iter().enumerate() {
        let matched = match &schema.element_default {
            Value::Empty => true,
            Value::NullString => matches!(value, Value::String(_) | Value::Utf16(_) | Value::ByteString(_) | Value::NullString),
            Value::Nothing => matches!(value, Value::Object(_) | Value::Nothing),
            Value::Integer(_) => matches!(value, Value::Integer(value) if i32::try_from(*value).is_ok()),
            Value::Error(_) => matches!(value, Value::Error(value) if i32::try_from(*value).is_ok()),
            expected => std::mem::discriminant(value) == std::mem::discriminant(expected),
        };
        if !matched { return Err(format!("array element {} does not match {}", index + 1, schema.element_type)); }
    }
    Ok(Value::Array(ArrayValue {
        dimensions: schema.dimensions, values,
        element_default: Box::new(schema.element_default), resizable: schema.resizable,
    }))
}

fn vba_input_property(value: &JsValue, name: &str) -> Result<JsValue, JsError> {
    js_sys::Reflect::get(value, &JsValue::from_str(name))
        .map_err(|_| JsError::new("invalid VBA argument: cannot read array property"))
}

fn vba_input_fields(value: &JsValue, required: &[&str], optional: &[&str]) -> Result<(), JsError> {
    if !value.is_object() || value.is_null() || js_sys::Array::is_array(value) {
        return Err(JsError::new("invalid VBA argument: array descriptor must be an object"));
    }
    let keys = js_sys::Object::keys(&js_sys::Object::from(value.clone())).iter()
        .filter_map(|value| value.as_string()).collect::<Vec<_>>();
    if required.iter().any(|key| !keys.iter().any(|actual| actual == key))
        || keys.iter().any(|key| !required.contains(&key.as_str()) && !optional.contains(&key.as_str())) {
        return Err(JsError::new("invalid VBA argument: unknown or missing array field"));
    }
    Ok(())
}

fn decode_vba_input_array(value: &JsValue, ancestors: &mut Vec<JsValue>,
    references: Option<&ExternalReferences>) -> Result<Value, JsError> {
    vba_input_fields(value, &["type", "value"], &[])?;
    let payload = vba_input_property(value, "value")?;
    vba_input_fields(&payload, &["dimensions", "element_type", "values"], &["resizable"])?;
    let kind = vba_input_property(&payload, "element_type")?.as_string()
        .ok_or_else(|| JsError::new("invalid VBA argument: array element type must be a string"))?;
    let bounds = vba_input_property(&payload, "dimensions")?;
    let items = vba_input_property(&payload, "values")?;
    if !js_sys::Array::is_array(&bounds) || !js_sys::Array::is_array(&items) {
        return Err(JsError::new("invalid VBA argument: array dimensions and values must be arrays"));
    }
    let resizable = vba_input_property(&payload, "resizable")?;
    let resizable = if resizable.is_undefined() {
        true
    } else {
        resizable.as_bool().ok_or_else(|| JsError::new("invalid VBA argument: array resizable must be boolean"))?
    };
    let mut dimensions = Vec::new();
    for dimension in js_sys::Array::from(&bounds).iter() {
        vba_input_fields(&dimension, &["lower_bound", "length"], &[])?;
        let lower = vba_input_property(&dimension, "lower_bound")?.as_f64()
            .filter(|value| value.is_finite() && value.fract() == 0.0
                && *value >= f64::from(i32::MIN) && *value <= f64::from(i32::MAX))
            .ok_or_else(|| JsError::new("invalid VBA argument: array lower bound is out of range"))?;
        let length = vba_input_property(&dimension, "length")?.as_f64()
            .filter(|value| value.is_finite() && value.fract() == 0.0
                && *value >= 0.0 && *value <= f64::from(u32::MAX))
            .ok_or_else(|| JsError::new("invalid VBA argument: array length is out of range"))?;
        dimensions.push(serde_json::json!({"lower_bound": lower as i64, "length": length as u64}));
    }
    let items = js_sys::Array::from(&items);
    let metadata = serde_json::json!({"dimensions": dimensions, "element_type": kind, "resizable": resizable});
    let schema = decode_vba_input_array_schema(&metadata, items.length() as usize)
        .map_err(|message| JsError::new(&format!("invalid VBA argument: {message}")))?;
    let mut values = Vec::with_capacity(items.length() as usize);
    for item in items.iter() {
        let item = if !item.is_object() && !item.is_bigint() && !matches!(kind.as_str(), "variant" | "object") {
            let descriptor = js_sys::Object::new();
            js_sys::Reflect::set(&descriptor, &JsValue::from_str("type"), &JsValue::from_str(&kind))
                .map_err(|_| JsError::new("invalid VBA argument: cannot construct typed array element"))?;
            js_sys::Reflect::set(&descriptor, &JsValue::from_str("value"), &item)
                .map_err(|_| JsError::new("invalid VBA argument: cannot construct typed array element"))?;
            descriptor.into()
        } else { item };
        values.push(decode_vba_input_argument_inner(item, ancestors, references)?);
    }
    finish_vba_input_array(schema, values)
        .map_err(|message| JsError::new(&format!("invalid VBA argument: {message}")))
}

fn decode_vba_input_argument_inner(value: JsValue, ancestors: &mut Vec<JsValue>,
    references: Option<&ExternalReferences>) -> Result<Value, JsError> {
    if value.is_bigint() {
        let integer = js_sys::BigInt::new(&value)
            .map_err(|_| JsError::new("invalid VBA argument: expected a BigInt"))?;
        let text = integer.to_string(10)
            .map_err(|_| JsError::new("invalid VBA argument: cannot read BigInt"))?
            .as_string().ok_or_else(|| JsError::new("invalid VBA argument: cannot read BigInt digits"))?;
        return text.parse::<i64>().map(Value::LongLong)
            .map_err(|_| JsError::new("invalid VBA argument: BigInt is outside LongLong range"));
    }
    let bstr = |value: JsValue| {
        let text = js_sys::JsString::from(value);
        let units = (0..text.length()).map(|index| text.char_code_at(index) as u16).collect();
        Value::from_utf16(units)
    };
    if value.is_string() {
        return Ok(bstr(value));
    }
    if js_sys::Array::is_array(&value) {
        return Err(JsError::new("invalid VBA argument: array arguments require a typed descriptor"));
    }
    if value.is_object() && !value.is_null() && !js_sys::Array::is_array(&value) {
        vba_input_fields(&value, &["type"], &["value"])?;
        let tag = js_sys::Reflect::get(&value, &JsValue::from_str("type"))
            .map_err(|_| JsError::new("invalid VBA argument: cannot read type"))?.as_string();
        if tag.as_deref() == Some("object") {
            vba_input_fields(&value, &["type", "value"], &[])?;
            let payload = vba_input_property(&value, "value")?;
            vba_input_fields(&payload, &["reference"], &["handle", "kind"])?;
            let reference = vba_input_property(&payload, "reference")?.as_string()
                .ok_or_else(|| JsError::new("invalid VBA object reference: expected a string"))?;
            let object = references.and_then(|references| references.values.get(&reference))
                .ok_or_else(|| JsError::new("invalid VBA object reference: released, stale, or foreign reference"))?;
            let kind = vba_input_property(&payload, "kind")?;
            if !kind.is_undefined() && kind.as_string().as_deref() != Some(object.kind.as_str()) {
                return Err(JsError::new("invalid VBA object reference: kind does not match"));
            }
            let handle = vba_input_property(&payload, "handle")?;
            if !handle.is_undefined() {
                let valid = handle.as_string().is_some_and(|value| value == object.handle.to_string())
                    || handle.as_f64().is_some_and(|value| (0.0..=9_007_199_254_740_991.0).contains(&value)
                        && value.fract() == 0.0 && value as u64 == object.handle);
                if !valid { return Err(JsError::new("invalid VBA object reference: handle does not match")); }
            }
            return Ok(Value::Object(object.clone()));
        }
        if tag.as_deref() == Some("array") {
            if ancestors.iter().any(|parent| js_sys::Object::is(parent, &value)) {
                return Err(JsError::new("invalid VBA argument: recursive array descriptor"));
            }
            ancestors.push(value.clone());
            let result = decode_vba_input_array(&value, ancestors, references);
            ancestors.pop();
            return result;
        }
        if matches!(tag.as_deref(), Some("string" | "single" | "double" | "date")) {
            let keys = js_sys::Object::keys(&js_sys::Object::from(value.clone()));
            if keys.length() != 2 || keys.iter().any(|key|
                !matches!(key.as_string().as_deref(), Some("type" | "value")))
            {
                return Err(JsError::new("invalid VBA argument: unknown typed scalar field"));
            }
            let payload = js_sys::Reflect::get(&value, &JsValue::from_str("value"))
                .map_err(|_| JsError::new("invalid VBA argument: cannot read typed scalar value"))?;
            if tag.as_deref() == Some("string") {
                if !payload.is_string() {
                    return Err(JsError::new("invalid VBA argument: typed String requires a string"));
                }
                return Ok(bstr(payload));
            }
            let number = payload.as_f64().and_then(serde_json::Number::from_f64)
                .ok_or_else(|| JsError::new("invalid VBA argument: expected a finite number"))?;
            let descriptor = serde_json::json!({"type": tag, "value": number});
            return decode_typed_scalar(&descriptor)
                .map_err(|error| JsError::new(&format!("invalid VBA argument: {error}")));
        }
        return decode_vba_input_scalar_descriptor(&value, tag.as_deref().unwrap_or(""));
    }
    let input = serde_wasm_bindgen::from_value::<InputValue>(value)
        .map_err(|error| JsError::new(&format!("invalid VBA argument: {error}")))?;
    Value::try_from(input).map_err(|error| JsError::new(&format!("invalid VBA argument: {error}")))
}


fn serialize_vba_signed_integer<S: serde::Serializer>(value: &i64, serializer: S) -> Result<S::Ok, S::Error> {
    const LIMIT: i64 = 9_007_199_254_740_991;
    if (-LIMIT..=LIMIT).contains(value) {
        serializer.serialize_i64(*value)
    } else {
        serializer.serialize_str(&value.to_string())
    }
}
fn serialize_vba_object_handle<S: serde::Serializer>(value: &u64, serializer: S) -> Result<S::Ok, S::Error> {
    const LIMIT: u64 = 9_007_199_254_740_991;
    if *value <= LIMIT {
        serializer.serialize_u64(*value)
    } else {
        serializer.serialize_str(&value.to_string())
    }
}

#[derive(Serialize)]
#[serde(tag = "type", content = "value", rename_all = "snake_case")]
enum OutputValue {
    Empty,
    Missing,
    Nothing,
    Null,
    Boolean(bool),
    Integer(#[serde(serialize_with = "serialize_vba_signed_integer")] i64),
    Double(f64),
    Currency(String),
    Decimal(String),
    Error(i64),
    String(String),
    Utf16(Vec<u16>),
    Bstr(Vec<u8>),
    Array {
        lower_bound: i64,
        dimensions: Vec<OutputArrayDimension>,
        resizable: bool,
        values: Vec<OutputValue>,
    },
    Record {
        type_name: String,
        fields: Vec<(String, OutputValue)>,
    },
    Object {
        #[serde(serialize_with = "serialize_vba_object_handle")]
        handle: u64,
        kind: String,
        #[serde(skip_serializing_if = "Option::is_none")]
        reference: Option<String>,
        #[serde(skip)]
        object: ObjectRef,
    },
}


// Keep the existing execution protocol's optional values and UTF-16 handling.
// Only Workbook payloads use JSON objects so worker/client copies retain maps.
trait VbaWorkbookPayloads {
    fn write_workbooks(&self, js: &JsValue) -> Result<(), JsError>;
}

fn write_workbook_payload(js: &JsValue, workbook: &Workbook) -> Result<(), JsError> {
    js_sys::Reflect::set(js, &JsValue::from_str("workbook"), &crate::spreadsheet_value_to_js(workbook)?)
        .map(|_| ()).map_err(|_| JsError::new("cannot serialize workbook payload"))
}

fn write_other_workbook_payloads(js: &JsValue, books: &[OpenWorkbookOutput]) -> Result<(), JsError> {
    if books.is_empty() { return Ok(()); }
    let entries = js_sys::Reflect::get(js, &JsValue::from_str("other_workbooks"))
        .map_err(|_| JsError::new("VBA outcome has no workbook list"))?;
    let entries = js_sys::Array::from(&entries);
    for (index, book) in books.iter().enumerate() {
        write_workbook_payload(&entries.get(index as u32), &book.workbook)?;
    }
    Ok(())
}

fn write_selected_workbook_payloads(js: &JsValue, selection: Option<&WorkbookSelection>) -> Result<(), JsError> {
    if let Some(selection) = selection {
        let selected = js_sys::Reflect::get(js, &JsValue::from_str("workbook_selection"))
            .map_err(|_| JsError::new("VBA outcome has no workbook selection"))?;
        selection.write_workbooks(&selected)?;
    }
    Ok(())
}

impl VbaWorkbookPayloads for RunOutcome {
    fn write_workbooks(&self, js: &JsValue) -> Result<(), JsError> {
        write_workbook_payload(js, &self.workbook)?;
        write_other_workbook_payloads(js, &self.other_workbooks)?;
        write_selected_workbook_payloads(js, self.workbook_selection.as_ref())
    }
}

impl VbaWorkbookPayloads for RunResult {
    fn write_workbooks(&self, js: &JsValue) -> Result<(), JsError> {
        write_workbook_payload(js, &self.workbook)?;
        write_other_workbook_payloads(js, &self.other_workbooks)?;
        write_selected_workbook_payloads(js, self.workbook_selection.as_ref())
    }
}

impl VbaWorkbookPayloads for WorkbookSelection {
    fn write_workbooks(&self, js: &JsValue) -> Result<(), JsError> {
        let selected = js_sys::Reflect::get(js, &JsValue::from_str("selected"))
            .map_err(|_| JsError::new("VBA selection has no selected workbook"))?;
        write_workbook_payload(&selected, &self.selected.workbook)?;
        write_other_workbook_payloads(js, &self.other_workbooks)
    }
}

fn serialize_vba_outcome<T:Serialize + VbaWorkbookPayloads>(outcome:&T)->Result<JsValue,JsError>{
    let js=serde_wasm_bindgen::to_value(outcome).map_err(|error|JsError::new(&error.to_string()))?;
    outcome.write_workbooks(&js)?;
    fn convert(value:&JsValue)->Result<(),JsValue>{
        let tag=js_sys::Reflect::get(value,&JsValue::from_str("type"))?.as_string();
        let payload=js_sys::Reflect::get(value,&JsValue::from_str("value"))?;
        match tag.as_deref(){
            Some("utf16")=>{
                let units=js_sys::Array::from(&payload).iter().map(|u|u.as_f64().unwrap_or(0.0)as u16).collect::<Vec<_>>();
                js_sys::Reflect::set(value,&JsValue::from_str("type"),&JsValue::from_str("string"))?;
                let pieces=js_sys::Array::new();
                for chunk in units.chunks(8192){pieces.push(&js_sys::JsString::from_char_code(chunk));}
                js_sys::Reflect::set(value,&JsValue::from_str("value"),&pieces.join(""))?;
            },
            Some("array")=>{let values=js_sys::Reflect::get(&payload,&JsValue::from_str("values"))?;for v in js_sys::Array::from(&values).iter(){convert(&v)?;}},
            Some("record")=>{let fields=js_sys::Reflect::get(&payload,&JsValue::from_str("fields"))?;for pair in js_sys::Array::from(&fields).iter(){convert(&js_sys::Array::from(&pair).get(1))?;}},
            _=>{}
        }
        Ok(())
    }
    let result=js_sys::Reflect::get(&js,&JsValue::from_str("result")).map_err(|_|JsError::new("VBA outcome has no result"))?;
    if !result.is_undefined(){convert(&result).map_err(|_|JsError::new("cannot preserve VBA UTF16 result"))?;}
    Ok(js)
}

impl From<Value> for OutputValue {
    fn from(value: Value) -> Self {
        match value {
            Value::Empty => Self::Empty,
            Value::Missing => Self::Missing,
            Value::Nothing => Self::Nothing,
            Value::Null => Self::Null,
            Value::Boolean(value) => Self::Boolean(value),
            Value::Int16(value) => Self::Integer(value as i64),
            Value::Byte(value) => Self::Integer(value as i64),
            Value::Integer(value) => Self::Integer(value),
            Value::LongLong(value) => Self::Integer(value),
            Value::Single(value) => Self::Double(value as f64),
            Value::Currency(value) => Self::Currency(
                oxivba_core::decimal::Dec {
                    negative: value < 0,
                    magnitude: u128::from(value.unsigned_abs()),
                    scale: 4,
                }
                .to_string(),
            ),
            Value::Decimal(value) => Self::Decimal(value.to_string()),
            Value::Date(value) => Self::Double(value),
            Value::Double(value) => Self::Double(value),
            Value::Error(value) => Self::Error(value),
            Value::String(value) => Self::String(value),
            Value::NullString=>Self::String(String::new()),
            Value::Utf16(units)=>Self::Utf16(units),
            Value::ByteString(bytes)=>Self::Bstr(bytes),
            Value::Array(value) => Self::Array {
                lower_bound: value.lower_bound(1).unwrap_or(0),
                dimensions: value
                    .dimensions
                    .iter()
                    .map(|dimension| OutputArrayDimension {
                        lower_bound: dimension.lower_bound,
                        length: dimension.length,
                    })
                    .collect(),
                resizable: value.resizable,
                values: value.values.into_iter().map(OutputValue::from).collect(),
            },
            Value::Record(record) => Self::Record {
                type_name: record.type_name,
                fields: record
                    .fields
                    .into_iter()
                    .map(|(name, value)| (name, OutputValue::from(value)))
                    .collect(),
            },
            Value::Object(value) => Self::Object {
                handle: value.handle,
                kind: value.kind.clone(),
                reference: None,
                object: value,
            },
        }
    }
}

/// Whether Excel's `WorksheetFunction` carries this name at all.
///
/// It leaves off the worksheet functions VBA already has of its own, so a
/// macro calls `Len(text)` rather than `WorksheetFunction.Len(text)` — asking
/// for the second raises "object doesn't support this property or method".
/// Measured by asking Excel 16.0 for each name the engine knows: 82 answered
/// and these 30 were not there. `NOTAFUNCTION` was asked alongside them as a
/// control and was reported absent, which is what says the question was being
/// answered rather than deflected.
/// The worksheet functions Excel leaves off `WorksheetFunction`, because VBA
/// has one of its own or says it another way.
/// Application properties that answer a plain default until a macro sets
/// them: (name, default, settable). Measured on a fresh Excel: ReferenceStyle
/// 1, DecimalSeparator ".", ThousandsSeparator ",", UseSystemSeparators True,
/// CutCopyMode 0, Interactive True, EnableCancelKey 1 (Cursor keeps its own),
/// MaxChange 0.001, MaxIterations 100, Iteration False, CalculationState 0,
/// CalculateBeforeSave True, PathSeparator "\\".
#[cfg(target_arch = "wasm32")]
fn browser_standard_font_preference() -> Option<crate::vba_automation::StandardFontProfile> {
    use wasm_bindgen::JsCast;
    let global = js_sys::global();
    let callback = js_sys::Reflect::get(&global, &wasm_bindgen::JsValue::from_str("__oxiVbaReadStandardFontPreference")).ok()?;
    let callback = callback.dyn_ref::<js_sys::Function>()?;
    let value = callback.call0(&global).ok()?;
    if value.is_undefined() { return None; }
    if value.is_null() { return Some(crate::vba_automation::StandardFontProfile(Vec::new())); }
    let array = js_sys::Array::from(&value);
    let mut units = Vec::with_capacity(array.length() as usize);
    for value in array.iter() {
        let number = value.as_f64()?;
        if !number.is_finite() || number.fract() != 0.0 || !(0.0..=65535.0).contains(&number) { return None; }
        units.push(number as u16);
    }
    Some(crate::vba_automation::StandardFontProfile(units))
}

#[cfg(target_arch = "wasm32")]
fn store_browser_standard_font_preference(units: &[u16]) -> Result<(), String> {
    use wasm_bindgen::JsCast;
    let global = js_sys::global();
    let callback = js_sys::Reflect::get(&global, &wasm_bindgen::JsValue::from_str("__oxiVbaWriteStandardFontPreference"))
        .map_err(|_| host_error(1004, "The standard-font preference could not be saved."))?;
    if let Some(callback) = callback.dyn_ref::<js_sys::Function>() {
        callback.call1(&global, &js_sys::Uint16Array::from(units))
            .map_err(|_| host_error(1004, "The standard-font preference could not be saved."))?;
    }
    Ok(())
}

/// Supply the application's explicit Normal font when a package omits styles.
/// This must happen before shape anchors are projected onto the worksheet grid.
fn initialize_missing_package_styles(
    workbook: &mut Workbook,
    package: &[u8],
    application_font: &CellStyle,
) -> Result<bool, String> {
    if package_has_styles(package)? { return Ok(false); }
    let mut normal = application_font.clone();
    let face = normal.font_name.clone()
        .or_else(|| normal.latin_font_name().map(str::to_owned))
        .ok_or_else(|| "the application Normal font has no face".to_string())?;
    let reference = normal.font_reference.get_or_insert_with(Default::default);
    reference.scheme = None;
    if reference.latin_name_utf16.is_none() { reference.latin_name = Some(face.clone()); }
    let height = fresh_workbook_row_points(&normal);
    let seed = file_io::WorkbookFiles::blank_package(
        oxicells_core::ir::SheetKind::Worksheet, 1, &normal, (0.0, height),
    )?;
    let seed = oxicells_core::parse_xlsx_preserving_values(&seed)
        .map_err(|error| error.to_string())?;
    workbook.default_style = seed.default_style;
    workbook.named_styles = seed.named_styles;
    for sheet in &mut workbook.sheets {
        sheet.normal_font = Some((face.clone(), normal.font_size.unwrap_or(11.0)));
        sheet.column_width_font = Some(face.clone());
        if !sheet.default_row_custom { sheet.default_row_height = height; }
    }
    // Cells in a styleless package inherit the supplied Normal resource.
    // Freeze that identity before a VBA font edit allocates a new resource;
    // otherwise an omitted color becomes an independent automatic color.
    resolve_implicit_cell_styles(workbook);
    Ok(true)
}

/// A sparse editor font inherits an omitted color independently of its
/// explicitly edited face or size. A resolved font's absent color is its
/// own automatic color, so only views without resource provenance qualify.
fn inherit_implicit_font_color(style: &mut CellStyle, normal: &CellStyle) {
    if style.normal_font_link.is_some() || style.named_font_link.is_some()
        || style.format_reference.is_some() || style.font_color.is_some()
        || style.font_reference.as_ref().and_then(|reference| reference.color_reference()).is_some() {
        return;
    }
    style.font_color = normal.font_color.clone();
    if let Some(source) = normal.font_reference.as_ref().filter(|reference| reference.color_reference().is_some()) {
        let reference = style.font_reference.get_or_insert_with(Default::default);
        reference.rgb = source.rgb.clone();
        reference.theme = source.theme;
        reference.indexed = source.indexed;
        reference.automatic = source.automatic;
        reference.implicit_automatic = source.implicit_automatic;
        reference.tint = reference.tint.or(source.tint);
    }
}

/// Complete an older editor font before allocating its saved resource.
/// Missing fields inherit the default font; explicit values stay explicit.
fn complete_implicit_font(style: &mut CellStyle, normal: &CellStyle) {
    inherit_implicit_font_color(style, normal);
    if style.latin_font_units().is_none()
        && style.font_reference.as_ref().and_then(|reference|reference.scheme.as_ref()).is_none() {
        style.font_name=normal.font_name.clone();
        if let Some(source)=normal.font_reference.as_ref() {
            let reference=style.font_reference.get_or_insert_with(Default::default);
            reference.latin_name=source.latin_name.clone();
            reference.latin_name_utf16=source.latin_name_utf16.clone();
            reference.scheme=source.scheme.clone();
        }
    }
    style.font_size=style.font_size.or(normal.font_size);
    if style.latin_font_name()==normal.latin_font_name() {
        style.font_family=style.font_family.or(normal.font_family);
        style.font_charset=style.font_charset.or(normal.font_charset);
    } else if let Some(face)=style.latin_font_name() {
        let (family,charset)=requested_font_metadata(face);
        style.font_family=style.font_family.or(family).or(normal.font_family);
        style.font_charset=style.font_charset.or(charset);
    }
}

/// Resource defaults have canonical XML forms. An omitted fill and an
/// explicit empty fill must not become a spurious application flag.
fn same_export_style_group(left: &CellStyle, right: &CellStyle,
    part: oxicells_core::ir::CellFormatComponent) -> bool {
    use oxicells_core::ir::CellFormatComponent::*;
    match part {
        Font=>oxicells_core::editor::serialize_cell_font(left)==oxicells_core::editor::serialize_cell_font(right),
        Fill=>oxicells_core::editor::serialize_cell_fill(left)==oxicells_core::editor::serialize_cell_fill(right),
        Border=>oxicells_core::editor::serialize_cell_border(left)==oxicells_core::editor::serialize_cell_border(right),
        _=>WorkbookHost::same_style_group(left,right,part),
    }
}

/// Older views can omit font resources and application flags. Resolve them
/// before execution as well as saving, so a later Normal edit cannot change
/// a font that was already edited independently. Keep known identities intact.
fn resolve_implicit_cell_styles(workbook: &mut Workbook) {
    use oxicells_core::ir::CellFormatComponent::*;
    let empty=Dress::of_style(&CellStyle::default());
    let fallback=workbook.default_style.clone();
    let normal=workbook.named_styles.iter().find(|style|style.builtin_id==Some(0));
    let parent=normal.map_or(0,|style|style.source_id);
    let normal=normal.map_or(&fallback,|style|&style.style).clone();
    for sheet in &mut workbook.sheets {
        let bands=&sheet.band_styles;
        for row in &mut sheet.rows { for cell in &mut row.cells {
            if cell.style.normal_font_link.is_some() || cell.style.named_font_link.is_some()
                || cell.style.format_reference.is_some() {continue;}
            // This is the same row/column/sheet precedence as template_style.
            let mut default=bands.rows.get(&row.index).or_else(||bands.columns.get(&cell.col))
                .or(bands.sheet.as_ref()).unwrap_or(&fallback).clone();
            if default.normal_font_link.is_none() && default.named_font_link.is_none()
                && default.format_reference.is_none() {complete_implicit_font(&mut default,&fallback);}
            if Dress::of_style(&cell.style)==empty {Dress::of_style(&default).write_font(&mut cell.style);}
            complete_implicit_font(&mut cell.style,&default);
            let font_changed=!same_export_style_group(&cell.style,&default,Font);
            let mut reference=if let Some(reference)=default.format_reference.as_deref() {reference.clone()}
                else {
                    let mut reference=oxicells_core::ir::CellFormatReference::for_style(parent);
                    for part in [NumberFormat,Font,Fill,Border,Alignment,Protection] {
                        if !same_export_style_group(&default,&normal,part) {reference.mark(part);}
                    }
                    reference
                };
            for part in [NumberFormat,Font,Fill,Border,Alignment,Protection] {
                if !same_export_style_group(&cell.style,&default,part) {reference.mark(part);}
            }
            cell.style.normal_font_link=Some(!font_changed && default.normal_font_link
                .unwrap_or_else(||same_export_style_group(&cell.style,&normal,Font)));
            cell.style.named_font_link=if font_changed {None}else{default.named_font_link};
            cell.style.format_reference=Some(Box::new(reference));
        }}
    }
}

/// Loading the host's implicit defaults is not an edit to a styleless file.
/// Compare the entire document after applying the same load normalization,
/// so incoming editor edits and calculated values still require serialization.
fn unchanged_implicit_package(package: &[u8], workbook: &Workbook,
    application_font: &CellStyle) -> Result<bool, String> {
    if package_has_styles(package)? { return Ok(false); }
    let mut original = oxicells_core::parse_xlsx_preserving_values(package)
        .map_err(|error| error.to_string())?;
    initialize_initial_caller_styles(&mut original, package, application_font)?;
    original.calculation.dbcs_language = workbook.calculation.dbcs_language;
    let mut current = workbook.clone();
    resolve_implicit_cell_styles(&mut original);
    resolve_implicit_cell_styles(&mut current);
    Ok(observable_workbook_bytes(&mut original)? == observable_workbook_bytes(&mut current)?)
}

fn package_has_styles(package: &[u8]) -> Result<bool, String> {
    let mut archive = zip::ZipArchive::new(std::io::Cursor::new(package))
        .map_err(|error| error.to_string())?;
    let present = match archive.by_name("xl/styles.xml") {
        Ok(_) => true,
        Err(zip::result::ZipError::FileNotFound) => false,
        Err(error) => return Err(error.to_string()),
    };
    Ok(present)
}

/// The initially loaded editor IR may already contain user edits. Supply
/// implicit package defaults without replacing explicit fonts or geometry.
fn initialize_initial_caller_styles(
    workbook: &mut Workbook, package: &[u8], application_font: &CellStyle,
) -> Result<bool, String> {
    if package_has_styles(package)? {
        resolve_implicit_cell_styles(workbook);
        return Ok(false);
    }
    let original = oxicells_core::parse_xlsx_preserving_values(package)
        .map_err(|error| error.to_string())?;
    let mut loaded = original.clone();
    initialize_missing_package_styles(&mut loaded, package, application_font)?;
    let old_normal = original.named_styles.iter().find(|style|style.builtin_id==Some(0))
        .map(|style|&style.style).unwrap_or(&original.default_style);
    let wanted = workbook.named_styles.iter().find(|style|style.builtin_id==Some(0)
        && Dress::of_style(&style.style)!=Dress::of_style(old_normal))
        .map(|style|style.style.clone()).unwrap_or_else(||loaded.default_style.clone());
    if workbook.default_style==original.default_style {
        workbook.default_style=wanted;
    } else if Dress::of_style(&workbook.default_style)==Dress::of_style(&original.default_style) {
        Dress::of_style(&wanted).write_font(&mut workbook.default_style);
    }
    if workbook.default_style.normal_font_link.is_none() && workbook.default_style.named_font_link.is_none()
        && workbook.default_style.format_reference.is_none() {
        complete_implicit_font(&mut workbook.default_style,&loaded.default_style);
        // A font-only edit to the implicit default still owns cell format 0
        // and shares Normal's first font resource. Preserve non-font edits.
        if [oxicells_core::ir::CellFormatComponent::NumberFormat,oxicells_core::ir::CellFormatComponent::Fill,
            oxicells_core::ir::CellFormatComponent::Border,oxicells_core::ir::CellFormatComponent::Alignment,
            oxicells_core::ir::CellFormatComponent::Protection].into_iter()
            .all(|part|same_export_style_group(&workbook.default_style,&original.default_style,part)) {
            workbook.default_style.normal_font_link=loaded.default_style.normal_font_link;
            workbook.default_style.format_reference=loaded.default_style.format_reference.clone();
        }
    }
    if let Some(normal)=workbook.named_styles.iter_mut().find(|style|style.builtin_id==Some(0)) {
        if Dress::of_style(&normal.style)==Dress::of_style(old_normal) {
            Dress::of_style(&workbook.default_style).write_font(&mut normal.style);
        } else {
            if normal.style.normal_font_link.is_none() && normal.style.named_font_link.is_none()
                && normal.style.format_reference.is_none() {
                complete_implicit_font(&mut normal.style,&loaded.default_style);
            }
        }
    } else {
        let mut normal=loaded.named_styles.iter().find(|style|style.builtin_id==Some(0))
            .ok_or_else(||"the implicit package has no Normal style".to_string())?.clone();
        let normal_reference=normal.style.format_reference.clone();
        let normal_font_link=normal.style.normal_font_link;
        let named_font_link=normal.style.named_font_link;
        normal.style=workbook.default_style.clone();
        // A Normal style owns a style-format record, not the default cell's
        // cell-format record or its inheritance link back to Normal.
        normal.style.format_reference=normal_reference;
        normal.style.normal_font_link=normal_font_link;
        normal.style.named_font_link=named_font_link;
        workbook.named_styles.push(normal);
    }
    let face=workbook.default_style.font_name.clone()
        .or_else(||workbook.default_style.latin_font_name().map(str::to_owned))
        .or_else(||loaded.default_style.font_name.clone())
        .ok_or_else(||"the loaded Normal font has no face".to_string())?;
    let size=workbook.default_style.font_size.unwrap_or(11.0);
    let height=fresh_workbook_row_points(&workbook.default_style);
    for (index,sheet) in workbook.sheets.iter_mut().enumerate() {
        let before=sheet.origin_id.and_then(|id|original.sheets.iter().find(|old|old.origin_id==Some(id)))
            .or_else(||original.sheets.get(index).filter(|old|old.name==sheet.name));
        if sheet.normal_font.as_ref()==before.and_then(|old|old.normal_font.as_ref()) {
            sheet.normal_font=Some((face.clone(),size));
        }
        if sheet.column_width_font.as_ref()==before.and_then(|old|old.column_width_font.as_ref()) {
            sheet.column_width_font=Some(face.clone());
        }
        if !sheet.default_row_custom && (sheet.default_row_height==before.map_or(15.0,|old|old.default_row_height)
            || before.is_some_and(|old|old.default_row_custom)) {
            sheet.default_row_height=height;
        }
    }
    resolve_implicit_cell_styles(workbook);
    Ok(true)
}

fn default_application_font() -> CellStyle {
    CellStyle {
        font_name: Some("游ゴシック".into()),
        font_size: Some(11.0),
        font_color: Some("000000".into()),
        font_family: Some(2),
        font_reference: Some(Box::new(oxicells_core::ir::FontReference {
            latin_name: Some("Aptos Narrow".into()),
            scheme: Some("minor".into()),
            theme: Some(1),
            ..Default::default()
        })),
        ..Default::default()
    }
}

