    #[test]
    fn crossbook_newbook_mixed_ole_and_note_keep_distinct_legacy_ids() {
        // Exercise both creation orders and multiple embedded objects. This is
        // a structural regression, not a Native Excel insertion oracle.
        for mode in 0..3 {
        let bytes=include_bytes!("../../../tests/fixtures/vba/scale_picture_original_svg.xlsx");
        let mut context=failure_context();
        context.file_context=Some(file_io::FileContext {
            package_bytes:Some(bytes.to_vec()),full_name:Some(r"C:\work\mixed-source.xlsx".into()),
            read_only:Some(true),folders:vec![r"C:\work".into()],
            files:vec![file_io::ProducedFile {path:r"C:\work\sample.txt".into(),bytes:b"Oxi mixed-copy payload".to_vec()}],
            ..Default::default()
        });
        let source=r#"Public Sub MixedCopy()
            Dim source As Workbook,ws As Worksheet,embedded As Object
            Set source=Workbooks.Add(-4167)
            Set ws=source.Worksheets(1)
            Set embedded=ws.OLEObjects.Add(Filename:="C:\work\sample.txt",DisplayAsIcon:=True)
            ws.Range("D2").AddComment "copied note"
            ws.Copy
            ActiveWorkbook.SaveAs "C:\work\mixed-copy.xlsx",51
        End Sub"#;
        let note=r#"            ws.Range("D2").AddComment "copied note""#;
        let embedded=r#"            Set embedded=ws.OLEObjects.Add(Filename:="C:\work\sample.txt",DisplayAsIcon:=True)"#;
        let source=match mode {
            1=>source.replace(&format!("{note}\n"), "").replace(embedded,&format!("{note}\n{embedded}")),
            2=>source.replace(note,&format!("{embedded}\n{note}")),
            _=>source.to_owned(),
        };
        let out=execute_workbook_action_in_session(
            oxicells_core::parse_xlsx_preserving_values(bytes).unwrap(),&source,Some("MixedCopy"),
            vec![],0,context,&mut None,
        ).unwrap();
        assert!(out.error.is_none(),"{:?}",out.error.as_ref().map(|error| &error.message));
        assert!(!out.workbook_changed);
        let saved=out.files.iter().find(|file|file.path.ends_with("mixed-copy.xlsx")).unwrap();
        let book=oxicells_core::parse_xlsx_preserving_values(&saved.bytes).unwrap();
        let sheet=&book.sheets[0];
        assert_eq!(sheet.comments.len(),1);
        let ids=sheet.comments.iter().filter_map(|note|note.shape_id)
            .chain(sheet.drawings.iter().filter(|drawing|drawing.ole_prog_id.is_some()).filter_map(|drawing|drawing.non_visual_id))
            .collect::<Vec<_>>();
        let count=if mode==2 {3}else{2};
        assert_eq!(ids.len(),count);
        assert_eq!(ids.iter().copied().collect::<std::collections::BTreeSet<_>>().len(),count,"mode{mode}: copied OLE and note IDs collide: {ids:?}");
        let mut editor=oxicells_core::XlsxEditor::new(&saved.bytes).unwrap();
        let mut changed=book.clone();
        changed.sheets[0].comments[0].visible=true;
        changed.sheets[0].comments[0].position=Some((173.25,91.5));
        for drawing in changed.sheets[0].drawings.iter_mut().filter(|drawing|drawing.ole_prog_id.is_some()) {
            drawing.ole_shadow=Some(true);
        }
        editor.apply_workbook(&changed).unwrap();
        let edited=editor.save().unwrap();
        let reopened=oxicells_core::parse_xlsx_preserving_values(&edited).unwrap();
        let sheet=&reopened.sheets[0];
        assert_eq!(sheet.comments.len(),1);
        assert!(sheet.comments[0].visible);
        assert_eq!(sheet.comments[0].position,Some((173.25,91.5)));
        let ole=sheet.drawings.iter().filter(|drawing|drawing.ole_prog_id.is_some()).collect::<Vec<_>>();
        assert_eq!(ole.len(),count-1);
        assert!(ole.iter().all(|drawing|drawing.ole_shadow==Some(true)),"mode{mode}: simultaneous note update discarded OLE edits");
        let mut before=zip::ZipArchive::new(std::io::Cursor::new(&saved.bytes)).unwrap();
        let mut after=zip::ZipArchive::new(std::io::Cursor::new(&edited)).unwrap();
        let names=after.file_names().map(str::to_owned).collect::<Vec<_>>();
        assert_eq!(names.len(),names.iter().collect::<std::collections::BTreeSet<_>>().len());
        use std::io::Read;
        let mut embeddings=0;
        for name in names.iter().filter(|name|name.starts_with("xl/embeddings/")) {
            let mut original=Vec::new();let mut current=Vec::new();
            before.by_name(name).unwrap().read_to_end(&mut original).unwrap();
            after.by_name(name).unwrap().read_to_end(&mut current).unwrap();
            assert_eq!(original,current,"mode{mode}: embedded payload changed");embeddings+=1;
        }
        assert_eq!(embeddings,count-1);
        }
    }

    fn assert_complete_new_copy_native8(corpus: &[u8], label: &str, file_keys: &[&str]) {
        use std::io::{Read, Write};
        let mut archive = zip::ZipArchive::new(std::io::Cursor::new(corpus)).unwrap();
        let mut program = Vec::new();
        archive.by_name("program").unwrap().read_to_end(&mut program).unwrap();
        let mut controls = String::new();
        archive.by_name("controls.json").unwrap().read_to_string(&mut controls).unwrap();
        let controls: serde_json::Value = serde_json::from_str(&controls).unwrap();
        let source = crate::vba_project::read_project_source_with_code_page(&program, Some(932)).unwrap().unwrap();
        let source_path = controls["source_path"].as_str().unwrap();
        let capture = std::env::var_os("OXI_VBA_NEW_COPY_CAPTURE").map(|base| std::path::PathBuf::from(base).join(label));
        if let Some(path) = &capture { std::fs::create_dir(path).unwrap(); }
        let mut failures = Vec::new();
        let mut seen = std::collections::BTreeSet::new();
        for case in controls["cases"].as_array().unwrap() {
            let mode = case["mode"].as_i64().unwrap();
            assert!(seen.insert(mode), "duplicate Native condition");
            let mut context = failure_context();
            context.project_name = "OxiNamedProject".into();
            context.host_ansi_code_page = Some(AnsiCodePage::Japanese);
            context.environment.help_file = r"C:\Program Files\Common Files\Microsoft Shared\VBA\VBA7.1\1041\VbLR6.chm".into();
            context.file_name = Some(source_path.into());
            context.document_modules = Some(crate::vba_project::read_document_modules(&program).unwrap());
            context.application_state = Some(VbaApplicationState {
                standard_font_startup: Some(VbaStandardFontStartup {
                    profile_utf16: Some(controls["startup"].as_str().unwrap().encode_utf16().collect()),
                }),
                ..Default::default()
            });
            context.file_context = Some(file_io::FileContext {
                full_name: Some(source_path.into()), package_bytes: Some(program.clone()),
                read_only: Some(true), edit_revision: Some(0), ..Default::default()
            });
            let out = execute_workbook_action_in_session(
                oxicells_core::parse_xlsx_preserving_values(&program).unwrap(),
                &source, Some("DrawingIdentityProbe.Measure"), vec![Value::Integer(mode)],
                0, context, &mut None,
            ).unwrap();
            let actual = serde_json::to_value(&out.result).unwrap();
            let expected = serde_json::json!({"type":"string","value":case["result"]});
            let paths = out.files.iter().map(|file| file.path.as_str()).collect::<std::collections::BTreeSet<_>>();
            let expected_paths = file_keys.iter().map(|key| case[*key].as_str().unwrap()).collect::<std::collections::BTreeSet<_>>();
            assert_eq!(expected_paths.len(), file_keys.len(), "Native paths must be distinct");
            if let Some(folder) = &capture {
                for (index, file) in out.files.iter().enumerate() {
                    let role = file_keys.iter().find(|key| case[**key].as_str() == Some(file.path.as_str()))
                        .map(|key| key.trim_end_matches("_path").to_string())
                        .unwrap_or_else(|| format!("unexpected-{index}"));
                    let path = folder.join(format!("mode{mode}-{role}.xlsx"));
                    let mut output = std::fs::OpenOptions::new().write(true).create_new(true).open(path).unwrap();
                    output.write_all(&file.bytes).unwrap();
                }
                let path = folder.join(format!("mode{mode}-observation.json"));
                let mut output = std::fs::OpenOptions::new().write(true).create_new(true).open(path).unwrap();
                output.write_all(&serde_json::to_vec(&serde_json::json!({
                    "mode":mode,"actual":actual,"expected":expected,
                    "caller_changed":out.workbook_changed,"paths":paths,
                    "error":out.error.as_ref().map(|error| &error.message),
                })).unwrap()).unwrap();
            }
            if label.starts_with("link_enumeration") {
                // Full VBA observations and saved numeric reference identities
                // are independent gates: changing serialization order is wrong.
                for key in file_keys {
                    let role = key.trim_end_matches("_path");
                    let path = case[*key].as_str().expect("Native file path");
                    let mut native = Vec::new();
                    archive.by_name(&format!("goldens/forward/{mode}/{role}.xlsx"))
                        .unwrap().read_to_end(&mut native).unwrap();
                    let identities = |bytes: &[u8]| -> Result<Vec<String>, String> {
                        let book = oxicells_core::parse_xlsx_preserving_values(bytes)
                            .map_err(|error| error.to_string())?;
                        book.external_books.iter().map(|book|
                            external_book_source_name(book, Some(path))
                                .ok_or_else(|| "Missing saved external identity".to_string()))
                            .collect()
                    };
                    let expected_ids = identities(&native).expect("Native saved external identities");
                    let actual_ids = out.files.iter().find(|file| file.path == path)
                        .ok_or_else(|| "Expected saved package was not produced".to_string())
                        .and_then(|file| identities(&file.bytes));
                    if actual_ids.as_ref() != Ok(&expected_ids) {
                        failures.push(format!("mode{mode} {role}: saved external identity order {actual_ids:?}, Native {expected_ids:?}"));
                    }
                }
            }
            if label.starts_with("table") {
                let table_ids=|bytes:&[u8]|->Result<Vec<(String,u32,String)>,String>{
                    let mut package=zip::ZipArchive::new(std::io::Cursor::new(bytes)).map_err(|error|error.to_string())?;
                    let names=package.file_names().filter(|name|name.starts_with("xl/tables/")&&name.ends_with(".xml")).map(str::to_owned).collect::<Vec<_>>();
                    let mut identities=Vec::new();
                    for name in names {
                        let mut xml=String::new();package.by_name(&name).map_err(|error|error.to_string())?.read_to_string(&mut xml).map_err(|error|error.to_string())?;
                        let mut reader=quick_xml::Reader::from_str(&xml);
                        loop {
                            match reader.read_event().map_err(|error|error.to_string())? {
                                quick_xml::events::Event::Start(root)|quick_xml::events::Event::Empty(root)=>{
                                    if root.local_name().as_ref()!=b"table" {return Err("Invalid saved table root".into())}
                                    let mut attributes=std::collections::BTreeMap::new();
                                    for attr in root.attributes() {
                                        let attr=attr.map_err(|error|error.to_string())?;
                                        attributes.insert(String::from_utf8(attr.key.as_ref().to_vec()).map_err(|error|error.to_string())?,attr.unescape_value().map_err(|error|error.to_string())?.into_owned());
                                    }
                                    let id=attributes.get("id").ok_or("Missing saved table ID")?.parse::<u32>().map_err(|error|error.to_string())?;
                                    identities.push((attributes.get("name").ok_or("Missing saved table name")?.clone(),id,attributes.get("displayName").ok_or("Missing saved table display name")?.clone()));
                                    break;
                                }
                                quick_xml::events::Event::Eof=>return Err("Missing saved table root".into()),
                                _=>{},
                            }
                        }
                    }
                    identities.sort();Ok(identities)
                };
                for key in file_keys {
                    let role=key.trim_end_matches("_path");
                    let mut native=Vec::new();archive.by_name(&format!("goldens/forward/{mode}/{role}.xlsx")).unwrap().read_to_end(&mut native).unwrap();
                    let expected_tables=table_ids(&native).expect("Invalid frozen Native table package");
                    let actual_tables=out.files.iter().find(|file|Some(file.path.as_str())==case[*key].as_str())
                        .ok_or_else(||"Expected saved table package was not produced".to_string()).and_then(|file|table_ids(&file.bytes));
                    if actual_tables.as_ref()!=Ok(&expected_tables) {
                        failures.push(format!("mode{mode} {role}: saved table identities {actual_tables:?}, Native {expected_tables:?}"));
                    }
                }
            }
            if out.error.is_some() || out.workbook_changed || paths != expected_paths || actual != expected {
                failures.push(format!(
                    "mode{mode}: error={:?}, changed={}, files={paths:?}, actual={actual}, expected={}",
                    out.error.as_ref().map(|error| &error.message), out.workbook_changed, case["result"],
                ));
            }
        }
        assert_eq!(seen, (0..8).collect::<std::collections::BTreeSet<i64>>());
        assert!(failures.is_empty(), "{label}: {} complete Native vectors differ:\n{}", failures.len(), failures.join("\n"));
    }

