    #[test]
    fn crossbook_copy_foreign_link_lifecycle_native8() {
        use std::io::Read;
        // Self-authored complete Excel conformance corpus: CC BY-SA 4.0.
        let bytes=include_bytes!("../../../tests/fixtures/vba/copy_foreign_link_lifecycle_native8.zip").to_vec();

 
        let mut archive=zip::ZipArchive::new(std::io::Cursor::new(bytes)).unwrap();let mut program=Vec::new();archive.by_name("program").unwrap().read_to_end(&mut program).unwrap();
        let mut controls=String::new();archive.by_name("controls.json").unwrap().read_to_string(&mut controls).unwrap();let controls:serde_json::Value=serde_json::from_str(&controls).unwrap();
        let source=crate::vba_project::read_project_source_with_code_page(&program,Some(932)).unwrap().unwrap();
        let source_path=controls["source_path"].as_str().unwrap();let mut failures=Vec::new();let mut count=0;
        for case in controls["cases"].as_array().unwrap() {
            count+=1;let mut context=failure_context();context.project_name="OxiNamedProject".into();context.host_ansi_code_page=Some(AnsiCodePage::Japanese);
            context.environment.help_file=r"C:\Program Files\Common Files\Microsoft Shared\VBA\VBA7.1\1041\VbLR6.chm".into();context.file_name=Some(source_path.into());
            context.document_modules=Some(crate::vba_project::read_document_modules(&program).unwrap());
            context.application_state=Some(VbaApplicationState {standard_font_startup:Some(VbaStandardFontStartup {profile_utf16:Some(controls["startup"].as_str().unwrap().encode_utf16().collect())}),..Default::default()});
            context.file_context=Some(file_io::FileContext {full_name:Some(source_path.into()),package_bytes:Some(program.clone()),read_only:Some(true),edit_revision:Some(0),..Default::default()});
            let out=execute_workbook_action_in_session(oxicells_core::parse_xlsx_preserving_values(&program).unwrap(),&source,Some("DrawingIdentityProbe.Measure"),vec![Value::Integer(case["mode"].as_i64().unwrap())],0,context,&mut None).unwrap();let actual=serde_json::to_value(&out.result).unwrap();
            let file_paths=out.files.iter().map(|file|file.path.as_str()).collect::<std::collections::BTreeSet<_>>();
            let expected_paths=std::collections::BTreeSet::from([case["source_path"].as_str().unwrap(),case["output_path"].as_str().unwrap()]);
            if out.error.is_some()||out.workbook_changed||file_paths!=expected_paths||actual!=serde_json::json!({"type":"string","value":case["result"]}) {
                failures.push(format!("mode{}: error={:?}, changed={}, files={:?}, actual={actual}, expected={}",case["mode"],out.error.as_ref().map(|e|&e.message),out.workbook_changed,file_paths,case["result"]));
            }
        }
        assert_eq!(count,8);assert!(failures.is_empty(),"{} complete Native external-copy vectors differ:\n{}",failures.len(),failures.join("\n"));
    }

