    #[test]
    fn crossbook_copy_original_native208_8() {
        let (program, input, controls) = native_copy208_fixture();
        let source=crate::vba_project::read_project_source_with_code_page(&program,Some(932)).unwrap().unwrap();
        let source_path=controls["context"]["source_full_name"].as_str().unwrap();let input_path=controls["context"]["input_full_name"].as_str().unwrap();let output_path=controls["context"]["output_full_name"].as_str().unwrap();
        let mut failures=Vec::new();let mut count=0;
        for case in controls["cases"].as_array().unwrap() {
            count+=1;let mut context=failure_context();context.project_name="OxiNamedProject".into();context.host_ansi_code_page=Some(AnsiCodePage::Japanese);
            context.environment.help_file=r"C:\Program Files\Common Files\Microsoft Shared\VBA\VBA7.1\1041\VbLR6.chm".into();context.file_name=Some(source_path.into());
            context.document_modules=Some(crate::vba_project::read_document_modules(&program).unwrap());
            context.application_state=Some(VbaApplicationState {standard_font_startup:Some(VbaStandardFontStartup {profile_utf16:Some(controls["startup"].as_str().unwrap().encode_utf16().collect())}),..Default::default()});
            context.file_context=Some(file_io::FileContext {full_name:Some(source_path.into()),package_bytes:Some(program.clone()),read_only:Some(true),edit_revision:Some(0),folders:vec![source_path.rsplit_once('\\').unwrap().0.into()],files:vec![file_io::ProducedFile{path:input_path.into(),bytes:input.clone()}],..Default::default()});
            let args=vec![Value::String(input_path.into()),Value::String(output_path.into()),Value::String(case["initial_name"].as_str().unwrap().into()),Value::String(case["occupied_name"].as_str().unwrap().into()),Value::Integer(case["mode"].as_i64().unwrap())];
            let out=execute_workbook_action_in_session(oxicells_core::parse_xlsx_preserving_values(&program).unwrap(),&source,Some("DrawingIdentityProbe.Measure"),args,0,context,&mut None).unwrap();let actual=serde_json::to_value(&out.result).unwrap();
            if let Some(prefix) = std::env::var_os("OXI_VBA_SAVED_CASES") {
                for (index, file) in out.files.iter().enumerate() {
                    let path = format!("{}-mode{}-{index}.xlsm", std::path::PathBuf::from(&prefix).display(), case["mode"]);
                    let mut artifact = std::fs::OpenOptions::new().write(true).create_new(true).open(path).unwrap();
                    std::io::Write::write_all(&mut artifact, &file.bytes).unwrap();
                }
            }

            if out.error.is_some()||out.workbook_changed||out.files.len()!=1||actual!=serde_json::json!({"type":"string","value":case["result"]}) {
                failures.push(format!("mode{}: error={:?}, changed={}, files={}, debug={:?}, actual={actual}, expected={}",case["mode"],out.error.as_ref().map(|e|&e.message),out.workbook_changed,out.files.len(),out.debug_output,case["result"]));
            }
        }
        assert_eq!(count,8);assert!(failures.is_empty(),"{} complete original Native208 vectors differ:\n{}",failures.len(),failures.join("\n"));
    }

