    #[test]
    fn workbooks_property_creates_fresh_references_and_keeps_assigned_aliases() {
        const CODE: &str = r#"Attribute VB_Name = "Driver"
Private held As Object
Public Function Capture() As String
 Set held = Workbooks
 Capture = Report()
End Function
Public Function Report() As String
 Dim second As Object, copied As Object
 Set second = Workbooks
 Set copied = held
 Report = CStr(held Is copied) & "|" & CStr(held Is second) & "|" & CStr(held Is Workbooks) & "|" & CStr(held Is Application.Workbooks) & "|" & TypeName(held) & "|" & CStr(held.Count) & "|" & CStr(held.Parent Is Application)
End Function
Public Function AddPeer() As String
 Dim peer As Workbook
 Set peer = Workbooks.Add
 AddPeer = Report()
End Function
Public Sub ReleaseHeld()
 Set held = Nothing
End Sub
"#;
        let mut session = None;
        let mut book = workbook();
        for (procedure, expected) in [
            ("Driver.Capture", "True|False|False|False|Workbooks|1|True"),
            ("Driver.Report", "True|False|False|False|Workbooks|1|True"),
            ("Driver.AddPeer", "True|False|False|False|Workbooks|2|True"),
            ("Driver.Report", "True|False|False|False|Workbooks|2|True"),
        ] {
            let mut context = failure_context();
            context.file_name = Some("Identity.xlsm".into());
            let outcome = execute_workbook_action_in_session(book, CODE, Some(procedure),
                vec![], 0, context, &mut session).unwrap();
            assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
            assert_eq!(serde_json::to_value(outcome.result).unwrap()["value"], expected);
            book = outcome.workbook;
        }
    }

    #[test]
    fn project_name_overrides_are_per_call_until_a_workbook_is_selected() {
        const CODE: &str = r#"Attribute VB_Name = "Driver"
Private count As Long
Public Sub OpenPeer()
 Dim peer As Workbook
 Set peer = Workbooks.Open("C:\B.xlsm")
End Sub
Public Function ReadSource() As String
 count = count + 1
 On Error Resume Next
 Err.Raise 5
 ReadSource = Err.Source & "|" & CStr(count)
End Function
"#;
        fn read_source(book: Workbook, session: &mut Option<ProjectSessionState>,
            requested: Option<&str>, expected: &str) -> Workbook {
            let mut context = failure_context();
            context.project_name = invocation_project_name(session.as_ref(), requested);
            context.file_name = session.as_ref().and_then(|state| state.host.file_name.clone())
                .or_else(|| Some("A.xlsm".into()));
            let outcome = execute_workbook_action_in_session(book, CODE, Some("Driver.ReadSource"),
                vec![], 0, context, session).unwrap();
            assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
            assert_eq!(serde_json::to_value(outcome.result).unwrap()["value"], expected);
            outcome.workbook
        }
        let mut session = None;
        let book = read_source(workbook(), &mut session, Some("ExplicitProject"), "ExplicitProject|1");
        let book = read_source(book, &mut session, None, "VBAProject|2");
        let seed = include_bytes!("../../../tests/fixtures/vba/array_argument_rank.xlsm");
        let package = crate::vba_project::write_project_source(seed, CODE, None).unwrap();
        let mut context = failure_context();
        context.project_name = "RootProject".into();
        context.file_name = Some("A.xlsm".into());
        context.file_context = Some(file_io::FileContext {
            files: vec![file_io::ProducedFile { path: r"C:\B.xlsm".into(), bytes: package }],
            ..Default::default()
        });
        let outcome = execute_workbook_action_in_session(book, CODE, Some("Driver.OpenPeer"),
            vec![], 0, context, &mut session).unwrap();
        assert!(outcome.error.is_none());
        assert!(session.as_ref().unwrap().selected_project_name.is_none());
        assert_eq!(select_session_workbook(&mut session, "0").unwrap().selected.project_name, "RootProject");
        let view = select_session_workbook(&mut session, "1").unwrap();
        let child_name = view.selected.project_name;
        let book = read_source(view.selected.workbook, &mut session, None, &format!("{child_name}|1"));
        let book = read_source(book, &mut session, Some("OneCallOverride"), "OneCallOverride|2");
        assert_eq!(selection_snapshot(session.as_ref().unwrap()).unwrap().selected.project_name, child_name);
        let _book = read_source(book, &mut session, None, &format!("{child_name}|3"));
        let root = select_session_workbook(&mut session, "0").unwrap();
        assert_eq!(root.selected.project_name, "RootProject");
        let _book = read_source(root.selected.workbook, &mut session, None, "RootProject|3");
    }

    #[test]
    fn editor_selection_synchronizes_cells_without_resetting_code_and_exports_own_package() {
        const CODE: &str = r#"Attribute VB_Name = "Driver"
Private count As Long
Public Sub Seed()
 count = 7
 ThisWorkbook.Worksheets(1).Range("A1").Value = 1
 Dim peer As Workbook
 Set peer = Workbooks.Open("C:\B.xlsm")
End Sub
Public Function ReadPeer(ByVal peer As String) As String
 count = count + 1
 ReadPeer = CStr(count) & "|" & CStr(Workbooks(peer).Worksheets(1).Range("A1").Value)
End Function
"#;
        let seed = include_bytes!("../../../tests/fixtures/vba/array_argument_rank.xlsm");
        let package_a = crate::vba_project::write_project_source(seed, CODE, None).unwrap();
        let child = format!("{CODE}\n' Child package\n");
        let package_b = crate::vba_project::write_project_source(seed, &child, None).unwrap();
        assert_ne!(package_a, package_b);
        let mut context = failure_context();
        context.file_name = Some("A.xlsm".into());
        context.file_context = Some(file_io::FileContext {
            package_bytes: Some(package_a.clone()),
            files: vec![file_io::ProducedFile { path: r"C:\B.xlsm".into(), bytes: package_b.clone() }],
            ..Default::default()
        });
        let mut session = None;
        let seeded = execute_workbook_action_in_session(workbook(), CODE, Some("Driver.Seed"),
            vec![], 0, context, &mut session).unwrap();
        assert!(seeded.error.is_none());
        let mut edited_a = seeded.workbook;
        edited_a.sheets[0].rows.iter_mut().find(|row|row.index == 1).unwrap().cells
            .iter_mut().find(|cell|cell.col == 0).unwrap().value = CellValue::Number(777.0);
        let before = session.as_ref().unwrap().workbook.clone();
        assert!(select_session_workbook_with_edits(&mut session, "999", edited_a.clone(), 0).is_err());
        assert_eq!(session.as_ref().unwrap().workbook, before);
        let view = select_session_workbook_with_edits(&mut session, "1", edited_a, 0).unwrap();
        assert_eq!(view.package_bytes.as_deref(), Some(package_b.as_slice()));
        assert!(!view.other_workbooks[0].saved);
        let mut context = failure_context();
        context.file_name = Some("B.xlsm".into());
        let outcome = execute_workbook_action_in_session(view.selected.workbook, &child, Some("Driver.ReadPeer"),
            vec![Value::String("A.xlsm".into())], 0, context, &mut session).unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
        assert_eq!(serde_json::to_value(outcome.result).unwrap()["value"], "1|777");
        let view = select_session_workbook_with_edits(&mut session, "0", outcome.workbook, 0).unwrap();
        assert_eq!(view.package_bytes.as_deref(), Some(package_a.as_slice()));
        let mut context = failure_context();
        context.file_name = Some("A.xlsm".into());
        let outcome = execute_workbook_action_in_session(view.selected.workbook, CODE, Some("Driver.ReadPeer"),
            vec![Value::String("A.xlsm".into())], 0, context, &mut session).unwrap();
        assert!(outcome.error.is_none());
        assert_eq!(serde_json::to_value(outcome.result).unwrap()["value"], "8|777");
    }

    #[test]
    fn selecting_workbooks_preserves_code_owners_references_files_and_consumed_mounts() {
        const CODE: &str = r#"Attribute VB_Name = "Driver"
Private count As Long
Private kept As Object
Private heldBook As Workbook
Public Function Seed() As Object
 SeedLocal 10
 Dim peer As Workbook
 Set peer = Workbooks.Open("C:\B.xlsm", , True)
 Application.Run "'B.xlsm'!Driver.SeedLocal", 20
 Application.StatusBar = "shared"
 Kill "C:\a1.txt"
 Set Seed = kept
End Function
Public Sub SeedLocal(ByVal start As Long)
 count = start
 Set kept = New Counter
 kept.Data = start * 10
 Set heldBook = ThisWorkbook
 ThisWorkbook.Worksheets(1).Range("A1").Value = start
 Open "C:\" & ThisWorkbook.Name & ".dat" For Binary Access Read Write Shared As #1
 Put #1, , CByte(start)
 Dim first As String
 first = Dir("C:\" & LCase(Left(ThisWorkbook.Name, 1)) & "*.txt")
End Sub
Public Function Read() As String
 Read = CStr(count) & ":" & CStr(kept.Data)
End Function
Public Function Probe(ByVal peer As String) As String
 count = count + 1
 kept.Data = kept.Data + 1
 Put #1, , CByte(count)
 ThisWorkbook.Worksheets(1).Range("A1").Value = count
 Probe = ThisWorkbook.Name & "|" & CStr(count) & "|" & CStr(kept.Data) & "|" & CStr(Loc(1)) & "|" & Dir() & "|" & CStr(heldBook Is ThisWorkbook) & "|" & ActiveWorkbook.Name & "|" & Application.Run("'" & peer & "'!Driver.Read") & "|" & CStr(Application.StatusBar)
End Function
VERSION 1.0 CLASS
Attribute VB_Name = "Counter"
Public Data As Long
"#;
        let seed = include_bytes!("../../../tests/fixtures/vba/array_argument_rank.xlsm");
        let package = crate::vba_project::write_project_source(seed, CODE, None).unwrap();
        let mounted = || file_io::FileContext {
            files: std::iter::once(file_io::ProducedFile { path: r"C:\B.xlsm".into(), bytes: package.clone() })
                .chain(["a1", "a2", "b1", "b2"].into_iter().map(|name| file_io::ProducedFile {
                    path: format!(r"C:\{name}.txt"), bytes: b"original".to_vec(),
                })).collect(),
            ..Default::default()
        };
        let mut context = failure_context();
        context.file_name = Some("A.xlsm".into());
        context.project_name = "RootProject".into();
        context.file_context = Some(mounted());
        let mut session = None;
        let seeded = execute_workbook_action_in_session(workbook(), CODE, Some("Driver.Seed"),
            vec![], 0, context, &mut session).unwrap();
        assert!(seeded.error.is_none(), "{:?}", seeded.error.as_ref().map(|error| &error.message));
        let lease = match seeded.result {
            OutputValue::Object { reference: Some(reference), .. } => reference,
            _ => panic!("retained source reference"),
        };
        let arena = session.as_ref().unwrap().host.objects.arena.clone();
        let original_reference = session.as_ref().unwrap().external_references.values[&lease].clone();
        let before = selection_snapshot(session.as_ref().unwrap()).unwrap();
        assert!(select_session_workbook(&mut session, "999").is_err());
        assert!(select_session_workbook(&mut session, "01").is_err());
        assert_eq!(selection_snapshot(session.as_ref().unwrap()).unwrap().selected.name, before.selected.name);
        for (identity, name, peer, expected) in [
            ("1", "B.xlsm", "A.xlsm", "B.xlsm|21|201|2|b2.txt|True|B.xlsm|10:100|shared"),
            ("0", "A.xlsm", "B.xlsm", "A.xlsm|11|101|2|a2.txt|True|A.xlsm|21:201|shared"),
            ("1", "B.xlsm", "A.xlsm", "B.xlsm|22|202|3||True|B.xlsm|11:101|shared"),
        ] {
            let view = select_session_workbook(&mut session, identity).unwrap();
            assert_eq!(view.selected.name, name);
            assert_eq!(view.other_workbooks.len(), 1);
            assert_eq!(view.selected.read_only, identity == "1");
            let state = session.as_ref().unwrap();
            assert!(std::rc::Rc::ptr_eq(&arena, &state.host.objects.arena));
            assert_eq!(state.host.file_io.files.project_scope(), identity.parse::<u64>().unwrap());
            assert!(!state.host.file_io.files.exists(r"C:\a1.txt"));
            assert_eq!(state.external_references.values[&lease], original_reference);
            let mut context = failure_context();
            context.file_name = Some(view.selected.name);
            context.project_name = view.selected.project_name;
            context.file_context = Some(mounted());
            let outcome = execute_workbook_action_in_session(view.selected.workbook, &view.selected.source,
                Some("Driver.Probe"), vec![Value::String(peer.into())], view.selected.active_sheet,
                context, &mut session).unwrap();
            assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
            assert_eq!(serde_json::to_value(&outcome.result).unwrap()["value"], expected);
            assert_eq!(outcome.active_workbook.as_deref(), Some(identity));
            assert!(!session.as_ref().unwrap().host.file_io.files.exists(r"C:\a1.txt"));
        }
        // A source object remains callable while B supplies the editor's IR.
        let view = select_session_workbook(&mut session, "1").unwrap();
        let mut context = failure_context();
        context.file_name = Some(view.selected.name);
        context.project_name = view.selected.project_name;
        let outcome = execute_workbook_invocation(view.selected.workbook, &view.selected.source,
            VbaInvocation { procedure: None, args: vec![], action: Some(ExternalObjectAction::Invoke {
                reference: lease, member: "Data".into(), kind: 2,
            }) }, 0, context, &mut session).unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
        assert_eq!(serde_json::to_value(&outcome.result).unwrap()["value"], 101);
        assert_eq!(select_session_workbook(&mut session, "0").unwrap().selected.project_name, "RootProject");
    }

    #[test]
    fn legacy_chart_types_match_native_families() {
        const CODE: &str = r####"Attribute VB_Name = "Driver"
Private kept As Object
Public Sub Seed()
 Dim rowIndex As Long, columnIndex As Long
 For rowIndex = 1 To 6
  For columnIndex = 1 To 5
   ThisWorkbook.Worksheets(1).Cells(rowIndex, columnIndex).Value = rowIndex * columnIndex
  Next columnIndex
 Next rowIndex
 Set kept = ThisWorkbook.Worksheets(1).ChartObjects.Add(0, 0, 400, 300).Chart
 kept.SetSourceData ThisWorkbook.Worksheets(1).Range("A1:E6")
End Sub
Public Function ReadType(ByVal kind As Long) As String
 On Error GoTo failed
 kept.ChartType = kind
 ReadType = CStr(kept.ChartType) & "|" & CStr(kept.Type)
 Exit Function
failed:
 ReadType = "E|" & CStr(Err.Number)
End Function
"####;
        let expected = [(51, 3), (52, 3), (53, 3), (54, -4100), (55, -4100), (56, -4100), (57, 2), (58, 2), (59, 2), (60, -4099), (61, -4099), (62, -4099), (4, 4), (63, 4), (64, 4), (65, 4), (66, 4), (67, 4), (5, 5), (68, 5), (69, 5), (70, -4102), (71, 5), (72, -4169), (73, -4169), (74, -4169), (75, -4169), (76, 1), (77, 1), (1, 1), (78, -4098), (79, -4098), (80, -4120), (81, -4151), (82, -4151), (83, -4103), (84, -4103), (85, -4103), (86, -4103), (87, -4169), (-4169, -4169), (-4151, -4151), (-4102, -4102), (-4101, -4101), (-4100, -4100), (-4098, -4098)];
        let mut context = failure_context();
        context.file_name = Some("A.xlsm".into());
        let mut session = None;
        let initial = execute_workbook_action_in_session(workbook(), CODE, Some("Driver.Seed"), vec![],
            0, context, &mut session).unwrap();
        assert!(initial.error.is_none());
        let mut book = initial.workbook;
        for (modern, legacy) in expected {
            let mut context = failure_context();
            context.file_name = Some("A.xlsm".into());
            let outcome = execute_workbook_action_in_session(book, CODE, Some("Driver.ReadType"),
                vec![Value::Integer(modern)], 0, context, &mut session).unwrap();
            assert!(outcome.error.is_none(), "{modern}: {:?}", outcome.error.as_ref().map(|error| &error.message));
            assert_eq!(serde_json::to_value(&outcome.result).unwrap()["value"], format!("{modern}|{legacy}"));
            book = outcome.workbook;
        }
    }

    #[test]
    fn imported_normal_diagonal_survives_save_copy_and_shared_history() {
        const STYLES:&str=r#"<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
<fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font></fonts>
<fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills>
<borders count="2"><border><left/><right/><top/><bottom/><diagonal/></border><border diagonalUp="1"><left style="thin"><color rgb="FFFF0000"/></left><right style="double"><color rgb="FF0000FF"/></right><top style="mediumDashDot"><color rgb="FF008000"/></top><bottom style="dotted"><color rgb="FFFF00FF"/></bottom><diagonal style="thin"><color rgb="FF0000FF"/></diagonal></border></borders>
<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="1"/></cellStyleXfs>
<cellXfs count="3"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0" applyBorder="1"/><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0" applyBorder="1"/><xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0" applyFont="1" applyBorder="1"/></cellXfs>
<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>
</styleSheet>"#;
        const CODE:&str=r#"Attribute VB_Name = "Driver"
Public Function Driver(ByVal mode As Long) As String
 Application.DisplayAlerts = False
 Application.EnableEvents = False
 ThisWorkbook.SaveAs Filename:="C:\probe\diagonal-result.xlsm", FileFormat:=52, AccessMode:=mode
 ThisWorkbook.Worksheets(1).Range("A1").Style = "Normal"
 ThisWorkbook.Save
 ThisWorkbook.SaveCopyAs "C:\probe\diagonal-copy.xlsm"
 Driver = CStr(ThisWorkbook.Worksheets(1).Range("A1").Borders(6).LineStyle)
End Function
"#;
        let seed=include_bytes!("../../../tests/fixtures/vba/array_argument_rank.xlsm");
        for (flags,diagonal,expected_result,header,expected_diagonal) in [
            (r#" diagonalUp="1""#,r#"<diagonal style="thin"><color rgb="FF0000FF"/></diagonal>"#,"1",
                r#"<border diagonalUp="1" diagonalDown="0" outline="0">"#,
                r#"<diagonal style="thin"><color rgb="FF0000FF"/></diagonal>"#),
            (r#" diagonalDown="1""#,r#"<diagonal style="medium"/>"#,"-4142",
                r#"<border diagonalUp="0" diagonalDown="1" outline="0">"#,
                r#"<diagonal style="medium"><color auto="1"/></diagonal>"#),
            (r#" diagonalUp="1" diagonalDown="1""#,r#"<diagonal style="double"><color rgb="FFFF0000"/></diagonal>"#,"-4119",
                r#"<border diagonalUp="1" diagonalDown="1" outline="0">"#,
                r#"<diagonal style="double"><color rgb="FFFF0000"/></diagonal>"#),
            ("",r#"<diagonal style="thin"><color rgb="FF008000"/></diagonal>"#,"-4142",
                r#"<border diagonalUp="0" diagonalDown="0" outline="0">"#,""),
        ] {
            let styles=STYLES.replace(r#" diagonalUp="1""#,flags)
                .replace(r#"<diagonal style="thin"><color rgb="FF0000FF"/></diagonal>"#,diagonal);
            let package=shared_fixture_styles(seed,&styles);
            let input=oxicells_core::parse_xlsx_preserving_values(&package).unwrap();
            let before=&input.sheets[0].rows.iter().find(|r|r.index==1).unwrap()
                .cells.iter().find(|c|c.col==0).unwrap().style;
            assert!(before.bold);
            assert!(before.border_diagonal.is_none());
            let mut expected=input
                .named_styles.iter().find(|style|style.builtin_id==Some(0)).unwrap().style.clone();
            if !expected.diagonal_up && !expected.diagonal_down {expected.border_diagonal=None;}
            for mode in [1,2] {
                let mut context=failure_context();
                context.file_name=Some("diagonal.xlsm".into());
                context.file_context=Some(file_io::FileContext {
                    full_name:Some(r"C:\probe\diagonal.xlsm".into()),
                    package_bytes:Some(package.clone()),folders:vec![r"C:\probe".into()],
                    ..Default::default()
                });
                let outcome=execute_workbook_action_in_session(
                    oxicells_core::parse_xlsx_preserving_values(&package).unwrap(),CODE,
                    Some("Driver.Driver"),vec![Value::Integer(mode)],0,context,&mut None).unwrap();
                assert!(outcome.error.is_none(),"{:?}",outcome.error.as_ref().map(|e|&e.message));
                assert_eq!(serde_json::to_value(&outcome.result).unwrap()["value"],expected_result);
                let state=serde_json::to_value(&outcome.file_system_state).unwrap();
                let files:Vec<file_io::ProducedFile>=serde_json::from_value(state["files"].clone()).unwrap();
                for name in ["diagonal-result.xlsm","diagonal-copy.xlsm"] {
                    let file=files.iter().find(|file|file.path.eq_ignore_ascii_case(&format!(r"C:\probe\{name}"))).unwrap();
                    let book=oxicells_core::parse_xlsx_preserving_values(&file.bytes).unwrap();
                    let actual=&book.sheets[0].rows.iter().find(|r|r.index==1).unwrap()
                        .cells.iter().find(|c|c.col==0).unwrap().style;
                    assert_eq!(actual.border_diagonal,expected.border_diagonal);
                    assert_eq!((actual.diagonal_up,actual.diagonal_down),(expected.diagonal_up,expected.diagonal_down));
                    assert_eq!(actual.border_left,expected.border_left);
                    assert_eq!(actual.border_right,expected.border_right);
                    assert_eq!(actual.border_top,expected.border_top);
                    assert_eq!(actual.border_bottom,expected.border_bottom);
                    if mode==2 {
                        let mut archive=oxidocs_common::archive::OoxmlArchive::new(&file.bytes).unwrap();
                        let revisions=archive.read_part("xl/revisions/revisionLog2.xml").unwrap();
                        let expected=format!("{header}<left style=\"thin\"><color rgb=\"FFFF0000\"/></left><right style=\"double\"><color rgb=\"FF0000FF\"/></right><top style=\"mediumDashDot\"><color rgb=\"FF008000\"/></top><bottom style=\"dotted\"><color rgb=\"FFFF00FF\"/></bottom>{expected_diagonal}</border>");
                        assert!(revisions.contains(&expected),"{revisions}");
                    }
                }
            }
        }
    }

