    #[test]
    fn named_font_aliases_keep_native_normal_updates_separate() {
        let cases:Vec<(String,String,f32)>=serde_json::from_str(r####"[["native_independent","",11.0],["parent_font0_cell_independent","",11.0],["parent_and_cell_font0","",11.0],["shared0_apply1","",11.0]]"####).unwrap();
        const CODE:&str=r#"Attribute VB_Name = "NamedAlias"
Public Function Measure() As String
 ThisWorkbook.Styles("Normal").Font.Size = 26
 Measure = CStr(ThisWorkbook.Worksheets(1).Range("C2").Font.Size)
 ThisWorkbook.SaveCopyAs "C:\probe\named-alias-result.xlsx"
End Function
"#;
        let mut failures=Vec::new();
        for (name,encoded,expected)in cases {
            let original=super::sheet_base64(&encoded).unwrap();
            let book=oxicells_core::parse_xlsx_preserving_values(&original).unwrap();
            let mut context=failure_context();context.file_name=Some("named-alias.xlsx".into());
            context.file_context=Some(file_io::FileContext{full_name:Some(r"C:\probe\named-alias.xlsx".into()),
                package_bytes:Some(original),read_only:Some(true),folders:vec![r"C:\probe".into()],..Default::default()});
            let out=execute_workbook_action_in_session(book,CODE,Some("NamedAlias.Measure"),vec![],0,context,&mut None).unwrap();
            assert!(out.error.is_none(),"{name}: {}",out.error.as_ref().map(|e|e.message.as_str()).unwrap_or("unknown"));
            let result=serde_json::to_value(&out.result).unwrap();
            if result["value"]!=expected.to_string(){failures.push(format!("{name}: runtime {:?}, expected {expected}",result["value"]));}
            let state=serde_json::to_value(&out.file_system_state).unwrap();
            let files:Vec<file_io::ProducedFile>=serde_json::from_value(state["files"].clone()).unwrap();
            let saved=files.iter().find(|f|f.path.eq_ignore_ascii_case(r"C:\probe\named-alias-result.xlsx")).unwrap();
            let restored=oxicells_core::parse_xlsx_preserving_values(&saved.bytes).unwrap();
            if failure_cell(&restored.sheets[0],2,2).unwrap().style.font_size!=Some(expected){failures.push(format!("{name}: saved font"));}
        }
        assert!(failures.is_empty(),"{}",failures.join("\n"));
    }

    #[test]
    fn direct_font_writes_preserve_native_normal_link_history() {
        let cases:Vec<(usize,String,f32,bool)>=serde_json::from_str(r####"[[12,"",26.0,false],[13,"",26.0,false],[14,"",32.0,true],[15,"",16.0,false],[16,"",32.0,true],[17,"",11.0,false],[18,"",32.0,true],[19,"",32.0,true],[20,"",32.0,true],[21,"",32.0,true],[22,"",32.0,true],[23,"",32.0,true],[24,"",32.0,true],[25,"",11.0,false],[26,"",16.0,false],[27,"",11.0,false]]"####).unwrap();
        const CODE:&str=r#"Attribute VB_Name = "NormalWrite"
Public Function Measure(ByVal mode As Long) As String
 Dim cell As Range
 Set cell = ThisWorkbook.Worksheets(1).Range("C2")
 Select Case mode
 Case 22, 23, 26
  cell.Font.Size = 16
  ThisWorkbook.Styles("Normal").Font.Size = 16
  cell.Font.Size = 16
 Case 24, 25, 27
  cell.Font.Bold = True
  cell.Font.Bold = False
 Case 12, 13, 14
  ThisWorkbook.Styles("Normal").Font.Size = 26
  If mode = 12 Then cell.Font.Size = 26
  If mode = 13 Then cell.Font.Name = ThisWorkbook.Styles("Normal").Font.Name
 Case 15
  cell.Font.Size = 16
  ThisWorkbook.Styles("Normal").Font.Size = 16
 Case 16, 19
  cell.Font.Size = 11
 Case 17, 20
  cell.Font.Bold = False
 Case 18, 21
  cell.Font.Name = ThisWorkbook.Styles("Normal").Font.Name
 End Select
 ThisWorkbook.Styles("Normal").Font.Size = 32
 Measure = CStr(cell.Font.Size)
 ThisWorkbook.SaveCopyAs "C:\probe\normal-write-result.xlsx"
End Function
"#;
        let mut failures=Vec::new();
        for (mode,encoded,expected,linked) in cases {
            let original=super::sheet_base64(&encoded).unwrap();
            let book=oxicells_core::parse_xlsx_preserving_values(&original).unwrap();
            let mut context=failure_context();context.file_name=Some("normal-write.xlsx".into());
            context.file_context=Some(file_io::FileContext{full_name:Some(r"C:\probe\normal-write.xlsx".into()),
                package_bytes:Some(original),read_only:Some(true),folders:vec![r"C:\probe".into()],..Default::default()});
            let out=execute_workbook_action_in_session(book,CODE,Some("NormalWrite.Measure"),
                vec![Value::Integer(mode as i64)],0,context,&mut None).unwrap();
            assert!(out.error.is_none(),"mode {mode}: {}",out.error.as_ref().map(|e|e.message.as_str()).unwrap_or("unknown"));
            let result=serde_json::to_value(&out.result).unwrap();
            if result["value"]!=expected.to_string(){failures.push(format!("mode {mode} runtime {:?}, expected {expected}",result["value"]));}
            let state=serde_json::to_value(&out.file_system_state).unwrap();
            let files:Vec<file_io::ProducedFile>=serde_json::from_value(state["files"].clone()).unwrap();
            let saved=files.iter().find(|f|f.path.eq_ignore_ascii_case(r"C:\probe\normal-write-result.xlsx")).unwrap();
            if let Some(directory)=std::env::var_os("OXI_NORMAL_HISTORY_RUNTIME_EXPORT") {
                std::fs::write(std::path::Path::new(&directory).join(format!("normal-write-{mode}.xlsx")),&saved.bytes).unwrap();
            }
            let restored=oxicells_core::parse_xlsx_preserving_values(&saved.bytes).unwrap();
            let cell=failure_cell(&restored.sheets[0],2,2).unwrap();
            if cell.style.font_size!=Some(expected){failures.push(format!("mode {mode} saved {:?}, expected {expected}",cell.style.font_size));}
            if cell.style.normal_font_link!=Some(linked){failures.push(format!("mode {mode} Normal link {:?}, expected {linked}",cell.style.normal_font_link));}
        }
        assert!(failures.is_empty(),"{}",failures.join("\n"));
    }

