    fn assert_native_callbyname_cases(fixture: &str) {
        let fixtures = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/vba");
        let cases: Vec<serde_json::Value> = serde_json::from_str(fixture).unwrap();
        let mut failures = Vec::new();
        for case in &cases {
            let source = std::fs::read_to_string(fixtures.join(case["source"].as_str().unwrap())).unwrap();
            let mut book = workbook();
            book.sheets[0].name = case["host_context"]["sheets"][0]["name"].as_str().unwrap().to_string();
            let mut session = None;
            for call in 0..3 {
                let mut context = failure_context();
                context.host_ansi_code_page = Some(AnsiCodePage::Japanese);
                if case["execution_options"]["errorLanguage"] == "ja-JP" { context.environment.language = ErrorLanguage::Japanese; }
                context.file_name = Some(case["host_context"]["book_name"].as_str().unwrap().to_string());
                context.document_modules = Some(serde_json::from_value(case["document_modules"].clone()).unwrap());
                let outcome = execute_workbook_action_in_session(book, &source, Some(case["procedure"].as_str().unwrap()), vec![], 0, context, &mut session).unwrap();
                assert!(outcome.error.is_none(), "{}: {:?}", case["name"], outcome.error.as_ref().map(|e| &e.message));
                let actual = serde_json::to_value(&outcome.result).unwrap();
                let expected = case["expected"].as_str().unwrap();
                let actual = actual["value"].as_str().unwrap();
                if actual != expected {
                    for (want, got) in expected.lines().zip(actual.lines()) {
                        if want != got { failures.push(format!("{} call{call}: {want} <> {got}",case["name"])); }
                    }
                    if expected.lines().count() != actual.lines().count() { failures.push(format!("{}: output line count differs",case["name"])); }
                }
                book = outcome.workbook;
            }
        }
        assert!(failures.is_empty(), "{}", failures.join("\n"));
    }

