    #[test]
    fn vba_source_edit_storage_matches_excel() {
        for (source, data, prime, read) in [
            (include_str!("../../../tests/fixtures/vba/source_edit_standard.bas"), include_str!("../../../tests/fixtures/vba/source_edit_standard.json"), "Prime", "ReadGlobals"),
            (include_str!("../../../tests/fixtures/vba/source_edit_classes.bas"), include_str!("../../../tests/fixtures/vba/source_edit_classes.json"), "Prime", "ReadState"),
            (include_str!("../../../tests/fixtures/vba/source_edit_standard.bas"), include_str!("../../../tests/fixtures/vba/source_edit_controls.json"), "Prime", "ReadGlobals"),
        ] {
            let cases: serde_json::Value = serde_json::from_str(data).unwrap();
            for case in cases.as_array().unwrap() {
                let mut session = None;
                let run = |book, code: &str, procedure, args, session: &mut Option<ProjectSessionState>| {
                    execute_workbook_action_in_session(book, code, Some(procedure), args, 0, failure_context(), session).unwrap()
                };
                let args = if read == "ReadGlobals" { vec![Value::Integer(0)] } else { vec![] };
                let seeded = run(workbook(), source, prime, args, &mut session);
                assert!(seeded.error.is_none(), "{case}");
                let mut before = run(seeded.workbook, source, read, vec![], &mut session);
                assert_eq!(serde_json::to_value(&before.result).unwrap(), serde_json::json!({"type": "string", "value": case["before"]}));
                let edited = case["source"].as_str().unwrap();
                if read == "ReadGlobals" {
                    before.workbook.sheets[0].rows.iter_mut().find(|row| row.index == 1).unwrap().cells.iter_mut().find(|cell| cell.col == 0).unwrap().value = CellValue::Number(9.0);
                }
                let mut context = failure_context();
                context.source_edits = Some(case["edits"].as_array().unwrap().iter().map(|edit| oxivba_core::SourceEdit {
                    line: edit["line"].as_u64().unwrap() as usize,
                    delete_lines: edit["deleteLines"].as_u64().unwrap() as usize,
                    text: edit["text"].as_str().unwrap().to_string(),
                }).collect());
                let after = execute_workbook_action_in_session(before.workbook, edited, Some(read), vec![], 0, context, &mut session).unwrap();
                assert!(after.error.is_none(), "{case}: {:?}", after.error.as_ref().map(|error| &error.message));
                assert_eq!(serde_json::to_value(&after.result).unwrap(), serde_json::json!({"type": "string", "value": case["after"]}), "{}", case["name"]);
            }
        }
    }

    #[test]
    fn vba_project_session_matches_excel_state_and_live_range_references() {
        let source = include_str!("../../../tests/fixtures/vba/project_state.bas");
        let cases: serde_json::Value = serde_json::from_str(include_str!("../../../tests/fixtures/vba/project_state.json")).unwrap();
        for case in cases.as_array().unwrap() {
            let mut session = None;
            let run = |book, procedure, args, session: &mut Option<ProjectSessionState>| {
                execute_workbook_action_in_session(book, source, Some(procedure), args, 0, failure_context(), session).unwrap()
            };
            let prime = run(workbook(), "Prime", vec![Value::Integer(case["mode"].as_i64().unwrap())], &mut session);
            assert_eq!(prime.error.is_some(), case["failed"].as_bool().unwrap(), "{case}");
            assert_eq!(failure_value(failure_cell(&prime.workbook.sheets[0], 1, 3)), case["inside"]);
            if let Some(expected) = case["returned"].as_str() {
                assert_eq!(serde_json::to_value(&prime.result).unwrap(), serde_json::json!({"type": "string", "value": expected}));
            }
            let mut after = run(prime.workbook, "ReadGlobals", vec![], &mut session);
            assert_eq!(serde_json::to_value(&after.result).unwrap(), serde_json::json!({"type": "string", "value": case["after"]}));
            let cell = after.workbook.sheets[0].rows.iter_mut().find(|row| row.index == 1).unwrap().cells.iter_mut().find(|cell| cell.col == 0).unwrap();
            cell.value = CellValue::Number(9.0);
            let again = run(after.workbook, "ReadGlobals", vec![], &mut session);
            assert_eq!(serde_json::to_value(&again.result).unwrap(), serde_json::json!({"type": "string", "value": case["again"]}));
        }
    }



    #[test]
    fn vba_rand_replay_and_manual_entry_match_native_excel() {
        let fixture: serde_json::Value = serde_json::from_str(include_str!("../../../tests/fixtures/vba/rand_replay.json")).unwrap();
        let mut failures = Vec::new(); let mut count = 0;
        for group in fixture["groups"].as_array().unwrap() {
            let (source, packet): (&str, &[u8]) = match group["source"].as_str().unwrap() {
                "rand_replay.bas" => (include_str!("../../../tests/fixtures/vba/rand_replay.bas"), include_bytes!("../../../tests/fixtures/vba/rand_replay.xlsm")),
                "rand_replay_boundaries.bas" => (include_str!("../../../tests/fixtures/vba/rand_replay_boundaries.bas"), include_bytes!("../../../tests/fixtures/vba/rand_replay_boundaries.xlsm")),
                name => panic!("unknown fixture {name}"),
            };
            for case in group["cases"].as_array().unwrap() {
                let mut book = oxicells_core::parse_xlsx(packet).unwrap(); let mut session = None;
                for step in case["steps"].as_array().unwrap() {
                    let args = step["arguments"].as_array().unwrap().iter().map(|v| match v {
                        serde_json::Value::String(v) => Value::String(v.clone()),
                        serde_json::Value::Bool(v) => Value::Boolean(*v),
                        serde_json::Value::Number(v) => Value::Integer(v.as_i64().unwrap()),
                        _ => panic!("unsupported fixture argument"),
                    }).collect();
                    let mut context = failure_context(); context.host_ansi_code_page = Some(AnsiCodePage::Japanese);
                    context.file_name = Some(format!("case-{}.xlsm", case["id"]));
                    let outcome = execute_workbook_action_in_session(book, source, Some(step["procedure"].as_str().unwrap()), args, 0, context, &mut session).unwrap();
                    let actual = serde_json::to_value(&outcome.result).unwrap();
                    let matched = outcome.error.is_none() && if let Some(expected) = step["expected"].as_str() {
                        actual == serde_json::json!({"type":"string", "value":expected})
                    } else { actual["value"] == step["expected_number"] };
                    if !matched { failures.push(format!("case{} {}: {actual}; error:{:?}", case["id"], step["procedure"], outcome.error.as_ref().map(|error| &error.message))); }
                    // Worker messages carry the workbook through JSON between macro invocations.
                    book = serde_json::from_value(serde_json::to_value(&outcome.workbook).unwrap()).unwrap();
                }
                count += 1;
            }
        }
        assert_eq!(count, 104); assert!(failures.is_empty(), "{}", failures.join("\n"));
    }

