    fn failure_context() -> VbaRunContext {
        VbaRunContext {
            environment: ErrorEnvironment { language: ErrorLanguage::Japanese, help_file: String::new() },
            host_ansi_code_page: None,
            project_name: "VBAProject".to_string(), file_name: None,
            random_seed: 1, current_time: 46000.0,
            application_state: None,
            source_edits: None,
            document_modules: None,
            file_context: None,
            file_system_state: None,
        }
    }

    fn failure_workbook() -> Workbook {
        let mut book = workbook();
        let mut second = book.sheets[0].clone();
        second.name = "Sheet2".to_string();
        book.sheets.push(second);
        execute_workbook_vba(book, include_str!("../../../tests/fixtures/vba/failure_state.bas"),
            "Seed", vec![], 0, failure_context()).unwrap().workbook
    }

    fn failure_cell(sheet: &Sheet, row: u32, col: u32) -> Option<&Cell> {
        sheet.rows.iter().find(|value| value.index == row)?.cells.iter().find(|cell| cell.col == col)
    }

    fn application_run(book: Workbook, procedure: &str, args: Vec<Value>, state: VbaApplicationState) -> RunOutcome {
        let mut context = failure_context();
        context.application_state = Some(state);
        execute_workbook_vba(book, include_str!("../../../tests/fixtures/vba/application_state.bas"),
            procedure, args, 0, context).unwrap()
    }

    fn application_continue(previous: RunOutcome, procedure: &str, args: Vec<Value>) -> RunOutcome {
        application_run(previous.workbook, procedure, args, previous.application_state)
    }

    #[test]
    fn vba_application_state_across_invocations_matches_excel() {
        let fixture: serde_json::Value = serde_json::from_str(include_str!("../../../tests/fixtures/vba/application_state.json")).unwrap();
        for case in fixture["cases"].as_array().unwrap() {
            let mode = case["mode"].as_i64().unwrap();
            let reset = application_run(workbook(), "ResetState", vec![], VbaApplicationState::default());
            let configured = application_continue(reset, "Configure", vec![Value::Integer(mode)]);
            assert_eq!(configured.error.is_some(), case["failed"].as_bool().unwrap(), "mode {mode}");
            assert_eq!(configured.debug_output, vec![case["inside"].as_str().unwrap()], "mode {mode}");
            assert_eq!(failure_value(failure_cell(&configured.workbook.sheets[0], 1, 3)), case["inside"]);
            let mut outcome = configured;
            for (procedure, column) in [("ReadState", "after"), ("WriteMore", "after_write"),
                ("Automatic", "automatic"), ("ResetText", "reset_text")] {
                outcome = application_continue(outcome, procedure, vec![]);
                assert!(outcome.error.is_none(), "mode {mode} {procedure}");
                assert_eq!(serde_json::to_value(&outcome.result).unwrap(),
                    serde_json::json!({"type": "string", "value": case[column]}), "mode {mode} {procedure}");
            }
        }
        for transition in fixture["transitions"].as_array().unwrap() {
            let reset = application_run(workbook(), "ResetState", vec![], VbaApplicationState::default());
            let initial = transition["initial"].as_i64().unwrap();
            let target = transition["target"].as_i64().unwrap();
            let switched = application_continue(reset, "SwitchMode", vec![Value::Integer(initial)]);
            let mut outcome = switched;
            for (procedure, argument, column) in [("ChangeInput", 7, "before"),
                ("SwitchMode", target, "after"), ("ChangeInput", 9, "following")] {
                outcome = application_continue(outcome, procedure, vec![Value::Integer(argument)]);
                assert!(outcome.error.is_none());
                assert_eq!(serde_json::to_value(&outcome.result).unwrap(),
                    serde_json::json!({"type": "string", "value": transition[column]}), "{initial}->{target} {column}");
            }
        }
    }

    #[test]
    fn vba_application_state_validates_external_values() {
        assert!(VbaApplicationState { calculation: 999, ..Default::default() }.validate().is_err());
        assert!(VbaApplicationState { cursor: 4, ..Default::default() }.validate().is_err());
        assert!(VbaApplicationState { status_bar: Some("x".repeat(256)), ..Default::default() }.validate().is_err());
        let normalized = VbaApplicationState { cursor: 0, status_bar: Some(String::new()), ..Default::default() }.validate().unwrap();
        assert_eq!(normalized.cursor, CURSOR_DEFAULT);
        assert_eq!(normalized.status_bar, None);
        for directory_state in [
            VbaDirectoryState {current_drive:"Z".into(),directories:vec!["C:\\".into()]},
            VbaDirectoryState {current_drive:"CC".into(),directories:vec!["C:\\".into()]},
            VbaDirectoryState {current_drive:"C".into(),directories:vec!["relative".into()]},
        ] {
            assert!(VbaApplicationState {directory_state:Some(directory_state),..Default::default()}.validate().is_err());
        }
    }

    #[test]
    fn vba_directory_environment_survives_end_and_project_changes() {
        let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../tests/fixtures/vba/directory_lifetime.json")).unwrap();
        let package=include_bytes!("../../../tests/fixtures/vba/directory_lifetime.xlsm");
        let source=include_str!("../../../tests/fixtures/vba/directory_lifetime.bas");
        let mut session=None;let mut project=None;let mut book=oxicells_core::parse_xlsx(package).unwrap();
        let mut application_state=Some(VbaApplicationState {display_alerts:false,
            directory_state:Some(serde_json::from_value(fixture["initial_directory_state"].clone()).unwrap()),..Default::default()});
        for case in fixture["cases"].as_array().unwrap() {
            let next_project=case["project"].as_str().unwrap();
            if project!=Some(next_project) {session=None;book=oxicells_core::parse_xlsx(package).unwrap();project=Some(next_project);}
            book.calculation.compatibility_version=1;
            let mut context=failure_context();context.application_state=application_state;
            context.document_modules=Some(crate::vba_project::read_document_modules(package).unwrap());
            context.file_context=Some(file_io::FileContext {
            edit_revision: None, source_code_page: None,package_bytes:Some(package.to_vec()),full_name:Some(case["full_name"].as_str().unwrap().into()),read_only:Some(true),folders:serde_json::from_value(fixture["folders"].clone()).unwrap(),files:vec![]});
            let args=case["arguments"].as_array().unwrap().iter().map(|value|Value::String(value.as_str().unwrap().into())).collect();
            let outcome=execute_workbook_action_in_session(book,source,Some(case["procedure"].as_str().unwrap()),args,0,context,&mut session).unwrap();
            if case["expected_termination"].as_bool().unwrap() {
                assert_eq!(outcome.error.as_ref().map(|failure|failure.kind),Some("terminated"));
                assert_eq!(serde_json::to_value(&outcome.result).unwrap(),serde_json::json!({"type":"empty"}));
            } else {
                assert!(outcome.error.is_none(),"{:?}",outcome.error.as_ref().map(|failure|&failure.message));
                assert_eq!(serde_json::to_value(&outcome.result).unwrap(),serde_json::json!({"type":"string","value":case["expected"]}));
            }
            assert_eq!(serde_json::to_value(&outcome.application_state.directory_state).unwrap(),case["directory_state_after"]);
            application_state=Some(outcome.application_state);book=outcome.workbook;
        }
    }

    #[test]
    fn vba_filesystem_namespace_survives_end_mount_replay_and_project_changes() {
        let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../tests/fixtures/vba/namespace_lifetime.json")).unwrap();
        let package=include_bytes!("../../../tests/fixtures/vba/namespace_lifetime.xlsm");
        let source=include_str!("../../../tests/fixtures/vba/namespace_lifetime.bas");
        let mut session=None;let mut project=None;let mut book=oxicells_core::parse_xlsx(package).unwrap();
        let mut state=None;
        let mut application_state=Some(VbaApplicationState {display_alerts:false,
            directory_state:Some(serde_json::from_value(fixture["initial_directory_state"].clone()).unwrap()),..Default::default()});
        for (index,case) in fixture["cases"].as_array().unwrap().iter().enumerate() {
            let next_project=case["project"].as_str().unwrap();
            let changed=project!=Some(next_project);
            if changed {session=None;book=oxicells_core::parse_xlsx(package).unwrap();project=Some(next_project);}
            book.calculation.compatibility_version=1;
            let mut context=failure_context();context.application_state=application_state;
            if changed {context.file_system_state=state.take();}
            context.document_modules=Some(crate::vba_project::read_document_modules(package).unwrap());
            context.file_context=Some(file_io::FileContext {
            edit_revision: None, source_code_page: None,package_bytes:Some(package.to_vec()),full_name:Some(case["full_name"].as_str().unwrap().into()),read_only:Some(true),folders:serde_json::from_value(fixture["folders"].clone()).unwrap(),files:serde_json::from_value(fixture["files"].clone()).unwrap()});
            let args=case["arguments"].as_array().unwrap().iter().map(|value|Value::String(value.as_str().unwrap().into())).collect();
            let outcome=execute_workbook_action_in_session(book,source,Some(case["procedure"].as_str().unwrap()),args,0,context,&mut session).unwrap();
            if case["expected_termination"].as_bool().unwrap() {
                assert_eq!(outcome.error.as_ref().map(|failure|failure.kind),Some("terminated"),"step {index}");
                assert_eq!(serde_json::to_value(&outcome.result).unwrap(),serde_json::json!({"type":"empty"}));
            } else {
                assert!(outcome.error.is_none(),"step {index}: {:?}",outcome.error.as_ref().map(|failure|&failure.message));
                assert_eq!(serde_json::to_value(&outcome.result).unwrap(),serde_json::json!({"type":"string","value":case["expected"]}),"step {index}");
            }
            // The transport carries closed filesystem facts separately from
            // project storage, through actual serialization rather than Clone.
            state=Some(serde_json::from_slice::<file_io::FileSystemState>(&serde_json::to_vec(&outcome.file_system_state).unwrap()).unwrap());
            application_state=Some(outcome.application_state);book=outcome.workbook;
        }
    }

    #[test]
    fn vba_folder_operations_match_native_errors_and_partial_filesystem_effects() {
        let fixtures=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/vba");
        let mut count=0;
        for name in ["folder_mutations","folder_mutations_more","folder_mutations_edges"] {
            let fixture:serde_json::Value=serde_json::from_slice(&std::fs::read(fixtures.join(format!("{name}.json"))).unwrap()).unwrap();
            let package=std::fs::read(fixtures.join(fixture["package"].as_str().unwrap())).unwrap();
            let source=std::fs::read_to_string(fixtures.join(fixture["source"].as_str().unwrap())).unwrap();
            for case in fixture["cases"].as_array().unwrap() {
                let kind=case["kind"].as_i64().unwrap();
                let root=case["arguments"][1].as_str().unwrap().to_lowercase();let prefix=format!("{root}\\");
                let mut book=oxicells_core::parse_xlsx(&package).unwrap();book.calculation.compatibility_version=1;
                let mut context=failure_context();context.host_ansi_code_page=Some(AnsiCodePage::from_id(932).unwrap());
                context.application_state=Some(VbaApplicationState {display_alerts:false,
                    directory_state:Some(serde_json::from_value(fixture["initial_directory_state"].clone()).unwrap()),..Default::default()});
                context.document_modules=Some(crate::vba_project::read_document_modules(&package).unwrap());
                context.file_context=Some(file_io::FileContext {
            edit_revision: None, source_code_page: None,package_bytes:Some(package.clone()),full_name:Some(case["full_name"].as_str().unwrap().into()),read_only:Some(true),
                    folders:serde_json::from_value(case["folders"].clone()).unwrap(),files:serde_json::from_value(case["files"].clone()).unwrap()});
                let args=vec![Value::Integer(kind),Value::String(case["arguments"][1].as_str().unwrap().into())];
                let outcome=execute_workbook_action_in_session(book,&source,Some("FolderMutation"),args,0,context,&mut None).unwrap();
                assert!(outcome.error.is_none(),"case {kind}: {:?}",outcome.error.as_ref().map(|error|&error.message));
                assert_eq!(serde_json::to_value(&outcome.result).unwrap(),serde_json::json!({"type":"string","value":case["expected"]}),"case {kind}");
                let state=serde_json::to_value(&outcome.file_system_state).unwrap();
                let mut files:Vec<_>=state["files"].as_array().unwrap().iter().filter(|file|file["path"].as_str().unwrap().to_lowercase().starts_with(&prefix)).cloned().collect();
                let mut expected=case["expected_files"].as_array().unwrap().clone();
                files.sort_by(|a,b|a["path"].as_str().cmp(&b["path"].as_str()));expected.sort_by(|a,b|a["path"].as_str().cmp(&b["path"].as_str()));
                assert_eq!(files,expected,"case {kind} file bytes/paths");
                let folders:BTreeSet<_>=state["folders"].as_array().unwrap().iter().map(|path|path.as_str().unwrap().to_lowercase())
                    .filter(|path|*path==root || path.starts_with(&prefix)).collect();
                let expected_folders:BTreeSet<_>=serde_json::from_value(case["expected_folder_keys"].clone()).unwrap();
                assert_eq!(folders,expected_folders,"case {kind} folder namespace");
                let kept:BTreeSet<_>=expected.iter().map(|file|file["path"].as_str().unwrap()).collect();
                let deleted:BTreeSet<_>=case["files"].as_array().unwrap().iter().map(|file|file["path"].as_str().unwrap().to_string()).filter(|path|!kept.contains(path.as_str())).collect();
                assert_eq!(outcome.deleted_files.into_iter().collect::<BTreeSet<_>>(),deleted,"case {kind} deletion outputs");
                assert!(outcome.files.is_empty(),"case {kind} unexpectedly wrote files");
                count+=1;
            }
        }
        assert_eq!(count,58);
    }

