    #[test]
    fn copying_extended_icons_to_two_new_sheets_uses_distinct_ids() {
        let bytes = include_bytes!("../../../tests/fixtures/conditional/x14_icons.xlsx");
        let source = "Public Sub Change()\nDim original As Object: Set original=ActiveSheet\nWorksheets.Add\noriginal.Range(\"A2:A6\").Copy Range(\"F2\")\nWorksheets.Add\noriginal.Range(\"A2:A6\").Copy Range(\"F2\")\nEnd Sub";
        let result = execute_workbook_action_in_session(oxicells_core::parse_xlsx(bytes).unwrap(), source, Some("Change"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(result.error.is_none(), "{:?}", result.error.as_ref().map(|error| &error.message));
        let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap(); editor.apply_workbook(&result.workbook).unwrap();
        let reopened = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
        let copied: Vec<_> = reopened.sheets.iter().flat_map(|sheet| &sheet.conditional_rules)
            .filter(|rule| rule.visual_extension_only && rule.ranges.iter().any(|range| range.1 == 5))
            .map(|rule| rule.visual_extension_id.clone().unwrap()).collect();
        assert_eq!(copied.len(), 2);
        assert_ne!(copied[0], copied[1], "separate copied rules need independent extension ids");
    }

    #[test]
    fn extended_icons_copy_with_settings_to_same_or_new_sheet() {
        let bytes = include_bytes!("../../../tests/fixtures/conditional/x14_icons.xlsx");
        for (action, address, expected) in [
            ("Range(\"A2:A6\").Copy Range(\"E2\")", "E2", "$E$2:$E$6|1|True|True|=$B$1"),
            ("Dim original As Object: Set original=ActiveSheet\nWorksheets.Add\noriginal.Range(\"A2:A6\").Copy Range(\"F2\")", "F2", "$F$2:$F$6|1|True|True|=$B$1"),
        ] {
            let source = format!("Public Function Change() As String\nDim c As Object: Set c=Range(\"A2\").FormatConditions(1)\nc.ShowIconOnly=True: c.ReverseOrder=True\nc.IconCriteria(2).Type=4: c.IconCriteria(2).Value=\"=$B$1\"\n{action}\nChange=ReadRule()\nEnd Function\nPublic Function ReadRule() As String\nDim c As Object: Set c=Range(\"{address}\").FormatConditions(1)\nReadRule=c.AppliesTo.Address & \"|\" & CStr(c.Priority) & \"|\" & CStr(c.ShowIconOnly) & \"|\" & CStr(c.ReverseOrder) & \"|\" & CStr(c.IconCriteria(2).Value)\nEnd Function");
            let result = execute_workbook_action_in_session(oxicells_core::parse_xlsx(bytes).unwrap(), &source, Some("Change"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "{action}: {:?}", result.error.as_ref().map(|error| &error.message));
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}));
            let active = result.active_sheet;
            let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap(); editor.apply_workbook(&result.workbook).unwrap();
            let saved = editor.save().unwrap();
            let reopened = oxicells_core::parse_xlsx(&saved).unwrap();
            let copied = reopened.sheets[active].conditional_rules.iter().find(|rule| rule.visual_extension_only && rule.ranges.iter().any(|range| range.1 == if address == "E2" { 4 } else { 5 })).unwrap();
            assert!(copied.visual_extension_xml.as_deref().unwrap().contains("iconSet=\"3Stars\""));
            if address == "E2" {
                let original = reopened.sheets[active].conditional_rules.iter().find(|rule| rule.visual_extension_only && rule.ranges.iter().any(|range| range.1 == 0)).unwrap();
                assert_ne!(copied.visual_extension_id, original.visual_extension_id);
            }
            let result = execute_workbook_action_in_session(reopened, &source, Some("ReadRule"), vec![], active, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "{action}: {:?}", result.error.as_ref().map(|error| &error.message));
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}));
        }
    }

