    #[test]
    fn extended_only_icon_sets_are_visible_and_preserved() {
        let bytes = include_bytes!("../../../tests/fixtures/conditional/x14_icons.xlsx");
        let source = "Public Function ReadRule() As String\nDim c As Object, p As Object, col As Long\nFor col=1 To 3\nSet c=Cells(2,col).FormatConditions(1)\nReadRule=ReadRule & CStr(c.Type) & \":\" & CStr(c.IconCriteria.Count) & \":\"\nFor Each p In c.IconCriteria\nReadRule=ReadRule & CStr(p.Value) & \",\"\nNext p\nReadRule=ReadRule & \";\"\nNext col\nEnd Function\nPublic Function Change() As String\nRange(\"F1\").Value=42\nRange(\"D2:D6\").FormatConditions.AddDatabar\nChange=ReadRule()\nEnd Function\nPublic Function EditIcon() As String\nDim c As Object\nSet c=Range(\"A2\").FormatConditions(1)\nc.IconCriteria(2).Type=0: c.IconCriteria(2).Value=42: c.IconCriteria(2).Operator=5\nc.IconCriteria(3).Type=4: c.IconCriteria(3).Value=\"=$B$1\"\nc.ShowIconOnly=True: c.ReverseOrder=True\nEditIcon=ReadIcon()\nEnd Function\nPublic Function ReadIcon() As String\nDim c As Object, p As Object\nSet c=Range(\"A2\").FormatConditions(1)\nReadIcon=CStr(c.ShowIconOnly) & \"|\" & CStr(c.ReverseOrder) & \"|\"\nFor Each p In c.IconCriteria\nReadIcon=ReadIcon & CStr(p.Type) & \",\" & CStr(p.Value) & \",\" & CStr(p.Operator) & \";\"\nNext p\nEnd Function";
        let expected = serde_json::json!({"type":"string", "value":"6:3:0,33,67,;6:3:0,33,67,;6:5:0,20,40,60,80,;"});
        let workbook = oxicells_core::parse_xlsx(bytes).unwrap();
        assert_eq!(workbook.sheets[0].conditional_rules.len(), 3);
        let result = execute_workbook_action_in_session(workbook, source, Some("Change"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(result.error.is_none(), "{:?}", result.error.as_ref().map(|error| &error.message));
        assert_eq!(serde_json::to_value(&result.result).unwrap(), expected);
        let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap(); editor.apply_workbook(&result.workbook).unwrap();
        let saved = editor.save().unwrap();
        let reopened = oxicells_core::parse_xlsx(&saved).unwrap();
        let result = execute_workbook_action_in_session(reopened, source, Some("ReadRule"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(result.error.is_none());
        assert_eq!(serde_json::to_value(&result.result).unwrap(), expected);
        let result = execute_workbook_action_in_session(result.workbook, source, Some("EditIcon"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(result.error.is_none(), "{:?}", result.error.as_ref().map(|error| &error.message));
        let edited = serde_json::json!({"type":"string", "value":"True|True|3,0,7;0,42,5;4,=$B$1,7;"});
        assert_eq!(serde_json::to_value(&result.result).unwrap(), edited);
        let mut editor = oxicells_core::XlsxEditor::new(&saved).unwrap(); editor.apply_workbook(&result.workbook).unwrap();
        let reopened = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
        let result = execute_workbook_action_in_session(reopened, source, Some("ReadIcon"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(result.error.is_none());
        assert_eq!(serde_json::to_value(&result.result).unwrap(), edited);
        let delete_source = "Public Sub Change()\nRange(\"A2\").FormatConditions.Delete\nEnd Sub";
        let result = execute_workbook_action_in_session(oxicells_core::parse_xlsx(bytes).unwrap(), delete_source, Some("Change"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(result.error.is_none());
        let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap(); editor.apply_workbook(&result.workbook).unwrap();
        let reopened = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
        let rule = reopened.sheets[0].conditional_rules.iter().find(|rule| rule.visual_extension_only && rule.priority == 1).unwrap();
        assert_eq!(rule.ranges, vec![(2, 0, 5, 0)]);
    }

