    #[test]
    fn conditional_formats_are_added_read_worked_out_and_taken_away() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Ask() As String
               Dim out As String, fc As Object, fc2 As Object
               On Error Resume Next
               Range(\"A1\").Value = 1
               Range(\"A2\").Value = 3
               Range(\"A3\").Value = \"abc\"
               Set fc = Range(\"A1:A4\").FormatConditions.Add(Type:=xlCellValue, Operator:=xlGreater, Formula1:=\"2\")
               fc.Font.Bold = True
               fc.Interior.Color = 65535
               out = TypeName(fc) & \"/\" & fc.Formula1 & \"/\" & fc.AppliesTo.Address & \"/\" & fc.Priority & \"/\" & fc.StopIfTrue & \"|\"
               out = out & Range(\"A1:B4\").FormatConditions.Count & Range(\"B1\").FormatConditions.Count & \"/\" & Range(\"A2\").Font.Bold & \"/\" & Range(\"A2\").DisplayFormat.Font.Bold & Range(\"A1\").DisplayFormat.Font.Bold & Range(\"A3\").DisplayFormat.Font.Bold & \"/\" & Range(\"A2\").DisplayFormat.Interior.Color & \"|\"
               Set fc2 = Range(\"A1:A4\").FormatConditions.Add(Type:=xlExpression, Formula1:=\"=$A1<2\")
               fc2.Font.Italic = True
               fc2.Interior.Color = 255
               fc2.SetFirstPriority
               out = out & fc.Priority & fc2.Priority & \"/\" & Range(\"A1:A4\").FormatConditions(1).Formula1 & \"/\" & Range(\"A1\").DisplayFormat.Font.Italic & Range(\"A1\").DisplayFormat.Interior.Color & \"|\"
               Range(\"A5\").FormatConditions.Add Type:=1, Operator:=1, Formula1:=\"1\"
               out = out & Err.Number & \"|\"
               Err.Clear
               Range(\"A3\").FormatConditions.Delete
               out = out & Range(\"A1:A4\").FormatConditions.Count & Range(\"A3\").FormatConditions.Count & \"/\" & fc.AppliesTo.Address & \"|\"
               Range(\"A1\").Copy Range(\"C1\")
               out = out & Range(\"C1\").FormatConditions.Count & \"/\" & Range(\"C1\").FormatConditions(1).AppliesTo.Address & \"|\"
               Range(\"A1\").ClearFormats
               out = out & Range(\"A1\").FormatConditions.Count & \"/\" & Range(\"A1:A4\").FormatConditions.Count
               Ask = out
             End Function
",
        )
        .unwrap();
        let answer = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Ask", vec![], &mut host).unwrap()
        };
        assert_eq!(
            answer,
            Value::String(
                "FormatCondition/=2/$A$1:$A$4/1/True|10/False/TrueFalseTrue/65535|21/=$A1<2/True255|449|20/$A$1:$A$2,$A$4|2/$C$1|0/2"
                    .to_string()
            )
        );
    }

    /// Data validation is added, read, checked and taken away as Excel does
    /// it.
    ///
    /// Measured against Excel: a bare cell's `Validation.Type` is 1004; a
    /// list validation reads back its parts with the flags all True; `Value`
    /// says whether the cell passes -- a blank passes with `IgnoreBlank`; a
    /// second `Add` is 1004; `Modify` changes the parts; a whole-number rule
    /// refuses 15.5 and text; `Between` wants both bounds; a range validated
    /// unevenly is 1004; a list is matched case-sensitively on the trimmed
    /// text; a cell with no validation passes; `Clear` takes it and
    /// `ClearContents` does not; a copy carries it; and an inserted row
    /// moves it.
    #[test]
    fn data_validation_is_added_read_checked_and_taken_away() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Ask() As String
               Dim out As String, v As Variant
               On Error Resume Next
               v = Range(\"D1\").Validation.Type
               out = Err.Number & \"|\"
               Err.Clear
               Range(\"D1\").Validation.Add Type:=xlValidateList, Formula1:=\"a,b,c\"
               With Range(\"D1\").Validation
                 out = out & .Type & .AlertStyle & .Operator & \"/\" & .Formula1 & \"/\" & .IgnoreBlank & .InCellDropdown & \"/\" & .Value & \"|\"
               End With
               Range(\"D1\").Value = \"B\"
               out = out & Range(\"D1\").Validation.Value
               Range(\"D1\").Value = \" b\"
               out = out & Range(\"D1\").Validation.Value & \"|\"
               Range(\"D1\").Validation.Add Type:=1, Formula1:=\"1\", Formula2:=\"9\"
               out = out & Err.Number & \"|\"
               Err.Clear
               Range(\"D1\").Validation.Modify Type:=1, Operator:=xlGreater, Formula1:=\"10\"
               out = out & Range(\"D1\").Validation.Type & Range(\"D1\").Validation.Operator & \"/\"
               Range(\"D1\").Value = 15
               out = out & Range(\"D1\").Validation.Value
               Range(\"D1\").Value = 15.5
               out = out & Range(\"D1\").Validation.Value
               Range(\"D1\").Value = \"x\"
               out = out & Range(\"D1\").Validation.Value & \"|\"
               Range(\"D2\").Validation.Add Type:=1, Formula1:=\"1\"
               out = out & Err.Number & \"|\"
               Err.Clear
               Range(\"D3:D4\").Validation.Add Type:=2, Operator:=1, Formula1:=\"1\", Formula2:=\"10\"
               v = Range(\"D3:D5\").Validation.Type
               out = out & Err.Number & \"/\" & Range(\"D3:D4\").Validation.Formula2 & \"/\" & Range(\"D5\").Validation.Value & \"|\"
               Err.Clear
               Range(\"D3\").Copy Range(\"E3\")
               Range(\"D3\").ClearContents
               Range(\"D4\").Clear
               v = Range(\"D4\").Validation.Type
               out = out & Range(\"E3\").Validation.Type & Range(\"D3\").Validation.Type & Err.Number & \"|\"
               Err.Clear
               Rows(1).Insert
               out = out & Range(\"D4\").Validation.Type
               Ask = out
             End Function
",
        )
        .unwrap();
        let answer = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Ask", vec![], &mut host).unwrap()
        };
        assert_eq!(
            answer,
            Value::String(
                "1004|311/a,b,c/TrueTrue/True|FalseTrue|1004|15/TrueFalseFalse|1004|1004/10/True|221004|2"
                    .to_string()
            )
        );
    }

    /// A stretch of a cell's characters is dressed, read, replaced and taken
    /// out as Excel does it.
    ///
    /// Measured against Excel: `Characters(1, 5).Font.Bold = True` on
    /// `Hello World` leaves the first word bold, the rest not, and the cell's
    /// own `Font.Bold` Null; `Characters(7, 5).Text = "There"` keeps the
    /// dress of what it replaces; a deleted character closes the gap; text
    /// put in at a point wears the dress of the character before it; a
    /// numeric cell dresses whole; the whole cell made bold keeps a red
    /// word red; a new value takes the runs off; a copy carries them; a
    /// character bolded and unbolded leaves `Font.Bold` a plain False; and
    /// `Count` answers the start when a length was given and the whole
    /// text's length when not.
    #[test]
    fn characters_are_dressed_read_replaced_and_taken_out() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Ask() As String
               Dim out As String, v As Variant
               On Error Resume Next
               Range(\"B1\").Value = \"Hello World\"
               Range(\"B1\").Characters(1, 5).Font.Bold = True
               out = Range(\"B1\").Characters(1, 5).Font.Bold & \"/\" & Range(\"B1\").Characters(6, 6).Font.Bold & \"/\" & TypeName(Range(\"B1\").Font.Bold) & \"/\" & Range(\"B1\").Characters(7).Text & \"|\"
               Range(\"B1\").Characters(7, 5).Text = \"There\"
               Range(\"B1\").Characters(7, 5).Font.Color = 255
               Range(\"B1\").Characters(6, 1).Delete
               Range(\"B1\").Characters(6, 0).Insert \"-\"
               out = out & Range(\"B1\").Value & \"/\" & Range(\"B1\").Characters(6, 1).Font.Bold & Range(\"B1\").Characters(6, 1).Font.Color & \"/\" & Range(\"B1\").Characters(7, 5).Font.Color & \"|\"
               out = out & Range(\"B1\").Characters(1, 5).Count & Range(\"B1\").Characters(7).Count & \"|\"
               Range(\"B1\").Font.Bold = True
               out = out & Range(\"B1\").Characters(7, 5).Font.Bold & TypeName(Range(\"B1\").Font.Color) & \"|\"
               Range(\"B1\").Copy Range(\"B2\")
               Range(\"B1\").Value = \"New\"
               out = out & Range(\"B2\").Characters(7, 5).Font.Color & \"/\" & Range(\"B1\").Characters(1, 3).Font.Color & Range(\"B1\").Font.Bold & \"|\"
               Range(\"B3\").Value = 12345
               Range(\"B3\").Characters(1, 2).Font.Bold = True
               out = out & TypeName(Range(\"B3\").Value) & Range(\"B3\").Font.Bold & \"|\"
               Range(\"B4\").Value = \"abc\"
               Range(\"B4\").Characters(2, 1).Font.Bold = True
               Range(\"B4\").Characters(2, 1).Font.Bold = False
               v = Range(\"B4\").Font.Bold
               out = out & TypeName(v) & v
               Ask = out
             End Function
",
        )
        .unwrap();
        let answer = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Ask", vec![], &mut host).unwrap()
        };
        assert_eq!(
            answer,
            Value::String(
                "True/False/Null/World|Hello-There/True0/255|111|TrueNull|255/0True|DoubleTrue|BooleanFalse"
                    .to_string()
            )
        );
    }

    /// A hyperlink is added, read, replaced, moved and taken away as Excel
    /// does it.
    ///
    /// Measured against Excel: `Hyperlinks.Add` answers a Hyperlink; the
    /// address is kept with its `/` after a bare host; an empty anchor cell
    /// shows the address, `TextToDisplay` when given, and a cell with
    /// something in it keeps that; the cell is dressed in `Hyperlink`, which
    /// joins the workbook's styles right after `Percent`; a second link on
    /// the same cell takes the first one's place and number; the collection
    /// counts in the order added; `Delete` puts the cell back to `Normal`;
    /// `ClearContents` takes the link and leaves the underline; and an
    /// inserted row moves it.
    #[test]
    fn a_hyperlink_is_added_read_replaced_moved_and_taken_away() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Ask() As String
               Dim out As String, h As Object
               On Error Resume Next
               out = ActiveSheet.Hyperlinks.Count & \"/\" & ActiveWorkbook.Styles.Count & \"|\"
               Set h = ActiveSheet.Hyperlinks.Add(Anchor:=Range(\"C1\"), Address:=\"http://x.example\")
               out = out & TypeName(h) & \"/\" & Range(\"C1\").Value & \"/\" & h.Address & \"/\" & h.Range.Address & \"|\"
               out = out & Range(\"C1\").Font.Color & \"/\" & Range(\"C1\").Font.Underline & \"/\" & Range(\"C1\").Style.Name & \"/\" & ActiveWorkbook.Styles.Count & \"/\" & ActiveWorkbook.Styles(29).Name & \"|\"
               ActiveSheet.Hyperlinks.Add Range(\"C2\"), \"https://x.example?q=1\", , \"tip\", \"Click\"
               Range(\"C3\").Value = \"keep\"
               ActiveSheet.Hyperlinks.Add Range(\"C3\"), \"mailto:a@b.c\"
               out = out & Range(\"C2\").Value & \"/\" & ActiveSheet.Hyperlinks(2).Address & \"/\" & ActiveSheet.Hyperlinks(2).ScreenTip & \"/\" & Range(\"C3\").Value & \"|\"
               ActiveSheet.Hyperlinks.Add Range(\"C1\"), \"http://y.example\"
               out = out & ActiveSheet.Hyperlinks.Count & \"/\" & Range(\"C1\").Value & \"/\" & ActiveSheet.Hyperlinks(1).Address & \"/\" & h.Address & \"|\"
               out = out & Range(\"C1:C3\").Hyperlinks.Count & \"/\" & Range(\"C1:C3\").Hyperlinks(2).TextToDisplay & \"|\"
               ActiveSheet.Hyperlinks(2).Delete
               out = out & ActiveSheet.Hyperlinks.Count & \"/\" & Range(\"C2\").Value & \"/\" & Range(\"C2\").Font.Underline & \"/\" & Range(\"C2\").Style.Name & \"|\"
               Range(\"C3\").ClearContents
               out = out & Range(\"C3\").Hyperlinks.Count & \"/\" & Range(\"C3\").Font.Underline & \"|\"
               Rows(1).Insert
               out = out & Range(\"C1\").Hyperlinks.Count & Range(\"C2\").Hyperlinks.Count & \"/\" & Range(\"C2\").Hyperlinks(1).Address
               Ask = out
             End Function
",
        )
        .unwrap();
        let answer = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Ask", vec![], &mut host).unwrap()
        };
        assert_eq!(
            answer,
            Value::String(
                "0/47|Hyperlink/http://x.example//http://x.example//$C$1|8812614/2/Hyperlink/48/Hyperlink|Click/https://x.example/?q=1/tip/keep|3/http://x.example//http://y.example//http://y.example/|3/Click|2/Click/-4142/Normal|0/2|01/http://y.example/"
                    .to_string()
            )
        );
    }

    /// A tint moves a theme colour the way Excel moves it.
    ///
    /// Every pair is a colour Excel answered for `Interior.Color` after
    /// `ThemeColor` and `TintAndShade` were set: the first accent under
    /// sixteen tints, black under eleven, the fourth accent under seven. The
    /// ones a floating-point HLS gets wrong by one or two are in here.
    #[test]
    fn a_tint_moves_a_theme_colour_the_way_excel_does() {
        let accent1 = 8_544_277;
        let accent4 = 13_999_631;
        let measured: [(i64, f64, i64); 34] = [
            (accent1, 0.8, 16_115_392),
            (accent1, 0.6, 15_453_315),
            (accent1, 0.4, 14_791_492),
            (accent1, 0.5, 15_122_020),
            (accent1, 0.25, 13_539_874),
            (accent1, -0.25, 6_375_440),
            (accent1, -0.5, 4_206_603),
            (accent1, 0.9, 16_446_176),
            (accent1, -0.9, 854_530),
            (accent1, 0.35, 14_593_078),
            (accent1, 1.0, 16_777_215),
            (accent1, -1.0, 0),
            (accent1, 0.05, 9_530_391),
            (accent1, -0.05, 8_018_708),
            (accent1, 0.75, 15_916_720),
            (accent1, -0.75, 2_037_509),
            (0, 0.8, 13_421_772),
            (0, 0.6, 10_066_329),
            (0, 0.4, 6_710_886),
            (0, 0.5, 8_421_504),
            (0, 0.25, 4_210_752),
            (0, -0.25, 0),
            (0, 0.9, 15_132_390),
            (0, 0.35, 5_855_577),
            (0, 1.0, 16_777_215),
            (0, 0.05, 855_309),
            (0, 0.75, 12_566_463),
            (accent4, 0.8, 16_510_410),
            (accent4, 0.6, 16_309_396),
            (accent4, 0.4, 15_977_313),
            (accent4, 0.5, 16_110_458),
            (accent4, 0.25, 15_842_872),
            (accent4, -0.25, 10_384_908),
            (accent4, -0.5, 6_901_511),
        ];
        for (colour, tint, expected) in measured {
            assert_eq!(tinted(colour, tint), expected, "{colour} tinted {tint}");
        }
        assert_eq!(quantised_tint(0.8), 26_213.0 / 32_767.0);
        assert_eq!(quantised_tint(0.4), 13_106.0 / 32_767.0);
        assert_eq!(quantised_tint(-0.25), -8_191.0 / 32_767.0);
    }

    #[test]
    fn color_format_brightness_matches_excel_text_forecolor() {
        let accent1 = THEME_COLOURS[4];
        let measured = [
            (-1.0, 0), (-0.75, 2_103_301), (-0.4, 5_126_669), (-0.1, 7_689_747),
            (0.0, 8_544_277), (0.1, 10_581_786), (0.4, 14_790_982),
            (0.75, 15_982_258), (1.0, 16_777_215),
        ];
        for (brightness, expected) in measured {
            assert_eq!(color_format_brightness(accent1, brightness), expected, "Brightness={brightness}");
        }
        assert_eq!(color_format_brightness(255, 0.4), 6_711_039, "RGB red keeps its hue");
        for (theme, expected) in [(1, 0), (2, 16_777_215), (3, 4_270_094), (4, 15_263_976), (5, accent1)] {
            assert_eq!(office_theme_colour(theme), expected, "ObjectThemeColor={theme}");
        }
    }

    #[test]
    fn theme_scheme_color_tracks_excel_brightness_transitions() {
        let baseline = [8, 9, 56, 9, 21, 53, 57, 40, 25, 57, 49, 25];
        for (theme, expected) in (1..=12).zip(baseline) {
            let rgb = office_theme_colour(theme);
            assert_eq!(scheme_color_for_style(Some(theme), None, rgb, 0.0), expected);
        }
        let measured = [
            (8, 8, 23), (55, 9, 9), (56, 56, 49), (23, 9, 9),
            (56, 21, 49), (60, 53, 47), (58, 57, 57), (21, 40, 48),
            (25, 25, 25), (57, 57, 11), (57, 49, 49), (25, 25, 25),
        ];
        for (theme, (dark, base, light)) in (1..=12).zip(measured) {
            let rgb = office_theme_colour(theme);
            assert_eq!(scheme_color_for_style(Some(theme), None, color_format_brightness(rgb, -0.4), -0.4), dark, "theme {theme} dark tint");
            assert_eq!(scheme_color_for_style(Some(theme), None, rgb, 0.0), base, "theme {theme} base");
            assert_eq!(scheme_color_for_style(Some(theme), None, color_format_brightness(rgb, 0.4), 0.4), light, "theme {theme} light tint");
        }
        // Excel COM: custom Accent1 #CC6600 at Brightness 0.4 resolves to
        // RGB 4695039 and SchemeColor 52 (the fixed default-theme table said 49).
        assert_eq!(scheme_color_for_style(Some(5), None, 4_695_039, 0.4), 52);
    }

    #[test]
    fn direct_rgb_scheme_color_uses_excel_canonical_palette_indices() {
        // Excel COM: after assigning ColorFormat.RGB, duplicate legacy colors
        // resolve to the canonical 8..63 color-scheme index.
        for (rgb, expected) in [
            (0, 8),
            (16_777_215, 9),
            (255, 10),
            (65_280, 11),
            (16_711_680, 12),
            (8_421_504, 23),
            (39_423, 52),
            (13_209, 60),
        ] {
            assert_eq!(scheme_color_for_style(None, None, rgb, 0.0), expected, "RGB={rgb}");
        }
    }

    #[test]
    fn windows_hls_conversion_matches_color_rgb_to_hls_samples() {
        // Values were captured from shlwapi!ColorRGBToHLS on Windows. The
        // integer formula was also compared against the API for 13,312
        // independently sampled RGB values, with no component mismatches.
        for (rgb, expected) in [
            ([255, 0, 0], WindowsHls { hue: 0, luminance: 120, saturation: 240 }),
            ([0, 255, 0], WindowsHls { hue: 80, luminance: 120, saturation: 240 }),
            ([0, 0, 255], WindowsHls { hue: 160, luminance: 120, saturation: 240 }),
            ([142, 120, 56], WindowsHls { hue: 30, luminance: 93, saturation: 104 }),
            ([87, 119, 190], WindowsHls { hue: 148, luminance: 130, saturation: 106 }),
        ] {
            let actual = windows_hls_from_rgb(rgb[0], rgb[1], rgb[2]);
            assert_eq!(
                (actual.hue, actual.luminance, actual.saturation),
                (expected.hue, expected.luminance, expected.saturation),
                "RGB={rgb:?}"
            );
        }
    }

    #[test]
    fn direct_rgb_scheme_color_quantizes_unmatched_colors_like_excel_samples() {
        // Excel 16 COM samples, including both sides of the measured
        // near-neutral spread boundary (10 -> grayscale, 11 -> HLS).
        for (red, green, blue, expected) in [
            (79, 75, 84, 63),
            (197, 197, 207, 22),
            (11, 20, 22, 8),
            (142, 120, 56, 51),
            (229, 157, 254, 46),
            (104, 43, 3, 60),
            (28, 51, 148, 62),
            (108, 186, 251, 44),
        ] {
            let color = red | (green << 8) | (blue << 16);
            assert_eq!(
                scheme_color_for_style(None, None, color, 0.0),
                expected,
                "RGB=({}, {}, {})",
                red,
                green,
                blue
            );
        }
    }

    #[test]
    fn direct_rgb_scheme_color_uses_the_first_exact_workbook_palette_slot() {
        let custom = 4_402_555;
        let mut palette = COLOUR_PALETTE;
        palette[19] = custom;
        assert_eq!(scheme_color_for_style_in_palette(None, None, custom, 0.0, &palette), 27);

        // Excel COM: moving red and white in Workbook.Colors moves their
        // direct-RGB SchemeColor result too; exact current-palette matches
        // take precedence over their canonical 10/9 indices.
        palette = COLOUR_PALETTE;
        palette[2] = custom;
        palette[19] = 255;
        assert_eq!(scheme_color_for_style_in_palette(None, None, 255, 0.0, &palette), 27);

        palette = COLOUR_PALETTE;
        palette[1] = custom;
        palette[29] = 16_777_215;
        assert_eq!(scheme_color_for_style_in_palette(None, None, 16_777_215, 0.0, &palette), 37);

        palette[19] = custom;
        palette[29] = custom;
        assert_eq!(scheme_color_for_style_in_palette(None, None, custom, 0.0, &palette), 9);
    }

    #[test]
    fn direct_rgb_scheme_color_quantizes_against_the_current_workbook_palette() {
        // Excel 16 COM: after Workbook.Colors(20) becomes RGB(20,200,20),
        // its HLS-identical neighbour RGB(21,200,20) resolves to scheme 27.
        let mut palette = COLOUR_PALETTE;
        palette[19] = 1_362_940;
        assert_eq!(
            scheme_color_for_style_in_palette(None, None, 1_362_941, 0.0, &palette),
            27,
        );

        // Excel 16 COM: moving gray slot 16 to RGB(224,224,224) moves the
        // direct-gray transition: input gray 210 now selects that slot.
        palette = COLOUR_PALETTE;
        palette[15] = 14_737_632;
        assert_eq!(
            scheme_color_for_style_in_palette(None, None, 13_816_530, 0.0, &palette),
            23,
        );

        // When canonical red/black have been removed from Workbook.Colors,
        // Excel resolves them against the remaining palette rather than
        // returning their old built-in scheme indices.
        palette = COLOUR_PALETTE;
        palette[2] = 1_362_940;
        assert_eq!(
            scheme_color_for_style_in_palette(None, None, 255, 0.0, &palette),
            53,
        );
        palette = COLOUR_PALETTE;
        palette[0] = 1_362_940;
        assert_eq!(
            scheme_color_for_style_in_palette(None, None, 0, 0.0, &palette),
            63,
        );
    }

    #[test]
    fn direct_rgb_neutrals_use_near_gray_entries_when_exact_grays_are_absent() {
        // Excel 16 COM: palette entries whose channel spread is at most ten
        // remain neutral candidates even when they are not exact grays.
        let mut palette = COLOUR_PALETTE;
        for (slot, color) in [
            (0, 197_121),
            (1, 16_645_885),
            (14, 13_150_900),
            (15, 7_900_290),
            (47, 10_850_715),
            (55, 4_600_380),
        ] {
            palette[slot] = color;
        }
        assert!(!palette.iter().any(|color| {
            let red = color & 0xff;
            red == ((color >> 8) & 0xff) && red == ((color >> 16) & 0xff)
        }));
        for (color, expected) in [
            (0, 8),
            (20 * 0x010101, 8),
            (80 * 0x010101, 8),
            (128 * 0x010101, 9),
            (210 * 0x010101, 9),
            (255 * 0x010101, 9),
            (5 | (5 << 8) | (12 << 16), 8),
            (210 | (210 << 8) | (215 << 16), 9),
        ] {
            assert_eq!(
                scheme_color_for_style_in_palette(None, None, color, 0.0, &palette),
                expected,
                "RGB={color}"
            );
        }
    }

    #[test]
    fn direct_rgb_neutrals_use_hls_when_the_palette_has_no_neutral_entries() {
        // Excel 16 COM: when no Workbook.Colors entry has channel spread <=10,
        // low-chroma RGB is resolved against all 56 entries with the HLS rule.
        let mut palette = COLOUR_PALETTE;
        for (slot, color) in [
            (0, 255),
            (1, 20),
            (14, 13_150_900),
            (15, 7_900_290),
            (47, 10_850_715),
            (55, 4_600_380),
        ] {
            palette[slot] = color;
        }
        assert!(!palette.iter().any(|color| {
            let channels = [color & 0xff, (color >> 8) & 0xff, (color >> 16) & 0xff];
            channels.iter().max().unwrap() - channels.iter().min().unwrap() <= 10
        }));
        for (color, expected) in [
            (0, 63),
            (120 * 0x010101, 54),
            (128 * 0x010101, 54),
            (200 * 0x010101, 22),
            (255 * 0x010101, 22),
            (5 | (5 << 8) | (12 << 16), 63),
            (128 | (130 << 8) | (135 << 16), 54),
        ] {
            assert_eq!(
                scheme_color_for_style_in_palette(None, None, color, 0.0, &palette),
                expected,
                "RGB={color}"
            );
        }
    }

    #[test]
    fn direct_rgb_scheme_color_matches_excel_for_every_grayscale_value() {
        // Excel 16 COM measured all 256 RGB(gray, gray, gray) values. These
        // ranges are the exact transitions among its six achromatic entries.
        for gray in 0..=255 {
            let expected = match gray {
                0..=25 => 8,
                26..=89 => 63,
                90..=139 => 23,
                140..=170 => 55,
                171..=223 => 22,
                _ => 9,
            };
            assert_eq!(
                scheme_color_for_style(None, None, gray * 0x010101, 0.0),
                expected,
                "gray {gray}"
            );
        }
    }

