    /// Theme colours are set and read on a font, a fill and an edge.
    ///
    /// Measured against Excel: a bare font answers ThemeColor 2 and a bare
    /// fill xlNone; a colour given by number answers error 5 on the font and
    /// 0 on the fill; giving a theme colour puts the tint back to 0; a tint
    /// on a bare font tints black; a theme colour out of the twelve is error
    /// 9 and a tint past 1 is error 5; `ClearFormats` forgets; a copy carries;
    /// and `20% - アクセンチE1` is the first accent at eight tenths.
    #[test]
    fn theme_colours_are_set_and_read() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Ask() As String
               Dim out As String, v As Variant
               On Error Resume Next
               out = Range(\"A1\").Font.ThemeColor & \"/\" & Range(\"A1\").Interior.ThemeColor & \"|\"
               Range(\"A1\").Interior.ThemeColor = 5
               Range(\"A1\").Interior.TintAndShade = 0.6
               Range(\"A1\").Interior.ThemeColor = 6
               out = out & Range(\"A1\").Interior.TintAndShade & \"/\" & Range(\"A1\").Interior.Color & \"|\"
               Range(\"A2\").Font.ThemeColor = 5
               Range(\"A2\").Font.TintAndShade = -0.25
               out = out & Range(\"A2\").Font.Color & \"/\" & Range(\"A2\").Font.ThemeColor & \"|\"
               Range(\"A3\").Font.TintAndShade = 0.5
               out = out & Range(\"A3\").Font.Color & \"/\" & Range(\"A3\").Font.ThemeColor & \"|\"
               Range(\"A4\").Font.Color = 255
               v = Range(\"A4\").Font.ThemeColor
               out = out & Err.Number & \"|\"
               Err.Clear
               Range(\"A5\").Interior.Color = 255
               out = out & Range(\"A5\").Interior.ThemeColor & \"|\"
               Range(\"A6\").Interior.ThemeColor = 13
               out = out & Err.Number
               Err.Clear
               Range(\"A6\").Interior.TintAndShade = 1.5
               out = out & Err.Number & \"|\"
               Err.Clear
               Range(\"A7\").Borders(9).ThemeColor = 5
               Range(\"A7\").Borders(9).TintAndShade = 0.4
               out = out & Range(\"A7\").Borders(9).Color & \"/\" & Range(\"A7\").Borders(9).ThemeColor & \"|\"
               Range(\"A8\").Style = \"20% - アクセント 1\"
               out = out & Range(\"A8\").Interior.ThemeColor & \"/\" & Range(\"A8\").Interior.TintAndShade & \"/\" & Range(\"A8\").Font.ThemeColor & \"|\"
               Range(\"A8\").Copy Range(\"B8\")
               Range(\"A8\").ClearFormats
               out = out & Range(\"A8\").Interior.ThemeColor & \"/\" & Range(\"B8\").Interior.ThemeColor
               Ask = out
             End Function
",
        )
        .unwrap();
        let answer = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Ask", vec![], &mut host).unwrap()
        };
        assert_eq!(
            answer,
            Value::String(
                "2/-4142|0/3305961|6375440/5|8421504/2|5|0|95|14791492/5|5/0.799981688894314/2|-4142/5"
                    .to_string()
            )
        );
    }

    /// A cell style is applied by name, and reports what it includes.
    ///
    /// Measured on a Japanese Office: `Percent` sets `0%` and leaves a bold
    /// cell bold; `Normal` takes everything back; `見出し 1` is bold 15pt in
    /// the theme's dark colour with a thick accent rule under it; `良い` is a
    /// green face on a green fill; the name is matched without regard to case
    /// or edges and the Japanese name will do, while `Good`, `Heading 1` and
    /// a number are error 450; a range whose cells wear different styles
    /// answers Nothing; `ClearFormats` puts a cell back to `Normal`; a copy
    /// carries the style; and `Styles` counts forty-seven, the first of them
    /// `20% - 郢�E�・�E�郢�E�・�E�郢�E�・�E�郢晢�E��E�郢昴・1`.
    #[test]
    fn a_cell_style_is_applied_by_name() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Ask() As String
               Dim out As String
               On Error Resume Next
               Range(\"A1\").Value = 7
               Range(\"A1\").Font.Bold = True
               Range(\"A1\").Style = \"Percent\"
               out = Range(\"A1\").NumberFormat & \"/\" & Range(\"A1\").Font.Bold & \"/\" & Range(\"A1\").Style.Name & \"|\"
               Range(\"A1\").Style = \"Normal\"
               out = out & Range(\"A1\").NumberFormat & \"/\" & Range(\"A1\").Font.Bold & \"|\"
               Range(\"A2\").Style = \"\u{898b}\u{51fa}\u{3057} 1\"
               out = out & Range(\"A2\").Font.Bold & Range(\"A2\").Font.Size & \"/\" & Range(\"A2\").Font.Color & \"/\" & Range(\"A2\").Borders(9).LineStyle & Range(\"A2\").Borders(9).Weight & \"/\" & Range(\"A2\").Borders(9).Color & \"/\" & Range(\"A3\").Borders(8).Weight & \"|\"
               Range(\"A4\").Style = \" \u{826f}\u{3044} \"
               out = out & Range(\"A4\").Font.Color & \"/\" & Range(\"A4\").Interior.Color & \"|\"
               Range(\"A5\").Style = \"percent\"
               Range(\"A6\").Style = \"\u{30d1}\u{30fc}\u{30bb}\u{30f3}\u{30c8}\"
               out = out & Range(\"A5\").NumberFormat & Range(\"A6\").NumberFormat & \"|\"
               Range(\"A7\").Style = \"Good\"
               out = out & Err.Number
               Err.Clear
               Range(\"A7\").Style = \"Heading 1\"
               out = out & Err.Number
               Err.Clear
               Range(\"A7\").Style = 28
               out = out & Err.Number & \"|\"
               Err.Clear
               out = out & (Range(\"A5:A7\").Style Is Nothing) & (Range(\"A5:A6\").Style Is Nothing) & \"|\"
               Range(\"A2\").ClearFormats
               out = out & Range(\"A2\").Style.Name & \"|\"
               Range(\"A4\").Copy Range(\"B4\")
               out = out & Range(\"B4\").Style.Name & \"|\"
               out = out & ActiveWorkbook.Styles.Count & \"/\" & ActiveWorkbook.Styles(1).Name & \"/\" & ActiveWorkbook.Styles(\"Comma\").NumberFormat & \"/\" & TypeName(Range(\"A1\").Style) & \"/\" & Range(\"A1\").Style
               Ask = out
             End Function
",
        )
        .unwrap();
        let answer = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Ask", vec![], &mut host).unwrap()
        };
        assert_eq!(
            answer,
            Value::String(
                "0%/True/Percent|General/False|True15/4270094/14/8544277/4|24832/13561798|0%0%|450450450|TrueFalse|Normal|\u{826f}\u{3044}|47/20% - \u{30a2}\u{30af}\u{30bb}\u{30f3}\u{30c8} 1/_(* #,##0.00_);_(* (#,##0.00);_(* \"-\"??_);_(@_)/Style/Normal"                    .to_string()
            )
        );
    }

    /// An edge takes a colour, and a bare edge given one grows a thin line.
    ///
    /// Measured against Excel: a bare edge answers Color 0 and ColorIndex
    /// xlColorIndexNone; `Borders(xlEdgeBottom).Color = 255` on it reads back
    /// LineStyle 1, Weight 2, Color 255, ColorIndex 3; edges that disagree
    /// answer 0; `Range.Borders.Color` lines every edge of every cell, the
    /// inside ones too; a colour out of range reads back 0; and a cell reads
    /// the edge it shares with its neighbour.
    #[test]
    fn an_edge_takes_a_colour() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Ask() As String
               Dim out As String
               On Error Resume Next
               Set r = Range(\"B2\")
               out = r.Borders(9).Color & \"/\" & r.Borders(9).ColorIndex & \"|\"
               r.Borders(9).Color = 255
               out = out & r.Borders(9).LineStyle & \"/\" & r.Borders(9).Weight & \"/\" & r.Borders(9).Color & \"/\" & r.Borders(9).ColorIndex & \"|\"
               r.Borders(8).LineStyle = 1
               r.Borders(8).Weight = 4
               r.Borders(8).Color = 65280
               out = out & r.Borders(8).Weight & \"/\" & r.Borders(8).Color & \"/\" & r.Borders.Color & \"|\"
               Range(\"D4:E5\").Borders.Color = 16711680
               out = out & Range(\"D4\").Borders(7).LineStyle & \"/\" & Range(\"D4\").Borders(7).Color & \"/\" & Range(\"D4:E5\").Borders(11).LineStyle & \"/\" & Range(\"D4:E5\").Borders.Color & \"|\"
               Range(\"G1\").Borders(9).ColorIndex = 3
               out = out & Range(\"G1\").Borders(9).Color & Range(\"G1\").Borders(9).LineStyle & \"|\"
               Range(\"G5\").Borders(9).Color = -1
               out = out & Err.Number & \"/\" & Range(\"G5\").Borders(9).Color & \"|\"
               out = out & Range(\"B3\").Borders(8).Color & \"/\" & Range(\"B1\").Borders(9).Weight
               Ask = out
             End Function
",
        )
        .unwrap();
        let answer = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Ask", vec![], &mut host).unwrap()
        };
        assert_eq!(
            answer,
            Value::String(
                "0/-4142|1/2/255/3|4/65280/0|1/16711680/1/16711680|2551|0/0|255/4".to_string()
            )
        );
    }

    /// `TextToColumns` splits a column the way Excel does.
    ///
    /// Measured against Excel: `a,b,c` on Comma lands a b c across, and
    /// `1,2.5,x` lands two numbers and a string; `a,,b` leaves the middle cell
    /// empty unless `ConsecutiveDelimiter`; `"a,b",c` keeps the fenced comma;
    /// a `Destination` leaves the source alone; two source columns are 1004;
    /// `FieldInfo` keeps `001` as text and skips a field; fixed widths cut at
    /// 0, 3 and 5; runs of spaces are one delimiter either way; a call naming
    /// no delimiter uses the last call's; existing cells to the right are
    /// written over; `="f,g"` is split as written; and `3-` is text unless
    /// `TrailingMinusNumbers`.
    #[test]
    fn text_to_columns_splits_the_way_excel_does() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Ask() As String
               Dim out As String, r As Variant
               On Error Resume Next
               Range(\"A1\").Value = \"a,b,c\"
               Range(\"A2\").Value = \"1,2.5,x\"
               Range(\"A3\").Value = \"a,,b\"
               r = Range(\"A1:A3\").TextToColumns(DataType:=1, Comma:=True, Tab:=False)
               out = r & \"|\" & Range(\"A1\").Value & Range(\"B1\").Value & Range(\"C1\").Value & \"|\" & TypeName(Range(\"B2\").Value) & TypeName(Range(\"C2\").Value) & \"|\" & IsEmpty(Range(\"B3\").Value) & Range(\"C3\").Value & \"|\"
               Range(\"A5\").Value = \"a,,b\"
               Range(\"A5\").TextToColumns DataType:=1, Comma:=True, Tab:=False, ConsecutiveDelimiter:=True
               out = out & Range(\"B5\").Value & \"|\"
               Range(\"A7\").Value = \"\"\"a,b\"\",c\"
               Range(\"A7\").TextToColumns DataType:=1, Comma:=True, Tab:=False, TextQualifier:=1
               out = out & Range(\"A7\").Value & \"/\" & Range(\"B7\").Value & \"|\"
               Range(\"A10\").Value = \"x;y\"
               Range(\"A10\").TextToColumns Destination:=Range(\"C10\"), DataType:=1, Semicolon:=True, Tab:=False
               out = out & Range(\"A10\").Value & Range(\"C10\").Value & Range(\"D10\").Value & \"|\"
               Range(\"A12\").Value = \"a,b\"
               Range(\"B12\").Value = \"c,d\"
               Range(\"A12:B12\").TextToColumns DataType:=1, Comma:=True, Tab:=False
               out = out & Err.Number & \"|\"
               Err.Clear
               Range(\"A16\").Value = \"001,skip,003\"
               Range(\"A16\").TextToColumns DataType:=1, Comma:=True, Tab:=False, FieldInfo:=Array(Array(1, 2), Array(2, 9), Array(3, 1))
               out = out & Range(\"A16\").Value & TypeName(Range(\"A16\").Value) & Range(\"B16\").Value & IsEmpty(Range(\"C16\").Value) & \"|\"
               Range(\"A18\").Value = \"abcdefgh\"
               Range(\"A18\").TextToColumns DataType:=2, FieldInfo:=Array(Array(0, 1), Array(3, 1), Array(5, 1))
               out = out & Range(\"A18\").Value & \"/\" & Range(\"B18\").Value & \"/\" & Range(\"C18\").Value & \"|\"
               Range(\"A21\").Value = \"  s  t \"
               Range(\"A21\").TextToColumns DataType:=1, Space:=True, Tab:=False
               out = out & \"[\" & Range(\"A21\").Value & \"/\" & Range(\"B21\").Value & \"/\" & Range(\"C21\").Value & \"/\" & Range(\"D21\").Value & \"]|\"
               Range(\"A28\").Value = \"u\" & vbTab & \"v,w\"
               Range(\"A28\").TextToColumns DataType:=1, Comma:=True, Tab:=False
               Range(\"A29\").Value = \"k,l\"
               Range(\"A29\").TextToColumns
               out = out & Range(\"B28\").Value & Range(\"B29\").Value & \"|\"
               Range(\"A30\").Value = \"m,n\"
               Range(\"B30\").Value = \"old\"
               Range(\"C30\").Value = \"older\"
               Range(\"A30\").TextToColumns DataType:=1, Comma:=True, Tab:=False
               out = out & Range(\"B30\").Value & Range(\"C30\").Value & \"|\"
               Range(\"A31\").Formula = \"=\"\"f,g\"\"\"
               Range(\"A31\").TextToColumns DataType:=1, Comma:=True, Tab:=False
               out = out & Range(\"A31\").Formula & Range(\"B31\").Value & \"|\"
               Range(\"A37\").Value = \"-5, 7 ,3-\"
               Range(\"A37\").TextToColumns DataType:=1, Comma:=True, Tab:=False
               out = out & TypeName(Range(\"B37\").Value) & TypeName(Range(\"C37\").Value) & \"|\"
               Range(\"A38\").Value = \"3-\"
               Range(\"A38\").TextToColumns DataType:=1, Comma:=True, Tab:=False, TrailingMinusNumbers:=True
               out = out & CStr(Range(\"A38\").Value)
               Ask = out
             End Function
",
        )
        .unwrap();
        let answer = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Ask", vec![], &mut host).unwrap()
        };
        assert_eq!(
            answer,
            Value::String(
                "True|abc|DoubleString|Trueb|b|a,b/c|x;yxy|1004|001String3True|abc/de/fgh|[/s/t/]|wl|nolder|=\"fg\"|DoubleString|-3"
                    .to_string()
            )
        );
    }

    /// A formula that cannot be read is refused, and never stored.
    ///
    /// Measured against Excel: `="f`, `=1+` and `=nosuchfn(` are each 1004
    /// and leave the cell as it was, where `=nosuchfn()` is stored.
    #[test]
    fn a_malformed_formula_is_refused() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Ask() As String
               Dim out As String
               On Error Resume Next
               Range(\"A1\").Value = \"=\"\"f\"
               out = Err.Number & \"/\" & Range(\"A1\").HasFormula & \"|\"
               Err.Clear
               Range(\"A2\").Value = \"=1+\"
               out = out & Err.Number & \"|\"
               Err.Clear
               Range(\"A3\").Formula = \"=nosuchfn(\"
               out = out & Err.Number & \"|\"
               Err.Clear
               Range(\"A4\").Formula = \"=nosuchfn()\"
               out = out & Err.Number & \"/\" & Range(\"A4\").Formula & \"|\"
               Range(\"A5\").Formula = \"='My Sheet(1)'!A1\"
               out = out & Err.Number
               Ask = out
             End Function
",
        )
        .unwrap();
        let answer = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Ask", vec![], &mut host).unwrap()
        };
        assert_eq!(
            answer,
            Value::String("1004/False|1004|1004|0/=nosuchfn()|0".to_string())
        );
    }

    /// A note is added, read, edited, moved and taken away as Excel does it.
    ///
    /// Measured against Excel: `Range("A1").Comment` is Nothing until
    /// `AddComment`, which answers a Comment whose Text is the note and whose
    /// Parent is the cell; a second `AddComment` on the same cell is 1004 and
    /// on two cells is 5; `Comment.Text "ab", 2` on `hello` gives `hab`
    /// (Overwrite left out drops the rest) and `"AB", 3, False` on
    /// `hello world` gives `heABllo world`; `Comments` counts in row order,
    /// A1 C1 B2 for notes added C1 A1 B2; `Clear` takes a note with it and
    /// `ClearContents` does not; an inserted row moves it; and `NoteText ""`
    /// deletes it.
    #[test]
    fn a_note_is_added_read_edited_moved_and_taken_away() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Ask() As String
               Dim out As String, c As Object, k As Object
               On Error Resume Next
               out = (Range(\"A1\").Comment Is Nothing) & \"|\"
               Range(\"C1\").AddComment \"c\"
               Set c = Range(\"A1\").AddComment(\"hello\")
               out = out & TypeName(c) & \"/\" & c.Text & \"/\" & c.Parent.Address & \"|\"
               Range(\"A1\").AddComment \"again\"
               out = out & Err.Number & \"|\"
               Err.Clear
               Range(\"D1:D2\").AddComment \"two\"
               out = out & Err.Number & \"|\"
               Err.Clear
               c.Text \"ab\", 2
               out = out & c.Text & \"|\"
               c.Text \"hello world\"
               c.Text \"AB\", 3, False
               out = out & c.Text & \"|\"
               Range(\"B2\").AddComment \"b\"
               For Each k In ActiveSheet.Comments
                 out = out & k.Parent.Address(False, False)
               Next
               out = out & \"|\" & ActiveSheet.Comments.Count & \"|\"
               Range(\"A1\").ClearContents
               out = out & (Range(\"A1\").Comment Is Nothing)
               Range(\"A1\").Clear
               out = out & (Range(\"A1\").Comment Is Nothing) & \"|\"
               Rows(1).Insert
               out = out & (Range(\"C1\").Comment Is Nothing) & Range(\"C2\").Comment.Text & \"|\"
               Range(\"C2\").NoteText \"\"
               out = out & (Range(\"C2\").Comment Is Nothing) & ActiveSheet.Comments.Count
               Ask = out
             End Function
",
        )
        .unwrap();
        let answer = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Ask", vec![], &mut host).unwrap()
        };
        assert_eq!(
            answer,
            Value::String(
                "True|Comment/hello/$A$1|1004|5|hab|heABllo world|A1C1B2|3|FalseTrue|Truec|True1"
                    .to_string()
            )
        );
    }

    #[test]
    fn legacy_add_comment_rejects_extra_arguments() {
        let mut workbook = workbook();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        let cell = CellRange { sheet: 0, start_row: 1, start_column: 1, end_row: 1, end_column: 1 };
        let extra = [Value::String("one".into()), Value::String("two".into())];
        assert!(host.add_comment(cell, &extra).is_err());
        assert!(host.notes.is_empty());
        assert!(host.add_comment(cell, &[]).is_ok());
        assert_eq!(host.notes.len(), 1);
    }

    #[test]
    fn legacy_note_positions_count_utf16_code_units() {
        let mut workbook = workbook();
        let module = parse_module("Public Function Probe() As String\nRange(\"A1\").AddComment \"A😀B\"\nProbe = CStr(AscW(Range(\"A1\").NoteText(, 2, 1))) & \"|\" & CStr(AscW(Range(\"A1\").NoteText(, 3, 1))) & \"|\" & Range(\"A1\").NoteText(, 2, 2)\nRange(\"A1\").Comment.Text \"X\", 4, False\nProbe = Probe & \"|\" & Range(\"A1\").Comment.Text\nEnd Function").unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        assert_eq!(execute_with_host(&module, "Probe", vec![], &mut host).unwrap(), Value::String("-10179|-8704|😀|A😀XB".into()));
    }

    #[test]
    fn comment_and_textbox_character_ranges_match_excel_utf16_rules() {
        let mut workbook = workbook();
        let module = parse_module("Public Function Probe() As String\nDim c As Object, s As Object\nSet c=Range(\"A1\").AddComment(\"A😀B\")\nSet s=ActiveSheet.Shapes.AddTextbox(1, 10, 10, 100, 50)\ns.TextFrame.Characters.Text=\"A😀B\"\nProbe=CStr(AscW(c.Shape.TextFrame.Characters(2,1).Text)) & \"|\" & CStr(AscW(c.Shape.TextFrame.Characters(3,1).Text)) & \"|\" & CStr(c.Shape.TextFrame.Characters(4,10).Count) & \"|\" & CStr(IsError(c.Shape.TextFrame.Characters(5,1).Text)) & \"|\" & CStr(c.Shape.TextFrame.Characters(2,0).Count)\nProbe=Probe & \"|\" & s.TextFrame.Characters(2,1).Text & \"|\" & CStr(s.TextFrame.Characters(2,1).Count) & \"|\" & s.TextFrame.Characters(3,2).Text & \"|\" & CStr(s.TextFrame.Characters(3,2).Count)\nEnd Function").unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        assert_eq!(execute_with_host(&module, "Probe", vec![], &mut host).unwrap(), Value::String("-10179|-8704|10|True|4|😀|2|😀B|3".into()));
    }

    #[test]
    fn comment_and_textbox_character_replacement_uses_excel_utf16_rules() {
        let bytes = include_bytes!("../../../tests/fixtures/conditional/visual_rules.xlsx");
        let source = "Public Function Change() As String\nDim c As Object, s As Object, t As String\nSet c=Range(\"F2\").AddComment(\"A😀B\")\nRange(\"G2\").AddCommentThreaded \"thread\"\nc.Shape.TextFrame.Characters(2,1).Text=\"X\"\nt=c.Text\nChange=CStr(Len(t)) & \"|\" & CStr(AscW(Mid$(t,3,1)))\nSet s=ActiveSheet.Shapes.AddTextbox(1,10,10,100,50)\ns.TextFrame.Characters.Text=\"A😀B\"\ns.TextFrame.Characters(3,1).Text=\"X\"\nChange=Change & \"|\" & s.TextFrame.Characters.Text\nEnd Function\nPublic Function ReadNote() As String\nDim t As String\nt=Range(\"F2\").Comment.Text\nReadNote=CStr(Len(t)) & \"|\" & CStr(AscW(Mid$(t,3,1)))\nEnd Function";
        let changed = execute_workbook_action_in_session(oxicells_core::parse_xlsx(bytes).unwrap(), source, Some("Change"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(changed.error.is_none(), "{:?}", changed.error.as_ref().map(|error| &error.message));
        assert_eq!(serde_json::to_value(&changed.result).unwrap(), serde_json::json!({"type":"string", "value":"4|-8704|AXB"}));
        let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
        editor.apply_workbook(&changed.workbook).unwrap();
        let saved = editor.save().unwrap();
        {
            use std::io::Read;
            let mut package = zip::ZipArchive::new(std::io::Cursor::new(&saved)).unwrap();
            let mut rels_xml = String::new();
            package.by_name("xl/worksheets/_rels/sheet1.xml.rels").unwrap().read_to_string(&mut rels_xml).unwrap();
            let relations = oxidocs_common::relationships::parse_relationships(&rels_xml).unwrap();
            let drawing = relations.values().find(|relation| relation.rel_type.ends_with("/drawing")).expect("drawing relationship");
            let note = relations.values().find(|relation| relation.rel_type.ends_with("/comments")).expect("comment relationship");
            let vml = relations.values().find(|relation| relation.rel_type.ends_with("/vmlDrawing")).expect("VML relationship");
            let thread = relations.values().find(|relation| relation.rel_type.ends_with("/threadedComment")).expect("threaded comment relationship");
            assert!(drawing.id != note.id && drawing.id != vml.id && note.id != vml.id && thread.id != drawing.id && thread.id != note.id && thread.id != vml.id);
            let mut sheet_xml = String::new();
            package.by_name("xl/worksheets/sheet1.xml").unwrap().read_to_string(&mut sheet_xml).unwrap();
            assert!(sheet_xml.contains(&format!("r:id=\"{}\"", drawing.id)));
            assert!(sheet_xml.contains(&format!("r:id=\"{}\"", vml.id)));
        }
        let read = execute_workbook_action_in_session(oxicells_core::parse_xlsx(&saved).unwrap(), source, Some("ReadNote"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(read.error.is_none(), "{:?}", read.error.as_ref().map(|error| &error.message));
        assert_eq!(serde_json::to_value(&read.result).unwrap(), serde_json::json!({"type":"string", "value":"4|-8704"}));
    }

