    #[test]
    fn nonfinite_financial_values_reach_excel_functions_as_num_errors() {
        let mut workbook = workbook();
        let source = "Public Function ProbeNan() As Variant\nProbeNan=Application.Sum(FV(-2,.5,100,50))\nEnd Function\nPublic Function ProbeInf() As Variant\nProbeInf=Application.Sum(1,FV(-1,-1,100,-50))\nEnd Function\nPublic Function ProbeArray() As Variant\nProbeArray=Application.Sum(Array(1,FV(-2,.5,100,50)))\nEnd Function\nPublic Function ProbeTypes() As String\nDim v As Variant, a As Variant\nv=FV(-2,.5,100,50): a=Array(1,v)\nProbeTypes=CStr(Application.Count(v)) & \":\" & CStr(Application.CountA(v)) & \":\" & CStr(Application.IsError(v)) & \":\" & CStr(Application.IsNumber(v)) & \":\" & CStr(Application.IfError(v,7)) & \":\" & CStr(Application.Count(a)) & \":\" & CStr(Application.CountA(a))\nEnd Function\nPublic Function ProbeError() As Long\nDim x As Variant\nOn Error Resume Next\nx=Application.WorksheetFunction.Sum(FV(-1,-1,100,-50)): ProbeError=Err.Number\nEnd Function";
        let module = parse_module(source).unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        assert_eq!(execute_with_host(&module, "ProbeNan", vec![], &mut host).unwrap(), Value::Error(2036));
        assert_eq!(execute_with_host(&module, "ProbeInf", vec![], &mut host).unwrap(), Value::Error(2036));
        assert_eq!(execute_with_host(&module, "ProbeArray", vec![], &mut host).unwrap(), Value::Error(2036));
        assert_eq!(execute_with_host(&module, "ProbeTypes", vec![], &mut host).unwrap(), Value::String("0:1:True:False:7:1:2".to_string()));
        assert_eq!(execute_with_host(&module, "ProbeError", vec![], &mut host).unwrap(), Value::Integer(1004));
    }

