    #[test]
    fn legacy_notes_preserve_unpaired_utf16_through_save_and_reload() {
        let bytes = include_bytes!("../../../tests/fixtures/conditional/visual_rules.xlsx");
        let source = "Public Sub CreateNote()\nRange(\"F2\").AddComment \"A😀B\"\nRange(\"F2\").Comment.Text \"X\", 3, False\nRange(\"F2\").Comment.Visible = True\nRange(\"G2\").AddComment ChrW(-10179)\nRange(\"H2\").NoteText ChrW(-8704)\nEnd Sub\nPublic Function ReadNote() As String\nDim t As String\nt = Range(\"F2\").Comment.Text\nReadNote = CStr(Len(t)) & \"|\" & CStr(AscW(Mid$(t, 2, 1))) & \"|\" & Mid$(t, 3, 1) & \"|\" & CStr(AscW(Mid$(t, 4, 1))) & \"|\" & CStr(AscW(Range(\"G2\").Comment.Text)) & \"|\" & CStr(AscW(Range(\"H2\").NoteText))\nEnd Function";
        let created = execute_workbook_action_in_session(oxicells_core::parse_xlsx(bytes).unwrap(), source, Some("CreateNote"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(created.error.is_none(), "{:?}", created.error.as_ref().map(|error| &error.message));
        let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
        editor.apply_workbook(&created.workbook).unwrap();
        let saved = editor.save().unwrap();
        let reopened = oxicells_core::parse_xlsx(&saved).unwrap();
        let comment = reopened.sheets[0].comments.iter().find(|comment| comment.cell == (1, 5)).unwrap();
        assert_eq!(comment.utf16_text.as_deref(), Some(&[65, 0xD83D, 88, 0xDE00, 66][..]));
        let read = execute_workbook_action_in_session(reopened, source, Some("ReadNote"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(read.error.is_none(), "{:?}", read.error.as_ref().map(|error| &error.message));
        assert_eq!(serde_json::to_value(&read.result).unwrap(), serde_json::json!({"type":"string", "value":"5|-10179|X|-8704|-10179|-8704"}));
    }

