    #[test]
    fn threaded_comments_saved_state_and_resolved_mutations_match_excel() {
        let mut workbook = workbook();
        let source = "Public Function Probe() As String\nDim c As Object, r As Object, ignored As Object\nThisWorkbook.Saved=True: Set c=Range(\"A1\").AddCommentThreaded(\"first\"): Probe=CStr(ThisWorkbook.Saved)\nThisWorkbook.Saved=True: c.Text \"first\": Probe=Probe & \"|\" & CStr(ThisWorkbook.Saved)\nThisWorkbook.Saved=True: c.Text \"\": Probe=Probe & \"|\" & CStr(ThisWorkbook.Saved)\nThisWorkbook.Saved=True: Set r=c.AddReply(\"reply\"): Probe=Probe & \"|\" & CStr(ThisWorkbook.Saved)\nThisWorkbook.Saved=True: r.Text \"reply\": Probe=Probe & \"|\" & CStr(ThisWorkbook.Saved)\nThisWorkbook.Saved=True: c.Resolved=True: Probe=Probe & \"|\" & CStr(ThisWorkbook.Saved)\nThisWorkbook.Saved=True: c.Text \"changed\": Probe=Probe & \"|\" & CStr(ThisWorkbook.Saved) & \"/\" & c.Text\nThisWorkbook.Saved=True: Set ignored=c.AddReply(\"blocked\"): Probe=Probe & \"|\" & CStr(ThisWorkbook.Saved) & \"/\" & CStr(ignored Is Nothing)\nThisWorkbook.Saved=True: r.Delete: Probe=Probe & \"|\" & CStr(ThisWorkbook.Saved) & \"/\" & CStr(c.Replies.Count)\nThisWorkbook.Saved=True: c.Resolved=False: Probe=Probe & \"|\" & CStr(ThisWorkbook.Saved)\nThisWorkbook.Saved=True: r.Delete: Probe=Probe & \"|\" & CStr(ThisWorkbook.Saved)\nThisWorkbook.Saved=True: c.Delete: Probe=Probe & \"|\" & CStr(ThisWorkbook.Saved)\nEnd Function";
        let module = parse_module(source).unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        assert_eq!(execute_with_host(&module, "Probe", vec![], &mut host).unwrap(), Value::String("False|False|True|False|False|False|True/first|True/True|True/1|False|False|False".into()));
    }

