    #[test]
    fn protected_sheet_threaded_comments_and_clear_match_excel() {
        let mut workbook = workbook();
        let source = "Public Function Probe() As String\nDim c As Object, r As Object\nRange(\"A1\").AddComment \"note\"\nRange(\"C1:D1\").Locked=False\nRange(\"D1\").AddComment \"other note\"\nActiveSheet.Protect \"probe\"\nThisWorkbook.Saved=True\nSet c=Range(\"B1\").AddCommentThreaded(\"thread\")\nSet r=c.AddReply(\"reply\")\nProbe=CStr(ThisWorkbook.Saved) & \"|\" & CStr(c.Replies.Count)\nOn Error Resume Next\nThisWorkbook.Saved=True\nRange(\"B1\").ClearNotes\nProbe=Probe & \"|\" & CStr(Err.Number) & \"/\" & CStr(ThisWorkbook.Saved) & \"/\" & CStr(Range(\"B1\").CommentThreaded Is Nothing)\nErr.Clear\nThisWorkbook.Saved=True\nRange(\"A1:B1\").ClearComments\nProbe=Probe & \"|\" & CStr(Range(\"A1\").Comment Is Nothing) & \"/\" & CStr(Range(\"B1\").CommentThreaded Is Nothing) & \"/\" & CStr(ThisWorkbook.Saved)\nSet c=Range(\"C1\").AddCommentThreaded(\"thread\")\nThisWorkbook.Saved=True\nRange(\"C1:D1\").ClearNotes\nProbe=Probe & \"|\" & CStr(Err.Number) & \"/\" & CStr(Range(\"C1\").CommentThreaded Is Nothing) & \"/\" & CStr(Range(\"D1\").Comment Is Nothing) & \"/\" & CStr(ThisWorkbook.Saved)\nEnd Function";
        let module = parse_module(source).unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        assert_eq!(execute_with_host(&module, "Probe", vec![], &mut host).unwrap(), Value::String("False|1|1004/True/False|False/True/False|0/True/False/False".into()));
    }

    #[test]
    fn save_copy_persists_a_comment_thread_created_by_vba() {
        let package = include_bytes!("../../../tests/fixtures/basic_test.xlsx");
        let mut context = failure_context();
        context.file_context = Some(file_io::FileContext {
            edit_revision: None, source_code_page: None,
            package_bytes: Some(package.to_vec()),
            full_name: Some("C:\\work\\source.xlsx".into()),
            read_only: Some(true),
            folders: vec!["C:\\work".into()],
            files: vec![],
        });
        let source = r#"Public Sub PersistThread()
            Set root = Range("C5").AddCommentThreaded("saved thread & text")
            Set legacy = Range("D5").AddComment("saved legacy note")
            legacy.Shape.Line.ForeColor.RGB = 255
            legacy.Shape.Line.Weight = 2.25
            Set reply = root.AddReply("saved reply")
            root.Resolved = True
            ActiveWorkbook.SaveCopyAs "C:\work\saved.xlsx"
        End Sub"#;
        let book = oxicells_core::parse_xlsx(package).unwrap();
        let mut session = None;
        let outcome = execute_workbook_action_in_session(
            book, source, Some("PersistThread"), vec![], 0, context, &mut session,
        ).unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
        assert_eq!(outcome.files.len(), 1);
        let saved = oxicells_core::parse_xlsx(&outcome.files[0].bytes).unwrap();
        assert_eq!(saved.sheets[0].threaded_comments.len(), 2);
        assert_eq!(saved.sheets[0].threaded_comments[0].cell, (4, 2));
        assert_eq!(saved.sheets[0].threaded_comments[0].text, "saved thread & text");
        assert!(saved.sheets[0].threaded_comments[0].resolved);
        assert_eq!(saved.sheets[0].threaded_comments[1].text, "saved reply");
        assert_eq!(saved.sheets[0].threaded_comments[1].parent_id.as_deref(), Some(saved.sheets[0].threaded_comments[0].id.as_str()));
        assert_eq!(saved.sheets[0].comments.len(), 2);
        let compatibility = saved.sheets[0].comments.iter().find(|comment| comment.cell == (4, 2)).unwrap();
        assert_eq!(compatibility.author, format!("tc={}", saved.sheets[0].threaded_comments[0].id));
        assert!(compatibility.text.paragraphs.iter().map(|paragraph| paragraph.text.as_str()).collect::<Vec<_>>().join("\n").ends_with("コメント:\n    saved thread & text\n返信:\nsaved reply"));
        assert_eq!(saved.sheets[0].comments.iter().find(|comment| comment.cell == (4, 3)).unwrap().text.paragraphs[0].text, "saved legacy note");
        let mut editor = oxicells_core::XlsxEditor::new(&outcome.files[0].bytes).unwrap();
        let mut edited = saved.clone();
        edited.sheets[0].threaded_comments[0].text = "updated root".into();
        edited.sheets[0].threaded_comments[1].text = "updated reply".into();
        editor.apply_workbook(&edited).unwrap();
        let updated = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
        let compatibility = updated.sheets[0].comments.iter().find(|comment| comment.cell == (4, 2)).unwrap();
        assert!(compatibility.text.paragraphs.iter().map(|paragraph| paragraph.text.as_str()).collect::<Vec<_>>().join("\n").ends_with("コメント:\n    updated root\n返信:\nupdated reply"));
        let probe_source = "Public Function Probe() As String\nProbe=CStr(Range(\"C5\").Comment Is Nothing) & \"|\" & CStr(ActiveSheet.Comments.Count) & \"|\" & CStr(ActiveSheet.Shapes.Count)\nEnd Function";
        let probe = execute_workbook_action_in_session(saved.clone(), probe_source, Some("Probe"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(probe.error.is_none(), "{:?}", probe.error.as_ref().map(|error| &error.message));
        assert_eq!(serde_json::to_value(&probe.result).unwrap(), serde_json::json!({"type":"string", "value":"True|1|1"}));
        let clear = execute_workbook_action_in_session(saved.clone(), "Public Sub ClearThread()\nRange(\"C5\").ClearComments\nEnd Sub", Some("ClearThread"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(clear.error.is_none(), "{:?}", clear.error.as_ref().map(|error| &error.message));
        let mut clear_editor = oxicells_core::XlsxEditor::new(&outcome.files[0].bytes).unwrap();
        clear_editor.apply_workbook(&clear.workbook).unwrap();
        let cleared = oxicells_core::parse_xlsx(&clear_editor.save().unwrap()).unwrap();
        assert!(cleared.sheets[0].threaded_comments.is_empty());
        assert!(cleared.sheets[0].comments.iter().all(|comment| comment.cell != (4, 2)));
        assert!(cleared.sheets[0].comments.iter().any(|comment| comment.cell == (4, 3)));

        let saved_bytes = outcome.files[0].bytes.clone();
        let mut unchanged_context = failure_context();
        unchanged_context.file_context = Some(file_io::FileContext {
            edit_revision: None, source_code_page: None,
            package_bytes: Some(saved_bytes.clone()),
            full_name: Some("C:\\work\\saved.xlsx".into()),
            read_only: Some(true),
            folders: vec!["C:\\work".into()],
            files: vec![],
        });
        let unchanged_source = r#"Public Sub SaveUnchanged()
            ActiveWorkbook.SaveCopyAs "C:\work\unchanged.xlsx"
        End Sub"#;
        let mut session = None;
        let unchanged = execute_workbook_action_in_session(
            outcome.workbook.clone(), unchanged_source, Some("SaveUnchanged"), vec![], 0,
            unchanged_context, &mut session,
        ).unwrap();
        assert!(unchanged.error.is_none(), "{:?}", unchanged.error.as_ref().map(|error| &error.message));
        assert_eq!(unchanged.files[0].bytes, saved_bytes);

        let mut delete_context = failure_context();
        delete_context.file_context = Some(file_io::FileContext {
            edit_revision: None, source_code_page: None,
            package_bytes: Some(saved_bytes.clone()),
            full_name: Some("C:\\work\\saved.xlsx".into()),
            read_only: Some(true),
            folders: vec!["C:\\work".into()],
            files: vec![],
        });
        let delete_source = r#"Public Sub DeleteThread()
            Range("C5").CommentThreaded.Delete
            Range("D5").Comment.Delete
            ActiveWorkbook.SaveCopyAs "C:\work\deleted.xlsx"
        End Sub"#;
        let mut session = None;
        let deleted = execute_workbook_action_in_session(
            outcome.workbook, delete_source, Some("DeleteThread"), vec![], 0, delete_context, &mut session,
        ).unwrap();
        assert!(deleted.error.is_none(), "{:?}", deleted.error.as_ref().map(|error| &error.message));
        let reopened = oxicells_core::parse_xlsx(&deleted.files[0].bytes).unwrap();
        assert!(reopened.sheets[0].threaded_comments.is_empty());
        assert!(reopened.sheets[0].comments.is_empty());
    }

    #[test]
    fn save_copy_reads_adds_and_deletes_cell_hyperlinks() {
        let base = include_bytes!("../../../tests/fixtures/basic_test.xlsx");
        let mut source_editor = oxicells_core::XlsxEditor::new(base).unwrap();
        let mut source_workbook = source_editor.workbook().clone();
        source_workbook.sheets[0].hyperlinks.push(oxicells_core::ir::Hyperlink {
            cell: (0, 0),
            end_cell: Some((1, 1)),
            target: "Sheet1!A1".into(),
            internal: true,
            sub_address: None,
            tooltip: Some("existing link".into()),
        });
        source_editor.apply_workbook(&source_workbook).unwrap();
        let source_package = source_editor.save().unwrap();
        let book = oxicells_core::parse_xlsx(&source_package).unwrap();
        assert_eq!(book.sheets[0].hyperlinks.len(), 1, "source link was not serialized");

        let mut context = failure_context();
        context.file_context = Some(file_io::FileContext {
            edit_revision: None, source_code_page: None,
            package_bytes: Some(source_package),
            full_name: Some("C:\\work\\source.xlsx".into()),
            read_only: Some(true),
            folders: vec!["C:\\work".into()],
            files: vec![],
        });
        let source = r#"Public Sub PersistLinks()
            Debug.Print ActiveSheet.Hyperlinks.Count & "/" & ActiveSheet.Hyperlinks(1).SubAddress
            Debug.Print Range("A1:B2").Hyperlinks.Count & "/" & ActiveSheet.Hyperlinks(1).Range.Address
            ActiveSheet.Hyperlinks.Add Range("B2:C3"), "https://new.example/?a=1&b=2", "Section 1", "tip & tag", "shown"
            ActiveSheet.Hyperlinks(1).Delete
            Debug.Print ActiveSheet.Hyperlinks.Count & "/" & ActiveSheet.Hyperlinks(1).Address
            Set added = Worksheets.Add()
            added.Hyperlinks.Add added.Range("C3"), "https://added.example/?x=1&y=2"
            ActiveWorkbook.SaveCopyAs "C:\work\links.xlsx"
        End Sub"#;
        let mut session = None;
        let outcome = execute_workbook_action_in_session(
            book, source, Some("PersistLinks"), vec![], 0, context, &mut session,
        ).unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
        assert_eq!(outcome.debug_output, ["1/Sheet1!A1", "1/$A$1:$B$2", "1/https://new.example/?a=1&b=2"]);
        assert_eq!(outcome.files.len(), 1);

        let saved = oxicells_core::parse_xlsx(&outcome.files[0].bytes).unwrap();
        assert_eq!(saved.sheets.len(), 2);
        let existing_link_sheet = saved.sheets.iter().find(|sheet| sheet.hyperlinks.iter().any(|link| link.target.starts_with("https://new.example/"))).unwrap();
        assert_eq!(existing_link_sheet.hyperlinks, [oxicells_core::ir::Hyperlink {
            cell: (1, 1),
            end_cell: Some((2, 2)),
            target: "https://new.example/?a=1&b=2".into(),
            internal: false,
            sub_address: Some("Section 1".into()),
            tooltip: Some("tip & tag".into()),
        }]);
        let added_link_sheet = saved.sheets.iter().find(|sheet| sheet.hyperlinks.iter().any(|link| link.target.starts_with("https://added.example/"))).unwrap();
        assert_eq!(added_link_sheet.hyperlinks, [oxicells_core::ir::Hyperlink {
            cell: (2, 2),
            end_cell: None,
            target: "https://added.example/?x=1&y=2".into(),
            internal: false,
            sub_address: None,
            tooltip: None,
        }]);
    }

