    #[test]
    fn initial_styleless_caller_uses_native_defaults_and_keeps_saved_state() {
        let package=include_bytes!("../../../tests/fixtures/basic_test.xlsx");
        let source=r#"Public Function Probe() As Variant
            Set ws = ActiveSheet
            Probe = Array(ws.Cells(100, 100).Font.Name, ws.Cells(100, 100).Font.Size, ws.Cells(100, 100).Font.ThemeFont, ws.StandardHeight, ws.Columns(100).Width, ws.Rows(1).RowHeight, ThisWorkbook.Saved)
        End Function
        Public Sub MarkSaved()
            ThisWorkbook.Saved = True
        End Sub
        Public Sub Export()
            ThisWorkbook.SaveCopyAs "C:\work\initial-normal.xlsx"
        End Sub"#;
        let context=|| {
            let mut context=failure_context();
            context.file_context=Some(file_io::FileContext {
                package_bytes:Some(package.to_vec()),full_name:Some(r"C:\work\original.xlsx".into()),
                read_only:Some(true),folders:vec![r"C:\work".into()],..Default::default()
            });
            context
        };
        let mut session=None;
        let mut incoming=oxicells_core::parse_xlsx_preserving_values(package).unwrap();
        let mut expected_saved=false;
        for procedure in ["Probe","MarkSaved","Probe","Export","Probe"] {
            // The page keeps document fields after a read-only call while
            // carrying its returned calculation metadata into the next call.
            let outcome=execute_workbook_action_in_session(
                incoming.clone(),source,Some(procedure),vec![],0,context(),&mut session,
            ).unwrap();
            incoming.calculation=outcome.workbook.calculation.clone();
            if procedure=="MarkSaved" { expected_saved=true; }
            assert!(outcome.error.is_none(),"{:?}",outcome.error.as_ref().map(|error|&error.message));
            assert!(!outcome.workbook_changed,"unexpected document edit during {procedure}");
            if procedure=="Probe" {
                let raw=serde_json::to_value(&outcome.result).unwrap();
                let values=raw["value"]["values"].as_array().unwrap();
                assert_eq!(values[0]["value"].as_str(),Some("\u{6e38}\u{30b4}\u{30b7}\u{30c3}\u{30af}"));
                assert_eq!(values[1..6].iter().map(|v|v["value"].as_f64().unwrap()).collect::<Vec<_>>(),[11.0,0.0,18.75,54.0,18.75]);
                assert_eq!(values[6]["value"].as_bool(),Some(expected_saved));
            }
            if procedure=="MarkSaved" || procedure=="Export" {assert!(session.as_ref().unwrap().host.saved);}
            if procedure=="Export" {
                let bytes=&outcome.files.iter().find(|file|file.path==r"C:\work\initial-normal.xlsx").unwrap().bytes;
                // A styleless file and Excel's own normalized copy have the
                // same reopened font/grid. Assert the host-visible result;
                // an explicit styles.xml is not required to express it.
                assert_eq!(bytes,package);
                let mut reopened_context=failure_context();
                reopened_context.file_context=Some(file_io::FileContext {
                    package_bytes:Some(bytes.clone()),full_name:Some(r"C:\work\reopened.xlsx".into()),
                    read_only:Some(true),folders:vec![r"C:\work".into()],..Default::default()
                });
                let reopened=execute_workbook_action_in_session(
                    oxicells_core::parse_xlsx_preserving_values(bytes).unwrap(),source,Some("Probe"),
                    vec![],0,reopened_context,&mut None,
                ).unwrap();
                assert!(reopened.error.is_none());assert!(!reopened.workbook_changed);
                let raw=serde_json::to_value(&reopened.result).unwrap();
                let values=raw["value"]["values"].as_array().unwrap();
                assert_eq!(values[0]["value"].as_str(),Some("\u{6e38}\u{30b4}\u{30b7}\u{30c3}\u{30af}"));
                assert_eq!(values[1..6].iter().map(|v|v["value"].as_f64().unwrap()).collect::<Vec<_>>(),[11.0,0.0,18.75,54.0,18.75]);
            }
        }
        assert!(session.as_ref().unwrap().host.saved);
    }

    #[test]
    fn initial_styleless_empty_spill_cache_is_not_an_edit() {
        let package=include_bytes!("../../../tests/fixtures/basic_test.xlsx");
        let mut workbook=oxicells_core::parse_xlsx_preserving_values(package).unwrap();
        workbook.sheets[0].cached_spills=None;
        let empty=observable_workbook_bytes(&mut workbook).unwrap();
        workbook.sheets[0].cached_spills=Some(Vec::new());
        assert_eq!(observable_workbook_bytes(&mut workbook).unwrap(),empty);
        assert_eq!(workbook.sheets[0].cached_spills,Some(Vec::new()));
        workbook.sheets[0].cached_spills=Some(vec![((0,0),(2,3))]);
        let spill=observable_workbook_bytes(&mut workbook).unwrap();
        assert_ne!(spill,empty);
        assert_eq!(workbook.sheets[0].cached_spills,Some(vec![((0,0),(2,3))]));
        workbook.sheets[0].cached_spills=None;
        workbook.sheets[0].rows[0].cells[0].value=CellValue::String("real edit".into());
        assert_ne!(observable_workbook_bytes(&mut workbook).unwrap(),empty);
    }

    #[test]
    fn sparse_editor_fonts_inherit_only_omitted_color_and_keep_explicit_identity() {
        use oxicells_core::ir::{CellFormatReference, FontReference};
        let normal=CellStyle {font_name:Some("Calibri".into()),font_size:Some(11.0),
            font_color:Some("000000".into()),font_reference:Some(Box::new(FontReference {
                latin_name:Some("Calibri".into()),theme:Some(1),..Default::default()
            })),..Default::default()};
        let mut edited=CellStyle {font_name:Some("Arial".into()),font_size:Some(17.0),
            font_reference:Some(Box::new(FontReference {tint:Some(0.25),..Default::default()})),..Default::default()};
        inherit_implicit_font_color(&mut edited,&normal);
        assert_eq!(edited.font_name.as_deref(),Some("Arial"));assert_eq!(edited.font_size,Some(17.0));
        assert_eq!(edited.font_color.as_deref(),Some("000000"));
        let reference=edited.font_reference.as_ref().unwrap();
        assert_eq!(reference.theme,Some(1));assert_eq!(reference.latin_name,None);assert_eq!(reference.tint,Some(0.25));
        let once=edited.clone();inherit_implicit_font_color(&mut edited,&normal);assert_eq!(edited,once);
        for kind in 0..9 {
            let mut explicit=CellStyle {font_size:Some(17.0),..Default::default()};
            match kind {
                0=>explicit.font_color=Some("000000".into()),
                1=>explicit.font_reference=Some(Box::new(FontReference {rgb:Some("FF000000".into()),..Default::default()})),
                2=>explicit.font_reference=Some(Box::new(FontReference {theme:Some(5),tint:Some(0.4),..Default::default()})),
                3=>explicit.font_reference=Some(Box::new(FontReference {indexed:Some(8),..Default::default()})),
                4=>explicit.font_reference=Some(Box::new(FontReference {automatic:true,..Default::default()})),
                5=>explicit.font_reference=Some(Box::new(FontReference {implicit_automatic:true,..Default::default()})),
                6=>explicit.normal_font_link=Some(false),
                7=>explicit.named_font_link=Some(false),
                _=>explicit.format_reference=Some(Box::new(CellFormatReference::for_style(0))),
            }
            let before=explicit.clone();inherit_implicit_font_color(&mut explicit,&normal);
            assert_eq!(explicit,before,"kind {kind}");
        }
    }

    #[test]
    fn implicit_cell_export_defaults_preserve_explicit_edits_and_inheritance() {
        let package=include_bytes!("../../../tests/fixtures/basic_test.xlsx");
        let mut workbook=oxicells_core::parse_xlsx_preserving_values(package).unwrap();
        initialize_initial_caller_styles(&mut workbook,package,&default_application_font()).unwrap();
        let normal=workbook.default_style.clone();
        let row=&mut workbook.sheets[0].rows[0];
        assert!(row.cells.len()>=3);
        for cell in &mut row.cells[..3] {cell.style=CellStyle::default();}
        row.cells[0].style.bg_color=Some("123456".into());
        row.cells[1].style.font_name=Some("Arial".into());
        row.cells[1].style.font_size=Some(17.0);
        row.cells[2].style.normal_font_link=Some(false);
        let explicit=row.cells[1].style.clone();let detached=row.cells[2].style.clone();
        resolve_implicit_cell_styles(&mut workbook);
        let row=&workbook.sheets[0].rows[0];
        assert_eq!(Dress::of_style(&row.cells[0].style),Dress::of_style(&normal));
        assert_eq!(row.cells[0].style.bg_color.as_deref(),Some("123456"));
        assert_eq!(row.cells[0].style.format_reference.as_ref().unwrap().style_id,
            normal.format_reference.as_ref().unwrap().style_id);
        assert_eq!(row.cells[0].style.format_reference.as_ref().unwrap().fill,Some(true));
        assert_eq!(row.cells[1].style.font_name,explicit.font_name);
        assert_eq!(row.cells[1].style.font_size,explicit.font_size);
        assert_eq!(row.cells[1].style.font_color,normal.font_color);
        assert_eq!(row.cells[1].style.format_reference.as_ref().unwrap().font,Some(true));
        assert_eq!(row.cells[1].style.format_reference.as_ref().unwrap().fill,None);
        assert_eq!(row.cells[1].style.format_reference.as_ref().unwrap().border,None);
        assert_eq!(row.cells[2].style,detached);
        let before=serde_json::to_value(&workbook).unwrap();
        resolve_implicit_cell_styles(&mut workbook);
        assert_eq!(serde_json::to_value(&workbook).unwrap(),before);
    }



    #[test]
    fn sheet_structure_saved_state_matches_native_history() {
        const FONT_SOURCE:&str=r#"Option Explicit
Public Function SavedFont(ByVal inputPath As String, ByVal sheetIndex As Long) As Variant
    Dim book As Object, ws As Object
    Dim row As Long, col As Long, failed As Long
    Dim color As Variant, theme As Variant
    Dim values(0 To 24) As Variant
    Set book = Workbooks.Open(inputPath, 0, True)
    Set ws = book.Worksheets(sheetIndex)
    For row = 1 To 5
        For col = 1 To 5
            color = ws.Cells(row, col).Font.ColorIndex
            theme = Empty
            On Error Resume Next
            Err.Clear
            theme = ws.Cells(row, col).Font.ThemeColor
            failed = Err.Number
            On Error GoTo 0
            values((row - 1) * 5 + col - 1) = Array(color, theme, failed)
        Next col
    Next row
    book.Close False
    SavedFont = values
End Function"#;
        let cases:serde_json::Value=serde_json::from_str(include_str!("../../../tests/fixtures/vba/sheet_package_native.json")).unwrap();
        let caller=include_bytes!("../../../tests/fixtures/basic_test.xlsx");
        let startup:Vec<u16>=cases["startup_profile_utf16"].as_array().unwrap().iter().map(|x|u16::try_from(x.as_u64().unwrap()).unwrap()).collect();
        for (source,conditions) in [
            (cases["program"].as_str().unwrap(),cases["cases"].as_array().unwrap()),
            (cases["row_order_program"].as_str().unwrap(),cases["row_order_cases"].as_array().unwrap()),
        ] {
          for case in conditions {
            let label=case["label"].as_str().unwrap();let mode=case["mode"].as_i64().unwrap();
            let hex=cases["inputs"][label]["bytes_hex"].as_str().unwrap();
            let input:Vec<u8>=(0..hex.len()).step_by(2).map(|at|u8::from_str_radix(&hex[at..at+2],16).unwrap()).collect();
            let workbook=oxicells_core::parse_xlsx_preserving_values(caller).unwrap();
            let mut context=failure_context();
            context.application_state=Some(VbaApplicationState {standard_font_startup:Some(VbaStandardFontStartup {profile_utf16:Some(startup.clone())}),..Default::default()});
            context.file_context=Some(file_io::FileContext {
                package_bytes:Some(caller.to_vec()),full_name:Some(r"C:\work\caller.xlsx".into()),read_only:Some(true),
                folders:vec![r"C:\work".into()],files:vec![file_io::ProducedFile {path:r"C:\work\input.xlsx".into(),bytes:input}],..Default::default()
            });
            let result=execute_workbook_action_in_session(workbook,source,Some("Probe"),vec![Value::Integer(mode),Value::String(r"C:\work\input.xlsx".into()),Value::String(r"C:\work\copy.xlsx".into())],0,context,&mut None).unwrap();
            assert!(result.error.is_none(),"{label} mode {mode}: {}",serde_json::to_value(&result.error).unwrap());
            let value=serde_json::to_value(result.result).unwrap();
            let states:Vec<Vec<serde_json::Value>>=value["value"]["values"].as_array().unwrap().iter().map(|state|
                state["value"]["values"].as_array().unwrap().iter().map(|cell|cell["value"].clone()).collect()
            ).collect();
            assert_eq!(serde_json::to_value(states).unwrap(),case["expected"],"{label} mode {mode}");
            assert!(result.files.iter().any(|file|file.path==r"C:\work\copy.xlsx"),"{label} mode {mode}: no exported copy");
            let copy=result.files.iter().find(|file|file.path==r"C:\work\copy.xlsx").unwrap();
            let mut font_context=failure_context();
            font_context.application_state=Some(VbaApplicationState {standard_font_startup:Some(VbaStandardFontStartup {profile_utf16:Some(startup.clone())}),..Default::default()});
            font_context.file_context=Some(file_io::FileContext {
                package_bytes:Some(caller.to_vec()),full_name:Some(r"C:\work\caller.xlsx".into()),read_only:Some(true),
                folders:vec![r"C:\work".into()],files:vec![file_io::ProducedFile {path:r"C:\work\copy.xlsx".into(),bytes:copy.bytes.clone()}],..Default::default()
            });
            let font=execute_workbook_action_in_session(oxicells_core::parse_xlsx_preserving_values(caller).unwrap(),FONT_SOURCE,Some("SavedFont"),
                vec![Value::String(r"C:\work\copy.xlsx".into()),Value::Integer(case["saved_font_sheet"].as_i64().unwrap())],0,font_context,&mut None).unwrap();
            assert!(font.error.is_none(),"{label} mode {mode}: {}",serde_json::to_value(&font.error).unwrap());
            let value=serde_json::to_value(font.result).unwrap();
            let fonts:Vec<Vec<serde_json::Value>>=value["value"]["values"].as_array().unwrap().iter().map(|row|
                row["value"]["values"].as_array().unwrap().iter().map(|cell|cell.get("value").cloned().unwrap_or(serde_json::Value::Null)).collect()
            ).collect();
            assert_eq!(serde_json::to_value(fonts).unwrap(),cases["saved_font_grids"][case["saved_font_grid"].as_u64().unwrap() as usize],"{label} mode {mode}: saved font identity");
          }
        }
    }

