    #[test]
    fn ole_objects_add_class_type_failures_match_excel_descriptions() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/scale_picture_original_svg.xlsx");
        let cases = [
            (
                "WordDocumentWithFilename",
                r#"Public Sub WordDocumentWithFilename()
                    Set o = ActiveSheet.OLEObjects.Add(ClassType:="Word.Document.12", Filename:="C:\work\sample.txt")
                End Sub"#,
                "OLEObjects クラスの Add メソッドが失敗しました。",
            ),
            (
                "WordDocumentBadWidth",
                r#"Public Sub WordDocumentBadWidth()
                    Set o = ActiveSheet.OLEObjects.Add(ClassType:="Word.Document.12", Width:="bad")
                End Sub"#,
                "OLEObjects クラスの Add メソッドが失敗しました。",
            ),
            (
                "WordDocumentBadDisplayAsIcon",
                r#"Public Sub WordDocumentBadDisplayAsIcon()
                    Set o = ActiveSheet.OLEObjects.Add(ClassType:="Word.Document.12", DisplayAsIcon:="1")
                End Sub"#,
                "OLEObjects クラスの Add メソッドが失敗しました。",
            ),
            (
                "WordDocumentBadLink",
                r#"Public Sub WordDocumentBadLink()
                    Set o = ActiveSheet.OLEObjects.Add(ClassType:="Word.Document.12", Link:="1")
                End Sub"#,
                "OLEObjects クラスの Add メソッドが失敗しました。",
            ),
            (
                "PackageWithFilename",
                r#"Public Sub PackageWithFilename()
                    Set o = ActiveSheet.OLEObjects.Add(ClassType:="Package", Filename:="C:\work\sample.txt")
                End Sub"#,
                "OLEObjects クラスの Add メソッドが失敗しました。",
            ),
            (
                "EmptyClassWithoutFilename",
                r#"Public Sub EmptyClassWithoutFilename()
                    Set o = ActiveSheet.OLEObjects.Add(ClassType:="")
                End Sub"#,
                "オブジェクトを挿入できません。",
            ),
        ];
        for (procedure, source, expected_message) in cases {
            let book = oxicells_core::parse_xlsx(bytes).unwrap();
            let outcome = execute_workbook_vba(book, source, procedure, vec![], 0, failure_context()).unwrap();
            let error = outcome.error.expect("Excel rejects this Add argument combination");
            assert!(error.message.ends_with(expected_message), "{procedure}: {}", error.message);
        }
    }

    #[test]
    fn ole_objects_duplicate_preserves_the_original_collection_view() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/scale_picture_original_ole.xlsx");
        let book = oxicells_core::parse_xlsx(bytes).unwrap();
        let source = r#"Public Sub DuplicateOleCollection()
            Set originals = ActiveSheet.OLEObjects
            Set returned = originals.Duplicate
            Debug.Print TypeName(returned) & "/" & CStr(returned.Count) & "/" & returned.Item(1).Name & "/" & returned.Item(2).Name
            Debug.Print CStr(originals.Count) & "/" & CStr(ActiveSheet.OLEObjects.Count) & "/" & CStr(ActiveSheet.Shapes.Count)
            For i = 3 To 4
                Set o = ActiveSheet.OLEObjects(i)
                Debug.Print o.Name & ";" & o.progId & ";" & CStr(o.Visible) & ";" & CStr(o.Left) & ";" & CStr(o.Top)
            Next
            ActiveSheet.OLEObjects.Visible = False
            Set hiddenReturn = ActiveSheet.OLEObjects.Duplicate
            Debug.Print CStr(hiddenReturn.Count) & "/" & CStr(ActiveSheet.OLEObjects.Count)
            For i = 5 To 8
                Set o = ActiveSheet.OLEObjects(i)
                Debug.Print o.Name & ";" & o.progId & ";" & CStr(o.Visible)
            Next
            ActiveWorkbook.SaveCopyAs "C:\work\ole-collection-duplicate.xlsx"
        End Sub"#;
        let mut context = failure_context();
        context.file_context = Some(file_io::FileContext {
            edit_revision: None, source_code_page: None,
            package_bytes: Some(bytes.to_vec()),
            full_name: Some("C:\\work\\ole-original.xlsx".into()),
            read_only: Some(true),
            folders: vec!["C:\\work".into()],
            files: vec![],
        });
        let outcome = execute_workbook_vba(book, source, "DuplicateOleCollection", vec![], 0, context).unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
        assert_eq!(outcome.debug_output, [
            "OLEObjects/2/Object 1/Object 2",
            "2/4/4",
            "Object 3;Package;True;211.5;111.75",
            "Object 4;Word.Document.12;True;211.5;271.5",
            "4/8",
            "Object 5;Package;False",
            "Object 6;Word.Document.12;False",
            "Object 7;Package;False",
            "Object 8;Word.Document.12;False",
        ]);
        let saved = outcome.files.iter().find(|file| file.path.ends_with("ole-collection-duplicate.xlsx")).unwrap();
        if let Some(path) = std::env::var_os("OXI_OLE_DUPLICATE_OUTPUT") {
            std::fs::write(path, &saved.bytes).unwrap();
        }
        let reopened = oxicells_core::parse_xlsx(&saved.bytes).unwrap();
        assert_eq!(reopened.sheets[0].drawings.iter().filter(|drawing| drawing.ole_prog_id.is_some()).count(), 8);
        assert_eq!(reopened.sheets[0].drawings[2].ole_prog_id.as_deref(), Some("Package"));
        assert_eq!(reopened.sheets[0].drawings[3].ole_prog_id.as_deref(), Some("Word.Document.12"));
        assert_eq!(reopened.sheets[0].drawings[4].ole_prog_id.as_deref(), Some("Package"));
        assert_eq!(reopened.sheets[0].drawings[7].ole_prog_id.as_deref(), Some("Word.Document.12"));
    }

