    #[test]
    fn ole_objects_geometry_setters_match_excel_pixel_and_anchor_rules() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/scale_picture_original_ole.xlsx");
        for (property, value, expected) in [
            (
                "Left",
                "220",
                ["Object 1/219.75/99.75/30.00/27.75", "Object 2/219.75/259.50/72.00/60.75"],
            ),
            (
                "Top",
                "220",
                ["Object 1/199.50/60.00/30.00/27.75", "Object 2/199.50/219.75/72.00/60.75"],
            ),
            (
                "Width",
                "60",
                ["Object 1/199.50/99.75/60.00/55.50", "Object 2/199.50/259.50/60.00/51.00"],
            ),
            (
                "Height",
                "60",
                ["Object 1/199.50/99.75/64.50/60.00", "Object 2/199.50/259.50/71.25/60.00"],
            ),
        ] {
            let book = oxicells_core::parse_xlsx(bytes).unwrap();
            let source = format!(
                r#"Public Sub SetOleCollectionGeometry()
                    ActiveSheet.OLEObjects.{property} = {value}
                    For i = 1 To ActiveSheet.OLEObjects.Count
                        Set item = ActiveSheet.OLEObjects(i)
                        Debug.Print item.Name & "/" & Format(item.Left, "0.00") & "/" & Format(item.Top, "0.00") & "/" & Format(item.Width, "0.00") & "/" & Format(item.Height, "0.00")
                    Next
                End Sub"#
            );
            let outcome = execute_workbook_vba(
                book,
                &source,
                "SetOleCollectionGeometry",
                vec![],
                0,
                failure_context(),
            )
            .unwrap();
            assert!(outcome.error.is_none(), "{property}: {:?}", outcome.error.as_ref().map(|error| &error.message));
            assert_eq!(outcome.debug_output, expected, "{property}");
        }

        let book = oxicells_core::parse_xlsx(bytes).unwrap();
        let source = r#"Public Sub SetOleCollectionLeftAnchor()
            ActiveSheet.OLEObjects(2).Left = 210
            ActiveSheet.OLEObjects.Left = 220
            For i = 1 To ActiveSheet.OLEObjects.Count
                Set item = ActiveSheet.OLEObjects(i)
                Debug.Print item.Name & "/" & Format(item.Left, "0.00")
            Next
        End Sub"#;
        let outcome = execute_workbook_vba(
            book,
            source,
            "SetOleCollectionLeftAnchor",
            vec![],
            0,
            failure_context(),
        )
        .unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
        assert_eq!(outcome.debug_output, ["Object 1/209.25", "Object 2/219.75"]);
    }

    #[test]
    fn ole_objects_group_matches_excel_group_object_and_persists() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/scale_picture_original_ole.xlsx");
        let book = oxicells_core::parse_xlsx(bytes).unwrap();
        let source = r#"Public Sub GroupOleObjects()
            Set grouped = ActiveSheet.OLEObjects.Group
            Debug.Print TypeName(grouped) & "/" & grouped.Name & "/" & CStr(grouped.Index) & "/" & CStr(grouped.Left) & "/" & CStr(grouped.Top) & "/" & CStr(grouped.Width) & "/" & CStr(grouped.Height) & "/" & CStr(grouped.Visible)
            Set range = grouped.ShapeRange
            Debug.Print TypeName(range) & "/" & CStr(range.Count) & "/" & TypeName(range.Item(1)) & "/" & range.Item(1).Name
            Set parent = range.Item(1)
            Debug.Print CStr(parent.Type) & "/" & CStr(parent.GroupItems.Count)
            For i = 1 To parent.GroupItems.Count
                Set child = parent.GroupItems(i)
                Debug.Print TypeName(child) & "/" & child.Name & "/" & child.OLEFormat.ProgID
            Next
            names = ""
            For Each child In ActiveSheet.OLEObjects
                names = names & child.Name & "/"
            Next
            Debug.Print "Each/" & names & "/" & CStr(ActiveSheet.OLEObjects.Count) & "/" & CStr(ActiveSheet.Shapes.Count)
            On Error Resume Next
            Set item = ActiveSheet.OLEObjects(1)
            Debug.Print CStr(Err.Number) & "/" & Err.Description
            ActiveWorkbook.SaveCopyAs "C:\work\ole-grouped.xlsx"
        End Sub"#;
        let mut context = failure_context();
        context.file_context = Some(file_io::FileContext {
            edit_revision: None, source_code_page: None,
            package_bytes: Some(bytes.to_vec()),
            full_name: Some("C:\\work\\ole-original.xlsx".into()),
            read_only: Some(true),
            folders: vec!["C:\\work".into()],
            files: vec![],
        });
        let outcome = execute_workbook_vba(book, source, "GroupOleObjects", vec![], 0, context).unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
        let ole_item_error = format!("1004/OLEObjects \u{30af}\u{30e9}\u{30b9}\u{306e} Item \u{30d7}\u{30ed}\u{30d1}\u{30c6}\u{30a3}\u{3092}\u{53d6}\u{5f97}\u{3067}\u{304d}\u{307e}\u{305b}\u{3093}\u{3002}");
        assert_eq!(outcome.debug_output, [
            "GroupObject/Group 1/1/199.5/99.75/72/220.5/True",
            "ShapeRange/1/Shape/Group 1",
            "6/2",
            "Shape/Object 1/Package",
            "Shape/Object 2/Word.Document.12",
            "Each//1/1",
            ole_item_error.as_str(),
        ]);
        let saved = outcome.files.iter().find(|file| file.path.ends_with("ole-grouped.xlsx")).unwrap();
        if let Some(path) = std::env::var_os("OXI_OLE_GROUP_OUTPUT") {
            std::fs::write(path, &saved.bytes).unwrap();
        }
        let reopened = oxicells_core::parse_xlsx(&saved.bytes).unwrap();
        assert_eq!(reopened.sheets[0].drawings.len(), 2);
        assert!(reopened.sheets[0].drawings.iter().all(|drawing| drawing.grouped));
        assert!(reopened.sheets[0].drawings.iter().all(|drawing| drawing.group_name.as_deref() == Some("Group 1")));
    }

