        context.file_context = Some(file_io::FileContext {
            edit_revision: None, source_code_page: None,
            package_bytes: Some(bytes.to_vec()),
            full_name: Some("C:\\work\\grouped.xlsx".into()),
            read_only: Some(true),
            folders: vec!["C:\\work".into()],
            files: vec![],
        });
        let source = r#"Public Sub RemoveGroupChild()
            ActiveSheet.Shapes("MyGroup").GroupItems("ChildA").Delete
            Debug.Print ActiveSheet.Shapes.Count & "/" & ActiveSheet.Shapes(1).Name & "/" & ActiveSheet.Shapes(1).Left
            ActiveWorkbook.SaveCopyAs "C:\work\ungrouped.xlsx"
        End Sub"#;
        let mut session = None;
        let outcome = execute_workbook_action_in_session(
            book, source, Some("RemoveGroupChild"), vec![], 0, context, &mut session,
        ).unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
