    #[test]
    fn vba_replace_format_changes_only_replaced_cells() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub ReplaceFormatCells()
               Range(\"A1:A3\").Value = \"x\"
               Range(\"A1\").Font.Bold = True
               Range(\"A1\").Font.Strikethrough = True
               Application.ReplaceFormat.Clear
               Application.ReplaceFormat.Font.Italic = True
               changed = Range(\"A1:A3\").Replace(\"x\", \"y\", xlWhole, xlByRows, False, False, False, True)
               Debug.Print Range(\"A1\").Font.Bold, Range(\"A1\").Font.Italic, Range(\"A1\").Font.Strikethrough, Range(\"A2\").Font.Bold, Range(\"A2\").Font.Italic
               Range(\"A2\").Font.Bold = True
               Application.FindFormat.Clear
               Application.FindFormat.Font.Bold = True
               Application.ReplaceFormat.Clear
               Application.ReplaceFormat.Interior.Color = 65535
               changed = Range(\"A1:A3\").Replace(\"y\", \"z\", xlWhole, xlByRows, False, False, True, True)
               Debug.Print Range(\"A1\").Value, Range(\"A2\").Value, Range(\"A3\").Value, Range(\"A1\").Interior.Color, Range(\"A2\").Interior.Color
               Range(\"B1:B2\").Value = \"a\"
               Application.ReplaceFormat.Clear
               Application.ReplaceFormat.HorizontalAlignment = xlCenter
               Application.ReplaceFormat.VerticalAlignment = xlTop
               Application.ReplaceFormat.WrapText = True
               Application.ReplaceFormat.ShrinkToFit = True
               Application.ReplaceFormat.Orientation = 45
               changed = Range(\"B1:B2\").Replace(\"a\", \"b\", xlWhole, xlByRows, False, False, False, True)
               Debug.Print Range(\"B1\").HorizontalAlignment, Range(\"B1\").VerticalAlignment, Range(\"B1\").WrapText, Range(\"B1\").ShrinkToFit, Range(\"B1\").Orientation
               Debug.Print Range(\"B2\").HorizontalAlignment, Range(\"B2\").VerticalAlignment, Range(\"B2\").WrapText, Range(\"B2\").ShrinkToFit, Range(\"B2\").Orientation
               Range(\"C1:C2\").Value = \"pattern\"
               Range(\"C1\").Interior.Color = 65535
               Application.ReplaceFormat.Clear
               Application.ReplaceFormat.Interior.Pattern = -4142
               changed = Range(\"C1:C2\").Replace(\"pattern\", \"plain\", xlWhole, xlByRows, False, False, False, True)
               Debug.Print Range(\"C1\").Interior.Pattern, Range(\"C1\").Interior.Color, Range(\"C2\").Interior.Pattern
               Range(\"D1:D2\").Value = \"pattern\"
               Application.ReplaceFormat.Clear
               Application.ReplaceFormat.Interior.Pattern = -4121
               Application.ReplaceFormat.Interior.PatternColor = 255
               changed = Range(\"D1:D2\").Replace(\"pattern\", \"hatch\", xlWhole, xlByRows, False, False, False, True)
               Debug.Print Range(\"D1\").Interior.Pattern, Range(\"D1\").Interior.PatternColor, Range(\"D2\").Interior.Pattern
             End Sub\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        execute_with_host(&module, "ReplaceFormatCells", vec![], &mut host).unwrap();
        assert_eq!(
            host.take_debug_output(),
            vec![
                "False\tTrue\tTrue\tFalse\tTrue".to_string(),
                "y\tz\ty\t16777215\t65535".to_string(),
                "-4108\t-4160\tTrue\tTrue\t45".to_string(),
                "-4108\t-4160\tTrue\tTrue\t45".to_string(),
                "-4142\t16777215\t-4142".to_string(),
                "-4121\t255\t-4121".to_string(),
            ]
        );
    }

    #[test]
    fn vba_merges_and_unmerges_ranges_without_keeping_hidden_contents() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub MergeRanges()
               Range(\"A1\").Value = \"heading\"
               Range(\"B1\").Value = \"discarded\"
               Range(\"A2\").Value = 3
               Range(\"B2\").Formula = \"=A2*2\"
               Range(\"A1:B2\").Merge
               Debug.Print Range(\"A1\").MergeCells, Range(\"A1:B2\").MergeCells, Range(\"A1:C2\").MergeCells, Range(\"C1\").MergeCells
               Range(\"A1:B2\").UnMerge
               Range(\"C1:D1\").MergeCells = True
               Range(\"E1:F1\").MergeCells = True
               Range(\"E1\").MergeCells = False
             End Sub\n",
        )
        .unwrap();
        let debug_output = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "MergeRanges", vec![], &mut host).unwrap();
            host.take_debug_output()
        };

        let sheet = &workbook.sheets[0];
        assert!(matches!(
            &sheet.rows[0].cells[0].value,
            CellValue::String(value) if value == "heading"
        ));
        assert!(matches!(sheet.rows[0].cells[1].value, CellValue::Empty));
        assert!(matches!(sheet.rows[1].cells[0].value, CellValue::Empty));
        assert!(matches!(sheet.rows[1].cells[1].value, CellValue::Empty));
        assert_eq!(sheet.rows[1].cells[1].formula, None);
        assert_eq!(sheet.merge_cells.len(), 1);
        let merge = &sheet.merge_cells[0];
        assert_eq!(
            (
                merge.start_row,
                merge.start_col,
                merge.end_row,
                merge.end_col
            ),
            (1, 2, 1, 3)
        );
        assert_eq!(debug_output, vec!["True\tTrue\tNull\tFalse".to_string()]);

        let overlap = parse_module(
            "Public Sub OverlapMerge()
               Range(\"D1:E1\").Merge
             End Sub\n",
        )
        .unwrap();
        // Measured: a merge over part of another takes the whole of it in,
        // D1:E1 over C1:D1 making C1:E1.
        {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&overlap, "OverlapMerge", vec![], &mut host).unwrap();
        }
        assert_eq!(workbook.sheets[0].merge_cells.len(), 1);
        let merge = &workbook.sheets[0].merge_cells[0];
        assert_eq!((merge.start_row, merge.start_col, merge.end_row, merge.end_col), (1, 2, 1, 4));
    }

