    #[test]
    fn vba_reads_and_writes_range_formulas() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function WriteFormulas() As String
               Range(\"A1\").Value = 10
               Range(\"A2\").Value = 20
               Range(\"A3\").Formula = \"=SUM(A1:A2)\"
               Range(\"B1:B2\").Formula2 = \"=A1*2\"
               WriteFormulas = Range(\"A3\").Formula & \"|\" & Range(\"B1\").Formula2
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "WriteFormulas", vec![], &mut host).unwrap()
        };

        assert_eq!(result, Value::String("=SUM(A1:A2)|=A1*2".to_string()));
        assert_eq!(
            workbook.sheets[0].rows[2].cells[0].formula.as_deref(),
            Some("SUM(A1:A2)")
        );
        assert_eq!(
            workbook.sheets[0].rows[0].cells[1].formula.as_deref(),
            Some("A1*2")
        );
        // The second cell of the block is not a copy of the first: the
        // reference moved down with it, as it does in Excel.
        assert_eq!(
            workbook.sheets[0].rows[1].cells[1].formula.as_deref(),
            Some("A2*2")
        );
    }

    /// A formula written to a block is filled from its top-left corner.
    ///
    /// Every answer here was asked of Excel: `Range("F1:G2").Formula = "=A1"`
    /// leaves F1 `=A1`, G1 `=B1`, F2 `=A2`, G2 `=B2`; `"=$A$1"` leaves all
    /// three cells of a column alone; and `.Value` fills the same way, because
    /// a string starting with `=` is a formula through either door. An array
    /// names each cell's own content, so nothing in it moves.
    #[test]
    fn vba_fills_a_block_with_a_formula_from_its_corner() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function FillBlock() As String
               Range(\"F1:G2\").Formula = \"=A1\"
               Range(\"H1:H3\").Value = \"=A1*3\"
               Range(\"I1:I3\").Formula = \"=$A$1\"
               Range(\"M1:O1\").Value = Array(\"=A1*7\", \"=A1*8\", \"=A1*9\")
               FillBlock = Range(\"F1\").Formula & \"|\" & Range(\"G1\").Formula & \"|\" & _
                 Range(\"F2\").Formula & \"|\" & Range(\"G2\").Formula & \"|\" & _
                 Range(\"H2\").Formula & \"|\" & Range(\"H3\").Formula & \"|\" & _
                 Range(\"I3\").Formula & \"|\" & Range(\"N1\").Formula & \"|\" & _
                 Range(\"H1:H3\").HasFormula
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "FillBlock", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String(
                "=A1|=B1|=A2|=B2|=A2*3|=A3*3|=$A$1|=A1*8|True".to_string()
            )
        );
    }

    /// `.Value` and `.Formula` read a string the same way.
    ///
    /// Asked of Excel, `.Formula = "0123"` leaves the number 123 with
    /// `HasFormula` False, `"TRUE"` leaves a Boolean, `"(5)"` leaves −5,
    /// `"'=B1"` keeps its text, and `"="` on its own stays the text `=`.
    /// Only a leading `=` with something after it makes a formula.
    #[test]
    fn vba_reads_an_assigned_string_the_same_way_through_value_and_formula() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function TypedIn() As String
               Range(\"A1\").Formula = \"0123\"
               Range(\"A2\").Formula = \"TRUE\"
               Range(\"A3\").Formula = \"(5)\"
               Range(\"A4\").Formula = \"'=B1\"
               Range(\"A5\").Formula = \"=\"
               Range(\"A6\").Formula = \"hello\"
               TypedIn = TypeName(Range(\"A1\").Value) & \"|\" & Range(\"A1\").Value & \"|\" & _
                 TypeName(Range(\"A2\").Value) & \"|\" & Range(\"A3\").Value & \"|\" & _
                 Range(\"A4\").Value & \"|\" & Range(\"A5\").Value & \"|\" & _
                 Range(\"A6\").Value & \"|\" & Range(\"A1:A6\").HasFormula
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "TypedIn", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String("Double|123|Boolean|-5|=B1|=|hello|False".to_string())
        );
    }

    /// `FormulaR1C1` says a formula from where it sits, so one string fills a
    /// column correctly. Every answer was asked of Excel: a formula in B2
    /// pointing at A1 shows `=R[-1]C[-1]*2`, `=RC[-3]*2` written down D1:D3
    /// leaves `=A1*2`, `=A2*2`, `=A3*2`, `=R1C1` leaves `=$A$1`, and a cell
    /// holding a number answers with the number.
    #[test]
    fn vba_says_a_formula_from_where_it_sits() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function R1C1() As String
               Range(\"A1\").Value = 10
               Range(\"A2\").Value = 20
               Range(\"A3\").Value = 30
               Range(\"B2\").Formula = \"=A1*2\"
               Range(\"D1:D3\").FormulaR1C1 = \"=RC[-3]*2\"
               Range(\"D5\").FormulaR1C1 = \"=R1C1\"
               Range(\"F1:F3\").FormulaR1C1 = \"=R1C1+RC[-5]\"
               R1C1 = Range(\"B2\").FormulaR1C1 & \"|\" & Range(\"D1\").Formula & \"|\" & _
                 Range(\"D3\").Formula & \"|\" & Range(\"D3\").FormulaR1C1 & \"|\" & _
                 Range(\"D5\").Formula & \"|\" & Range(\"F2\").Formula & \"|\" & _
                 Range(\"A1\").FormulaR1C1
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "R1C1", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String(
                "=R[-1]C[-1]*2|=A1*2|=A3*2|=RC[-3]*2|=$A$1|=$A$1+A2|10".to_string()
            )
        );
    }

    /// A block answers with one formula per cell, each said from that cell.
    #[test]
    fn vba_reads_a_block_of_r1c1_formulas_cell_by_cell() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Block() As String
               Range(\"B1:B2\").Formula = \"=A1*2\"
               Dim said, plain
               said = Range(\"B1:B2\").FormulaR1C1
               plain = Range(\"B1:B2\").Formula
               Block = said(1, 1) & \"|\" & said(2, 1) & \"|\" & plain(2, 1)
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Block", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String("=RC[-1]*2|=RC[-1]*2|=A2*2".to_string())
        );
    }

    /// An array is a block laid on the corner, and what it does not cover is
    /// either filled or left `#N/A`.
    ///
    /// Asked of Excel with `Array("=A1*7", "=A1*8", "=A1*9")`, which is one
    /// ROW of three: down five rows only the first entry is used and it fills,
    /// leaving `=A1*7 … =A5*7`; across five columns the three entries land and
    /// the last two cells are `#N/A`; over two rows of three, the second row
    /// is the first filled down. `Array(1, 2, 3)` down three rows leaves 1, 1,
    /// 1 — a number fills by repeating.
    #[test]
    fn vba_lays_an_array_on_the_corner_and_fills_the_free_side() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Spread() As String
               Range(\"A1\").Value = 10
               Range(\"A2\").Value = 20
               Range(\"A3\").Value = 30
               Range(\"A4\").Value = 40
               Range(\"A5\").Value = 50
               Range(\"C1:C5\").Value = Array(\"=A1*7\", \"=A1*8\", \"=A1*9\")
               Range(\"F1:H1\").Value = Array(\"=A1*7\", \"=A1*8\", \"=A1*9\")
               Range(\"F3:J3\").Value = Array(\"=A1*7\", \"=A1*8\", \"=A1*9\")
               Range(\"L1:N2\").Value = Array(\"=A1*7\", \"=A1*8\", \"=A1*9\")
               Range(\"L4:L6\").Value = Array(1, 2, 3)
               Range(\"U1:V3\").Formula = Range(\"C1:C3\").Formula
               Range(\"X1:Y3\").Formula = Range(\"C1:C2\").Formula
               Spread = Range(\"C1\").Formula & \"|\" & Range(\"C5\").Formula & \"|\" & _
                 Range(\"H1\").Formula & \"|\" & Range(\"N2\").Formula & \"|\" & _
                 Range(\"L6\").Value & \"|\" & Range(\"V3\").Formula & \"|\" & _
                 Range(\"Y2\").Formula
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Spread", vec![], &mut host).unwrap()
        };

        // The last two come from a column of three and a column of two laid
        // across two columns: the free side fills to the right.
        assert_eq!(
            result,
            Value::String("=A1*7|=A5*7|=A1*9|=A2*9|1|=B3*7|=B2*7".to_string())
        );
        // A column of two laid down three rows leaves the third row `#N/A`.
        let short = |column: u32| {
            workbook.sheets[0]
                .rows
                .iter()
                .find(|row| row.index == 3)
                .and_then(|row| row.cells.iter().find(|cell| cell.col == column))
                .map(|cell| match &cell.value {
                    CellValue::Error(text) => text.clone(),
                    other => format!("{other:?}"),
                })
        };
        assert_eq!(short(23).as_deref(), Some("#N/A"));
        assert_eq!(short(24).as_deref(), Some("#N/A"));
        // I3 and J3 are past the far end of a row of three.
        let beyond = |column: u32| {
            workbook.sheets[0]
                .rows
                .iter()
                .find(|row| row.index == 3)
                .and_then(|row| row.cells.iter().find(|cell| cell.col == column))
                .map(|cell| match &cell.value {
                    CellValue::Error(text) => text.clone(),
                    other => format!("{other:?}"),
                })
        };
        assert_eq!(beyond(8).as_deref(), Some("#N/A"));
        assert_eq!(beyond(9).as_deref(), Some("#N/A"));
    }

    /// A cut moves the cells and the references that named them.
    ///
    /// Asked of Excel, cutting `A1:B2` onto `D5`: the block arrives whole with
    /// its fill, the source is left bare, `=A1*10` written inside the block
    /// now reads `=D5*10` while `=G9` written inside it is untouched, and the
    /// watchers outside follow — `=A1` to `=D5`, `=SUM(A1:B2)` to
    /// `=SUM(D5:E6)`, `=$A$1` to `=$D$5`. A watcher of `D5`, which the block
    /// landed on, is left with `#REF!`.
    #[test]
    fn vba_cut_takes_the_references_that_named_the_cells_with_it() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function MoveBlock() As String
               Range(\"A1\").Value = 1
               Range(\"A2\").Value = 2
               Range(\"B1\").Formula = \"=A1*10\"
               Range(\"B2\").Formula = \"=G9\"
               Range(\"F1\").Formula = \"=A1\"
               Range(\"F2\").Formula = \"=SUM(A1:B2)\"
               Range(\"F3\").Formula = \"=$A$1\"
               Range(\"F4\").Formula = \"=D5\"
               Range(\"F5\").Formula = \"=SUM(A1:B4)\"
               Range(\"A1:B2\").Interior.Color = 255
               Range(\"A1:B2\").Cut Range(\"D5\")
               MoveBlock = Range(\"D5\").Value & \"|\" & Range(\"D6\").Value & \"|\" & _
                 Range(\"E5\").Formula & \"|\" & Range(\"E6\").Formula & \"|\" & _
                 Range(\"F1\").Formula & \"|\" & Range(\"F2\").Formula & \"|\" & _
                 Range(\"F3\").Formula & \"|\" & Range(\"F4\").Formula & \"|\" & _
                 Range(\"F5\").Formula & \"|\" & Range(\"D5\").Interior.Color
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "MoveBlock", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String(
                "1|2|=D5*10|=G9|=D5|=SUM(D5:E6)|=$D$5|=#REF!|=SUM(A1:B4)|255".to_string()
            )
        );
        // The block left nothing behind, not even the face it was wearing.
        let left = |row: u32, column: u32| {
            workbook.sheets[0]
                .rows
                .iter()
                .find(|held| held.index == row)
                .and_then(|held| held.cells.iter().find(|cell| cell.col == column))
                .is_some()
        };
        assert!(!left(1, 0), "A1 should be bare");
        assert!(!left(1, 1), "B1 should be bare");
        assert!(!left(2, 0), "A2 should be bare");
        assert!(!left(2, 1), "B2 should be bare");
    }

    /// A workbook with two sheets and a handful of names, as measured.
    fn named_workbook() -> Workbook {
        let mut workbook = workbook();
        let mut second = workbook.sheets[0].clone();
        second.name = "Sheet2".to_string();
        workbook.sheets.push(second);
        workbook.defined_names = vec![
            ("Sales".to_string(), "Sheet1!$A$1:$A$5".to_string()),
            ("OneCell".to_string(), "Sheet1!$A$2".to_string()),
            ("Away".to_string(), "Sheet2!$B$2".to_string()),
            (
                "Scattered".to_string(),
                "Sheet1!$A$1,Sheet1!$A$3".to_string(),
            ),
            ("Number".to_string(), "42".to_string()),
            ("WholeColumn".to_string(), "Sheet1!$A:$A".to_string()),
        ];
        workbook
    }

    /// A range can be reached by the name the workbook gave it.
    ///
    /// Asked of Excel: the lookup ignores case; a worksheet answers only for
    /// the names pointing at itself, so `Sheets("Sheet1").Range("Away")`
    /// raises while `Application.Range("Away")` reaches it.
    #[test]
    fn vba_reaches_a_range_by_the_name_the_workbook_gave_it() {
        let mut workbook = named_workbook();
        let module = parse_module(
            "Public Function ByName() As String
               Range(\"A1\").Value = 100
               Range(\"A2\").Value = 200
               Worksheets(\"Sheet2\").Range(\"B2\").Value = \"over here\"
               ByName = Range(\"Sales\").Address(False, False) & \"|\" & _
                 Range(\"sales\").Count & \"|\" & Range(\"OneCell\").Value & \"|\" & _
                 Application.Range(\"Away\").Value & \"|\" & _
                 Worksheets(\"Sheet2\").Range(\"Away\").Address(False, False) & \"|\" & _
                 Range(\"Sales\").Worksheet.Name
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "ByName", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String("A1:A5|5|200|over here|B2|Sheet1".to_string())
        );
    }

    /// A name points at cells, so it follows them when they move.
    ///
    /// Asked of Excel: a name standing for `Sheet1!$A$1:$A$5` reads
    /// `=Sheet1!$D$1:$D$5` once those cells are cut onto D1, and asking for it
    /// by name afterwards finds them where they went.
    #[test]
    fn vba_a_name_follows_the_cells_a_cut_moved() {
        let mut workbook = named_workbook();
        let module = parse_module(
            "Public Function Follow() As String
               Range(\"A2\").Value = 200
               Range(\"A1:A5\").Cut Range(\"D1\")
               Follow = Range(\"Sales\").Address(False, False) & \"|\" & _
                 Range(\"OneCell\").Address(False, False) & \"|\" & _
                 Range(\"OneCell\").Value & \"|\" & _
                 Application.Range(\"Away\").Address(False, False)
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Follow", vec![], &mut host).unwrap()
        };

        assert_eq!(result, Value::String("D1:D5|D2|200|B2".to_string()));
        assert_eq!(
            workbook.defined_names[0],
            ("Sales".to_string(), "Sheet1!$D$1:$D$5".to_string())
        );
        // A name on another sheet was never named by this cut.
        assert_eq!(
            workbook.defined_names[2],
            ("Away".to_string(), "Sheet2!$B$2".to_string())
        );
    }

    /// A name follows rows put in and taken out, the same as a formula does.
    ///
    /// Asked of Excel with a name standing for `$A$1:$A$5`: a row put in above
    /// leaves `$A$2:$A$6`, and taking out a row it covers closes it up to
    /// `$A$1:$A$4` while a name on that one row alone is left with `#REF!`.
    #[test]
    fn vba_a_name_follows_rows_put_in_and_taken_out() {
        let mut workbook = named_workbook();
        let module = parse_module(
            "Public Function Pushed() As String
               Range(\"A1\").EntireRow.Insert
               Pushed = Range(\"Sales\").Address(False, False) & \"|\" & _
                 Range(\"OneCell\").Address(False, False)
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Pushed", vec![], &mut host).unwrap()
        };
        assert_eq!(result, Value::String("A2:A6|A3".to_string()));

        let mut workbook = named_workbook();
        let module = parse_module(
            "Public Function Closed() As String
               Range(\"A2\").EntireRow.Delete
               Closed = Range(\"Sales\").Address(False, False)
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Closed", vec![], &mut host).unwrap()
        };
        assert_eq!(result, Value::String("A1:A4".to_string()));
        // The name standing on the row that went has nothing left to point at.
        assert!(
            workbook.defined_names[1].1.contains("#REF!"),
            "OneCell says {:?}",
            workbook.defined_names[1].1
        );
    }

    /// Where the edges are, from every cell that has one.
    ///
    /// A sheet with a run in A1:A3, a gap, a run in A6:A7, a lone cell at A20,
    /// a run in C3:D3 and a block in B6:C7 — every answer below was asked of
    /// Excel. `End` starts from the block's TOP-LEFT cell, and running out of
    /// the sheet stops at its edge rather than raising.
    #[test]
    fn vba_finds_the_edge_from_a_cell_and_from_a_block() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Edges() As String
               Range(\"A1\").Value = \"a1\"
               Range(\"A2\").Value = \"a2\"
               Range(\"A3\").Value = \"a3\"
               Range(\"A6\").Value = \"a6\"
               Range(\"A7\").Value = \"a7\"
               Range(\"A20\").Value = \"a20\"
               Range(\"C3\").Value = \"c3\"
               Range(\"D3\").Value = \"d3\"
               Range(\"B6\").Value = \"b6\"
               Range(\"C6\").Value = \"c6\"
               Range(\"B7\").Value = \"b7\"
               Range(\"C7\").Value = \"c7\"
               Edges = Range(\"A1\").End(xlDown).Address(False, False) & \"|\" & _
                 Range(\"A3\").End(xlDown).Address(False, False) & \"|\" & _
                 Range(\"A4\").End(xlDown).Address(False, False) & \"|\" & _
                 Range(\"A5\").End(xlDown).Address(False, False) & \"|\" & _
                 Range(\"A7\").End(xlDown).Address(False, False) & \"|\" & _
                 Range(\"A20\").End(xlDown).Address(False, False) & \"|\" & _
                 Range(\"A1\").End(xlUp).Address(False, False) & \"|\" & _
                 Range(\"A20\").End(xlUp).Address(False, False) & \"|\" & _
                 Range(\"A4\").End(xlUp).Address(False, False) & \"|\" & _
                 Range(\"B3\").End(xlToRight).Address(False, False) & \"|\" & _
                 Range(\"C3\").End(xlToRight).Address(False, False) & \"|\" & _
                 Range(\"D3\").End(xlToLeft).Address(False, False) & \"|\" & _
                 Range(\"A1\").End(xlToLeft).Address(False, False) & \"|\" & _
                 Range(\"B6:C7\").End(xlDown).Address(False, False) & \"|\" & _
                 Range(\"B6:C7\").End(xlToRight).Address(False, False) & \"|\" & _
                 Range(\"B6:C7\").End(xlUp).Address(False, False)
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Edges", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String(
                "A3|A6|A6|A6|A20|A1048576|A1|A7|A3|C3|D3|C3|A1|B7|C6|B1".to_string()
            )
        );
    }

    /// The block a cell belongs to, which blanks fence in on every side.
