    /// Stepping a block about and changing its shape, and how it counts.
    ///
    /// Every answer was asked of Excel. An omitted `Offset` argument moves
    /// nothing and an omitted `Resize` argument keeps that side's size, one
    /// index into `Cells` counts row-major and MAY leave the block — the 13th
    /// cell of `B2:D5` is `B6` — and stepping or growing off the sheet raises.
    #[test]
    fn vba_steps_a_block_about_and_counts_it() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Shape() As String
               Shape = Range(\"B2\").Offset(1).Address(False, False) & \"|\" & _
                 Range(\"B2\").Offset(, 2).Address(False, False) & \"|\" & _
                 Range(\"B2:C3\").Offset(1, 1).Address(False, False) & \"|\" & _
                 Range(\"A1\").Resize(2).Address(False, False) & \"|\" & _
                 Range(\"A1:C1\").Resize(2).Address(False, False) & \"|\" & _
                 Range(\"A1:C1\").Resize(, 1).Address(False, False) & \"|\" & _
                 Rows.Count & \"|\" & Columns.Count & \"|\" & _
                 Range(\"B2:D5\").Rows.Count & \"|\" & Range(\"B2:D5\").Columns.Count & \"|\" & _
                 Range(\"B2:D5\").Count & \"|\" & _
                 Range(\"A1\").EntireRow.Address & \"|\" & _
                 Range(\"A1\").EntireColumn.Address & \"|\" & _
                 Range(\"B2:D5\").Rows(2).Address(False, False) & \"|\" & _
                 Range(\"B2:D5\").Columns(2).Address(False, False) & \"|\" & _
                 Range(\"B2:D5\").Cells(2, 2).Address(False, False) & \"|\" & _
                 Range(\"B2:D5\").Cells(5).Address(False, False) & \"|\" & _
                 Range(\"B2:D5\").Cells(13).Address(False, False)
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Shape", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String(
                "B3|D2|C3:D4|A1:A2|A1:C2|A1|1048576|16384|4|3|12|$1:$1|$A:$A|\
                 B3:D3|C2:C5|C3|C3|B6"
                    .to_string()
            )
        );
    }

    /// Stepping or growing off the sheet raises, as it does in Excel.
    #[test]
    fn vba_refuses_a_step_that_leaves_the_sheet() {
        for call in [
            "Range(\"A1\").Offset(-1, 0)",
            "Range(\"A1\").Offset(0, -1)",
            "Range(\"XFD1\").Offset(0, 1)",
            "Range(\"A1\").Resize(0, 1)",
            "Range(\"A1\").Resize(-1, 1)",
            "Range(\"XFC1\").Resize(1, 3)",
        ] {
            let mut workbook = workbook();
            let module =
                parse_module(&format!("Public Sub Step1()\n  {call}.Select\nEnd Sub\n")).unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            assert!(
                execute_with_host(&module, "Step1", vec![], &mut host).is_err(),
                "{call} should have refused"
            );
        }
    }

    /// What a format getter answers about a cell nobody has dressed, and about
    /// a block whose cells disagree.
    ///
    /// Asked of Excel: an untouched cell answers with the value it is actually
    /// WEARING — `False`, `11`, `General`, white — rather than with nothing.
    /// A block whose cells disagree answers Null, which is how a macro can
    /// tell "they all say X" from "they do not agree".
    #[test]
    fn vba_answers_for_the_format_a_cell_is_actually_wearing() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Dressed() As String
               Range(\"A2\").Value = \"dressed\"
               Range(\"A3\").Value = \"plain\"
               Range(\"A2\").Font.Bold = True
               Range(\"A2\").Font.Size = 14
               Range(\"A2\").NumberFormat = \"0.00\"
               Range(\"A2\").HorizontalAlignment = xlRight
               Range(\"A2\").WrapText = True
               Range(\"A2\").IndentLevel = 2
               Range(\"E1:E2\").Font.Bold = True
               Range(\"G1\").Font.Color = 255
               Range(\"G1\").Interior.Color = 255
               Range(\"H1\").Interior.Color = 255
               Range(\"H2\").Interior.Color = 255
               Dressed = TypeName(Range(\"C5\").Font.Bold) & \":\" & Range(\"C5\").Font.Bold & \"|\" & _
                 Range(\"C5\").Font.Italic & \"|\" & Range(\"C5\").Font.Size & \"|\" & _
                 Range(\"C5\").Interior.Color & \"|\" & Range(\"C5\").NumberFormat & \"|\" & _
                 Range(\"C5\").HorizontalAlignment & \"|\" & Range(\"C5\").WrapText & \"|\" & _
                 Range(\"C5\").IndentLevel & \"|\" & _
                 TypeName(Range(\"A2:A3\").Font.Bold) & \"|\" & _
                 TypeName(Range(\"A2:A3\").Font.Size) & \"|\" & _
                 TypeName(Range(\"A2:A3\").NumberFormat) & \"|\" & _
                 TypeName(Range(\"A2:A3\").HorizontalAlignment) & \"|\" & _
                 TypeName(Range(\"A2:A3\").WrapText) & \"|\" & _
                 TypeName(Range(\"A2:A3\").IndentLevel) & \"|\" & _
                 Range(\"E1:E2\").Font.Bold & \"|\" & Range(\"E1:E2\").Font.Size & \"|\" & _
                 Range(\"C5\").Font.Color & \"|\" & _
                 TypeName(Range(\"G1:G2\").Font.Color) & \"|\" & _
                 Range(\"G1:G2\").Interior.Color & \"|\" & _
                 Range(\"H1:H2\").Interior.Color
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Dressed", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String(
                "Boolean:False|False|11|16777215|General|1|False|0|\
                 Null|Null|Null|Null|Null|Null|True|11|0|Null|0|255"
                    .to_string()
            )
        );
    }

    /// `Font.Underline` answers with a STYLE, not with True or False.
    ///
    /// Asked of Excel: a cell nobody has underlined answers
    /// `xlUnderlineStyleNone` (-4142), and one set with either `True` or
    /// `xlUnderlineStyleSingle` answers `2`. A block whose cells disagree
    /// answers Null. The double and accounting rules are kept beside the
    /// cell and read back as themselves -- measured, -4119 and 3 both read
    /// -4119, 4 and 5 read 4 and 5, and 0 is refused with 1004.
    #[test]
    fn vba_says_which_rule_runs_under_a_cell() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Ruled() As String
               Range(\"A1\").Font.Underline = True
               Range(\"A2\").Font.Underline = xlUnderlineStyleSingle
               Range(\"A3\").Font.Underline = False
               Range(\"B1\").Font.Underline = True
               Ruled = Range(\"A1\").Font.Underline & \"|\" & _
                 Range(\"A2\").Font.Underline & \"|\" & _
                 Range(\"A3\").Font.Underline & \"|\" & _
                 Range(\"C9\").Font.Underline & \"|\" & _
                 TypeName(Range(\"B1:B2\").Font.Underline) & \"|\" & _
                 Range(\"A1:A2\").Font.Underline
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Ruled", vec![], &mut host).unwrap()
        };

        assert_eq!(result, Value::String("2|2|-4142|-4142|Null|2".to_string()));

        for (asked, read) in [("xlUnderlineStyleDouble", -4119), ("3", -4119), ("4", 4), ("5", 5)] {
            let module = parse_module(&format!(
                "Public Function Rule() As Long\n  Range(\"A1\").Font.Underline = {asked}\n  Rule = Range(\"A1\").Font.Underline\nEnd Function\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            let result = execute_with_host(&module, "Rule", vec![], &mut host).unwrap();
            assert_eq!(result, Value::Integer(read), "{asked}");
        }
        let module =
            parse_module("Public Sub Rule()\n  Range(\"A1\").Font.Underline = 0\nEnd Sub\n").unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        let refused = execute_with_host(&module, "Rule", vec![], &mut host).unwrap_err();
        assert_eq!(refused.vba_number, Some(1004));
    }

    /// Excel ColorIndex oracle cases: exact palette colors, selected RGB
    /// values, and all 256 achromatic values with measured transition ranges.
    #[test]
    fn a_colour_is_called_by_the_nearest_of_the_fifty_six() {
        for (colour, index) in [
            (255, 3),
            (16711680, 5),
            (65535, 6),
            (0, 1),
            (16777215, 2),
            (12345, 52),
            (8421504, 16),
            (1193046, 52),
            (5592405, 56),
            (11184810, 48),
            (3355443, 56),
            (16777214, 2),
            (1, 1),
            (128, 9),
            (4210752, 56),
            (8388736, 13),
            (255255, 4),
            (6710886, 16),
            (9474192, 48),
            (2105376, 56),
            (15790320, 2),
            (100, 9),
            (40000, 10),
            (8000000, 11),
            (16000000, 5),
            (7829367, 16),
            (2430558, 56),
            (3158480, 53),
            (2883910, 56),
            (14031529, 7),
            (3043823, 46),
            (4154104, 46),
            (1663941, 46),
            (14063972, 17),
        ] {
            assert_eq!(
                nearest_palette_index(colour),
                index,
                "Excel calls {colour} colour {index}"
            );
        }
        // Excel COM measured every gray value from 0 through 255. These
        // ranges preserve every transition, including the achromatic-only
        // palette selection used for grayscale input.
        for gray in 0..=255 {
            let expected = match gray {
                0..=25 => 1,
                26..=89 => 56,
                90..=139 => 16,
                140..=170 => 48,
                171..=223 => 15,
                _ => 2,
            };
            assert_eq!(nearest_palette_index(gray * 0x010101), expected, "gray {gray}");
        }
        // And the two directions agree where a colour IS one of the 56.
        for index in 1..=56 {
            let hex = colour_from_packed(COLOUR_PALETTE[index - 1]);
            assert_eq!(
                colour_to_packed(Some(&hex)),
                Some(COLOUR_PALETTE[index - 1]),
                "colour {index} did not come back"
            );
        }
    }

    #[test]
    fn colorindex_reads_and_writes_the_workbooks_indexed_palette() {
        let palette = [
            "000000", "FFFFFF", "FF0000", "00FF00", "0000FF", "FFFF00", "FF00FF", "00FFFF",
            "000000", "FFFFFF", "DD0806", "1FB714", "0000D4", "FCF305", "F20884", "00ABEA",
            "900000", "006411", "000090", "90713A", "4600A5", "008080", "C0C0C0", "808080",
            "9999FF", "993366", "FFFFCC", "CCFFFF", "660066", "FF8080", "0066CC", "CCCCFF",
            "000080", "FF00FF", "FFFF00", "00FFFF", "800080", "800000", "008080", "0000FF",
            "00CCFF", "CCFFFF", "CCFFCC", "FFFF99", "99CCFF", "FF99CC", "CC99FF", "FFCC99",
            "3366FF", "33CCCC", "99CC00", "FFCC00", "FF9900", "FF6600", "666699", "969696",
            "003366", "339966", "003300", "333300", "993300", "993366", "333399", "333333",
        ].iter().map(|rgb| format!(r#"<rgbColor rgb="FF{rgb}"/>"#)).collect::<String>();
        let seed = include_bytes!("../../../tests/fixtures/conditional/cell_is.xlsx");
        let mut archive = zip::ZipArchive::new(std::io::Cursor::new(seed)).unwrap();
        let mut styles = String::new();
        std::io::Read::read_to_string(&mut archive.by_name("xl/styles.xml").unwrap(), &mut styles).unwrap();
        assert!(!styles.contains("<colors>"));
        let styles = styles.replace("</styleSheet>", &format!("<colors><indexedColors>{palette}</indexedColors></colors></styleSheet>"));
        let package = shared_fixture_styles(seed, &styles);
        let book = oxicells_core::parse_xlsx(&package).unwrap();
        assert_eq!(book.indexed_colors[20], "4600A5");
        let source = r#"Public Sub UseWorkbookPalette()
            ActiveSheet.Range("A1").Interior.ColorIndex = 13
            Debug.Print ActiveSheet.Range("A1").Interior.Color
            Debug.Print ActiveSheet.Range("A1").Interior.ColorIndex
            ActiveSheet.Range("B1").Interior.Color = 10813510
            Debug.Print ActiveSheet.Range("B1").Interior.ColorIndex
            ActiveSheet.Range("C1").Interior.Color = 14474461
            Debug.Print ActiveSheet.Range("C1").Interior.ColorIndex
            ActiveSheet.Range("D1").Interior.Color = 255
            Debug.Print ActiveSheet.Range("D1").Interior.ColorIndex
            ActiveSheet.Range("E1").Interior.Color = 65280
            Debug.Print ActiveSheet.Range("E1").Interior.ColorIndex
            Set box = ActiveSheet.Shapes.AddShape(1, 1, 1, 10, 10)
            box.Fill.ForeColor.RGB = 10813510
            Debug.Print box.Fill.ForeColor.SchemeColor
            box.Line.ForeColor.RGB = 10813510
            Debug.Print box.Line.ForeColor.SchemeColor
            box.TextFrame2.TextRange.Text = "x"
            box.TextFrame2.TextRange.Font.Fill.ForeColor.RGB = 10813510
            Debug.Print box.TextFrame2.TextRange.Font.Fill.ForeColor.SchemeColor
        End Sub"#;
        let outcome = execute_workbook_vba(
            book,
            source,
            "UseWorkbookPalette",
            vec![],
            0,
            failure_context(),
        )
        .unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
        assert!(outcome.debug_output.iter().any(|line| line == "10813510"), "{:?}", outcome.debug_output);
        for expected in ["13", "24", "-5", "-4"] {
            assert!(
                outcome.debug_output.iter().any(|line| line == expected),
                "missing Excel ColorIndex {expected}: {:?}",
                outcome.debug_output
            );
        }
        assert_eq!(
            outcome.debug_output.iter().filter(|line| line.as_str() == "20").count(),
            3,
            "exact custom Workbook.Colors RGB should resolve through fill, line and text ColorFormat: {:?}",
            outcome.debug_output
        );
        assert_eq!(outcome.workbook.indexed_colors[20], "4600A5");
    }

