    #[test]
    fn workbook_colors_gets_sets_and_drives_colorformat_scheme_color() {
        let package = include_bytes!("../../oxicells-core/tests/fixtures/wrapped.xlsx");
        let mut context = failure_context();
        context.file_context = Some(file_io::FileContext {
            edit_revision: None, source_code_page: None,
            package_bytes: Some(package.to_vec()),
            full_name: Some("C:\\work\\source.xlsx".into()),
            read_only: Some(true),
            folders: vec!["C:\\work".into()],
            files: vec![],
        });
        let source = r#"Public Sub WorkbookColors()
            Dim palette As Variant
            palette = ThisWorkbook.Colors
            Debug.Print LBound(palette)
            Debug.Print UBound(palette)
            Debug.Print palette(13)
            ThisWorkbook.Colors(3) = 4402555
            ThisWorkbook.Colors(20) = 255
            Debug.Print ThisWorkbook.Colors(20)
            ThisWorkbook.Colors(19) = 1.6
            Debug.Print ThisWorkbook.Colors(19)
            Set box = ActiveSheet.Shapes.AddShape(1, 1, 1, 10, 10)
            box.Fill.ForeColor.RGB = 255
            Debug.Print box.Fill.ForeColor.SchemeColor
            palette = ThisWorkbook.Colors
            palette(21) = 4402555
            ThisWorkbook.Colors = palette
            Debug.Print ThisWorkbook.Colors(21)
            ReDim palette(0 To 54)
            For i = 0 To 54
                palette(i) = 100000 + i
            Next i
            ThisWorkbook.Colors = palette
            Debug.Print ThisWorkbook.Colors(1)
            Debug.Print ThisWorkbook.Colors(55)
            Debug.Print ThisWorkbook.Colors(56)
            ReDim palette(1 To 57)
            For i = 1 To 57
                palette(i) = 200000 + i
            Next i
            ThisWorkbook.Colors = palette
            Debug.Print ThisWorkbook.Colors(56)
            ReDim palette(1 To 7, 1 To 8)
            On Error Resume Next
            ThisWorkbook.Colors = palette
            Debug.Print Err.Number
            On Error GoTo 0
            ThisWorkbook.SaveCopyAs "C:\work\colors.xlsx"
        End Sub"#;
        let outcome = execute_workbook_vba(
            oxicells_core::parse_xlsx(package).unwrap(),
            source,
            "WorkbookColors",
            vec![],
            0,
            context,
        )
        .unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
        for expected in ["1", "56", "8388736", "255", "1", "27", "4402555", "100000", "100054", "0", "200056", "1004"] {
            assert!(
                outcome.debug_output.iter().any(|line| line == expected),
                "missing Workbook.Colors result {expected}: {:?}",
                outcome.debug_output
            );
        }
        assert_eq!(outcome.workbook.indexed_colors.len(), 64);
        assert_eq!(outcome.workbook.indexed_colors[8], "410D03");
        assert_eq!(outcome.workbook.indexed_colors[62], "770D03");
        assert_eq!(outcome.workbook.indexed_colors[63], "780D03");
        assert_eq!(outcome.files.len(), 1);
        let saved = oxicells_core::parse_xlsx(&outcome.files[0].bytes).unwrap();
        assert_eq!(saved.indexed_colors[8], "410D03");
        assert_eq!(saved.indexed_colors[62], "770D03");
        assert_eq!(saved.indexed_colors[63], "780D03");
    }

    #[test]
    fn colorindex_uses_current_palette_for_exact_colors_and_builtin_for_nearby_rgb() {
        let mut palette = COLOUR_PALETTE;
        palette[2] = 14_474_460;
        palette[3] = 1_357_599;
        assert_eq!(nearest_palette_index_in(14_474_460, &palette), 3);
        assert_eq!(nearest_palette_index_in(14_474_461, &palette), 24);
        assert_eq!(nearest_palette_index_in(14_474_459, &palette), 24);
        assert_eq!(nearest_palette_index_in(255, &palette), -5);
        assert_eq!(nearest_palette_index_in(65_280, &palette), -4);

        // Excel returns the first eight legacy indices minus eight when their
        // colors have been removed from the current palette.
        let mut without_system_colours = COLOUR_PALETTE;
        for index in [0, 1, 2, 3, 4, 31, 5, 26, 6, 25, 7, 27] {
            without_system_colours[index] = 16_000_000 - index as i64 * 1_000;
        }
        for (index, colour) in COLOUR_PALETTE[..8].iter().enumerate() {
            assert_eq!(
                nearest_palette_index_in(*colour, &without_system_colours),
                index as i64 - 7,
                "missing built-in palette index {}",
                index + 1
            );
        }
    }

    /// A colour the FILE gave a cell is the colour the macro sees.
    ///
    /// The file writes six hex digits with nothing in front, and that is what
    /// the IR keeps. A macro used to see white where the file said red,
    /// because the host wrote its own colours with a `#` and read only that
    /// form back.
    #[test]
    fn vba_sees_the_colour_the_file_gave_a_cell() {
        let mut workbook = workbook();
        workbook.sheets[0].rows.push(Row {
            index: 1,
            cells: vec![Cell {
                formula_utf16: None,
                array_block: None,
                spill: Default::default(),
                col: 0,
                value: CellValue::Empty,
                style: CellStyle {
                    bg_color: Some("FF0000".to_string()),
                    font_color: Some("00FF00".to_string()),
                    ..CellStyle::default()
                },
                formula: None,
                runs: Vec::new(),
            }],
            height: None,
            custom_height: false,
            format_recorded: None, style_font: None,
            thick_top: false,
            thick_bottom: false,
            hidden: false,
        });
        let module = parse_module(
            "Public Function Seen() As String
               Seen = Range(\"A1\").Interior.Color & \"|\" & Range(\"A1\").Font.Color & \"|\" & _
                 Range(\"A1\").Interior.ColorIndex
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Seen", vec![], &mut host).unwrap()
        };
        assert_eq!(result, Value::String("255|65280|3".to_string()));

        // And what the macro writes is written the same way, so the file and
        // the page both read it back.
        let module = parse_module(
            "Public Sub Paint()\n  Range(\"B1\").Interior.Color = 255\nEnd Sub\n",
        )
        .unwrap();
        {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Paint", vec![], &mut host).unwrap();
        }
        let painted = workbook.sheets[0]
            .rows
            .iter()
            .find(|row| row.index == 1)
            .and_then(|row| row.cells.iter().find(|cell| cell.col == 1))
            .and_then(|cell| cell.style.bg_color.clone());
        assert_eq!(painted.as_deref(), Some("FF0000"));
    }

    /// `ColorIndex` names a colour by the nearest of Excel's 56.
    ///
    /// Every answer was asked of Excel: index 3 is red (255) and 5 is blue
    /// (16711680); an off-palette colour is called by the NEAREST entry, so
    /// 12345 answers 52; a cell with no fill answers `xlNone` and one that
    /// names no writing colour answers 1; and a block whose cells disagree
    /// answers Null.
    #[test]
    fn vba_names_a_colour_by_the_nearest_of_the_fifty_six() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Named() As String
               Range(\"A1\").Interior.ColorIndex = 3
               Range(\"A2\").Interior.Color = 12345
               Range(\"A3\").Interior.Color = 8421504
               Range(\"B1\").Interior.ColorIndex = 5
               Range(\"B1\").Interior.ColorIndex = xlNone
               Range(\"C1\").Font.ColorIndex = 3
               Range(\"D1:D2\").Interior.ColorIndex = 3
               Named = Range(\"A1\").Interior.Color & \"|\" & _
                 Range(\"A1\").Interior.ColorIndex & \"|\" & _
                 Range(\"A2\").Interior.ColorIndex & \"|\" & _
                 Range(\"A3\").Interior.ColorIndex & \"|\" & _
                 Range(\"B1\").Interior.ColorIndex & \"|\" & _
                 Range(\"Z9\").Interior.ColorIndex & \"|\" & _
                 Range(\"C1\").Font.Color & \"|\" & _
                 Range(\"C1\").Font.ColorIndex & \"|\" & _
                 Range(\"Z9\").Font.ColorIndex & \"|\" & _
                 TypeName(Range(\"A1:A2\").Interior.ColorIndex) & \"|\" & _
                 Range(\"D1:D2\").Interior.ColorIndex
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Named", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String("255|3|52|16|-4142|-4142|255|3|1|Null|3".to_string())
        );
    }

    /// What Copy sets aside can be put down again; what Cut sets aside is
    /// moved, once.
    ///
    /// Asked of Excel: `CutCopyMode` answers 0 at rest, `xlCopy` (1) after a
    /// Copy and `xlCut` (2) after a Cut; `Paste` with no destination lands on the
    /// selection; a Copy survives being pasted while a Cut does not; and
    /// pasting with nothing held raises.
    #[test]
    fn vba_puts_down_what_copy_and_cut_set_aside() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Held() As String
               Range(\"A1\").Value = 1
               Range(\"A2\").Value = 2
               Range(\"B1\").Formula = \"=A1*10\"
               Held = Application.CutCopyMode & \"|\"
               Range(\"A1:B2\").Copy
               Held = Held & Application.CutCopyMode & \"|\"
               ActiveSheet.Paste Range(\"D1\")
               Held = Held & Range(\"D1\").Value & Range(\"E1\").Formula & \"|\" & _
                 Application.CutCopyMode & \"|\"
               Range(\"G5\").Select
               ActiveSheet.Paste
               Held = Held & Range(\"G5\").Value & Range(\"H5\").Formula & \"|\"
               Range(\"A1:B2\").Cut
               Held = Held & Application.CutCopyMode & \"|\"
               ActiveSheet.Paste Range(\"J1\")
               Held = Held & Range(\"J1\").Value & Range(\"K1\").Formula & \"|\" & _
                 Application.CutCopyMode & \"|\" & \"[\" & Range(\"A1\").Value & \"]\"
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Held", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String("0|1|1=D1*10|1|1=G5*10|2|1=J1*10|0|[]".to_string())
        );
    }

    /// Putting down what nothing set aside raises, and letting go empties the
    /// hand.
    #[test]
    fn vba_refuses_a_paste_with_nothing_held() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Nothing1()\n  ActiveSheet.Paste Range(\"A1\")\nEnd Sub\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        let error = execute_with_host(&module, "Nothing1", vec![], &mut host)
            .expect_err("there is nothing to put down")
            .to_string();
        assert!(error.contains("nothing to put down"), "{error}");
        drop(host);

        let module = parse_module(
            "Public Function LetGo() As String
               Range(\"A1\").Value = 1
               Range(\"A1\").Copy
               Application.CutCopyMode = False
               LetGo = Application.CutCopyMode
             End Function\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        let result = execute_with_host(&module, "LetGo", vec![], &mut host).unwrap();
        assert_eq!(result, Value::String("0".to_string()));
    }

    /// A paste can skip the blanks it carries, and can combine rather than
    /// replace.
    ///
    /// Every answer was asked of Excel: with `SkipBlanks` the cell under a
    /// blank keeps what it had; an operation makes the DESTINATION the left
    /// side and what is being put down the right, so 100 with 10 added answers
    /// 110 and `=A5+1` with 3 subtracted answers `=(A5+1)-3`; a blank counts
    /// as nothing, so multiplying by one answers 0; and text on either side
    /// leaves the cell exactly as it was.
    #[test]
    fn vba_pastes_over_blanks_or_combines_with_what_is_there() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Combined() As String
               Range(\"A1\").Value = 10
               Range(\"A3\").Value = 30
               Range(\"D1\").Value = \"keep\"
               Range(\"D2\").Value = \"keep too\"
               Range(\"D3\").Value = \"and this\"
               Range(\"F1\").Value = \"keep\"
               Range(\"F2\").Value = \"keep too\"
               Range(\"F3\").Value = \"and this\"
               Range(\"A1:A3\").Copy
               Range(\"D1\").PasteSpecial xlPasteAll, xlPasteSpecialOperationNone, False
               Range(\"A1:A3\").Copy
               Range(\"F1\").PasteSpecial xlPasteAll, xlPasteSpecialOperationNone, True
               Range(\"H1\").Value = 100
               Range(\"A1\").Copy
               Range(\"H1\").PasteSpecial xlPasteAll, xlPasteSpecialOperationAdd
               Range(\"H2\").Value = 100
               Range(\"A1\").Copy
               Range(\"H2\").PasteSpecial xlPasteAll, xlPasteSpecialOperationDivide
               Range(\"H3\").Formula = \"=A5+1\"
               Range(\"A5\").Value = 7
               Range(\"B1\").Value = 3
               Range(\"B1\").Copy
               Range(\"H3\").PasteSpecial xlPasteAll, xlPasteSpecialOperationSubtract
               Range(\"H4\").Value = 100
               Range(\"B2\").Value = \"abc\"
               Range(\"B2\").Copy
               Range(\"H4\").PasteSpecial xlPasteAll, xlPasteSpecialOperationMultiply
               Range(\"H5\").Value = 100
               Range(\"B3\").Copy
               Range(\"H5\").PasteSpecial xlPasteAll, xlPasteSpecialOperationMultiply
               Combined = Range(\"D2\").Value & \"|\" & Range(\"F2\").Value & \"|\" & _
                 Range(\"H1\").Value & \"|\" & Range(\"H2\").Value & \"|\" & _
                 Range(\"H3\").Formula & \"|\" & Range(\"H4\").Value & \"|\" & _
                 Range(\"H5\").Value
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Combined", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String("|keep too|110|10|=(A5+1)-3|100|0".to_string())
        );
    }

    /// A transposed paste turns the formulas it carries as well as the cells.
    ///
    /// Asked of Excel with `H1:I2` — two numbers and two formulas each looking
    /// one cell to their left — pasted transposed onto K5: the block comes out
    /// on its side and the formulas look one cell ABOVE instead.
    #[test]
    fn vba_turns_a_formula_with_the_block_it_is_in() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Turned() As String
               Range(\"H1\").Value = 1
               Range(\"H2\").Value = 2
               Range(\"I1\").Formula = \"=H1*10\"
               Range(\"I2\").Formula = \"=H2*10\"
               Range(\"H1:I2\").Copy
               Range(\"K5\").PasteSpecial xlPasteAll, xlPasteSpecialOperationNone, False, True
               Turned = Range(\"K5\").Value & \"|\" & Range(\"L5\").Value & \"|\" & _
                 Range(\"K6\").Formula & \"|\" & Range(\"L6\").Formula
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Turned", vec![], &mut host).unwrap()
        };

        assert_eq!(result, Value::String("1|2|=K5*10|=L5*10".to_string()));
    }

    /// The ranking family, on a block holding things that are not numbers.
    ///
    /// Every answer was asked of Excel about 10, 30, 20, "text", a blank, TRUE
    /// and 30: only the numbers are read, so `Large` runs 30, 30, 20, 10 and
    /// then refuses; equal numbers share a place and the next one is skipped,
    /// so 20 ranks third; `CountBlank` counts the one cell that is really
    /// blank; and the plain spread is the SAMPLE one, dividing by one less
    /// than the count.
    #[test]
    fn vba_ranks_and_spreads_the_numbers_in_a_block() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Ranked() As String
               Range(\"A1\").Value = 10
               Range(\"A2\").Value = 30
               Range(\"A3\").Value = 20
               Range(\"A4\").Value = \"text\"
               Range(\"A6\").Value = True
               Range(\"A7\").Value = 30
               Ranked = WorksheetFunction.Large(Range(\"A1:A7\"), 1) & \"|\" & _
                 WorksheetFunction.Large(Range(\"A1:A7\"), 3) & \"|\" & _
                 WorksheetFunction.Large(Range(\"A1:A7\"), 1.7) & \"|\" & _
                 WorksheetFunction.Small(Range(\"A1:A7\"), 1) & \"|\" & _
                 WorksheetFunction.Small(Range(\"A1:A7\"), 4) & \"|\" & _
                 WorksheetFunction.CountBlank(Range(\"A1:A7\")) & \"|\" & _
                 WorksheetFunction.Rank(30, Range(\"A1:A7\")) & \"|\" & _
                 WorksheetFunction.Rank(20, Range(\"A1:A7\")) & \"|\" & _
                 WorksheetFunction.Rank(10, Range(\"A1:A7\")) & \"|\" & _
                 WorksheetFunction.Rank(30, Range(\"A1:A7\"), 1) & \"|\" & _
                 WorksheetFunction.Rank(10, Range(\"A1:A7\"), 1) & \"|\" & _
                 WorksheetFunction.Round(WorksheetFunction.Var(Range(\"A1:A7\")), 4) & \"|\" & _
                 WorksheetFunction.Var_P(Range(\"A1:A7\")) & \"|\" & _
                 WorksheetFunction.Large(Array(5, 15, 25), 2)
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Ranked", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String(
                "30|20|30|10|30|1|1|3|4|3|1|91.6667|68.75|15".to_string()
            )
        );
    }

    /// What the ranking family refuses, as Excel refuses it.
    #[test]
    fn vba_refuses_a_place_that_is_not_there() {
        for call in [
            "WorksheetFunction.Large(Range(\"A1:A3\"), 4)",
            "WorksheetFunction.Large(Range(\"A1:A3\"), 0)",
            "WorksheetFunction.Small(Range(\"A1:A3\"), 9)",
            "WorksheetFunction.Rank(25, Range(\"A1:A3\"))",
            "WorksheetFunction.StDev(Range(\"A1:A1\"))",
        ] {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Ask()
                   Range(\"A1\").Value = 10
                   Range(\"A2\").Value = 30
                   Range(\"A3\").Value = 20
                   Debug.Print {call}
                 End Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            assert!(
                execute_with_host(&module, "Ask", vec![], &mut host).is_err(),
                "{call} should have refused"
            );
        }
    }

    /// Several blocks named as one range.
    ///
    /// Every answer was asked of Excel: `Union(A1:A2, C1:C2)` says its address
    /// with a comma between the blocks, counts 4 cells over 2 areas, and
    /// answers for the FIRST block where it has to give one answer — `.Row` 1,
    /// `.Rows.Count` 2. Blocks that JOIN are one block, whether they overlap
    /// (A1:A3 with A2:A4) or merely touch (A1:A2 with A3:A4): both answer
    /// `A1:A4` with one area.
    #[test]
    fn vba_names_several_blocks_as_one_range() {
        // The last arm is the one that separates the two rules: `Union` joins
        // blocks that touch, and a comma-written address never joins anything.
        // Measured in Excel 16.0 — `Union(A1:A2, A3:A4)` is `A1:A4` with one
        // area, `Range("A1:A2,A3:A4")` is `A1:A2,A3:A4` with two.

        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Joined() As String
               Dim broken
               Set broken = Application.Union(Range(\"A1:A2\"), Range(\"C1:C2\"))
               Joined = broken.Address(False, False) & \"|\" & _
                 broken.Areas.Count & \"|\" & broken.Count & \"|\" & _
                 broken.Areas(2).Address(False, False) & \"|\" & _
                 broken.Row & \"|\" & broken.Column & \"|\" & _
                 broken.Rows.Count & \"|\" & broken.Columns.Count & \"|\" & _
                 Application.Union(Range(\"A1:A3\"), Range(\"A2:A4\")).Address(False, False) & \"|\" & _
                 Application.Union(Range(\"A1:A2\"), Range(\"A3:A4\")).Address(False, False) & \"|\" & _
                 Range(\"A1:A2,C1:C2\").Areas.Count & \"|\" & _
                 Range(\"A1:A2,A3:A4\").Address(False, False)
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Joined", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String(
                "A1:A2,C1:C2|2|4|C1:C2|1|1|2|1|A1:A4|A1:A4|2|A1:A2,A3:A4".to_string()
            )
        );
    }

    /// What is done to a many-block range is done to every block of it.
    ///
    /// Asked of Excel, colouring `Union(A1:A2, C1:C2)` leaves A1 and C2 red
    /// and B1 — which is between them and in neither block — as it was, and
    /// writing 7 to it writes 7 to both blocks.
    #[test]
    fn vba_dresses_every_block_of_a_many_block_range() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Dressed() As String
               Dim broken
               Set broken = Application.Union(Range(\"A1:A2\"), Range(\"C1:C2\"))
               broken.Interior.Color = 255
               broken.Font.Bold = True
               broken.Value = 7
               Dressed = Range(\"A1\").Interior.Color & \"|\" & _
                 Range(\"C2\").Interior.Color & \"|\" & _
                 Range(\"B1\").Interior.Color & \"|\" & _
                 Range(\"C1\").Font.Bold & \"|\" & _
                 Range(\"A1\").Value & \"|\" & Range(\"C2\").Value & \"|\" & _
                 \"[\" & Range(\"B2\").Value & \"]\"
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Dressed", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String("255|255|16777215|True|7|7|[]".to_string())
        );
    }

    /// The cells of a block that answer to a description.
    ///
    /// Every answer was asked of Excel about A1:A8 holding 10, "text", a
    /// blank, `=A1*2`, 30, `=1/0`, a blank and TRUE.
    #[test]
    fn vba_picks_out_the_cells_that_answer_a_description() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Picked() As String
               Range(\"A1\").Value = 10
               Range(\"A2\").Value = \"text\"
               Range(\"A4\").Formula = \"=A1*2\"
               Range(\"A5\").Value = 30
               Range(\"A6\").Value = True
               Range(\"C3\").Value = \"corner\"
               Picked = Range(\"A1:A8\").SpecialCells(xlCellTypeConstants).Address(False, False) & \"|\" & _
                 Range(\"A1:A8\").SpecialCells(xlCellTypeConstants, xlNumbers).Address(False, False) & \"|\" & _
                 Range(\"A1:A8\").SpecialCells(xlCellTypeConstants, xlTextValues).Address(False, False) & \"|\" & _
                 Range(\"A1:A8\").SpecialCells(xlCellTypeConstants, 3).Address(False, False) & \"|\" & _
                 Range(\"A1:A8\").SpecialCells(xlCellTypeConstants, xlLogical).Address(False, False) & \"|\" & _
                 Range(\"A1:A8\").SpecialCells(xlCellTypeFormulas).Address(False, False) & \"|\" & _
                 Range(\"A1:A8\").SpecialCells(xlCellTypeBlanks).Address(False, False) & \"|\" & _
                 Range(\"A1:A8\").SpecialCells(xlCellTypeBlanks).Areas.Count & \"|\" & _
                 Range(\"A1:A8\").SpecialCells(xlCellTypeVisible).Address(False, False) & \"|\" & _
                 Range(\"A1\").SpecialCells(xlCellTypeLastCell).Address(False, False)
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Picked", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String(
                // Blanks are looked for inside the used range only (A1:C6):
                // measured, Excel answers A3 and one area, not A3,A7:A8.
                "A1:A2,A5:A6|A1,A5|A2|A1:A2,A5|A6|A4|A3|1|A1:A8|C6".to_string()
            )
        );
    }

    /// After a filter, the visible cells are the rows the filter left showing.
    #[test]
    fn vba_picks_out_the_rows_a_filter_left_showing() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Showing() As String
               Range(\"G1\").Value = \"head\"
               Range(\"G2\").Value = 1
               Range(\"G3\").Value = 2
               Range(\"G4\").Value = 1
               Range(\"G5\").Value = 2
               Range(\"G1:G5\").AutoFilter 1, \"1\"
               Showing = Range(\"G1:G5\").SpecialCells(xlCellTypeVisible).Address(False, False) & \"|\" & _
                 Range(\"G1:G5\").SpecialCells(xlCellTypeVisible).Areas.Count
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Showing", vec![], &mut host).unwrap()
        };

        assert_eq!(result, Value::String("G1:G2,G4|2".to_string()));
    }

    /// Each kind of paste carries a different part of what was copied.
    ///
    /// Measured on Excel with a source holding a formula, a red fill, a number
    /// format and a line under it, put down on a cell that was green with its
    /// own format: `xlPasteAllExceptBorders` carried everything but the line,
    /// `xlPasteColumnWidths` carried nothing but the width of the column, and
    /// `xlPasteValuesAndNumberFormats` carried the VALUE 遯�E�繝ｻnot the formula 遯�E�繝ｻ    /// and the number format, leaving the fill alone.
    #[test]
    fn vba_pastes_the_part_of_a_cell_that_was_asked_for() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Parts() As String
               Range(\"A1\").Value = 5
               Range(\"B1\").Formula = \"=A1*2\"
               Range(\"B1\").Interior.Color = 255
               Range(\"B1\").NumberFormat = \"0.00\"
               Range(\"B1\").Borders(xlEdgeBottom).LineStyle = xlContinuous
               Range(\"B1\").ColumnWidth = 25
               Range(\"H1\").Value = 99
               Range(\"H1\").Interior.Color = 65280
               Range(\"H1\").NumberFormat = \"0%\"
               Range(\"B1\").Copy
               Range(\"H1\").PasteSpecial xlPasteAllExceptBorders
               Range(\"I1\").Value = 99
               Range(\"B1\").Copy
               Range(\"I1\").PasteSpecial xlPasteColumnWidths
               Range(\"J1\").Value = 99
               Range(\"J1\").Interior.Color = 65280
               Range(\"K1\").Value = 5
               Range(\"K1\").NumberFormat = \"0.00\"
               Range(\"K1\").Interior.Color = 255
               Range(\"K1\").Copy
               Range(\"J1\").PasteSpecial xlPasteValuesAndNumberFormats
               Parts = Range(\"H1\").Formula & \"|\" & Range(\"H1\").Interior.Color & \"|\" & _
                 Range(\"H1\").NumberFormat & \"|\" & Range(\"H1\").Borders(xlEdgeBottom).LineStyle & \"|\" & _
                 Range(\"I1\").Value & \"|\" & Range(\"I1\").ColumnWidth & \"|\" & _
                 Range(\"J1\").Formula & \"|\" & Range(\"J1\").NumberFormat & \"|\" & _
                 Range(\"J1\").Interior.Color
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Parts", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String("=G1*2|255|0.00|-4142|99|25|5|0.00|65280".to_string())
        );
    }


