    #[test]
    fn returned_reference_hints_require_an_unambiguous_literal_cell() {
        let cases = [
            ("Function F() As Range\nSet F = Range(\"M1\")\nEnd Function", true),
            ("Function F() As Range\nSet F = Range(target)\nEnd Function", false),
            ("Function F() As Range\nSet F = Range(\"NamedRange\")\nEnd Function", false),
            ("Function F() As Range\nIf flag Then\nSet F = Range(\"M1\")\nElse\nSet F = Range(\"O1\")\nEnd If\nEnd Function", false),
            ("Dim Range As Object\nFunction F() As Range\nSet F = Range(\"M1\")\nEnd Function", false),
            // parse_project resolves this unrelated compiler constant before
            // either execution or the reference-hint analysis sees the body.
            ("#Const mode = 1\nFunction F() As Range\nSet F = Range(\"M1\")\nEnd Function", true),
            ("Function F(target As String) As Range\nSet F = Range(\"M1\")\nEnd Function", false),
            ("Function F() As Range\nSet F = Range(\"M1\")\nSet F = Range(\"O1\")\nEnd Function", false),
            ("Function F() As Range\nSet F = Range(\"M1\")\nx = Mutate(F)\nEnd Function", false),
        ];
        for (source, expected) in cases {
            let (module, classes) = oxivba_core::parse_project(source).unwrap();
            assert_eq!(fixed_reference_functions(&module, &classes).contains("F"), expected, "{source}");
        }
    }

    #[test]
    fn taking_callbacks_preserves_outer_operation_queue() {
        let mut workbook = workbook();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        let make_call = |number, operation_depth| PendingCall {
            number, operation_depth, name: "F".into(), key: format!("call-{number}"),
            provisional_indirect_text_value: false, dynamic_reference_argument_mask: 0,
            args: PendingArgs::Vba(Vec::new()), once: false, caller: None,
            read_view: None, written_dependencies: Vec::new(),
        };
        host.begin_member_call(None, "outer");
        host.user_functions.borrow_mut().pending.push(make_call(41, 1));
        host.begin_member_call(None, "inner");
        host.user_functions.borrow_mut().calculation = Some(UserCalculation::Cells {
            cells: Vec::new(), changed: false, clear_dirty: false, reason: CalculationReason::Calculate,
        });
        let calculated = vec![("Sheet1".into(), (2, 0))];
        host.retain_pending_calculation_cells(&calculated);
        let UserCalculation::Cells { cells, .. } = host.user_functions.borrow().calculation.clone().unwrap() else { panic!("expected cell calculation") };
        assert!(cells.is_empty(), "outer pending work must not extend the inner calculation");
        host.user_functions.borrow_mut().pending.push(make_call(42, 2));
        host.retain_pending_calculation_cells(&calculated);
        let UserCalculation::Cells { cells, .. } = host.user_functions.borrow().calculation.clone().unwrap() else { panic!("expected cell calculation") };
        assert_eq!(cells, calculated);
        let calls = host.take_user_function_calls();
        assert_eq!(calls.iter().map(|call| call.0).collect::<Vec<_>>(), vec![42]);
        assert_eq!(host.user_functions.borrow().pending.iter().map(|call| call.number).collect::<Vec<_>>(), vec![41]);
        host.user_functions.borrow_mut().asked.remove(&42);
        host.end_member_call(None, "inner");
        let calls = host.take_user_function_calls();
        assert_eq!(calls.iter().map(|call| call.0).collect::<Vec<_>>(), vec![41]);
        host.user_functions.borrow_mut().asked.remove(&41);
        host.end_member_call(None, "outer");
    }

    #[test]
    fn outstanding_callback_keys_are_local_to_each_operation() {
        let mut workbook = workbook();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        host.begin_member_call(None, "outer");
        {
            let mut held = host.user_functions.borrow_mut();
            let depth = held.operations.len();
            held.asked.insert(42, ("same".into(), false, depth));
            assert!(held.has_outstanding_key("same"));
            assert!(held.has_outstanding_callbacks());
        }
        host.begin_member_call(None, "inner");
        assert!(!host.user_functions.borrow().has_outstanding_key("same"));
        assert!(!host.user_functions.borrow().has_outstanding_callbacks());
        host.end_member_call(None, "inner");
        assert!(host.user_functions.borrow().has_outstanding_key("same"));
        host.user_functions.borrow_mut().asked.remove(&42);
        host.end_member_call(None, "outer");
    }

    #[test]
    fn refused_worksheet_callback_does_not_resume_as_a_reference() {
        let mut workbook = workbook();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        let range = host.object(HostObject::Range(CellRange::single(CellAddress {
            sheet: 0, row: 1, column: 0,
        })));
        assert!(host.user_function_returns_reference(42, &range));
        host.user_functions.borrow_mut().refused.insert(42);
        assert!(!host.user_function_returns_reference(42, &range));
        assert!(!host.user_function_returns_reference(43, &Value::Integer(1)));
    }

    #[test]
    fn fixed_reference_hints_respect_module_names_and_range_shadows() {
        let source = "Attribute VB_Name = \"First\"\nFunction F() As Range\nSet F = Range(\"M1\")\nEnd Function\n\
                      Attribute VB_Name = \"Second\"\nFunction F() As Range\nSet F = Range(target)\nEnd Function\n";
        let (module, classes) = oxivba_core::parse_project(source).unwrap();
        let hints = fixed_reference_functions(&module, &classes);
        assert!(!hints.contains("F"), "ambiguous unqualified name: {hints:?}");
        assert!(hints.contains("FIRST.F"), "fixed qualified function: {hints:?}");
        assert!(!hints.contains("SECOND.F"), "dynamic qualified function: {hints:?}");

        let duplicate = "Attribute VB_Name = \"First\"\nFunction F() As Range\nSet F = Range(\"M1\")\nEnd Function\n\
                         Function F() As Range\nSet F = Range(target)\nEnd Function\n";
        let (module, classes) = oxivba_core::parse_project(duplicate).unwrap();
        let hints = fixed_reference_functions(&module, &classes);
        assert!(!hints.contains("F"), "duplicate unqualified name: {hints:?}");
        assert!(!hints.contains("FIRST.F"), "duplicate qualified name: {hints:?}");

        let shadowed = "Attribute VB_Name = \"First\"\nFunction F() As Range\nSet F = Range(\"M1\")\nEnd Function\n\
                        Attribute VB_Name = \"Second\"\nPublic Range As Object\n";
        let (module, classes) = oxivba_core::parse_project(shadowed).unwrap();
        assert!(fixed_reference_functions(&module, &classes).is_empty());

        let class_shadow = "Attribute VB_Name = \"First\"\nFunction F() As Range\nSet F = Range(\"M1\")\nEnd Function\n\
                            VERSION 1.0 CLASS\nAttribute VB_Name = \"Range\"\n";
        let (module, classes) = oxivba_core::parse_project(class_shadow).unwrap();
        assert!(fixed_reference_functions(&module, &classes).is_empty());
    }

    fn returned_reference_trace_source() -> String {
        let source = include_str!("../../../tests/fixtures/vba/udf_returned_references.bas").replace("\r\n", "\n");
        let mut source = source;
        for (before, after) in [
            ("Private hitsA As Long, hitsB As Long, hitsC As Long, hitsR As Long", "Private hitsA As Long, hitsB As Long, hitsC As Long, hitsR As Long\nPrivate trace As String, traceStage As String"),
            ("    FlowTick = chosen", "    trace = trace & traceStage & \":\" & label & \"=\" & CStr(chosen) & \"|\"\n    FlowTick = chosen"),
            ("    hitsR = hitsR + 1\n    Set RefRange", "    hitsR = hitsR + 1\n    trace = trace & traceStage & \":R|\"\n    Set RefRange"),
            ("    hitsA = 0: hitsB = 0: hitsC = 0: hitsR = 0", "    hitsA = 0: hitsB = 0: hitsC = 0: hitsR = 0\n    trace = \"\": traceStage = \"entry\""),
            ("    Application.Calculate\n    report = report & \"|\" & FlowSnapshot(\"normal\")", "    traceStage = \"normal\"\n    Application.Calculate\n    report = report & \"|\" & FlowSnapshot(\"normal\")"),
            ("    Application.Calculate\n    report = report & \"|\" & FlowSnapshot(\"again\")", "    traceStage = \"again\"\n    Application.Calculate\n    report = report & \"|\" & FlowSnapshot(\"again\")"),
            ("    Application.Calculate\n    report = report & \"|\" & FlowSnapshot(\"dirty\")", "    traceStage = \"dirty\"\n    Application.Calculate\n    report = report & \"|\" & FlowSnapshot(\"dirty\")"),
            ("    Application.Calculate\n    report = report & \"|\" & FlowSnapshot(\"switch\")", "    traceStage = \"switch\"\n    Application.Calculate\n    report = report & \"|\" & FlowSnapshot(\"switch\")"),
            ("    Application.Calculate\n    report = report & \"|\" & FlowSnapshot(\"other\")", "    traceStage = \"other\"\n    Application.Calculate\n    report = report & \"|\" & FlowSnapshot(\"other\")"),
            ("    Application.CalculateFull\n    FlowCase =", "    traceStage = \"full\"\n    Application.CalculateFull\n    FlowCase ="),
        ] {
            assert!(source.contains(before), "trace instrumentation anchor missing: {before}");
            source = source.replacen(before, after, 1);
        }
        source.push_str("\nPublic Function CallTrace() As String\n    CallTrace = trace\nEnd Function\n");
        source
    }

    fn dynamic_returned_reference_source() -> String {
        let source = returned_reference_trace_source();
        let fixed = "    Set RefRange = Range(\"M1\")";
        assert!(source.contains(fixed));
        let mut source = source.replacen(fixed, "    If Range(\"D1\").Value2 = 0 Then\n        Set RefRange = Range(\"M1\")\n    Else\n        Set RefRange = Range(\"O1\")\n    End If", 1);
        source.push_str(r#"
Public Function DynamicProbe(ByVal initial As Long) As String
    Dim previous As Long, report As String, picked As String, other As String
    previous = Application.Calculation
    Application.Calculation = xlCalculationManual
    Range("M1:Q3").ClearContents
    Range("D1").Value2 = initial
    Range("M1").Value2 = 10: Range("O1").Value2 = 20: Range("Q1").Value2 = 0
    hitsA = 0: hitsB = 0: hitsC = 0: hitsR = 0
    trace = "": traceStage = "seed"
    Range("N1").Formula2 = "=RefRange()+0"
    Application.CalculateFull
    report = FlowSnapshot("seed")
    If initial = 0 Then picked = "M1": other = "O1" Else picked = "O1": other = "M1"
    traceStage = "other": Range(other).Value2 = 30: Application.Calculate
    report = report & "|" & FlowSnapshot("other")
    traceStage = "picked": Range(picked).Value2 = 40: Application.Calculate
    report = report & "|" & FlowSnapshot("picked")
    traceStage = "switch": Range("D1").Value2 = 1 - initial: Application.Calculate
    report = report & "|" & FlowSnapshot("switch")
    traceStage = "old": Range(picked).Value2 = 50: Application.Calculate
    report = report & "|" & FlowSnapshot("old")
    traceStage = "new": Range(other).Value2 = 60: Application.Calculate
    report = report & "|" & FlowSnapshot("new")
    traceStage = "full": Application.CalculateFull
    report = report & "|" & FlowSnapshot("full")
    DynamicProbe = report
    Range("M1:Q3").ClearContents
    Application.Calculation = previous
End Function
"#);
        source
    }

    #[test]
    fn dynamic_returned_reference_dependencies_match_recorded_excel() {
        let source = dynamic_returned_reference_source();
        // Excel 20527, three separate processes for each starting selector.
        // No direct dependency is inferred from the function body's reads or
        // returned cell; CalculateFull is what refreshes the selected value.
        for (initial, expected, expected_trace) in [
            (0, "seed:0,0,0,2[5:10,5:10,5:0,5:20]|other:0,0,0,2[5:10,5:10,5:0,5:30]|picked:0,0,0,2[5:40,5:10,5:0,5:30]|switch:0,0,0,2[5:40,5:10,5:0,5:30]|old:0,0,0,2[5:50,5:10,5:0,5:30]|new:0,0,0,2[5:50,5:10,5:0,5:60]|full:0,0,0,3[5:50,5:60,5:0,5:60]","seed:R|seed:R|full:R|"),
            (1, "seed:0,0,0,2[5:10,5:20,5:0,5:20]|other:0,0,0,2[5:30,5:20,5:0,5:20]|picked:0,0,0,2[5:30,5:20,5:0,5:40]|switch:0,0,0,2[5:30,5:20,5:0,5:40]|old:0,0,0,2[5:30,5:20,5:0,5:50]|new:0,0,0,2[5:60,5:20,5:0,5:50]|full:0,0,0,3[5:60,5:60,5:0,5:50]","seed:R|seed:R|full:R|"),
        ] {
            let book = oxicells_core::parse_xlsx(include_bytes!("../../../tests/fixtures/vba/udf_returned_references.xlsm")).unwrap();
            let mut session = None;
            let result = execute_workbook_action_in_session(book, &source, Some("DynamicProbe"), vec![Value::Integer(initial)], 0, failure_context(), &mut session).unwrap();
            assert!(result.error.is_none(), "initial={initial}");
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "initial={initial}");
            let trace = execute_workbook_action_in_session(result.workbook, &source, Some("CallTrace"), vec![], 0, failure_context(), &mut session).unwrap();
            assert!(trace.error.is_none());
            assert_eq!(serde_json::to_value(&trace.result).unwrap(), serde_json::json!({"type":"string", "value":expected_trace}), "initial={initial}");
        }
    }

