    #[test]
    fn cut_validation_references_match_excel_after_save() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/row_height_state.xlsm");
        let range_source = "Public Function MakeCut() As String\nWorksheets.Add\nRange(\"G1:G3\").Validation.Add 7,1,1,\"=A1\"\nRange(\"A1:A2\").Cut Range(\"C1\")\nMakeCut=ReadCut()\nEnd Function\nPublic Function ReadCut() As String\nReadCut=Range(\"G1\").Validation.Formula1 & \"|\" & Range(\"G2\").Validation.Formula1 & \"|\" & Range(\"G3\").Validation.Formula1\nEnd Function";
        let result = execute_workbook_action_in_session(oxicells_core::parse_xlsx(bytes).unwrap(), range_source, Some("MakeCut"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(result.error.is_none());
        assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":"=C1|=C2|=C3"}));
        let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
        editor.apply_workbook(&result.workbook).unwrap();
        let reopened = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
        let result = execute_workbook_action_in_session(reopened, range_source, Some("ReadCut"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(result.error.is_none());
        assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":"=C1|=C2|=C3"}));
        for (formula, operation, destination, expected) in [
            ("=D1+$E$2", "Range(\"A1:A3\").Cut Range(\"C1\")", "C1,C2,C3", "=D1+$E$2|=D2+$E$2|=D3+$E$2|=C1"),
            ("=A1+$A$2", "Range(\"A1:A3\").Cut Range(\"C1\")", "C1,C2,C3", "=C1+$C$2|=C2+$C$2|=C3+$C$2|=C1"),
            ("=D1+$E$2", "Range(\"A1:A3\").Cut Range(\"A2\")", "A2,A3,A4", "=D1+$E$2|=D2+$E$2|=D3+$E$2|=A2"),
            ("=D1+$E$2", "Range(\"A1:A3\").Cut Worksheets(\"Target\").Range(\"C1\"): Worksheets(\"Target\").Activate", "C1,C2,C3", "=F1+$E$2|=F2+$E$2|=F3+$E$2|=Target!C1"),
            ("=Target!D1", "Range(\"A1:A3\").Cut Worksheets(\"Target\").Range(\"C1\"): Worksheets(\"Target\").Activate", "C1,C2,C3", "=F1|=F2|=F3|=Target!C1"),
            ("=Other!D1", "Range(\"A1:A3\").Cut Worksheets(\"Target\").Range(\"C1\"): Worksheets(\"Target\").Activate", "C1,C2,C3", "=Other!D1|=Other!D2|=Other!D3|=Target!C1"),
        ] {
            let cells: Vec<_> = destination.split(',').collect();
            let destination_sheet = if operation.contains("Target") { "Target" } else { "Source" };
            let source = format!("Public Function MakeCut() As String\nWorksheets.Add: ActiveSheet.Name=\"Source\"\nWorksheets.Add: ActiveSheet.Name=\"Target\"\nWorksheets.Add: ActiveSheet.Name=\"Other\"\nWorksheets(\"Source\").Activate\nRange(\"A1:A3\").Validation.Add 7,1,1,\"{formula}\"\nRange(\"G1\").Validation.Add 7,1,1,\"=A1\"\n{operation}\nMakeCut=ReadCut()\nEnd Function\nPublic Function ReadCut() As String\nReadCut=Worksheets(\"{destination_sheet}\").Range(\"{}\").Validation.Formula1 & \"|\" & Worksheets(\"{destination_sheet}\").Range(\"{}\").Validation.Formula1 & \"|\" & Worksheets(\"{destination_sheet}\").Range(\"{}\").Validation.Formula1 & \"|\" & Worksheets(\"Source\").Range(\"G1\").Validation.Formula1\nEnd Function", cells[0], cells[1], cells[2]);
            let result = execute_workbook_action_in_session(oxicells_core::parse_xlsx(bytes).unwrap(), &source, Some("MakeCut"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "{operation}");
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "runtime {operation}");
            let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
            editor.apply_workbook(&result.workbook).unwrap();
            let reopened = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
            let result = execute_workbook_action_in_session(reopened, &source, Some("ReadCut"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "reopened {operation}");
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "reopened {operation}");
        }
    }

    #[test]
    fn overlap_sweep_matches_pairwise_for_validation_areas() {
        let mut seed = 1234567_u64;
        for iteration in 0..400 {
            let mut areas = Vec::new();
            for _ in 0..25 {
                let mut next = || { seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1); (seed >> 32) as u32 };
                let row = next() % 60 + 1;
                let column = next() % 60;
                areas.push(CellRange { sheet: 0, start_row: row, end_row: row + next() % 4, start_column: column, end_column: column + next() % 4 });
            }
            let expected = (0..areas.len()).any(|i| (i + 1..areas.len()).any(|j| ranges_overlap(areas[i], areas[j])));
            assert_eq!(validation_areas_overlap(&areas), expected);
            let expected_flags: Vec<_> = (0..areas.len()).map(|i| (0..areas.len()).any(|j| i != j && ranges_overlap(areas[i], areas[j]))).collect();
            assert_eq!(validation_overlap_flags(&areas), expected_flags);
            if iteration < 40 {
                let disjoint = WorkbookHost::disjoint_validation_blocks(&areas);
                assert_eq!(disjoint[0].first(), areas[0].first());
                for row in 1..=64 {
                    for column in 0..64 {
                        let contains = |area: &CellRange| (area.start_row..=area.end_row).contains(&row) && (area.start_column..=area.end_column).contains(&column);
                        assert_eq!(areas.iter().any(contains), disjoint.iter().any(contains));
                        assert!(disjoint.iter().filter(|area| contains(area)).count() <= 1);
                    }
                }
            }
        }
        let mut areas: Vec<_> = (0..100_000).map(|i| CellRange { sheet: 0, start_row: i * 2 + 1, end_row: i * 2 + 1, start_column: 0, end_column: 0 }).collect();
        assert!(!validation_areas_overlap(&areas));
        areas.push(areas[99_999]);
        assert!(validation_areas_overlap(&areas));
        assert_eq!(WorkbookHost::disjoint_validation_blocks(&areas).len(), 100_000);
        let mut dense = vec![CellRange { sheet: 0, start_row: 1, end_row: 1, start_column: 0, end_column: 0 }; 100_000];
        dense.push(CellRange { sheet: 0, start_row: 200_001, end_row: 200_001, start_column: 0, end_column: 0 });
        let flags = validation_overlap_flags(&dense);
        assert!(flags[..100_000].iter().all(|flag| *flag));
        assert!(!flags[100_000]);
        assert_eq!(WorkbookHost::disjoint_validation_blocks(&dense).len(), 2);
    }

