    #[test]
    fn distinct_overlapping_validation_rules_keep_first_and_survive_skip_blanks() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/row_height_state.xlsm");
        let mut book = oxicells_core::parse_xlsx(bytes).unwrap();
        let first = serde_json::from_value(serde_json::json!({"kind":"custom", "ranges":[[0,2,2,2]], "formula1":"H1"})).unwrap();
        let second = serde_json::from_value(serde_json::json!({"kind":"custom", "ranges":[[1,2,3,2]], "formula1":"J2"})).unwrap();
        book.sheets[0].validations = vec![first, second];
        let source = "Public Function ReadRules() As String\nReadRules=Range(\"C1\").Validation.Formula1 & \"|\" & Range(\"C2\").Validation.Formula1 & \"|\" & Range(\"C3\").Validation.Formula1 & \"|\" & Range(\"C4\").Validation.Formula1\nEnd Function\nPublic Function SkipRule() As String\nRange(\"A1\").Copy\nRange(\"C2\").PasteSpecial 6,-4142,True,False\nSkipRule=ReadRules()\nEnd Function\nPublic Function MixedRules() As String\nRange(\"A1\").Validation.Add 7,1,1,\"=Z1\"\nRange(\"A1:A3\").Copy\nRange(\"C1\").PasteSpecial 6,-4142,True,False\nMixedRules=ReadRules()\nEnd Function";
        for (procedure, expected) in [("ReadRules", "=H1|=H2|=H3|=J4"), ("SkipRule", "=H1|=H2|=H3|=J4"), ("MixedRules", "=AB1|=H2|=H3|=J4")] {
            let result = execute_workbook_action_in_session(book.clone(), source, Some(procedure), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "{procedure}");
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "{procedure}");
            for row in [1, 2] {
                let coverage = result.workbook.sheets[0].validations.iter().flat_map(|rule| &rule.ranges).filter(|&&(r0,c0,r1,c1)| (r0..=r1).contains(&row) && (c0..=c1).contains(&2)).count();
                assert_eq!(coverage, 2, "overlap must be preserved at C{} after {procedure}", row + 1);
            }
            let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
            editor.apply_workbook(&result.workbook).unwrap();
            let reopened = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
            let result = execute_workbook_action_in_session(reopened, source, Some("ReadRules"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "reopened {procedure}");
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "reopened {procedure}");
        }
    }

