            let result = execute_workbook_action_in_session(oxicells_core::parse_xlsx(bytes).unwrap(), &source, Some("MakeRelative"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "{deletion}");
