    #[test]
    fn save_copy_matches_native_rows_calculation_and_errors() {
        let corpus: serde_json::Value = serde_json::from_str(include_str!("../../../tests/fixtures/vba/save_copy_native_cases.json")).unwrap();
        let fixture = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/vba");
        let mut checked = 0;
        for group in corpus["groups"].as_array().unwrap() {
            let source = std::fs::read_to_string(fixture.join(group["source"].as_str().unwrap())).unwrap();
            let package = std::fs::read(fixture.join(group["package"].as_str().unwrap())).unwrap();
            let mut book = oxicells_core::parse_xlsx(&package).unwrap();
            book.calculation.compatibility_version = 1;
            let mut session = None;
            for case in group["cases"].as_array().unwrap() {
                if case["result_includes_file_length"] == true { continue; }
                let mut context = failure_context();
                context.document_modules = Some(crate::vba_project::read_document_modules(&package).unwrap());
                context.application_state = Some(VbaApplicationState { display_alerts: false, ..VbaApplicationState::default() });
                context.file_context = Some(file_io::FileContext {
            edit_revision: None, source_code_page: None,
                    package_bytes: Some(package.clone()),
                    full_name: Some(group["full_name"].as_str().unwrap().into()),
                    read_only: Some(true),
                    folders: serde_json::from_value(group["folders"].clone()).unwrap(),
                    files: serde_json::from_value(group["initial_files"].clone()).unwrap(),
                });
                let args = case["arguments"].as_array().unwrap().iter().map(|value| match value {
                    serde_json::Value::Bool(value) => Value::Boolean(*value),
                    serde_json::Value::String(value) => Value::String(value.clone()),
                    serde_json::Value::Number(value) => Value::Double(value.as_f64().unwrap()),
                    _ => panic!("unsupported oracle argument"),
                }).collect();
                let outcome = execute_workbook_action_in_session(book, &source, Some(case["procedure"].as_str().unwrap()), args, 0, context, &mut session).unwrap();
                assert!(outcome.error.is_none(), "{} {:?}: {:?}", group["name"], case["arguments"], outcome.error.as_ref().map(|error| &error.message));
                assert_eq!(serde_json::to_value(&outcome.result).unwrap(), serde_json::json!({"type":"string","value":case["expected"]}), "{} {:?}", group["name"], case["arguments"]);
                if case["copied"] == true {
                    assert_eq!(outcome.files.len(), 1);
                    assert_eq!(outcome.files[0].path, case["target"].as_str().unwrap());
                    let bytes = &outcome.files[0].bytes;
                    assert_eq!(crate::vba_project::read_project_source_with_code_page(bytes, None).unwrap().unwrap().replace("\r\n", "\n").trim_end(), source.replace("\r\n", "\n").trim_end());
                    let saved = oxicells_core::parse_xlsx_preserving_values(bytes).unwrap();
                    let expected = &case["saved"]["row4_attributes"];
                    if expected.is_object() {
                        let row = saved.sheets[0].rows.iter().find(|row| row.index == 4);
                        let height = expected["ht"].as_str().map(|value| value.parse::<f32>().unwrap());
                        assert_eq!(row.and_then(|row| row.height), height);
                        assert_eq!(row.is_some_and(|row| row.hidden), expected["hidden"] == "1");
                        assert_eq!(row.is_some_and(|row| row.custom_height), expected["customHeight"] == "1");
                    }
                    if let Some(formula) = case["saved"]["b2_formula"].as_str() {
                        let cell = saved.sheets[0].rows.iter().find(|row| row.index == 2).unwrap().cells.iter().find(|cell| cell.col == 1).unwrap();
                        assert_eq!(cell.formula.as_deref(), Some(formula));
                        assert!(matches!(cell.value, CellValue::Number(value) if value == case["saved"]["b2_value"].as_f64().unwrap()));
                    }
                } else { assert!(outcome.files.is_empty()); }
                book = outcome.workbook;
                checked += 1;
            }
        }
        assert_eq!(checked, 125);
    }

    #[test]
    fn save_copy_filename_variants_match_native_excel() {
        let mut corpus: serde_json::Value = serde_json::from_str(include_str!("../../../tests/fixtures/vba/save_copy_filename_native.json")).unwrap();
        let scalar: serde_json::Value = serde_json::from_str(include_str!("../../../tests/fixtures/vba/save_copy_scalar_native.json")).unwrap();
        corpus["groups"].as_array_mut().unwrap().extend(scalar["groups"].as_array().unwrap().iter().cloned());
        let directory: serde_json::Value = serde_json::from_str(include_str!("../../../tests/fixtures/vba/directory_outputs_native.json")).unwrap();
        corpus["groups"].as_array_mut().unwrap().extend(directory["groups"].as_array().unwrap().iter().cloned());
        let fixture = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/vba");
        let mut checked = 0;
        for group in corpus["groups"].as_array().unwrap() {
            let source = std::fs::read_to_string(fixture.join(group["source"].as_str().unwrap())).unwrap();
            let package = std::fs::read(fixture.join(group["package"].as_str().unwrap())).unwrap();
            assert_eq!(crate::vba_project::write_project_source(&package, &source, None).unwrap(), package);
            let mut book = oxicells_core::parse_xlsx(&package).unwrap();
            book.calculation.compatibility_version = 1;
            let mut session = None;
            for case in group["cases"].as_array().unwrap() {
                let mut context = failure_context();
                context.environment.help_file = group["vba_help_file"].as_str().unwrap().into();
                context.host_ansi_code_page = Some(AnsiCodePage::Japanese);
                context.document_modules = Some(crate::vba_project::read_document_modules(&package).unwrap());
                context.application_state = Some(VbaApplicationState { display_alerts: false, ..VbaApplicationState::default() });
                context.file_context = Some(file_io::FileContext {
            edit_revision: None, source_code_page: None,
                    package_bytes: Some(package.clone()), full_name: Some(group["full_name"].as_str().unwrap().into()), read_only: Some(true),
                    folders: serde_json::from_value(group["folders"].clone()).unwrap(),
                    files: serde_json::from_value(group["initial_files"].clone()).unwrap(),
                });
                let args = case["arguments"].as_array().unwrap().iter().map(|value| match value {
                    serde_json::Value::Bool(value) => Value::Boolean(*value),
                    serde_json::Value::String(value) => Value::String(value.clone()),
                    serde_json::Value::Number(value) => Value::Double(value.as_f64().unwrap()),
                    _ => panic!("unsupported oracle argument"),
                }).collect();
                let outcome = execute_workbook_action_in_session(book, &source, Some(case["procedure"].as_str().unwrap()), args, 0, context, &mut session).unwrap();
                assert!(outcome.error.is_none(), "{} {:?}: {:?}", group["name"], case["arguments"], outcome.error.as_ref().map(|error| &error.message));
                assert_eq!(serde_json::to_value(&outcome.result).unwrap(), serde_json::json!({"type":"string","value":case["expected"]}), "{} {:?}", group["name"], case["arguments"]);
                if let Some(deleted)=case.get("deleted_files") {
                    assert_eq!(serde_json::to_value(&outcome.deleted_files).unwrap(),*deleted);
                }
                let expected = case["files"].as_array().unwrap();
                assert_eq!(outcome.files.len(), expected.len(), "{} {:?}", group["name"], case["arguments"]);
                for file in &outcome.files {
                    let expected = expected.iter().find(|value| value["path"].as_str()==Some(file.path.as_str())).unwrap();
                    if let Some(bytes)=expected.get("bytes") {
                        assert_eq!(serde_json::to_value(&file.bytes).unwrap(),*bytes,"{} {:?} {}",group["name"],case["arguments"],file.path);
                        continue;
                    }
                    let actual_source = crate::vba_project::read_project_source_with_code_page(&file.bytes, None).unwrap().unwrap();
                    assert_eq!(actual_source.replace("\r\n", "\n").trim_end(), source.replace("\r\n", "\n").trim_end());
                    let saved = oxicells_core::parse_xlsx_preserving_values(&file.bytes).unwrap();
                    for (address, row, column) in [("A1", 1, 0), ("A2", 2, 0), ("A3", 3, 0), ("B1", 1, 1)] {
                        let value = saved.sheets[0].rows.iter().find(|held| held.index==row)
                            .and_then(|held| held.cells.iter().find(|cell| cell.col==column)).map(|cell| &cell.value);
                        let actual = match value {
                            None | Some(CellValue::Empty) => serde_json::Value::Null,
                            Some(value) => serde_json::to_value(value).unwrap(),
                        };
                        assert_eq!(actual, expected["cells"][address], "{} {:?} {} {address}", group["name"], case["arguments"], file.path);
                    }
                }
                book = outcome.workbook;
                checked += 1;
            }
        }
        assert_eq!(checked, 150);
    }

    #[test]
    fn save_copy_produces_native_row_state_and_preserves_vba_source() {
        let case: serde_json::Value = serde_json::from_str(include_str!("../../../tests/fixtures/vba/save_copy_native_row.json")).unwrap();
        let package = include_bytes!("../../../tests/fixtures/vba/row_height_state.xlsm");
        let source = include_str!("../../../tests/fixtures/vba/worksheet_row_height_state.bas");
        let target = case["arguments"][1].as_str().unwrap();
        let mut context = failure_context();
        context.file_context = Some(file_io::FileContext {
            edit_revision: None, source_code_page: None,
            package_bytes: Some(package.to_vec()),
            full_name: Some(case["full_name"].as_str().unwrap().into()),
            read_only: Some(true),
            folders: vec![target.rsplit_once('\\').unwrap().0.to_string()],
            files: vec![],
        });
        context.document_modules = Some(crate::vba_project::read_document_modules(package).unwrap());
        let mut book = oxicells_core::parse_xlsx(package).unwrap();
        book.calculation.compatibility_version = 1;
        let mut session = None;
        let outcome = execute_workbook_action_in_session(book, source, Some(case["procedure"].as_str().unwrap()),
            vec![Value::Double(22.0), Value::String(target.to_string())], 0, context, &mut session).unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
        assert_eq!(serde_json::to_value(&outcome.result).unwrap(), serde_json::json!({"type":"string","value":case["expected"]}));
        assert_eq!(outcome.files.len(), 1);
        assert_eq!(outcome.files[0].path, target);
        let bytes = &outcome.files[0].bytes;
        assert_eq!(crate::vba_project::read_project_source_with_code_page(bytes, None).unwrap().unwrap().replace("\r\n", "\n").trim_end(), source.replace("\r\n", "\n").trim_end());
        let loaded = oxicells_core::parse_xlsx_preserving_values(bytes).unwrap();
        let row = loaded.sheets[0].rows.iter().find(|row| row.index == 4).unwrap();
        assert_eq!(row.height, Some(case["row4_attributes"]["ht"].as_str().unwrap().parse::<f32>().unwrap()));
        assert!(row.custom_height);
        assert!(!row.hidden);
        let length = bytes.len();
        let mut context = failure_context();
        context.document_modules = Some(crate::vba_project::read_document_modules(package).unwrap());
        let inspect_source = format!("{source}\nPublic Function InspectCopy() As Long\n InspectCopy = FileLen(\"{target}\")\nEnd Function\n");
        let inspected = execute_workbook_action_in_session(outcome.workbook,
            &inspect_source, Some("InspectCopy"), vec![], 0, context, &mut session).unwrap();
        assert!(inspected.error.is_none());
        assert_eq!(serde_json::to_value(&inspected.result).unwrap()["value"].as_i64(), Some(length as i64));
        assert!(inspected.files.is_empty());
    }

