    #[test]
    fn row_height_defaults_matches_native_excel() {
        let source = include_str!("../../../tests/fixtures/vba/worksheet_row_height_defaults.bas");
        let rows: Vec<_> = include_str!("../../../tests/fixtures/vba/worksheet_row_height_defaults.tsv").lines()
            .filter(|line| !line.is_empty() && !line.starts_with('#')).map(|line| line.split('\t').collect::<Vec<_>>()).collect();
        assert_eq!(rows.len(), 14);
        let mut book = oxicells_core::parse_xlsx(include_bytes!("../../../tests/fixtures/vba/row_height_defaults.xlsm")).unwrap();
        book.calculation.compatibility_version = 1;
        let mut session = None;
        for fields in rows {
            let args = serde_json::from_str::<Vec<serde_json::Value>>(fields[2]).unwrap().into_iter().map(|value| match value {
                serde_json::Value::Bool(value) => Value::Boolean(value),
                serde_json::Value::Number(value) => Value::Double(value.as_f64().unwrap()),
                serde_json::Value::String(value) => Value::String(value),
                _ => panic!("unsupported oracle argument"),
            }).collect();
            let outcome = execute_workbook_action_in_session(book, source, Some(fields[1]), args, 0, failure_context(), &mut session).unwrap();
            assert!(outcome.error.is_none(), "{fields:?}: {:?}", outcome.error.as_ref().map(|error| &error.message));
            assert_eq!(serde_json::to_value(&outcome.result).unwrap(), serde_json::json!({"type":"string","value":fields[3]}), "{fields:?}");
            book = serde_json::from_slice(&serde_json::to_vec(&outcome.workbook).unwrap()).unwrap();
        }

        let query = parse_module(r#"Private Function Show(ByVal value As Variant) As String
 If IsNull(value) Then
  Show = "NULL"
 Else
  Show = CStr(value)
 End If
End Function
Public Function DefaultQueries(ByVal mode As Long) As String
 Select Case mode
  Case 1: Rows.RowHeight = 22
  Case 2: Rows(1).RowHeight = 22
  Case 3: Rows(2).RowHeight = 22
  Case 4
   Rows.RowHeight = 22
   Rows.UseStandardHeight = True
  Case 5
   Rows.RowHeight = 22
   Rows(1).UseStandardHeight = True
  Case 6
   Rows(1).RowHeight = 22
   Rows(2).RowHeight = 30
   Range("A1:A2").Value = "data"
  Case 7
   Rows("1:3").RowHeight = 22
   Range("A1:A2").Merge
  Case 8
   Rows(1).RowHeight = 22
   Range("A10:A11").Merge
  Case 9
   Rows(1).Hidden = True
   Rows.RowHeight = 22
 End Select
 DefaultQueries = CStr(ActiveSheet.StandardHeight) & "|" & Show(Rows.RowHeight) & "|" & Show(Rows.UseStandardHeight) & "|" & CStr(Rows(1).RowHeight) & "|" & CStr(Rows(2).RowHeight) & "|" & CStr(Range("A2").Top) & "|" & CStr(Range("A1:A3").Height)
End Function"#).unwrap();
        for (mode, expected) in [
            (0, "15|15|True|15|15|15|45"),
            (1, "22|22|False|22|22|21.75|65.25"),
            (2, "15|22|False|22|15|21.75|51.75"),
            (3, "15|15|True|15|22|15|51.75"),
            (4, "15|15|True|15|15|15|45"),
            (5, "22|15|True|15|22|15|58.5"),
            (6, "15|NULL|False|22|30|21.75|66.75"),
            (7, "15|22|False|22|22|21.75|65.25"),
            (8, "15|NULL|NULL|22|15|21.75|51.75"),
            (9, "22|22|False|22|22|21.75|65.25"),
        ] {
            let mut book = workbook();
            book.sheets[0].default_row_height = 18.75;
            book.sheets[0].normal_font = Some(("Aptos Narrow".into(), 11.0));
            let mut host = WorkbookHost::new(&mut book, 0).unwrap();
            let result = execute_with_host(&query, "DefaultQueries", vec![Value::Integer(mode)], &mut host).unwrap();
            assert_eq!(result, Value::String(expected.into()), "mode {mode}");
        }

        let package = file_io::WorkbookFiles::blank_package(
            oxicells_core::ir::SheetKind::Worksheet, 1, &default_application_font(), (0.0, 15.0),
        ).unwrap();
        let book = oxicells_core::parse_xlsx(&package).unwrap();
        assert!(book.sheets[0].rows.is_empty());
        assert_eq!(oxicells_core::XlsxEditor::new(&package).unwrap().save().unwrap(), package);
        let mut context = failure_context();
        context.file_context = Some(file_io::FileContext {
            edit_revision: None, source_code_page: None,
            package_bytes: Some(package), full_name: Some("C:\\work\\seed.xlsx".into()),
            read_only: Some(true), folders: vec!["C:\\work".into()], files: vec![],
        });
        let source = r#"Public Function SaveEmptyRow() As String
 Rows(1).RowHeight = 22
 ActiveWorkbook.SaveCopyAs "C:\work\saved.xlsx"
 Set copied = Workbooks.Open("C:\work\saved.xlsx")
 SaveEmptyRow = CStr(copied.Worksheets(1).Rows(1).RowHeight)
 copied.Close False
End Function"#;
        let mut session = None;
        let saved = execute_workbook_action_in_session(
            book, source, Some("SaveEmptyRow"), vec![], 0, context, &mut session,
        ).unwrap();
        assert!(saved.error.is_none(), "{:?}", saved.error.as_ref().map(|error| &error.message));
        assert_eq!(serde_json::to_value(&saved.result).unwrap(), serde_json::json!({"type":"string","value":"22"}));
        assert_eq!(saved.files.len(), 1);
        let reopened = oxicells_core::parse_xlsx(&saved.files[0].bytes).unwrap();
        let row = &reopened.sheets[0].rows[0];
        assert_eq!((row.index, row.height, row.custom_height), (1, Some(21.95), true));
        assert!(row.cells.is_empty());

        let font_query = parse_module(r#"Public Function EmptyRowFont(ByVal size As Double, ByVal flags As Long) As String
 Rows(3).Font.Size = size
 If flags Mod 2 = 1 Then Rows(3).Font.Bold = True
 If flags >= 2 Then Rows(3).Font.Italic = True
 EmptyRowFont = CStr(Rows(3).RowHeight) & "|" & CStr(Rows(3).Height) & "|" & CStr(Rows(3).UseStandardHeight)
End Function"#).unwrap();
        for flags in 0..4 {
            for (size, expected) in [(8.0, "11.25|11.25|True"), (11.0, "15|15|True"),
                (20.0, "26.25|26.25|True"), (40.0, "53.25|53.25|True")] {
                let mut book = workbook();
                book.sheets[0].normal_font = Some(("Aptos Narrow".into(), 11.0));
                let mut host = WorkbookHost::new(&mut book, 0).unwrap();
                let result = execute_with_host(&font_query, "EmptyRowFont", vec![Value::Double(size), Value::Integer(flags)], &mut host).unwrap();
                assert_eq!(result, Value::String(expected.into()), "size {size}, flags {flags}");
            }
        }

        let cleanup_source = r#"Private Function ShowCleanup(ByVal value As Variant) As String
 If IsNull(value) Then
  ShowCleanup = "NULL"
 Else
  ShowCleanup = CStr(value)
 End If
End Function
Public Function SaveCleanup(ByVal mode As Long) As String
 Rows(1).RowHeight = 22
 Rows(2).RowHeight = 30
 Select Case mode
  Case 0, 1
   Range("A1:A2").Merge
   Range("A1:A2").UnMerge
   If mode = 1 Then Range("A1:A2").Font.Bold = True
  Case 2: Range("A1:A2").Value = "data"
  Case 3
   Range("A1:A2").Value = "data"
   Range("A1:A2").ClearContents
  Case 4: Range("A1").Formula = "=1-1"
 End Select
 SaveCleanup = ShowCleanup(Rows.RowHeight)
 ActiveWorkbook.SaveCopyAs "C:\work\cleanup.xlsx"
 SaveCleanup = SaveCleanup & "|" & ShowCleanup(Rows.RowHeight) & "|" & CStr(ActiveWorkbook.Saved)
 Set copied = Workbooks.Open("C:\work\cleanup.xlsx")
 SaveCleanup = SaveCleanup & "|" & ShowCleanup(copied.Worksheets(1).Rows.RowHeight)
 If mode = 4 Then SaveCleanup = SaveCleanup & "|" & CStr(copied.Worksheets(1).Range("A1").HasFormula)
 copied.Close False
End Function"#;
        for (mode, expected) in [(0, "NULL|22|False|22"), (1, "NULL|NULL|False|NULL"),
            (2, "NULL|NULL|False|NULL"), (3, "NULL|22|False|22"), (4, "NULL|NULL|False|NULL|True")] {
            let package = file_io::WorkbookFiles::blank_package(
                oxicells_core::ir::SheetKind::Worksheet, 1, &default_application_font(), (0.0,15.0),
            ).unwrap();
            let book = oxicells_core::parse_xlsx(&package).unwrap();
            let mut context = failure_context();
            context.file_context = Some(file_io::FileContext {
                edit_revision: None, source_code_page: None, package_bytes: Some(package),
                full_name: Some("C:\\work\\seed.xlsx".into()), read_only: Some(true),
                folders: vec!["C:\\work".into()], files: vec![],
            });
            let mut session = None;
            let outcome = execute_workbook_action_in_session(book, cleanup_source, Some("SaveCleanup"),
                vec![Value::Integer(mode)], 0, context, &mut session).unwrap();
            assert!(outcome.error.is_none(), "mode {mode}: {:?}", outcome.error.as_ref().map(|error|&error.message));
            assert_eq!(serde_json::to_value(&outcome.result).unwrap(), serde_json::json!({"type":"string","value":expected}), "mode {mode}");
        }

        for prefix in ["", "s:"] {
            let namespace = if prefix.is_empty() { r#"xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main""# }
                else { r#"xmlns:s="http://schemas.openxmlformats.org/spreadsheetml/2006/main""# };
            let xml = format!(r#"<{prefix}worksheet {namespace} xmlns:z="urn:foreign"><{prefix}sheetData><{prefix}row r="1"><{prefix}c r="A1"/><{prefix}c r="B1"><{prefix}v/></{prefix}c><{prefix}c r="C1" cm="1"/><{prefix}c r="D1"><z:payload/></{prefix}c><{prefix}c r="E1"><{prefix}f>1</{prefix}f><{prefix}v/></{prefix}c><{prefix}c r="F1"><{prefix}v>5</{prefix}v></{prefix}c><z:c r="G1"/></{prefix}row></{prefix}sheetData></{prefix}worksheet>"#);
            let candidates = std::collections::BTreeSet::from(["A1", "B1", "C1", "D1", "E1", "F1", "G1"].map(String::from));
            let (pruned, cleanup) = file_io::WorkbookFiles::prune_empty_normal_cell_xml(&xml, &candidates).unwrap();
            let expected = xml.replace(&format!(r#"<{prefix}c r="A1"/>"#), "")
                .replace(&format!(r#"<{prefix}c r="B1"><{prefix}v/></{prefix}c>"#), "");
            assert_eq!(pruned, expected.into_bytes());
            assert_eq!(cleanup, std::collections::BTreeSet::from(["A1".to_string(), "B1".to_string()]));
            let xml=format!(r#"<{prefix}worksheet {namespace} xmlns:z="urn:foreign"><{prefix}sheetData><{prefix}row r="1"/><{prefix}row r="2"><{prefix}c r="A2"/></{prefix}row><{prefix}row r="3" ht="22" customHeight="1"/><{prefix}row r="4" z:token="keep"/><{prefix}row r="5"><z:payload/></{prefix}row><{prefix}row r="6"><!--keep--></{prefix}row><z:row r="7"/><{prefix}row r="8" s="1"/><{prefix}row r="9"> </{prefix}row></{prefix}sheetData></{prefix}worksheet>"#);
            let rows=std::collections::BTreeSet::from([1,2,3,4,5,6,7,8,9]);
            let (pruned,removed)=file_io::WorkbookFiles::prune_empty_cached_rows_xml(&xml,&rows).unwrap();
            let expected=xml.replace(&format!(r#"<{prefix}row r="1"/>"#),"")
                .replace(&format!(r#"<{prefix}row r="9"> </{prefix}row>"#),"");
            assert_eq!(pruned,expected.into_bytes());
            assert_eq!(removed,std::collections::BTreeSet::from([1,9]));
        }
    }

