    #[test]
    fn saved_sheet_protection_reaches_fresh_vba_hosts() {
        use std::io::{Cursor, Read, Write};
        let original = include_bytes!("../../../tests/fixtures/vba/array_argument_rank.xlsm");
        for protection in [
            "<sheetProtection sheet=\"1\" formatCells=\"0\"/>",
            "<sheetProtection sheet=\"1\" formatCells=\"0\"></sheetProtection>",
        ] {
            let mut source = zip::ZipArchive::new(Cursor::new(original)).unwrap();
            let mut target = zip::ZipWriter::new(Cursor::new(Vec::new()));
            for index in 0..source.len() {
                let mut part = source.by_index(index).unwrap();
                let name = part.name().to_string();
                let mut bytes = Vec::new();
                part.read_to_end(&mut bytes).unwrap();
                if name == "xl/worksheets/sheet1.xml" {
                    let text = String::from_utf8(bytes).unwrap();
                    assert!(!text.contains("<sheetProtection"));
                    bytes = text.replace("</sheetData>", &format!("</sheetData>{protection}")).into_bytes();
                }
                target.start_file(name, zip::write::SimpleFileOptions::default()).unwrap();
                target.write_all(&bytes).unwrap();
            }
            let bytes = target.finish().unwrap().into_inner();
            let mut book = oxicells_core::parse_xlsx(&bytes).unwrap();
            let module = parse_module(
                "Public Function FormatCell() As String\n\
                 Range(\"A1\").Font.Bold = True\n\
                 FormatCell = CStr(ActiveSheet.ProtectContents) & \"|\" & \
                 CStr(ActiveSheet.Protection.AllowFormattingCells) & \"|\" & \
                 CStr(ActiveSheet.Protection.AllowFormattingRows)\nEnd Function\n\
                 Public Function FitRow() As Long\nOn Error Resume Next\n\
                 Rows(1).AutoFit\nFitRow = Err.Number\nEnd Function\n\
                 Public Function DropProtection() As Boolean\nActiveSheet.Unprotect\n\
                 DropProtection = ActiveSheet.ProtectContents\nEnd Function\n"
            ).unwrap();
            {
                let mut host = WorkbookHost::new(&mut book, 0).unwrap();
                assert_eq!(execute_with_host(&module, "FormatCell", vec![], &mut host).unwrap(),
                    Value::String("True|True|False".to_string()));
            }
            let mut book: Workbook = serde_json::from_slice(&serde_json::to_vec(&book).unwrap()).unwrap();
            {
                let mut host = WorkbookHost::new(&mut book, 0).unwrap();
                assert_eq!(execute_with_host(&module, "FitRow", vec![], &mut host).unwrap(),
                    Value::Integer(1004));
                assert_eq!(execute_with_host(&module, "DropProtection", vec![], &mut host).unwrap(),
                    Value::Boolean(false));
            }
            let mut host = WorkbookHost::new(&mut book, 0).unwrap();
            assert_eq!(execute_with_host(&module, "DropProtection", vec![], &mut host).unwrap(),
                Value::Boolean(false));
        }
    }

    /// What a filter counts as a match.
    ///
    /// Every answer was asked of Excel about a column holding 10, "apple", a
    /// blank, 30, "Apricot", "banana" and 10 under a heading. Note `<>10`,
    /// which keeps the BLANK row, and that text is matched without regard to
    /// case.
    #[test]
    fn vba_filters_the_rows_a_criterion_names() {
        let showing = |criteria: &str| {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Function Showing() As String
                   Range(\"A1\").Value = \"head\"
                   Range(\"A2\").Value = 10
                   Range(\"A3\").Value = \"apple\"
                   Range(\"A5\").Value = 30
                   Range(\"A6\").Value = \"Apricot\"
                   Range(\"A7\").Value = \"banana\"
                   Range(\"A8\").Value = 10
                   Range(\"A1:A8\").AutoFilter {criteria}
                   Dim seen, row
                   seen = \"\"
                   For row = 2 To 8
                     If Not Rows(row).Hidden Then seen = seen & row & \",\"
                   Next row
                   Showing = seen
                 End Function\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            match execute_with_host(&module, "Showing", vec![], &mut host) {
                Ok(Value::String(seen)) => seen,
                Ok(other) => format!("{other:?}"),
                Err(error) => format!("! {error}"),
            }
        };

        assert_eq!(showing("1, \"10\""), "2,8,");
        assert_eq!(showing("1, \">10\""), "5,");
        assert_eq!(showing("1, \">=10\""), "2,5,8,");
        // A blank is not 10 either, so it stays.
        assert_eq!(showing("1, \"<>10\""), "3,4,5,6,7,");
        assert_eq!(showing("1, \"=\""), "4,");
        assert_eq!(showing("1, \"<>\""), "2,3,5,6,7,8,");
        assert_eq!(showing("1, \"apple\""), "3,");
        assert_eq!(showing("1, \"APPLE\""), "3,");
        assert_eq!(showing("1, \"a*\""), "3,6,");
        assert_eq!(showing("1, \"10\", xlOr, \"30\""), "2,5,8,");
        assert_eq!(showing("1, \">=10\", xlAnd, \"<=20\""), "2,8,");
        assert_eq!(showing(""), "2,3,4,5,6,7,8,");
        // A list of values keeps a row holding any of them.
        assert_eq!(showing("1, Array(\"10\", \"banana\"), xlFilterValues"), "2,7,8,");
    }

    /// Whether the first line of a range reads as a heading.
    ///
    /// Every answer was asked of Excel with `Header:=xlGuess`. A first row
    /// that differs from the one under it stays where it is: text over
    /// numbers, or a row that is bold, filled, larger or underlined where the
    /// rest is plain. A row like the ones below it is sorted with them, and an
    /// EMPTY first row is not a heading at all.
    #[test]
    fn vba_guesses_whether_the_first_row_is_a_heading() {
        let sorted = |fill: &str| {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Function Sorted() As String
                   {fill}
                   Range(\"A1:A4\").Sort Key1:=Range(\"A1\"), Order1:=xlAscending, \
                     Header:=xlGuess
                   Dim seen, row
                   seen = \"\"
                   For row = 1 To 4
                     seen = seen & Range(\"A\" & row).Value & \",\"
                   Next row
                   Sorted = seen
                 End Function\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            match execute_with_host(&module, "Sorted", vec![], &mut host) {
                Ok(Value::String(seen)) => seen,
                Ok(other) => format!("{other:?}"),
                Err(error) => format!("! {error}"),
            }
        };
        let numbers = "Range(\"A1\").Value = 99
                       Range(\"A2\").Value = 30
                       Range(\"A3\").Value = 10
                       Range(\"A4\").Value = 20";
        let words = "Range(\"A1\").Value = \"zebra\"
                     Range(\"A2\").Value = \"cherry\"
                     Range(\"A3\").Value = \"apple\"
                     Range(\"A4\").Value = \"banana\"";

        // Alike, so the first row is sorted with the rest.
        assert_eq!(sorted(numbers), "10,20,30,99,");
        assert_eq!(sorted(words), "apple,banana,cherry,zebra,");
        // Text over numbers is a heading.
        assert_eq!(
            sorted(
                "Range(\"A1\").Value = \"head\"
                 Range(\"A2\").Value = 30
                 Range(\"A3\").Value = 10
                 Range(\"A4\").Value = 20"
            ),
            "head,10,20,30,"
        );
        // So is any difference in the dress.
        for dressed in [
            "Range(\"A1\").Font.Bold = True",
            "Range(\"A1\").Interior.Color = 255",
            "Range(\"A1\").Font.Size = 16",
            "Range(\"A1\").Font.Underline = xlUnderlineStyleSingle",
        ] {
            assert_eq!(
                sorted(&format!("{numbers}\n{dressed}")),
                "99,10,20,30,",
                "with {dressed}"
            );
            assert_eq!(
                sorted(&format!("{words}\n{dressed}")),
                "zebra,apple,banana,cherry,",
                "with {dressed}"
            );
        }
        // An empty first row is not a heading.
        assert_eq!(
            sorted(
                "Range(\"A2\").Value = 30
                 Range(\"A3\").Value = 10
                 Range(\"A4\").Value = 20"
            ),
            "10,20,30,,"
        );
    }

    /// Excel 16.0 Japanese Find keeps wide and narrow forms distinct.
    ///
    /// Measured through Excel 16.0 COM (LCID 1041): Find("ABC") skips a cell
    /// holding fullwidth ＡＢＣ and returns the next ASCII match; MatchByte
    /// True gives the same result. Halfwidth and fullwidth kana behave likewise.
    #[test]
    fn vba_reads_a_wide_letter_and_a_narrow_one_as_one() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Found() As String
               Range(\"A1\").Value = \"ＡＢＣ\"
               Range(\"A2\").Value = \"ABC\"
               Range(\"A3\").Value = \"アイ\"
               Range(\"A4\").Value = \"ｱｲ\"\n\
               Range(\"A5\").Value = \"ガ\"\n\
               Range(\"A6\").Value = \"ABC\"
               Found = Range(\"A1:A6\").Find(\"ABC\", Range(\"A6\")).Address(False, False) & \"|\" & _
                 Range(\"A1:A6\").Find(\"ABC\", Range(\"A6\"), , , , , , True).Address(False, False) & \"|\" & _
                 Range(\"A1:A6\").Find(\"ｱｲ\", Range(\"A6\")).Address(False, False) & \"|\" & _\n\
                 Range(\"A1:A6\").Find(\"ｱｲ\", Range(\"A6\"), , , , , , True).Address(False, False) & \"|\" & _\n\
                 Range(\"A1:A6\").Find(\"ABC\", Range(\"A6\")).Address(False, False)
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Found", vec![], &mut host).unwrap()
        };

        assert_eq!(result, Value::String("A2|A2|A4|A4|A2".to_string()));
    }

    /// Hiding a sheet, and the one sheet that cannot be hidden.
    ///
    /// Asked of Excel: a fresh sheet answers -1, `Visible = False` leaves 0,
    /// 2 is the hidden-and-not-offered state, 1 is read as True, 3 is refused,
    /// and hiding the last sheet still showing raises. A hidden sheet's cells
    /// still answer.
    #[test]
    fn vba_hides_a_sheet_but_not_the_last_one_showing() {
        let mut workbook = workbook();
        for name in ["Sheet2", "Sheet3"] {
            let mut another = workbook.sheets[0].clone();
            another.name = name.to_string();
            workbook.sheets.push(another);
        }
        let module = parse_module(
            "Public Function Hidden() As String
               Hidden = Worksheets(\"Sheet2\").Visible & \"|\"
               Worksheets(\"Sheet2\").Visible = False
               Hidden = Hidden & Worksheets(\"Sheet2\").Visible & \"|\"
               Worksheets(\"Sheet3\").Visible = xlSheetVeryHidden
               Hidden = Hidden & Worksheets(\"Sheet3\").Visible & \"|\"
               Worksheets(\"Sheet2\").Range(\"A1\").Value = 5
               Hidden = Hidden & Worksheets(\"Sheet2\").Range(\"A1\").Value & \"|\"
               Worksheets(\"Sheet2\").Visible = True
               Hidden = Hidden & Worksheets(\"Sheet2\").Visible
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Hidden", vec![], &mut host).unwrap()
        };
        assert_eq!(result, Value::String("-1|0|2|5|-1".to_string()));

        // The workbook has to show something.
        let mut alone = super::tests::workbook();
        let module = parse_module(
            "Public Sub HideAll()\n  Worksheets(\"Sheet1\").Visible = False\nEnd Sub\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut alone, 0).unwrap();
        let error = execute_with_host(&module, "HideAll", vec![], &mut host)
            .expect_err("a workbook has to show something");
        assert_eq!(error.vba_number, Some(1004));
        assert_eq!(error.vba_source.as_deref(), Some("Microsoft Excel"));
        assert!(host.workbook.sheets[0].visibility.is_shown());
    }

    /// The names a workbook keeps: making them, asking for them, dropping one.
    ///
    /// Every answer was asked of Excel. `RefersTo` is read as a formula, so a
    /// string without a leading `=` is stored as TEXT — `"Sheet1!$A$2"` comes
    /// back as `="Sheet1!$A$2"` and names no cells. A Range hands over its own
    /// address written absolute. The collection is handed out in alphabetical
    /// order, and the case a name was made with is the case it keeps.
    #[test]
    fn vba_keeps_the_names_a_workbook_is_given() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Named() As String
               Range(\"A1\").Value = 100
               Names.Add \"Sales\", \"=Sheet1!$A$1:$A$5\"
               Names.Add Name:=\"Bare\", RefersTo:=\"Sheet1!$A$2\"
               Names.Add \"FromRange\", Range(\"A1:A2\")
               Range(\"A4:A5\").Name = \"Tail\"
               Named = Names(\"Sales\").RefersTo & \"|\" & Names(\"Bare\").RefersTo & \"|\" & _
                 Names(\"FromRange\").RefersTo & \"|\" & Names(\"Tail\").RefersTo & \"|\" & _
                 Names.Count & \"|\" & Names(1).Name & \"|\" & Names(\"sales\").Name & \"|\" & _
                 Range(\"Sales\").Address(False, False) & \"|\" & _
                 Range(\"A4:A5\").Name.Name & \"|\" & _
                 Names(\"Sales\").RefersToRange.Address(False, False)
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Named", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String(
                "=Sheet1!$A$1:$A$5|=\"Sheet1!$A$2\"|=Sheet1!$A$1:$A$2|=Sheet1!$A$4:$A$5|\
                 4|Bare|Sales|A1:A5|Tail|A1:A5"
                    .to_string()
            )
        );
    }

    /// A name can be dropped, and writing one again writes over it.
    #[test]
    fn vba_writes_over_a_name_and_drops_one() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Rework() As String
               Names.Add \"Sales\", \"=Sheet1!$A$1:$A$5\"
               Names.Add \"Spare\", \"=Sheet1!$B$1\"
               Names.Add \"Sales\", \"=Sheet1!$A$1\"
               Names(\"Spare\").Delete
               Rework = Names(\"Sales\").RefersTo & \"|\" & Names.Count
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Rework", vec![], &mut host).unwrap()
        };

        assert_eq!(result, Value::String("=Sheet1!$A$1|1".to_string()));
    }

    /// What Excel refuses to call a name.
    #[test]
    fn vba_refuses_a_name_excel_would_refuse() {
        for (called, why) in [
            ("1Bad", "starts with a letter"),
            ("Two Words", "cannot hold"),
            ("B7", "shaped like a cell reference"),
        ] {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Try()\n  Names.Add \"{called}\", \"=Sheet1!$A$1\"\nEnd Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            let error = execute_with_host(&module, "Try", vec![], &mut host)
                .expect_err("Excel refuses this name")
                .to_string();
            assert!(
                error.contains(why),
                "{called} said {error:?}, which does not mention {why:?}"
            );
        }
        // And one Excel allows.
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Fine() As String
               Names.Add \"_Fine\", \"=Sheet1!$A$1\"
               Fine = Names(\"_Fine\").Name
             End Function\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        let result = execute_with_host(&module, "Fine", vec![], &mut host).unwrap();
        assert_eq!(result, Value::String("_Fine".to_string()));
    }

    /// What a name cannot be asked for, and what it says instead. A bare
    /// `Range` reaches every name in the workbook -- measured, it finds a
    /// name on another sheet -- so it is the worksheet's own `Range` that
    /// keeps to the sheet's names.
    #[test]
    fn vba_says_why_a_name_is_not_a_range() {
        for (call, expected) in [
            ("ActiveSheet.Range(\"Away\")", "answers only for its own names"),
            // A name of several blocks is now that many-block range, as in
            // Excel (r231), so "Scattered" is no longer refused.
            ("Range(\"Number\")", "which worksheet it means"),
            ("Range(\"WholeColumn\")", "not a block of cells"),
            ("Range(\"NoSuchName\")", "no name \"NoSuchName\""),
        ] {
            let mut workbook = named_workbook();
            let module = parse_module(&format!(
                "Public Sub Ask()\n  {call}.Select\nEnd Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            let error = execute_with_host(&module, "Ask", vec![], &mut host)
                .expect_err("the name is not a range")
                .to_string();
            assert!(
                error.contains(expected),
                "{call} said {error:?}, which does not mention {expected:?}"
            );
        }
    }

    /// A cut onto another sheet carries the sheet name with it.
    ///
    /// Asked of Excel, cutting `Sheet1!A2:B3` onto `Sheet2!D2`: the watcher
    /// left on Sheet1 reads `=Sheet2!D2`, a third sheet's `=Sheet1!A2` reads
    /// `=Sheet2!D2`, a watcher of the cell the block landed on reads `#REF!`,
    /// and of the formulas that travelled the one naming a cell that came
    /// along reads `=D2*10` while the one naming a neighbour left behind reads
    /// `=Sheet1!G9`.
    #[test]
    fn vba_cut_onto_another_sheet_says_which_sheet_it_means() {
        let mut workbook = workbook();
        for name in ["Sheet2", "Sheet3"] {
            let mut another = workbook.sheets[0].clone();
            another.name = name.to_string();
            workbook.sheets.push(another);
        }
        let module = parse_module(
            "Public Function Across() As String
               Worksheets(\"Sheet1\").Range(\"A2\").Value = 42
               Worksheets(\"Sheet1\").Range(\"G9\").Value = 7
               Worksheets(\"Sheet1\").Range(\"B2\").Formula = \"=A2*10\"
               Worksheets(\"Sheet1\").Range(\"B3\").Formula = \"=G9\"
               Worksheets(\"Sheet1\").Range(\"F1\").Formula = \"=A2\"
               Worksheets(\"Sheet1\").Range(\"F2\").Formula = \"=SUM(A2:B3)\"
               Worksheets(\"Sheet3\").Range(\"C1\").Formula = \"=Sheet1!A2\"
               Worksheets(\"Sheet2\").Range(\"H2\").Formula = \"=D2\"
               Worksheets(\"Sheet1\").Range(\"A2:B3\").Cut Worksheets(\"Sheet2\").Range(\"D2\")
               Across = Worksheets(\"Sheet2\").Range(\"E2\").Formula & \"|\" & _
                 Worksheets(\"Sheet2\").Range(\"E3\").Formula & \"|\" & _
                 Worksheets(\"Sheet1\").Range(\"F1\").Formula & \"|\" & _
                 Worksheets(\"Sheet1\").Range(\"F2\").Formula & \"|\" & _
                 Worksheets(\"Sheet3\").Range(\"C1\").Formula & \"|\" & _
                 Worksheets(\"Sheet2\").Range(\"H2\").Formula & \"|\" & _
                 Worksheets(\"Sheet2\").Range(\"D2\").Value
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Across", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String(
                "=D2*10|=Sheet1!G9|=Sheet2!D2|=SUM(Sheet2!D2:E3)|=Sheet2!D2|=#REF!|42".to_string()
            )
        );
    }

    /// Asked of Excel from VBA itself: the bar answers `False` until a macro
    /// writes to it, holds whatever string it is given, and is handed back by
    /// an empty string, `Empty` or `Null` — but NOT by `False`, which writes
    /// the word FALSE across it.
    #[test]
    fn vba_writes_across_the_status_bar_and_hands_it_back() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Report()
               Debug.Print Application.StatusBar
               Application.StatusBar = \"Working\"
               Debug.Print Application.StatusBar
               Application.StatusBar = \"\"
               Debug.Print Application.StatusBar
               Application.StatusBar = \"Working\"
               Application.StatusBar = Empty
               Debug.Print Application.StatusBar
               Application.StatusBar = \"Working\"
               Application.StatusBar = Null
               Debug.Print Application.StatusBar
             End Sub\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        execute_with_host(&module, "Report", vec![], &mut host).unwrap();

        assert_eq!(host.status_bar, None);
        assert_eq!(
            host.take_debug_output(),
            vec![
                "False".to_string(),
                "Working".to_string(),
                "False".to_string(),
                "False".to_string(),
                "False".to_string(),
            ]
        );
    }

    /// The trap every guide walks into. `Application.StatusBar = False` is the
    /// documented way to restore the default bar, and Excel 16 does not
    /// restore it — it shows the word FALSE, and leaves it showing.
    #[test]
    fn vba_status_bar_false_writes_the_word_rather_than_giving_the_bar_back() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Report()
               Application.StatusBar = \"Working\"
               Application.StatusBar = False
               Debug.Print Application.StatusBar
               Application.StatusBar = True
               Debug.Print Application.StatusBar
             End Sub\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        execute_with_host(&module, "Report", vec![], &mut host).unwrap();

        assert_eq!(host.status_bar.as_deref(), Some("TRUE"));
        assert_eq!(
            host.take_debug_output(),
            vec!["FALSE".to_string(), "TRUE".to_string()]
        );
    }

    /// A number reaches the bar written the way Excel writes one as text:
    /// fifteen significant digits, plainly if that fits twenty characters and
    /// in exponent form when it does not.
    #[test]
    fn vba_status_bar_shows_a_number_the_way_excel_writes_one() {
        let measured = [
            ("0", "0"),
            ("42", "42"),
            ("-0.5", "-0.5"),
            ("3.5", "3.5"),
            ("100000", "100000"),
            ("1 / 3", "0.333333333333333"),
            ("2 / 3", "0.666666666666667"),
            ("0.1 + 0.2", "0.3"),
            ("1E+15", "1000000000000000"),
            ("1E+16", "10000000000000000"),
            ("0.0000001", "0.0000001"),
            // Twenty characters fit; the twenty-first sends it to an exponent.
            ("1E+19", "10000000000000000000"),
            ("1E+20", "1E+20"),
            ("1.5E+20", "1.5E+20"),
            ("1E-18", "0.000000000000000001"),
            ("1E-19", "1E-19"),
            ("-1.5E-20", "-1.5E-20"),
            ("1E+100", "1E+100"),
            ("1234567890123456", "1234567890123460"),
            ("1.23456789012345678E+20", "1.23456789012346E+20"),
            // The widest Double there is gives up a significant digit to fit.
            ("1.7976931348623157E+308", "1.7976931348623E+308"),
        ];
        for (number, shown) in measured {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Report()
  Application.StatusBar = {number}
End Sub
"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Report", vec![], &mut host).unwrap();
            assert_eq!(host.status_bar.as_deref(), Some(shown), "for {number}");
        }
    }

    /// `Range.Formula` asks the same question and gets the same answer, but it
    /// is allowed one character more than the bar — so `1E+20` writes out in
    /// full here and does not there. Measured at both entrances; the two
    /// differ ONLY in that width.
    #[test]
    fn vba_writes_a_number_into_a_formula_the_way_excel_does() {
        let measured = [
            ("0", "0"),
            ("42", "42"),
            ("-0.5", "-0.5"),
            ("123.456", "123.456"),
            ("100.5", "100.5"),
            ("1E-5", "0.00001"),
            ("1 / 3", "0.333333333333333"),
            ("2 / 3", "0.666666666666667"),
            ("0.1 + 0.2", "0.3"),
            ("0.000123456789012345678", "0.000123456789012346"),
            ("1234567890123456", "1234567890123460"),
            ("9.99999999999999E+19", "99999999999999900000"),
            // Twenty-one characters fit, where the bar stops at twenty.
            ("1E+19", "10000000000000000000"),
            ("1E+20", "100000000000000000000"),
            ("1.5E+20", "150000000000000000000"),
            ("-1.5E+20", "-150000000000000000000"),
            ("1E+21", "1E+21"),
            ("1E-18", "0.000000000000000001"),
            ("1E-19", "0.0000000000000000001"),
            ("1E-20", "1E-20"),
            ("-1.5E-20", "-1.5E-20"),
            ("1E+100", "1E+100"),
            ("1.7976931348623157E+308", "1.79769313486232E+308"),
        ];
        for (number, written) in measured {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()
                   Range(\"A1\").Value = {number}
                   Debug.Print Range(\"A1\").Formula
                 End Sub
"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            assert_eq!(
                host.take_debug_output(),
                vec![written.to_string()],
                "for {number}"
            );
        }
    }

    /// 255 characters fit and a 256th is refused, counted in characters rather
    /// than bytes — so 255 kana fit as well. What was already on the bar stays.
    #[test]
    fn vba_status_bar_holds_255_characters() {
        for filler in ['z', '\u{3042}'] {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Report()
                   Application.StatusBar = \"{}\"
                   Debug.Print Len(Application.StatusBar)
                   Application.StatusBar = \"{}\"
                 End Sub\n",
                filler.to_string().repeat(255),
                filler.to_string().repeat(256),
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Report", vec![], &mut host)
                .expect_err("a 256th character is refused");
            assert_eq!(
                host.status_bar.as_deref(),
                Some(filler.to_string().repeat(255).as_str())
            );
            assert_eq!(host.take_debug_output(), vec!["255".to_string()]);
        }
    }

    /// Only text goes on the bar. An `Error` variant is refused and what was
    /// there stays.
    #[test]
    fn vba_status_bar_refuses_an_error_value() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Report()
               Application.StatusBar = \"Working\"
               Application.StatusBar = CVErr(2042)
             End Sub\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        execute_with_host(&module, "Report", vec![], &mut host)
            .expect_err("an Error variant cannot be shown");
        assert_eq!(host.status_bar.as_deref(), Some("Working"));
    }

    /// The switches a macro flips take more than a Boolean. Measured by
    /// assigning to `Application.ScreenUpdating` from VBA: a number is False
    /// only at zero, `Empty` is False, a string that looks like a number is
    /// read as one, and otherwise it has to be the word itself.
    #[test]
    fn vba_application_switches_take_what_excel_takes() {
        let measured = [
            ("False", "False"),
            ("0", "False"),
            ("\"0\"", "False"),
            ("\"1\"", "True"),
            ("\"-1\"", "True"),
            ("\"2.5\"", "True"),
            ("\" -1 \"", "True"),
            ("0.4", "True"),
            ("-0.4", "True"),
            ("Empty", "False"),
            ("\"false\"", "False"),
            ("\"TRUE\"", "True"),
            ("\"#FALSE#\"", "False"),
        ];
        for (asked, shown) in measured {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()
                   Application.ScreenUpdating = {asked}
                   Debug.Print Application.ScreenUpdating
                 End Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            assert_eq!(
                host.take_debug_output(),
                vec![shown.to_string()],
                "for {asked}"
            );
        }
    }

    /// What they do not take. A word with a space beside it is a type
    /// mismatch even though a number with a space beside it is not, and `Null`
    /// is refused outright — where a cell's own `Font.Bold` takes `Null` and
    /// refuses `"0"`, which is why the two do not share a rule.
    #[test]
    fn vba_application_switches_refuse_what_excel_refuses() {
        for asked in ["\" False \"", "\"False \"", "\"no\"", "\"\"", "Null"] {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()\n  Application.DisplayAlerts = {asked}\nEnd Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            let refused = execute_with_host(&module, "Act", vec![], &mut host);
            assert!(refused.is_err(), "{asked} is refused");
            assert!(host.display_alerts, "for {asked}");
        }
    }

    /// The hourglass a long macro puts up and the arrow it puts back. Asked of
    /// Excel: it starts at `xlDefault`, takes the four pointers and 0, and 0
    /// answers as `xlDefault`.
    #[test]
    fn vba_puts_up_a_pointer_while_it_works() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Act()
               Debug.Print Application.Cursor
               Application.Cursor = xlWait
               Debug.Print Application.Cursor
               Application.Cursor = xlIBeam
               Debug.Print Application.Cursor
               Application.Cursor = xlNorthwestArrow
               Debug.Print Application.Cursor
               Application.Cursor = 0
               Debug.Print Application.Cursor
               Application.Cursor = xlWait
               Application.Cursor = xlDefault
               Debug.Print Application.Cursor
             End Sub\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        execute_with_host(&module, "Act", vec![], &mut host).unwrap();

        assert_eq!(host.cursor, -4143);
        assert_eq!(
            host.take_debug_output(),
            vec![
                "-4143".to_string(),
                "2".to_string(),
                "3".to_string(),
                "1".to_string(),
                "-4143".to_string(),
                "-4143".to_string(),
            ]
        );
    }

    /// What it is given is made whole VBA's way, with half going to the even
    /// side — which is why 2.5 gives 2 and 3.5 is refused for rounding to 4.
    #[test]
    fn vba_rounds_a_pointer_to_the_even_side() {
        let taken = [
            ("0.5", -4143),
            ("1.5", 2),
            ("2.4", 2),
            ("2.5", 2),
            ("2.7", 3),
            ("3.4", 3),
            ("-0.4", -4143),
            ("-4143.4", -4143),
            ("False", -4143),
            ("Empty", -4143),
            ("\" 3 \"", 3),
            ("\"+3\"", 3),
            ("\"0003\"", 3),
            ("\"-4143\"", -4143),
        ];
        for (asked, pointer) in taken {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()\n  Application.Cursor = {asked}\nEnd Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            assert_eq!(host.cursor, pointer, "for {asked}");
        }

        for asked in [
            "4", "5", "-1", "7", "-4142", "True", "3.5", "\"3.7\"", "\"xlIBeam\"", "\"\"", "Null",
        ] {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()
                   Application.Cursor = xlWait
                   Application.Cursor = {asked}
                 End Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            let refused = execute_with_host(&module, "Act", vec![], &mut host);
            assert!(refused.is_err(), "{asked} is refused");
            assert_eq!(host.cursor, 2, "for {asked}");
        }
    }

    /// `Interactive` is one of the switches, and answers like the others.
    #[test]
    fn vba_shuts_the_sheet_off_from_the_keyboard() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Act()
               Debug.Print Application.Interactive
               Application.Interactive = False
               Debug.Print Application.Interactive
               Application.Interactive = \"TRUE\"
               Debug.Print Application.Interactive
             End Sub\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        execute_with_host(&module, "Act", vec![], &mut host).unwrap();

        assert!(host.interactive);
        assert_eq!(
            host.take_debug_output(),
            vec!["True".to_string(), "False".to_string(), "True".to_string()]
        );
    }

    /// `Cells(n)` counts across the sheet by rows, 16384 to a row — the same
    /// walk `Range(...).Cells(n)` does across a block, so it is the same code.
    /// Asked of Excel: 16384 is XFD1, 16385 is A2, 17179869184 is the last
    /// cell there is, and one past it raises.
    #[test]
    fn vba_counts_cells_across_the_sheet_from_one_index() {
        let measured = [
            ("Cells(1)", "$A$1"),
            ("Cells(2)", "$B$1"),
            ("Cells(16384)", "$XFD$1"),
            ("Cells(16385)", "$A$2"),
            ("Cells(16386)", "$B$2"),
            ("Cells(2147483647#)", "$XFC$131072"),
            ("Cells(17179869184#)", "$XFD$1048576"),
            // Half goes to the even side, and a number written as text is read.
            ("Cells(1.5)", "$B$1"),
            ("Cells(2.5)", "$B$1"),
            ("Cells(\"3\")", "$C$1"),
        ];
        for (asked, address) in measured {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()\n  Debug.Print {asked}.Address\nEnd Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            assert_eq!(
                host.take_debug_output(),
                vec![address.to_string()],
                "for {asked}"
            );
        }

        for asked in ["Cells(0)", "Cells(-1)", "Cells(17179869185#)"] {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()\n  Debug.Print {asked}.Address\nEnd Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            let refused = execute_with_host(&module, "Act", vec![], &mut host);
            assert!(refused.is_err(), "{asked} is refused");
        }
    }

    /// The same index over a block. 0 is the cell BEFORE the first, which
    /// walks back into the column before, and one below the block keeps going.
    #[test]
    fn vba_counts_cells_across_a_block_from_one_index() {
        let measured = [
            ("Range(\"B2:D4\").Cells(2)", "$C$2"),
            ("Range(\"B2:D4\").Cells(4)", "$B$3"),
            ("Range(\"B2:D4\").Cells(10)", "$B$5"),
            ("Range(\"B2:D4\").Cells(0)", "$A$2"),
            ("Range(\"B2:D4\").Cells(1.5)", "$C$2"),
            ("Range(\"B2:D4\").Cells(2.5)", "$C$2"),
            ("Range(\"B2:D4\").Cells(3.5)", "$B$3"),
            ("Range(\"B2:D4\").Cells(\"3\")", "$D$2"),
        ];
        for (asked, address) in measured {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()\n  Debug.Print {asked}.Address\nEnd Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            assert_eq!(
                host.take_debug_output(),
                vec![address.to_string()],
                "for {asked}"
            );
        }

        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Act()\n  Debug.Print Range(\"B2:D4\").Cells(-1).Address\nEnd Sub\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        let refused = execute_with_host(&module, "Act", vec![], &mut host);
        assert!(refused.is_err(), "the cell before A2 is off the sheet");
    }

    /// A formula answers as soon as it is asked, not only once the macro is
    /// over. Measured in Excel with A1=10, A2="text", A3="" and A4 given
    /// `=A1*2`: A4 reads 20 straight away, and the functions that walk A1:A4
    /// see it — Sum 30, Count 2, CountA 3.
    #[test]
    fn vba_reads_a_formula_it_has_only_just_written() {
        let mut book = workbook();
        let module = parse_module(
            "Public Sub Act()
               Range(\"A1\").Value = 10
               Range(\"A2\").Value = \"text\"
               Range(\"A3\").Value = \"\"
               Range(\"A4\").Formula = \"=A1*2\"
               Debug.Print Application.WorksheetFunction.Sum(Range(\"A1:A4\"))
               Debug.Print Range(\"A4\").Value
               Debug.Print Range(\"A4\").Text
             End Sub\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut book, 0).unwrap();
        execute_with_host(&module, "Act", vec![], &mut host).unwrap();

        // The aggregation is asked FIRST, before any read has had a chance to
        // settle the book — otherwise it would pass whether it settles or not.
        assert_eq!(
            host.take_debug_output(),
            vec!["30".to_string(), "20".to_string(), "20".to_string()]
        );

        // And the counts, each on its own run for the same reason.
        for (asked, answer) in [
            ("Count(Range(\"A1:A4\"))", "2"),
            ("CountA(Range(\"A1:A4\"))", "3"),
        ] {
            let mut fresh = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()
                   Range(\"A1\").Value = 10
                   Range(\"A2\").Value = \"text\"
                   Range(\"A3\").Value = \"\"
                   Range(\"A4\").Formula = \"=A1*2\"
                   Debug.Print Application.WorksheetFunction.{asked}
                 End Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut fresh, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            assert_eq!(
                host.take_debug_output(),
                vec![answer.to_string()],
                "for {asked}"
            );
        }
    }

    /// With calculation off a formula is worked out as it is written and then
    /// left -- measured, `=B1*100` reads 100 on entry and still 100 once B1
    /// changes -- and turning calculation back on works it out again.
    #[test]
    fn vba_settles_only_what_it_has_to() {
        let mut first = workbook();
        let module = parse_module(
            "Public Sub Act()
               Application.Calculation = xlCalculationManual
               Range(\"A1\").Value = 10
               Range(\"A2\").Formula = \"=A1*2\"
               Debug.Print \"[\" & Range(\"A2\").Value & \"]\"
               Application.Calculation = xlCalculationAutomatic
               Debug.Print Range(\"A2\").Value
             End Sub\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut first, 0).unwrap();
        execute_with_host(&module, "Act", vec![], &mut host).unwrap();

        assert_eq!(
            host.take_debug_output(),
            vec!["[20]".to_string(), "20".to_string()]
        );

        // Reading a plain cell also preserves the formula result already
        // calculated by the preceding automatic assignment.
        let mut second = workbook();
        let module = parse_module(
            "Public Sub Act()
               Range(\"A1\").Value = 10
               Range(\"A2\").Formula = \"=A1*2\"
               Debug.Print Range(\"A1\").Value
             End Sub\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut second, 0).unwrap();
        execute_with_host(&module, "Act", vec![], &mut host).unwrap();
        assert_eq!(host.take_debug_output(), vec!["10".to_string()]);
        assert!(matches!(host.cell_here(0, 2, 0).unwrap().value, CellValue::Number(20.0)));
    }

    /// `Count` follows the axis the range was asked for by.
    ///
    /// Asked of Excel: `Rows(1).Count` is 1 — one row — where the same cells
    /// written as `Range("1:1")` count 16384. The sense belongs to how the
    /// range was obtained, not to the cells it covers.
    #[test]
    fn vba_counts_along_the_axis_a_range_was_asked_for_by() {
        let measured = [
            ("Rows(1).Count", "1"),
            ("Rows(1).Address", "$1:$1"),
            ("Rows(\"1:3\").Count", "3"),
            ("Columns(1).Count", "1"),
            ("Columns(\"A:C\").Count", "3"),
            // A plain range of the very same cells still counts cells.
            ("Range(\"1:1\").Count", "16384"),
            ("Range(\"A:A\").Count", "1048576"),
            ("Range(\"A1:C3\").Count", "9"),
            // Asking again through an axis re-reads it that way.
            ("Rows(1).Rows.Count", "1"),
            ("Rows(1).Columns.Count", "16384"),
            ("Range(\"1:1\").Rows.Count", "1"),
            ("Range(\"A1:C3\").Rows.Count", "3"),
            ("Range(\"A1:C3\").Columns.Count", "3"),
            ("Range(\"A1:C3\").Rows(1).Count", "1"),
            ("Range(\"A1:C3\").Rows(1).Address", "$A$1:$C$1"),
            ("Range(\"A1:C3\").Rows(2).Address", "$A$2:$C$2"),
            ("Range(\"A1:C3\").Columns(1).Count", "1"),
            ("Range(\"A1:C3\").Rows.Address", "$A$1:$C$3"),
            // Item walks the axis too.
            ("Rows(\"1:3\").Item(2).Address", "$2:$2"),
            ("Rows(\"1:3\").Item(2).Count", "1"),
            ("Columns(\"A:C\").Item(2).Address", "$B:$B"),
            // And a sensed range answers everything else like any other.
            ("Rows(2).Row", "2"),
            ("Rows(2).Column", "1"),
            ("Columns(3).Column", "3"),
            ("Rows(1).Cells(3).Address", "$C$1"),
        ];
        for (asked, answer) in measured {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()\n  Debug.Print {asked}\nEnd Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            assert_eq!(
                host.take_debug_output(),
                vec![answer.to_string()],
                "for {asked}"
            );
        }
    }

    /// Which operations carry the sense and which drop it.
    ///
    /// `Offset` and `Resize` carry it; `EntireRow` and `EntireColumn` SET it,
    /// even on a range that had none; `Cells` and `Union` drop it.
    #[test]
    fn vba_carries_the_axis_sense_through_some_operations_and_not_others() {
        let measured = [
            ("Rows(1).Offset(1, 0).Address", "$2:$2"),
            ("Rows(1).Offset(1, 0).Count", "1"),
            ("Columns(1).Offset(0, 1).Count", "1"),
            ("Rows(1).Resize(2).Count", "2"),
            // Set, not passed along: a plain range gets a sense from these.
            ("Range(\"A1\").EntireRow.Count", "1"),
            ("Range(\"A1:C3\").EntireRow.Count", "3"),
            ("Range(\"A1:C3\").EntireRow.Address", "$1:$3"),
            ("Range(\"A1\").EntireColumn.Count", "1"),
            ("Range(\"A1:C3\").EntireColumn.Count", "3"),
            ("Range(\"A1:C3\").EntireColumn.Address", "$A:$C"),
            ("Rows(1).EntireRow.Count", "1"),
            ("Rows(1).EntireColumn.Count", "16384"),
            ("Columns(1).EntireRow.Count", "1048576"),
            // Dropped: back to counting cells.
            ("Rows(1).Cells.Count", "16384"),
            ("Application.Union(Rows(1), Rows(3)).Count", "32768"),
        ];
        for (asked, answer) in measured {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()\n  Debug.Print {asked}\nEnd Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            assert_eq!(
                host.take_debug_output(),
                vec![answer.to_string()],
                "for {asked}"
            );
        }
    }

    /// A written error word IS that error, and the cell says so however it is
    /// asked. Measured in Excel at three entrances — `.Formula`, `.Text` and
    /// a `Find` — which is why one helper may carry the answer.
    #[test]
    fn vba_writes_an_error_word_into_a_cell_as_an_error() {
        let measured = [
            ("#N/A", "2042", "#N/A"),
            ("#VALUE!", "2015", "#VALUE!"),
            ("#REF!", "2023", "#REF!"),
            ("#DIV/0!", "2007", "#DIV/0!"),
            ("#NAME?", "2029", "#NAME?"),
            ("#NULL!", "2000", "#NULL!"),
            ("#NUM!", "2036", "#NUM!"),
            ("#GETTING_DATA", "2043", "########"),
        ];
        for (word, number, text) in measured {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()
                   Range(\"A1\").Value = \"{word}\"
                   Debug.Print TypeName(Range(\"A1\").Value)
                   Debug.Print CLng(Range(\"A1\").Value)
                   Debug.Print Range(\"A1\").Formula
                   Debug.Print Range(\"A1\").Text
                 End Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            assert_eq!(
                host.take_debug_output(),
                vec![
                    "Error".to_string(),
                    number.to_string(),
                    word.to_string(),
                    text.to_string(),
                ],
                "for {word}"
            );
        }
    }

    /// The word is read in any case and with nothing around it, and no other
    /// word beginning with a hash is read at all — `#SPILL!` included, though
    /// a sheet can work that one out for itself.
    #[test]
    fn vba_reads_an_error_word_exactly_or_not_at_all() {
        let measured = [
            ("\"#n/a\"", "Error", "#N/A"),
            ("\"#N/a\"", "Error", "#N/A"),
            ("\" #N/A\"", "String", " #N/A"),
            ("\"#N/A \"", "String", "#N/A "),
            ("\"#NOPE!\"", "String", "#NOPE!"),
            ("\"#SPILL!\"", "String", "#SPILL!"),
            ("\"#\"", "String", "#"),
            // An apostrophe still means "leave this alone".
            ("\"'#N/A\"", "String", "#N/A"),
        ];
        for (written, kind, formula) in measured {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()
                   Range(\"A1\").Value = {written}
                   Debug.Print TypeName(Range(\"A1\").Value)
                   Debug.Print Range(\"A1\").Formula
                 End Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            assert_eq!(
                host.take_debug_output(),
                vec![kind.to_string(), formula.to_string()],
                "for {written}"
            );
        }
    }

    /// `CVErr` puts the same thing in the cell as the word does, and a search
    /// reads the word — `Find("N/A")` lands on a cell holding `#N/A`.
    #[test]
    fn vba_finds_a_cell_by_the_error_it_holds() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Act()
               Range(\"A1\").Value = CVErr(2042)
               Range(\"A2\").Value = \"#DIV/0!\"
               Debug.Print Range(\"A1\").Formula
               Debug.Print Range(\"A1:A2\").Find(\"N/A\").Address
               Debug.Print Range(\"A1:A2\").Find(\"#DIV/0!\").Address
               Debug.Print Application.WorksheetFunction.CountA(Range(\"A1:A2\"))
             End Sub\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        execute_with_host(&module, "Act", vec![], &mut host).unwrap();

        assert_eq!(
            host.take_debug_output(),
            vec![
                "#N/A".to_string(),
                "$A$1".to_string(),
                "$A$2".to_string(),
                "2".to_string(),
            ]
        );
    }

    /// Some ways of writing a number carry a way of showing it. Measured in
    /// Excel by writing each into a fresh cell and reading `.Value` and
    /// `.NumberFormat` back.
    #[test]
    fn vba_reads_a_written_number_the_way_it_was_written() {
        let measured = [
            // per cent: a point in the writing asks for two decimals, however
            // many were actually written.
            ("50%", "0.5", "0%"),
            ("100%", "1", "0%"),
            ("-50%", "-0.5", "0%"),
            ("12%", "0.12", "0%"),
            ("50 %", "0.5", "0%"),
            ("%5", "0.05", "0%"),
            ("5.5%", "0.055", "0.00%"),
            ("0.5%", "0.005", "0.00%"),
            ("1.25%", "0.0125", "0.00%"),
            ("1.2%", "0.012", "0.00%"),
            ("1.23456%", "0.0123456", "0.00%"),
            // an exponent, whatever its mantissa
            ("1E3", "1000", "0.00E+00"),
            ("1e3", "1000", "0.00E+00"),
            ("1.5E3", "1500", "0.00E+00"),
            ("1.23E-4", "0.000123", "0.00E+00"),
            ("1.23456789E3", "1234.56789", "0.00E+00"),
            // a fraction, its width following the denominator
            ("1 1/2", "1.5", "# ?/?"),
            ("1 3/8", "1.375", "# ?/?"),
            ("0 1/2", "0.5", "# ?/?"),
            ("1 10/8", "2.25", "# ?/?"),
            ("-1 1/2", "-1.5", "# ?/?"),
            ("1 1/16", "1.0625", "# ??/??"),
            ("1 1/100", "1.01", "# ??/??"),
            ("1 1/1000", "1.001", "# ??/??"),
            ("1 11/100", "1.11", "# ??/??"),
        ];
        for (written, value, shown) in measured {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()
                   Range(\"A1\").Value = \"{written}\"
                   Debug.Print CStr(Range(\"A1\").Value)
                   Debug.Print Range(\"A1\").NumberFormat
                 End Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            assert_eq!(
                host.take_debug_output(),
                vec![value.to_string(), shown.to_string()],
                "for {written}"
            );
        }
    }

    /// What a written date, time or sum of money becomes. Every line is what
    /// Excel answered for `TypeName`, `Value2` and `NumberFormat` after the
    /// text was assigned, on a machine whose Windows reads dates
    /// month-day-year, whose currency is the dollar, and whose Office is
    /// Japanese; the year-less forms are read against a fixed 2026.
    #[test]
    fn vba_reads_a_written_date_time_or_sum_the_way_excel_does() {
        let measured = [
            ("2024/1/5", "Date", "45296", "m/d/yyyy"),
            ("1/5/2024", "Date", "45296", "m/d/yyyy"),
            ("1/5", "Date", "46027", "d-mmm"),
            ("2024-01-05", "Date", "45296", "m/d/yyyy"),
            ("1-5", "Date", "46027", "d-mmm"),
            ("5-Jan", "Date", "46027", "d-mmm"),
            ("5-Jan-24", "Date", "45296", "d-mmm-yy"),
            ("January 5, 2024", "Date", "45296", "d-mmm-yy"),
            ("13:30", "Double", "0.5625", "h:mm"),
            ("1:30 PM", "Double", "0.5625", "h:mm AM/PM"),
            ("1:30:15", "Double", "6.26736111111111E-02", "h:mm:ss"),
            ("1/5/2024 13:30", "Date", "45296.5625", "m/d/yyyy h:mm"),
            ("2024/1/5 1:30 PM", "Date", "45296.5625", "m/d/yyyy h:mm"),
            ("5/13/2024", "Date", "45425", "m/d/yyyy"),
            ("3/4", "Date", "46085", "d-mmm"),
            ("1/5/24", "Date", "45296", "m/d/yyyy"),
            ("1/5/2024 25:00", "Double", "45297.0416666667", "General"),
            ("24:00", "Double", "1", "[h]:mm:ss"),
            ("0:00", "Double", "0", "h:mm"),
            ("2/29/2024", "Date", "45351", "m/d/yyyy"),
            ("Feb 30", "Date", "10990", "mmm-yy"),
            ("$3", "Currency", "3", "$#,##0_);[Red]($#,##0)"),
            ("$1,234.5", "Currency", "1234.5", "$#,##0.00_);[Red]($#,##0.00)"),
            ("-$3", "Currency", "-3", "$#,##0_);[Red]($#,##0)"),
            ("$-3", "Currency", "-3", "$#,##0_);[Red]($#,##0)"),
            ("($3)", "Currency", "-3", "$#,##0_);[Red]($#,##0)"),
        ];
        for (written, kind, value, shown) in measured {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()
                   Range(\"A1\").Value = \"{written}\"
                   Debug.Print TypeName(Range(\"A1\").Value)
                   Debug.Print CStr(Range(\"A1\").Value2)
                   Debug.Print Range(\"A1\").NumberFormat
                 End Sub
"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            // The fifth of January 2026.
            host.now = Some(46027.5);
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            assert_eq!(
                host.take_debug_output(),
                vec![kind.to_string(), value.to_string(), shown.to_string()],
                "for {written}"
            );
        }
    }

    /// And what stays text. A fraction wants a whole part and ONE space; an
