    /// `Debug.Print` writes a number the way VBA writes one, which is the way
    /// `CStr` and `&` write it and the way the `Print` statement writes it 遯�E�繝ｻ    /// measured at all three. It leaves IEEE's own spelling behind: a third of
    /// seventy is `23.3333333333333` here as it is in Excel, not
    /// `23.333333333333332`.
    ///
    /// What is deliberately NOT copied is Print's spacing. Excel writes
    /// ` 42 ` — a space in front of a positive number and one after every
    /// number — because that is how the Immediate window lays its fields out.
    /// This log joins with tabs and has its own.
    #[test]
    fn vba_prints_a_number_the_way_vba_writes_one() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Act()
               Debug.Print 0.1 + 0.2
               Debug.Print 1# / 3#
               Debug.Print 1.23456 / 100
               Debug.Print 70# / 3#
               Debug.Print CDbl(1E15)
               Debug.Print CDbl(1E-16)
               Debug.Print 42
               Debug.Print -5
             End Sub\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        execute_with_host(&module, "Act", vec![], &mut host).unwrap();

        assert_eq!(
            host.take_debug_output(),
            vec![
                "0.3".to_string(),
                "0.333333333333333".to_string(),
                "0.0123456".to_string(),
                "23.3333333333333".to_string(),
                "1E+15".to_string(),
                "1E-16".to_string(),
                "42".to_string(),
                "-5".to_string(),
            ]
        );
    }

    /// Some functions step over an error in the cells and some pass it on.
    ///
    /// Asked of Excel over 10, text, a blank, 20 and `#N/A`: the counting ones
    /// answer — Count 2, CountA 4, CountBlank 1, CountIf 1, SumIf 10 — and the
    /// adding ones raise, which is `WorksheetFunction` saying what a sheet
    /// would have shown. A sheet agrees: `=COUNT` shows 2 where `=SUM` shows
    /// `#N/A`.
    #[test]
    fn vba_steps_over_an_error_where_excel_steps_over_one() {
        let setup = "Range(\"A1\").Value = 10
               Range(\"A2\").Value = \"text\"
               Range(\"A4\").Value = 20
               Range(\"A5\").Value = \"#N/A\"";

        for (asked, answer) in [
            ("Count(Range(\"A1:A5\"))", "2"),
            ("CountA(Range(\"A1:A5\"))", "4"),
            ("CountBlank(Range(\"A1:A5\"))", "1"),
            ("CountIf(Range(\"A1:A5\"), 10)", "1"),
            ("SumIf(Range(\"A1:A5\"), 10)", "10"),
        ] {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()\n  {setup}\n  \
                 Debug.Print Application.WorksheetFunction.{asked}\nEnd Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            assert_eq!(
                host.take_debug_output(),
                vec![answer.to_string()],
                "for {asked}"
            );
        }

        for asked in ["Sum", "Average", "Min", "Max"] {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()\n  {setup}\n  \
                 Debug.Print Application.WorksheetFunction.{asked}(Range(\"A1:A5\"))\nEnd Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            let refused = execute_with_host(&module, "Act", vec![], &mut host);
            assert!(refused.is_err(), "{asked} passes the error on");
        }
    }

    /// The faces a cell wears take what Excel takes there, which is not what
    /// the application's switches take: `"0"` is a number to a switch and a
    /// refusal to a face.
    #[test]
    fn vba_style_faces_take_what_excel_takes_there() {
        let measured = [
            ("True", "True"),
            ("0", "False"),
            ("5", "True"),
            ("0.4", "True"),
            ("Empty", "False"),
            ("\"true\"", "True"),
            ("\"TRUE\"", "True"),
            ("\"false\"", "False"),
        ];
        for (asked, answer) in measured {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()
                   Range(\"A1\").Font.Bold = False
                   Range(\"A1\").Font.Bold = {asked}
                   Debug.Print Range(\"A1\").Font.Bold
                 End Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            assert_eq!(
                host.take_debug_output(),
                vec![answer.to_string()],
                "for {asked}"
            );
        }

        for asked in ["\"0\"", "\"1\"", "\"no\"", "\"\"", "\" true \"", "\"#FALSE#\""] {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()\n  Range(\"A1\").Font.Bold = {asked}\nEnd Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            let refused = execute_with_host(&module, "Act", vec![], &mut host);
            assert!(refused.is_err(), "{asked} is refused");
        }
    }

    /// 隨倥・`Null` leaves a face alone. A bold cell given `Null` stays bold, and
    /// a range whose cells disagree keeps its disagreement — which is the one
    /// place reading `.Bold` answers `Null` in the first place.
    #[test]
    fn vba_a_null_leaves_a_style_face_as_it_was() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Act()
               Range(\"A1\").Font.Bold = True
               Range(\"A1\").Font.Bold = Null
               Debug.Print Range(\"A1\").Font.Bold
               Range(\"A2\").Font.Italic = True
               Range(\"A2\").Font.Italic = Null
               Debug.Print Range(\"A2\").Font.Italic
               Range(\"B1\").Font.Bold = True
               Range(\"B2\").Font.Bold = False
               Debug.Print TypeName(Range(\"B1:B2\").Font.Bold)
               Range(\"B1:B2\").Font.Bold = Null
               Debug.Print Range(\"B1\").Font.Bold
               Debug.Print Range(\"B2\").Font.Bold
               Range(\"B1:B2\").Font.Bold = Empty
               Debug.Print Range(\"B1\").Font.Bold
             End Sub\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        execute_with_host(&module, "Act", vec![], &mut host).unwrap();

        assert_eq!(
            host.take_debug_output(),
            vec![
                "True".to_string(),
                "True".to_string(),
                "Null".to_string(),
                "True".to_string(),
                "False".to_string(),
                "False".to_string(),
            ]
        );
    }

    /// And the one that looks like a face and is not: a hidden row given
