    #[test]
    fn vba_border_tint_rejects_values_outside_excel_range() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Ask() As String
               Dim out As String
               On Error Resume Next
               Range(\"A1\").Borders(9).TintAndShade = -1.0001
               out = CStr(Err.Number) & \"|\"
               Err.Clear
               Range(\"A2\").Borders(9).TintAndShade = 1.0001
               out = out & CStr(Err.Number) & \"|\"
               Err.Clear
               Application.FindFormat.Borders(9).TintAndShade = -1.0001
               out = out & CStr(Err.Number) & \"|\"
               Err.Clear
               Application.FindFormat.Clear
               Application.FindFormat.Borders(9).TintAndShade = 1.0001
               out = out & CStr(Err.Number) & \"|\"
               Err.Clear
               Application.FindFormat.Clear
               Application.ReplaceFormat.Borders(9).TintAndShade = -1.0001
               out = out & CStr(Err.Number) & \"|\"
               Err.Clear
               Application.ReplaceFormat.Clear
               Application.ReplaceFormat.Borders(9).TintAndShade = 1.0001
               out = out & CStr(Err.Number)
               Ask = out
             End Function
",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Ask", vec![], &mut host).unwrap()
        };
        assert_eq!(result, Value::String("5|5|5|5|5|5".into()));
    }

