    #[test]
    fn new_class_and_standard_module_source_roundtrip() {
        let template = include_bytes!("../../../tests/fixtures/vba/namespace_lifetime.xlsm");
        let mut archive = oxidocs_common::archive::OoxmlArchive::new(template).unwrap();
        let original = archive.read_binary_part("xl/vbaProject.bin").unwrap();
        let source = r#"Attribute VB_Name = "SaveProbe"
Option Explicit
Public Function Control() As Long
 Control = 1
End Function
VERSION 1.0 CLASS
Attribute VB_Name = "Widget"
Public marker As Long
Attribute VB_Name = "ExtraModule"
Public Function Other() As Long
 Other = 2
End Function
"#;
        let changed = crate::vba_source_writer::update_project(&original, source, Some(932)).unwrap();
        let project = ovba::open_project(changed.clone()).unwrap();
        let identities = crate::vba_module_directory::identities(&project, Some(932)).unwrap();
        assert_eq!(identities.len(), 5);
        let class = identities.iter().position(|name| name.name == "Widget").unwrap();
        let standard = identities.iter().position(|name| name.name == "ExtraModule").unwrap();
        assert!(matches!(project.modules[class].module_type, ovba::ModuleType::DocClsDesigner));
        assert!(matches!(project.modules[standard].module_type, ovba::ModuleType::Procedural));
        let body = crate::vba_module_directory::module_source(&project, &project.modules[class], &identities[class], Some(932)).unwrap();
        for attribute in [
            r#"Attribute VB_Base = "0{FCFB3D2A-A0FA-1068-A738-08002B3371B5}""#,
            "Attribute VB_TemplateDerived = False",
            "Attribute VB_Customizable = False",
            "Attribute VB_PredeclaredId = False",
        ] { assert!(body.contains(attribute), "{attribute}"); }
        let properties = String::from_utf8(project.read_stream("/PROJECT").unwrap()).unwrap();
        assert!(properties.lines().any(|line| line == "Class=Widget"));
        assert!(properties.lines().any(|line| line == "Module=ExtraModule"));
        assert_eq!(crate::vba_source_writer::update_project(&changed, source, Some(932)).unwrap(), changed);
        let duplicate = source.to_owned() + "Attribute VB_Name = \"ExtraModule\"\nPublic x As Long\n";
        assert!(crate::vba_source_writer::update_project(&original, &duplicate, Some(932)).unwrap_err().contains("duplicate"));
        let invalid = source.replace("ExtraModule", "9Invalid");
        assert!(crate::vba_source_writer::update_project(&original, &invalid, Some(932)).unwrap_err().contains("invalid VBA module name"));
        let document = source.replace("Public marker As Long", "Attribute VB_Base = \"0{00020820-0000-0000-C000-000000000046}\"\nPublic marker As Long");
        assert!(crate::vba_source_writer::update_project(&original, &document, Some(932)).unwrap_err().contains("document module creation"));
    }

