// Proposed WorkbookApplication methods; private proposal, not applied.
impl<'a> WorkbookApplication<'a> {
    fn external_formula_names(value: &Value) -> Vec<String> {
        fn collect(value: &Value, names: &mut Vec<String>) {
            match value {
                Value::Array(array) => {
                    for item in &array.values { collect(item, names); }
                }
                Value::String(text) if text.starts_with('=') => {
                    collect_units(&text.encode_utf16().collect::<Vec<_>>(), names);
                }
                Value::Utf16(units) if units.first() == Some(&(b'=' as u16)) => {
                    collect_units(units, names);
                }
                _ => {}
            }
        }
        fn collect_units(units: &[u16], names: &mut Vec<String>) {
            let _ = oxicells_calc::parser::transform_utf16_formula(units, |formula| {
                oxicells_calc::lexer::map_formula_sheet_references(formula, |sheet| {
                    if let Some(open) = sheet.rfind('[') {
                        if let Some(close) = sheet[open + 1..].find(']') {
                            let book = &sheet[..open + close + 2];
                            if !names.iter().any(|held| held.eq_ignore_ascii_case(book)) {
                                names.push(book.into());
                            }
                        }
                    }
                    None
                }).map_err(|error| error.to_string())
            });
        }
        let mut names = Vec::new();
        collect(value, &mut names);
        names
    }

    fn external_formula_sources_for_names(&self, owner: u64, names: &[String])
        -> std::rc::Rc<Vec<oxicells_core::ir::ExternalBook>> {
        if names.is_empty() { return Default::default(); }
        let mut sources = Vec::new();
        for (id, host) in &self.hosts {
            if *id == owner || self.closed.contains(id) { continue; }
            let Some(full) = host.file_io.full_name.as_deref().or(host.file_name.as_deref()) else { continue; };
            let leaf = full.rsplit(['\\', '/']).next().unwrap_or(full);
            let requested = names.iter().any(|name| {
                let Some(open) = name.rfind('[') else { return false; };
                let Some(book) = name[open+1..].strip_suffix(']') else { return false; };
                if open == 0 { leaf.eq_ignore_ascii_case(book) }
                else { full.eq_ignore_ascii_case(&format!("{}{book}", &name[..open])) }
            });
            if !requested { continue; }
            // This transient snapshot is scoped to one assignment operation.
            // Only actually referenced cells are committed to the external cache.
            sources.push(oxicells_core::ir::ExternalBook {
                origin_part: None, target: Some(full.into()),
                absolute_target: (full.as_bytes().get(1) == Some(&b':') || full.starts_with("\\\\"))
                    .then(|| format!("file:///{full}")),
                sheets: host.workbook.sheets.iter().map(|sheet| oxicells_core::ir::ExternalSheet {
                    name: sheet.name.clone(),
                    cells: sheet.rows.iter().flat_map(|row| row.cells.iter()
                        .map(move |cell| (row.index, cell.col, cell.value.clone()))).collect(),
                }).collect(),
            });
        }
        std::rc::Rc::new(sources)
    }
}

// Proposed WorkbookHost method. Both UTF8 and UTF16 stores must use its result.
impl WorkbookHost<'_> {
    fn bind_external_formula(&mut self, units: &[u16]) -> Result<Vec<u16>, String> {
        if self.external_formula_sources.is_empty() || !units.contains(&(b'[' as u16)) {
            return Ok(units.to_vec());
        }
        let sources = self.external_formula_sources.clone();
        let mut books = self.workbook.external_books.clone();
        let mut open = self.open_external_books.clone();
        let bound = oxicells_calc::parser::transform_utf16_formula(units, |formula| {
            oxicells_calc::lexer::map_formula_sheet_references(formula, |qualifier| {
                let start = qualifier.rfind('[')?;
                let end = qualifier[start + 1..].find(']')? + start + 1;
                let name = &qualifier[start + 1..end];
                if name.parse::<u32>().is_ok() { return None; }
                let source = sources.iter().find(|source| source.target.as_deref().is_some_and(|full| {
                    if start == 0 { full.rsplit(['\\','/']).next().unwrap_or(full).eq_ignore_ascii_case(name) }
                    else { full.eq_ignore_ascii_case(&format!("{}{name}", &qualifier[..start])) }
                }))?;
                let target = source.target.as_deref()?;
                let index = books.iter().position(|book| self.external_link_source_name(book)
                    .is_some_and(|full| full.eq_ignore_ascii_case(target))).unwrap_or_else(|| {
                        books.push(oxicells_core::ir::ExternalBook {
                            origin_part: None, target: source.target.clone(),
                            absolute_target: source.absolute_target.clone(),
                            sheets: source.sheets.iter().map(|sheet| oxicells_core::ir::ExternalSheet {
                                name: sheet.name.clone(), cells: Vec::new(),
                            }).collect(),
                        });
                        books.len() - 1
                    });
                open.insert(index);
                Some(format!("[{}]{}", index + 1, &qualifier[end + 1..]))
            }).map_err(|error| host_error(1004, error.to_string()))
        })?;
        fn refs(expression: &oxicells_calc::Expr, result: &mut Vec<oxicells_calc::Reference>) {
            use oxicells_calc::Expr;
            match expression {
                Expr::Ref(reference) => result.push(reference.clone()),
                Expr::Unary { operand, .. } => refs(operand, result),
                Expr::Binary { lhs, rhs, .. } => { refs(lhs, result); refs(rhs, result); }
                Expr::Function { args, .. } => for arg in args { refs(arg, result); },
                _ => {}
            }
        }
        let expression = oxicells_calc::parser::parse_utf16(&bound)
            .map_err(|error| host_error(1004, error.to_string()))?;
        let mut requested = Vec::new();
        refs(&expression, &mut requested);
        for reference in requested {
            let Some(index) = reference.book.and_then(|number| number.checked_sub(1)).map(|index| index as usize) else { continue; };
            let Some(book) = books.get_mut(index) else { continue; };
            let Some(source) = sources.iter().find(|source| self.external_link_source_name(book)
                .is_some_and(|full| source.target.as_deref().is_some_and(|target| full.eq_ignore_ascii_case(target)))) else { continue; };
            open.insert(index);
            let Some(asked) = &reference.sheet else { continue; };
            let selected = if let Some((first, last)) = asked.split_once(':') {
                let a = source.sheets.iter().position(|sheet| same_sheet_name(&sheet.name, first));
                let b = source.sheets.iter().position(|sheet| same_sheet_name(&sheet.name, last));
                a.zip(b).map(|(a,b)| (a.min(b),a.max(b)))
            } else {
                source.sheets.iter().position(|sheet| same_sheet_name(&sheet.name, asked)).map(|at| (at,at))
            };
            let Some((first,last)) = selected else { continue; };
            for sheet in &source.sheets[first..=last] {
                let position = book.sheets.iter().position(|held| same_sheet_name(&held.name, &sheet.name));
                let position = position.unwrap_or_else(|| {
                    book.sheets.push(oxicells_core::ir::ExternalSheet { name:sheet.name.clone(), cells:Vec::new() });
                    book.sheets.len()-1
                });
                let target = &mut book.sheets[position];
                for (row,col,value) in &sheet.cells {
                    let row_zero = row.saturating_sub(1);
                    if row_zero < reference.range.start.row.min(reference.range.end.row)
                        || row_zero > reference.range.start.row.max(reference.range.end.row)
                        || *col < reference.range.start.col.min(reference.range.end.col)
                        || *col > reference.range.start.col.max(reference.range.end.col) { continue; }
                    if let Some(held) = target.cells.iter_mut().find(|held| held.0 == *row && held.1 == *col) {
                        held.2 = value.clone();
                    } else { target.cells.push((*row,*col,value.clone())); }
                }
            }
        }
        // No registration on lexical/parse errors; callers have already checked
        // protection/array/merge rules before invoking the actual cell store.
        self.workbook.external_books = books;
        self.open_external_books = open;
        Ok(bound)
    }
}

impl ApplicationHost<'_> {
    fn external_formula_sources_for_input(&self, receiver: &ObjectRef, name: &str, value: &Value)
        -> std::rc::Rc<Vec<oxicells_core::ir::ExternalBook>> {
        let names = WorkbookApplication::external_formula_names(value);
        if names.is_empty() { return Default::default(); }
        let application = self.application.borrow();
        let owner = application.owner(self.code_owner, Some(receiver), name, true);
        application.external_formula_sources_for_names(owner, &names)
    }
}

impl WorkbookHost<'_> {
    fn finish_cell_assignment(&mut self, writes: &RangeInputWrite) -> Result<(), String> {
        if writes.refused && writes.failure.is_none() {
            // Ordinary value/formula setters dirty Saved even when every cell
            // is refused. FormulaArray instead rejects before any cell store.
            self.saved = false;
            let description = match self.error_language {
                ErrorLanguage::Japanese => "\u{5909}\u{66f4}\u{3057}\u{3088}\u{3046}\u{3068}\u{3057}\u{3066}\u{3044}\u{308b}\u{30bb}\u{30eb}\u{3084}\u{30b0}\u{30e9}\u{30d5}\u{306f}\u{4fdd}\u{8b77}\u{3055}\u{308c}\u{3066}\u{3044}\u{308b}\u{30b7}\u{30fc}\u{30c8}\u{4e0a}\u{306b}\u{3042}\u{308a}\u{307e}\u{3059}\u{3002}\u{5909}\u{66f4}\u{3059}\u{308b}\u{306b}\u{306f}\u{3001}\u{30b7}\u{30fc}\u{30c8}\u{306e}\u{4fdd}\u{8b77}\u{3092}\u{89e3}\u{9664}\u{3057}\u{3066}\u{304f}\u{3060}\u{3055}\u{3044}\u{3002}\u{30d1}\u{30b9}\u{30ef}\u{30fc}\u{30c9}\u{306e}\u{5165}\u{529b}\u{304c}\u{5fc5}\u{8981}\u{306a}\u{5834}\u{5408}\u{3082}\u{3042}\u{308a}\u{307e}\u{3059}\u{3002}",
                // Preserve the existing English description pending an English
                // Excel reference; exact localized wording is not certified.
                ErrorLanguage::English => "the cell is locked and the sheet is protected; unprotect it first",
            };
            Err(oxivba_core::host_error_from(1004,"Microsoft Excel",description))
        } else { writes.finish() }
    }
}

fn external_book_source_name(book: &oxicells_core::ir::ExternalBook, full_name: Option<&str>) -> Option<String> {
        fn decoded(text: &str) -> String {
            let mut bytes = Vec::new();
            let mut at = 0;
            while at < text.len() {
                if text.as_bytes()[at] == b'%' && at + 2 < text.len() {
                    if let Some(value) = std::str::from_utf8(&text.as_bytes()[at + 1..at + 3]).ok().and_then(|hex| u8::from_str_radix(hex, 16).ok()) {
                        bytes.push(value); at += 3; continue;
                    }
                }
                bytes.push(text.as_bytes()[at]); at += 1;
            }
            String::from_utf8(bytes).unwrap_or_else(|_| text.to_owned())
        }
        fn file_target(text: &str) -> String {
            let text = decoded(text);
            if text.get(..8).is_some_and(|prefix| prefix.eq_ignore_ascii_case("file:///")) {
                return text[8..].replace('/', "\\");
            }
            if text.get(..7).is_some_and(|prefix| prefix.eq_ignore_ascii_case("file://")) {
                return format!("\\\\{}", text[7..].replace('/', "\\"));
            }
            text
        }
        let target = file_target(book.target.as_deref().or(book.absolute_target.as_deref())?);
        if target.contains("://") { return Some(target) }
        let target = target.replace('/', "\\");
        let absolute = target.starts_with("\\\\") || target.as_bytes().get(1) == Some(&b':');
        if !absolute && full_name.is_none() {
            return Some(book.absolute_target.as_deref().map(file_target).unwrap_or(target));
        }
        let mut paths = oxivba_core::files::Files::default();
        if let Some(parent) = full_name.and_then(|name| name.rsplit_once(['\\', '/'])).map(|(parent, _)| parent) {
            paths.mount_folder(parent).ok()?;
            paths.change_directory(parent).ok()?;
        }
        Some(paths.absolute_path(&target))
    }

