struct CopiedSheetLinkImport<'a> {
    source_package: &'a [u8],
    source: &'a Workbook,
    source_sheet: usize,
    destination_sheet: usize,
    source_full_name: Option<&'a str>,
    target_full_name: Option<&'a str>,
    copied_parts: &'a std::collections::HashMap<String,String>,
    copied_part_names: &'a [String],
    imported_names_from: usize,
}

impl WorkbookApplication<'_> {
    fn finish_copied_sheet_external_links(
        context: CopiedSheetLinkImport<'_>, package: &[u8],
    ) -> Result<Vec<u8>,String> {
        let failed=|error:oxicells_core::parser::XlsxError|host_error(1004,error.to_string());
        let mut editor=oxicells_core::XlsxEditor::new(package).map_err(failed)?;
        let mut workbook=editor.workbook().clone();
        let original_name=&context.source.sheets[context.source_sheet].name;
        let mut needs_source=false;
        for row in &workbook.sheets[context.destination_sheet].rows {
            for cell in &row.cells {
                let mut inspect=|formula:&str| {
                    oxicells_calc::lexer::map_formula_sheet_references(formula,|sheet| {
                        if !same_sheet_name(sheet,original_name) && sheet.split(':').all(|name|
                            context.source.sheets.iter().any(|sheet|same_sheet_name(&sheet.name,name))) {
                            needs_source=true;
                        }
                        None
                    }).map_err(|error|host_error(1004,error.to_string()))
                };
                if let Some(units)=cell.formula_utf16.as_deref() {
                    oxicells_calc::parser::transform_utf16_formula(units,&mut inspect)?;
                }else if let Some(formula)=&cell.formula {inspect(formula)?;}
            }
        }
        if needs_source {
            if let Some(name)=context.source_full_name {
                let existing=workbook.external_books.iter().any(|book|
                    external_book_source_name(book,context.target_full_name)
                        .is_some_and(|held|held.eq_ignore_ascii_case(name))
                    || book.target.as_deref()==Some(name));
                if !existing {
                    workbook.external_books.push(oxicells_core::ir::ExternalBook {
                        origin_part:None,target:Some(name.into()),
                        absolute_target:(name.as_bytes().get(1)==Some(&b':')||name.starts_with("\\\\"))
                            .then(||format!("file:///{name}")),
                        sheets:context.source.sheets.iter().map(|sheet|oxicells_core::ir::ExternalSheet {
                            name:sheet.name.clone(),cells:Vec::new(),
                        }).collect(),
                    });
                }
            }
        }
        // Reserve the local-source identity first, as Excel does. Provider roots
        // are imported next, before any source numeric qualifiers are rebound.
        editor.apply_workbook(&workbook).map_err(failed)?;
        let prepared=editor.save().map_err(failed)?;
        let mut needed=BTreeSet::new();
        let mut collect=|units:&[u16]| -> Result<Vec<u16>,oxicells_core::parser::XlsxError> {
            if !units.contains(&(b'[' as u16)) {return Ok(units.to_vec());}
            oxicells_calc::parser::transform_utf16_formula(units,|formula|
                oxicells_calc::lexer::map_formula_sheet_references(formula,|sheet| {
                    if let Some((number,_))=sheet.strip_prefix('[').and_then(|sheet|sheet.split_once(']')) {
                        if let Ok(index)=number.parse::<u32>() {needed.insert(index);}
                    }
                    None
                }).map_err(|error|error.to_string())).map_err(oxicells_core::parser::XlsxError::InvalidData)
        };
        oxicells_core::editor::map_imported_part_formulas(&prepared,context.copied_part_names,&mut collect).map_err(failed)?;
        for (_,formula) in workbook.defined_names.iter().skip(context.imported_names_from) {
            collect(&formula.encode_utf16().collect::<Vec<_>>()).map_err(failed)?;
        }
        let mut targets=workbook.external_books.iter().map(|book|
            external_book_source_name(book,context.target_full_name)).collect::<Vec<_>>();
        let source_base=context.source_full_name.filter(|name|
            name.as_bytes().get(1)==Some(&b':')||name.starts_with("\\\\"));
        let mut roots=Vec::new();
        let mut pending=Vec::<(u32,Option<String>)>::new();
        let mut source_roots=std::collections::HashMap::new();
        let mut mapping=std::collections::BTreeMap::new();
        for number in needed {
            let index=number.checked_sub(1).ok_or_else(||host_error(1004,"Invalid copied external book index"))? as usize;
            let book=context.source.external_books.get(index).ok_or_else(||host_error(1004,"Copied external book is missing"))?;
            let target=external_book_source_name(book,source_base);
            let existing=target.as_ref().and_then(|name|targets.iter().position(|held|
                held.as_ref().is_some_and(|held|held.eq_ignore_ascii_case(name))));
            let destination=if let Some(existing)=existing {
                u32::try_from(existing+1).map_err(|_|host_error(1004,"External book index space exhausted"))?
            }else{
                let root=book.origin_part.as_ref().ok_or_else(||host_error(1004,"Copied external book source identity is missing"))?;
                if let Some(existing)=source_roots.get(root) {*existing}
                else {
                    let next=u32::try_from(targets.len()+1).map_err(|_|host_error(1004,"External book index space exhausted"))?;
                    targets.push(target.clone());roots.push(root.clone());pending.push((next,target));
                    source_roots.insert(root.clone(),next);next
                }
            };
            mapping.insert(number,destination);
        }
        let (imported,imported_roots)=oxicells_core::editor::import_workbook_external_link_graphs(
            context.source_package,&prepared,&roots,context.copied_parts).map_err(failed)?;
        if imported_roots.len()!=pending.len() {return Err(host_error(1004,"Imported external book identities differ"));}
        let mut remap=|units:&[u16]| -> Result<Vec<u16>,oxicells_core::parser::XlsxError> {
            if !units.contains(&(b'[' as u16)) {return Ok(units.to_vec());}
            oxicells_calc::parser::transform_utf16_formula(units,|formula|
                oxicells_calc::lexer::map_formula_sheet_references(formula,|sheet| {
                    let (number,name)=sheet.strip_prefix('[')?.split_once(']')?;
                    let old=number.parse::<u32>().ok()?;let new=*mapping.get(&old)?;
                    (old!=new).then(||format!("[{new}]{name}"))
                }).map_err(|error|error.to_string())).map_err(oxicells_core::parser::XlsxError::InvalidData)
        };
        let imported=oxicells_core::editor::map_imported_part_formulas(&imported,context.copied_part_names,&mut remap).map_err(failed)?;
        let mut editor=oxicells_core::XlsxEditor::new(&imported).map_err(failed)?;
        let mut workbook=editor.workbook().clone();
        for ((number,target),root) in pending.iter().zip(&imported_roots) {
            let book=workbook.external_books.get_mut((*number-1)as usize)
                .ok_or_else(||host_error(1004,"Imported external book registration is missing"))?;
            if book.origin_part.as_ref()!=Some(root) {return Err(host_error(1004,"Imported external book order differs"));}
            if let Some(target)=target {
                if context.target_full_name.is_none() || !external_book_source_name(book,context.target_full_name)
                    .is_some_and(|current|current.eq_ignore_ascii_case(target)) {
                    book.target=Some(target.clone());
                }
            }
        }
        for (_,formula) in workbook.defined_names.iter_mut().skip(context.imported_names_from) {
            let units=remap(&formula.encode_utf16().collect::<Vec<_>>()).map_err(failed)?;
            *formula=String::from_utf16(&units).map_err(|_|host_error(1004,"Imported name formula contains invalid UTF16"))?;
        }
        if let Some(name)=context.source_full_name {
            Self::attach_copied_sheet_links(context.source,&mut workbook,context.source_sheet,
                context.destination_sheet,name,context.target_full_name)?;
        }
        editor.apply_workbook(&workbook).map_err(failed)?;
        editor.save().map_err(failed)
    }
}
